// Package pager gives realms bounded, paginated iteration over an avl.Tree.
//
// Walking a whole tree inside Render or inside a transaction costs gas in
// proportion to the number of entries, so a realm that does it gets slower
// with every new entry until it no longer fits in the gas limit. pager caps
// every walk at MaxLimit entries and gives Render a ready-made "prev / next"
// navigation line.
//
//	func Render(path string) string {
//		offset, limit := pager.Parse(path)
//		page := pager.Of(posts, offset, limit, true)
//		out := ""
//		for _, it := range page.Items {
//			out += "- " + it.Value.(*Post).Body + "\n"
//		}
//		return out + page.Nav("")
//	}
//
// Assayer suggests this package as the fix for rules AS-G01 and AS-G02.
package pager

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	// DefaultLimit is the page size used when the path names none.
	DefaultLimit = 20
	// MaxLimit is the largest page size Of will ever return.
	MaxLimit = 100
)

// Item is one tree entry on a page.
type Item struct {
	Key   string
	Value any
}

// Page is a bounded slice of a tree.
type Page struct {
	Items   []Item
	Offset  int
	Limit   int
	Total   int
	HasPrev bool
	HasNext bool
}

// Clamp returns offset and limit forced into a safe range:
// offset >= 0 and 1 <= limit <= MaxLimit.
func Clamp(offset, limit int) (int, int) {
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 {
		limit = DefaultLimit
	}
	if limit > MaxLimit {
		limit = MaxLimit
	}
	return offset, limit
}

// Of returns at most limit entries of t starting at offset. With reverse
// set, entries come newest-key first. A nil tree gives an empty page.
func Of(t *avl.Tree, offset, limit int, reverse bool) Page {
	offset, limit = Clamp(offset, limit)
	p := Page{Offset: offset, Limit: limit}
	if t == nil {
		return p
	}
	p.Total = t.Size()
	collect := func(key string, value any) bool {
		p.Items = append(p.Items, Item{Key: key, Value: value})
		return false
	}
	if reverse {
		t.ReverseIterateByOffset(offset, limit, collect)
	} else {
		t.IterateByOffset(offset, limit, collect)
	}
	p.HasPrev = offset > 0
	p.HasNext = offset+len(p.Items) < p.Total
	return p
}

// Parse reads "page" (1-based) and "size" from the query part of a Render
// path, e.g. "posts?page=3&size=10". Missing or bad values fall back to the
// first page of DefaultLimit entries.
func Parse(path string) (offset, limit int) {
	page, size := 1, DefaultLimit
	if i := strings.Index(path, "?"); i >= 0 {
		for _, kv := range strings.Split(path[i+1:], "&") {
			parts := strings.SplitN(kv, "=", 2)
			if len(parts) != 2 {
				continue
			}
			n, err := strconv.Atoi(parts[1])
			if err != nil {
				continue
			}
			switch parts[0] {
			case "page":
				if n > 0 {
					page = n
				}
			case "size":
				size = n
			}
		}
	}
	_, size = Clamp(0, size)
	return (page - 1) * size, size
}

// Base strips the query part from a Render path.
func Base(path string) string {
	if i := strings.Index(path, "?"); i >= 0 {
		return path[:i]
	}
	return path
}

// PageNumber is the 1-based number of this page.
func (p Page) PageNumber() int {
	if p.Limit == 0 {
		return 1
	}
	return p.Offset/p.Limit + 1
}

// Nav renders a markdown "prev | page x/y | next" line whose links point at
// base with ?page= and &size= appended. It returns "" for a single page.
func (p Page) Nav(base string) string {
	if !p.HasPrev && !p.HasNext {
		return ""
	}
	pages := (p.Total + p.Limit - 1) / p.Limit
	cur := p.PageNumber()
	link := func(n int) string {
		return base + "?page=" + strconv.Itoa(n) + "&size=" + strconv.Itoa(p.Limit)
	}
	var b strings.Builder
	b.WriteString("\n")
	if p.HasPrev {
		b.WriteString("[« prev](" + link(cur-1) + ") | ")
	}
	b.WriteString("page " + strconv.Itoa(cur) + "/" + strconv.Itoa(pages))
	if p.HasNext {
		b.WriteString(" | [next »](" + link(cur+1) + ")")
	}
	b.WriteString("\n")
	return b.String()
}

package pager

import (
	"strconv"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/uassert/v0"
)

func fill(n int) *avl.Tree {
	t := avl.NewTree()
	for i := 0; i < n; i++ {
		k := strconv.Itoa(1000 + i) // fixed width keeps order numeric
		t.Set(k, i)
	}
	return t
}

func TestClamp(t *testing.T) {
	o, l := Clamp(-5, 0)
	uassert.Equal(t, 0, o)
	uassert.Equal(t, DefaultLimit, l)
	_, l = Clamp(0, 100000)
	uassert.Equal(t, MaxLimit, l)
}

func TestOfForward(t *testing.T) {
	p := Of(fill(45), 20, 20, false)
	uassert.Equal(t, 20, len(p.Items))
	uassert.Equal(t, "1020", p.Items[0].Key)
	uassert.Equal(t, 45, p.Total)
	uassert.True(t, p.HasPrev)
	uassert.True(t, p.HasNext)
	uassert.Equal(t, 2, p.PageNumber())
}

func TestOfReverseLastPage(t *testing.T) {
	p := Of(fill(45), 40, 20, true)
	uassert.Equal(t, 5, len(p.Items))
	uassert.Equal(t, "1004", p.Items[0].Key)
	uassert.False(t, p.HasNext)
}

func TestOfNeverExceedsMax(t *testing.T) {
	p := Of(fill(300), 0, 5000, false)
	uassert.Equal(t, MaxLimit, len(p.Items))
}

func TestOfNilTree(t *testing.T) {
	p := Of(nil, 0, 10, false)
	uassert.Equal(t, 0, len(p.Items))
	uassert.Equal(t, "", p.Nav("x"))
}

func TestParse(t *testing.T) {
	o, l := Parse("posts?page=3&size=10")
	uassert.Equal(t, 20, o)
	uassert.Equal(t, 10, l)

	o, l = Parse("posts")
	uassert.Equal(t, 0, o)
	uassert.Equal(t, DefaultLimit, l)

	o, l = Parse("?page=-2&size=abc")
	uassert.Equal(t, 0, o)
	uassert.Equal(t, DefaultLimit, l)

	_, l = Parse("?size=999999")
	uassert.Equal(t, MaxLimit, l)
}

func TestBase(t *testing.T) {
	uassert.Equal(t, "posts", Base("posts?page=2"))
	uassert.Equal(t, "posts", Base("posts"))
}

func TestNav(t *testing.T) {
	p := Of(fill(45), 20, 20, false)
	nav := p.Nav("board")
	uassert.Equal(t, "\n[« prev](board?page=1&size=20) | page 2/3 | [next »](board?page=3&size=20)\n", nav)

	single := Of(fill(3), 0, 20, false)
	uassert.Equal(t, "", single.Nav("board"))
}

// Package guard holds the small checks that Assayer's rules ask for.
//
// Every helper panics with a short, stable message when the check fails, so
// a realm can call it as the first line of a function and move on:
//
//	func Withdraw(cur realm, to address, amount int64) {
//		caller := cur.Previous().Address()
//		guard.RequireValidAddr(to, "to")
//		guard.RequirePositive(amount, "amount")
//		balances.Set(caller.String(), guard.SafeSub(balanceOf(caller), amount))
//		...
//	}
//
// Rule → helper:
//
//	AS-S01, AS-S02, AS-S06  OnlyOwner, OnlyOneOf
//	AS-S03                  SafeSub, SafeAdd
//	AS-S09                  RequireValidAddr
//	AS-T02                  RequireMaxLen, RequireNonEmpty
//	AS-T04                  RequireMaxItems
package guard

import "strconv"

// OnlyOwner panics unless caller is owner. owner must be a valid address:
// a zero owner would otherwise lock or open the function by accident.
func OnlyOwner(caller, owner address) {
	if !owner.IsValid() {
		panic("guard: owner is not set")
	}
	if caller != owner {
		panic("guard: caller is not the owner")
	}
}

// OnlyOneOf panics unless caller is one of allowed.
func OnlyOneOf(caller address, allowed ...address) {
	for _, a := range allowed {
		if a.IsValid() && caller == a {
			return
		}
	}
	panic("guard: caller is not authorized")
}

// RequireValidAddr panics if a is not a well-formed bech32 address.
// what names the argument in the error, e.g. "to".
func RequireValidAddr(a address, what string) {
	if !a.IsValid() {
		panic("guard: invalid address for " + what)
	}
}

// RequireMaxLen panics if s is longer than max bytes.
func RequireMaxLen(s string, max int, what string) {
	if len(s) > max {
		panic("guard: " + what + " longer than " + strconv.Itoa(max) + " bytes")
	}
}

// RequireNonEmpty panics if s is empty.
func RequireNonEmpty(s string, what string) {
	if s == "" {
		panic("guard: " + what + " is empty")
	}
}

// RequireMaxItems panics if n (usually len(slice)) is larger than max.
func RequireMaxItems(n, max int, what string) {
	if n > max {
		panic("guard: " + what + " has more than " + strconv.Itoa(max) + " items")
	}
}

// RequirePositive panics unless amount > 0.
func RequirePositive(amount int64, what string) {
	if amount <= 0 {
		panic("guard: " + what + " must be positive")
	}
}

// SafeSub returns balance - amount. It panics if amount is negative or
// larger than balance, so a balance can never go below zero.
func SafeSub(balance, amount int64) int64 {
	if amount < 0 {
		panic("guard: negative amount")
	}
	if amount > balance {
		panic("guard: insufficient balance")
	}
	return balance - amount
}

// SafeAdd returns a + b for non-negative values and panics on overflow.
func SafeAdd(a, b int64) int64 {
	if a < 0 || b < 0 {
		panic("guard: negative operand")
	}
	c := a + b
	if c < a {
		panic("guard: overflow")
	}
	return c
}

package guard

import (
	"testing"

	"gno.land/p/nt/testutils/v0"
