	bob   = testutils.TestAddress("bob")
)

func TestOnlyOwner(cur realm, t *testing.T) {
	uassert.NotPanics(t, cur, func() { OnlyOwner(alice, alice) })
	uassert.PanicsWithMessage(t, cur, "guard: caller is not the owner", func() { OnlyOwner(bob, alice) })
	uassert.PanicsWithMessage(t, cur, "guard: owner is not set", func() { OnlyOwner(bob, address("")) })
}

func TestOnlyOneOf(cur realm, t *testing.T) {
	uassert.NotPanics(t, cur, func() { OnlyOneOf(bob, alice, bob) })
	uassert.PanicsWithMessage(t, cur, "guard: caller is not authorized", func() { OnlyOneOf(bob, alice) })
	uassert.PanicsWithMessage(t, cur, "guard: caller is not authorized", func() { OnlyOneOf(address(""), address("")) })
}

func TestRequireValidAddr(cur realm, t *testing.T) {
	uassert.NotPanics(t, cur, func() { RequireValidAddr(alice, "to") })
	uassert.PanicsWithMessage(t, cur, "guard: invalid address for to", func() { RequireValidAddr(address("g1nope"), "to") })
}

func TestLengths(cur realm, t *testing.T) {
	uassert.NotPanics(t, cur, func() { RequireMaxLen("abc", 3, "body") })
	uassert.PanicsWithMessage(t, cur, "guard: body longer than 2 bytes", func() { RequireMaxLen("abc", 2, "body") })
	uassert.PanicsWithMessage(t, cur, "guard: body is empty", func() { RequireNonEmpty("", "body") })
	uassert.NotPanics(t, cur, func() { RequireMaxItems(5, 5, "ids") })
	uassert.PanicsWithMessage(t, cur, "guard: ids has more than 5 items", func() { RequireMaxItems(6, 5, "ids") })
}

func TestAmounts(cur realm, t *testing.T) {
	uassert.Equal(t, int64(3), SafeSub(10, 7))
	uassert.Equal(t, int64(0), SafeSub(7, 7))
	uassert.PanicsWithMessage(t, cur, "guard: insufficient balance", func() { SafeSub(5, 7) })
	uassert.PanicsWithMessage(t, cur, "guard: negative amount", func() { SafeSub(5, -1) })
	uassert.Equal(t, int64(12), SafeAdd(5, 7))
	uassert.PanicsWithMessage(t, cur, "guard: overflow", func() { SafeAdd(9223372036854775807, 1) })
	uassert.PanicsWithMessage(t, cur, "guard: amount must be positive", func() { RequirePositive(0, "amount") })
}

// Package board is Assayer's on-chain report board.
//
// The assayer CLI audits a realm before deploy (logic bugs, state layout,
// gas and storage cost) and posts the result here with Submit. Every report
// is kept, versioned per package path, so anyone can see on gnoweb whether a
// realm got safer, cheaper or more expensive between deploys.
//
// The board follows its own advice: all state lives in avl trees, inputs are
// size-capped and Render is paginated.
package board

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// Input limits. They keep one submission from bloating the realm's storage.
const (
	MaxPkgPathLen  = 256
	MaxToolLen     = 32
	MaxFuncs       = 32
	MaxFindings    = 64
	MaxNameLen     = 64
	MaxFileLen     = 64
	SourceHashLen  = 64 // hex sha256
	maxFieldsInput = 8192
	maxScoresInput = 32
)

var validClasses = map[string]bool{
	"O(1)": true, "O(log n)": true, "O(n)": true,
	"O(n log n)": true, "O(n^2)": true, "?": true,
}

var validSeverities = map[string]bool{
	"critical": true, "high": true, "medium": true, "low": true, "info": true,
}

// FuncBench is the measured cost of one function or Render path.
type FuncBench struct {
	Name         string // "Post", "Render:" (Render with its path)
	Class        string // fitted complexity, e.g. "O(n)"
	MaxN         int    // largest state size measured
	GasAtMaxN    int64  // gas used at MaxN
	GasPerItem   int64  // marginal gas per extra entry at MaxN
	StorageBytes int64  // storage delta of one call at MaxN
}

// Finding is one static-analysis result with its source location.
type Finding struct {
	Rule     string
	Severity string
	File     string
	Line     int
}

// Report is one benchmark submission.
type Report struct {
	ID         int
	PkgPath    string
	Version    int // 1-based, per PkgPath
	SourceHash string
	Tool       string
	Submitter  address
	Height     int64

	Overall  int
	Security int // logic bugs and access control
	State    int // state layout and storage growth
	Cost     int // measured gas
	Quality  int // tests, docs

	Funcs    []FuncBench
	Findings []Finding
}

var (
	reports = avl.NewTree() // padded id -> *Report
	byPkg   = avl.NewTree() // pkgPath -> *avl.Tree (padded version -> *Report)
	seen    = avl.NewTree() // pkgPath|hash|submitter -> id
	nextID  = 1
)

// Submit stores a benchmark report and returns its id.
//
//	scores:   "overall,security,state,cost,quality" (each 0-100)
//	funcs:    "name|class|maxN|gasAtMaxN|gasPerItem|storageBytes;..."
//	findings: "rule|severity|file|line;..."
//
// The assayer CLI builds these strings for you (assayer submit).
// A submitter can post a given source hash of a package only once.
func Submit(cur realm, pkgPath, sourceHash, tool, scores, funcs, findings string) int {
	caller := cur.Previous().Address()

	if pkgPath == "" || len(pkgPath) > MaxPkgPathLen || !strings.HasPrefix(pkgPath, "gno.land/") {
		panic("invalid pkgPath")
	}
	if !isHex(sourceHash) || len(sourceHash) != SourceHashLen {
		panic("sourceHash must be 64 hex chars")
	}
	if len(tool) > MaxToolLen {
		panic("tool too long")
	}
	if len(scores) > maxScoresInput || len(funcs) > maxFieldsInput || len(findings) > maxFieldsInput {
		panic("input too large")
	}

	// Validate every field before touching state, so a bad submission always
	// gets the error that describes it.
	s := parseScores(scores)
	fb := parseFuncs(funcs)
	fs := parseFindings(findings)

	key := pkgPath + "|" + sourceHash + "|" + caller.String()
	if seen.Has(key) {
		panic("report already submitted for this source")
	}

	r := &Report{
		ID:         nextID,
		PkgPath:    pkgPath,
		SourceHash: sourceHash,
		Tool:       tool,
		Submitter:  caller,
		Height:     runtime.ChainHeight(),
		Overall:    s[0],
		Security:   s[1],
		State:      s[2],
		Cost:       s[3],
		Quality:    s[4],
		Funcs:      fb,
		Findings:   fs,
	}

	var versions *avl.Tree
	if v, ok := byPkg.Get(pkgPath).(*avl.Tree); ok {
		versions = v
	} else {
		versions = avl.NewTree()
		byPkg.Set(pkgPath, versions)
	}
	r.Version = versions.Size() + 1
	versions.Set(pad(r.Version), r)

	reports.Set(pad(r.ID), r)
	seen.Set(key, r.ID)
	nextID++

	chain.Emit("ReportSubmitted",
		"id", strconv.Itoa(r.ID),
		"pkgpath", pkgPath,
		"version", strconv.Itoa(r.Version),
		"overall", strconv.Itoa(r.Overall),
	)
	return r.ID
}

// GetReport returns a report by id, or nil.
func GetReport(id int) *Report {
	r, _ := reports.Get(pad(id)).(*Report)
	return r
}

// Latest returns the newest report for pkgPath, or nil.
func Latest(pkgPath string) *Report {
	versions := versionsOf(pkgPath)
	if versions == nil || versions.Size() == 0 {
		return nil
	}
	_, v := versions.GetByIndex(versions.Size() - 1)
	return v.(*Report)
}

// LatestScore returns the newest overall score for pkgPath and whether one
// exists. Other realms can import board and gate on it.
func LatestScore(pkgPath string) (int, bool) {
	r := Latest(pkgPath)
	if r == nil {
		return 0, false
	}
	return r.Overall, true
}

// Count returns the number of stored reports.
func Count() int { return reports.Size() }

// PackageCount returns the number of distinct package paths benchmarked.
func PackageCount() int { return byPkg.Size() }

func versionsOf(pkgPath string) *avl.Tree {
	v := byPkg.Get(pkgPath)
	if v == nil {
		return nil
	}
	return v.(*avl.Tree)
}

// ---- parsing ----

func parseScores(s string) [5]int {
	var out [5]int
	parts := strings.Split(s, ",")
	if len(parts) != 5 {
		panic("scores must have 5 values")
	}
	for i, p := range parts {
		out[i] = mustInt(p, 0, 100, "score")
	}
	return out
}

func parseFuncs(s string) []FuncBench {
	if s == "" {
		return nil
	}
	entries := strings.Split(s, ";")
	if len(entries) > MaxFuncs {
		panic("too many funcs")
	}
	out := make([]FuncBench, 0, len(entries))
	for _, e := range entries {
		f := strings.Split(e, "|")
		if len(f) != 6 {
			panic("func entry needs 6 fields: " + e)
		}
		if f[0] == "" || len(f[0]) > MaxNameLen {
			panic("bad func name")
		}
		if !validClasses[f[1]] {
			panic("bad complexity class: " + f[1])
		}
		out = append(out, FuncBench{
			Name:         f[0],
			Class:        f[1],
			MaxN:         mustInt(f[2], 0, 1000000000, "maxN"),
			GasAtMaxN:    mustInt64(f[3], "gasAtMaxN"),
			GasPerItem:   mustInt64(f[4], "gasPerItem"),
			StorageBytes: mustInt64(f[5], "storageBytes"),
		})
	}
	return out
}

func parseFindings(s string) []Finding {
	if s == "" {
		return nil
	}
	entries := strings.Split(s, ";")
	if len(entries) > MaxFindings {
		panic("too many findings")
	}
	out := make([]Finding, 0, len(entries))
	for _, e := range entries {
		f := strings.Split(e, "|")
		if len(f) != 4 {
			panic("finding entry needs 4 fields: " + e)
		}
		if f[0] == "" || len(f[0]) > 16 {
			panic("bad rule id")
		}
		if !validSeverities[f[1]] {
			panic("bad severity: " + f[1])
		}
		if len(f[2]) > MaxFileLen {
			panic("file name too long")
		}
		out = append(out, Finding{
			Rule:     f[0],
			Severity: f[1],
			File:     f[2],
			Line:     mustInt(f[3], 0, 1000000, "line"),
		})
	}
	return out
}

func mustInt(s string, lo, hi int, what string) int {
	n, err := strconv.Atoi(strings.TrimSpace(s))
	if err != nil || n < lo || n > hi {
		panic("bad " + what + ": " + s)
	}
	return n
}

func mustInt64(s string, what string) int64 {
	n, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
	if err != nil {
		panic("bad " + what + ": " + s)
	}
	return n
}

func isHex(s string) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return false
		}
	}
	return true
}

// pad gives fixed-width keys so avl order matches numeric order.
func pad(n int) string {
	s := strconv.Itoa(n)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

package board

import (
	"strconv"
	"strings"

	pager "gno.land/p/g1yd9jn96nrgg8qyfkpcavxxvrp9g5u7nja3s9ex/pager/v0"
)

// JSON routes for dApps (read with vm/qrender, no gnoweb needed):
//
//	"api/stats"                      {"reports":n,"packages":m}
//	"api/reports?page=1&size=20"     newest reports, summaries only
//	"api/report/<id>"                one full report
//	"api/pkg/<pkgpath>?page=1"       version history of a package, newest first
//
// Every list is paginated with pager, so no route walks the whole board.
func renderAPI(route, path string) string {
	switch {
	case route == "stats":
		return `{"reports":` + strconv.Itoa(reports.Size()) + `,"packages":` + strconv.Itoa(byPkg.Size()) + `}`
	case route == "reports":
		offset, limit := pager.Parse(path)
		page := pager.Of(reports, offset, limit, true)
		var b strings.Builder
		writePageHead(&b, page)
		for i, it := range page.Items {
			if i > 0 {
				b.WriteByte(',')
			}
			if r, ok := it.Value.(*Report); ok {
				writeReport(&b, r, false)
			}
		}
		b.WriteString("]}")
		return b.String()
	case strings.HasPrefix(route, "report/"):
		id, err := strconv.Atoi(strings.TrimPrefix(route, "report/"))
		if err != nil {
			return `{"error":"bad id"}`
		}
		r := GetReport(id)
		if r == nil {
			return `{"error":"not found"}`
		}
		var b strings.Builder
		writeReport(&b, r, true)
		return b.String()
	case strings.HasPrefix(route, "pkg/"):
		versions := versionsOf(strings.TrimPrefix(route, "pkg/"))
		if versions == nil {
			return `{"error":"not found"}`
		}
		offset, limit := pager.Parse(path)
		page := pager.Of(versions, offset, limit, true)
		var b strings.Builder
		writePageHead(&b, page)
		for i, it := range page.Items {
			if i > 0 {
				b.WriteByte(',')
			}
			if r, ok := it.Value.(*Report); ok {
				writeReport(&b, r, true)
			}
		}
		b.WriteString("]}")
		return b.String()
	}
	return `{"error":"unknown route"}`
}

func writePageHead(b *strings.Builder, p pager.Page) {
	b.WriteString(`{"total":` + strconv.Itoa(p.Total) + `,"offset":` + strconv.Itoa(p.Offset) +
		`,"limit":` + strconv.Itoa(p.Limit) + `,"items":[`)
}

func writeReport(b *strings.Builder, r *Report, full bool) {
	b.WriteString(`{"id":` + strconv.Itoa(r.ID))
	b.WriteString(`,"pkgpath":` + jstr(r.PkgPath))
	b.WriteString(`,"version":` + strconv.Itoa(r.Version))
	b.WriteString(`,"sourceHash":` + jstr(r.SourceHash))
	b.WriteString(`,"tool":` + jstr(r.Tool))
	b.WriteString(`,"submitter":` + jstr(r.Submitter.String()))
	b.WriteString(`,"height":` + strconv.FormatInt(r.Height, 10))
	b.WriteString(`,"scores":{"overall":` + strconv.Itoa(r.Overall) + `,"security":` + strconv.Itoa(r.Security) +
		`,"state":` + strconv.Itoa(r.State) + `,"cost":` + strconv.Itoa(r.Cost) + `,"quality":` + strconv.Itoa(r.Quality) + `}`)
	b.WriteString(`,"worst":` + jstr(worstFunc(r)))
	b.WriteString(`,"counts":{`)
	counts := map[string]int{}
	for _, f := range r.Findings {
		counts[f.Severity]++
	}
	first := true
	for _, s := range []string{"critical", "high", "medium", "low", "info"} {
		if counts[s] == 0 {
			continue
		}
		if !first {
			b.WriteByte(',')
		}
		first = false
		b.WriteString(jstr(s) + ":" + strconv.Itoa(counts[s]))
	}
	b.WriteString("}")
	if full {
		b.WriteString(`,"funcs":[`)
		for i, f := range r.Funcs {
			if i > 0 {
				b.WriteByte(',')
			}
			b.WriteString(`{"name":` + jstr(f.Name) + `,"class":` + jstr(f.Class) + `,"maxN":` + strconv.Itoa(f.MaxN) +
				`,"gasAtMaxN":` + strconv.FormatInt(f.GasAtMaxN, 10) + `,"gasPerItem":` + strconv.FormatInt(f.GasPerItem, 10) +
				`,"storageBytes":` + strconv.FormatInt(f.StorageBytes, 10) + `}`)
		}
		b.WriteString(`],"findings":[`)
		for i, f := range r.Findings {
			if i > 0 {
				b.WriteByte(',')
			}
			b.WriteString(`{"rule":` + jstr(f.Rule) + `,"severity":` + jstr(f.Severity) + `,"file":` + jstr(f.File) +
				`,"line":` + strconv.Itoa(f.Line) + `}`)
		}
		b.WriteString("]")
	}
	b.WriteString("}")
}

const hexDigits = "0123456789abcdef"

// jstr encodes s as a JSON string.
func jstr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if c < 0x20 {
				b.WriteString(`\u00`)
				b.WriteByte(hexDigits[c>>4])
				b.WriteByte(hexDigits[c&15])
			} else {
				b.WriteByte(c)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

package board

import (
	"strconv"
	"strings"

	pager "gno.land/p/g1yd9jn96nrgg8qyfkpcavxxvrp9g5u7nja3s9ex/pager/v0"
)

// self is this realm's gnoweb path. Update it if you deploy under another namespace.
const self = "/r/g1yd9jn96nrgg8qyfkpcavxxvrp9g5u7nja3s9ex/board"

// Render routes:
//
//	""                 latest reports (paginated)
//	"pkg/<pkgpath>"    version history of one package, with gas deltas
//	"report/<id>"      one full report
//	"badge/<pkgpath>"  one-line markdown summary for READMEs
//	"api/..."          JSON for dApps (see json.gno)
func Render(path string) string {
	base := pager.Base(path)
	switch {
	case base == "":
		return renderHome(path)
	case strings.HasPrefix(base, "api/"):
		return renderAPI(strings.TrimPrefix(base, "api/"), path)
	case strings.HasPrefix(base, "pkg/"):
		return renderPkg(strings.TrimPrefix(base, "pkg/"), path)
	case strings.HasPrefix(base, "report/"):
		id, err := strconv.Atoi(strings.TrimPrefix(base, "report/"))
		if err != nil {
			return "# Not found\n"
		}
		return renderReport(id)
	case strings.HasPrefix(base, "badge/"):
		return renderBadge(strings.TrimPrefix(base, "badge/"))
	}
	return "# Not found\n"
}

func renderHome(path string) string {
	var b strings.Builder
	b.WriteString("# Assayer\n\n")
	b.WriteString("Pre-deploy audits of Gno realms: logic bugs, state layout, and measured gas & storage cost.\n\n")
	b.WriteString("**" + strconv.Itoa(Count()) + "** reports · **" + strconv.Itoa(PackageCount()) + "** packages\n\n")

	offset, limit := pager.Parse(path)
	page := pager.Of(reports, offset, limit, true)
	if len(page.Items) == 0 {
		b.WriteString("_No reports yet. Run `assayer audit` and `assayer submit`._\n")
		return b.String()
	}
	b.WriteString("| # | Package | v | Score | Worst function | Height |\n")
	b.WriteString("|---|---|---|---|---|---|\n")
	for _, it := range page.Items {
		r := it.Value.(*Report)
		b.WriteString("| [" + strconv.Itoa(r.ID) + "](" + self + ":report/" + strconv.Itoa(r.ID) + ") | ")
		b.WriteString("[" + r.PkgPath + "](" + self + ":pkg/" + r.PkgPath + ") | ")
		b.WriteString(strconv.Itoa(r.Version) + " | ")
		b.WriteString(scoreLabel(r.Overall) + " | ")
		b.WriteString(worstFunc(r) + " | ")
		b.WriteString(strconv.FormatInt(r.Height, 10) + " |\n")
	}
	b.WriteString(page.Nav(""))
	return b.String()
}

func renderPkg(pkgPath, path string) string {
	versions := versionsOf(pkgPath)
	if versions == nil {
		return "# " + pkgPath + "\n\n_No reports for this package._\n"
	}
	var b strings.Builder
	b.WriteString("# " + pkgPath + "\n\n")
	b.WriteString(renderBadge(pkgPath) + "\n\n")

	offset, limit := pager.Parse(path)
	page := pager.Of(versions, offset, limit, true)
	for _, it := range page.Items {
		r := it.Value.(*Report)
		b.WriteString("## v" + strconv.Itoa(r.Version) + " · " + scoreLabel(r.Overall))
		b.WriteString(" · [report " + strconv.Itoa(r.ID) + "](" + self + ":report/" + strconv.Itoa(r.ID) + ")\n\n")
		b.WriteString("source `" + r.SourceHash[:12] + "` · height " + strconv.FormatInt(r.Height, 10) + "\n\n")

		var prev *Report
		if r.Version > 1 {
			if v := versions.Get(pad(r.Version - 1)); v != nil {
				prev = v.(*Report)
			}
		}
		if len(r.Funcs) > 0 {
			b.WriteString("| Function | Complexity | Gas @ n | Δ vs previous |\n|---|---|---|---|\n")
			for _, f := range r.Funcs {
				b.WriteString("| " + f.Name + " | " + f.Class + " | " + fmtGas(f.GasAtMaxN) + " @ " + strconv.Itoa(f.MaxN) + " | ")
				b.WriteString(delta(prev, f) + " |\n")
			}
			b.WriteString("\n")
		}
	}
	b.WriteString(page.Nav("pkg/" + pkgPath))
	return b.String()
}

func renderReport(id int) string {
	r := GetReport(id)
	if r == nil {
		return "# Not found\n"
	}
	var b strings.Builder
	b.WriteString("# Report " + strconv.Itoa(r.ID) + "\n\n")
	b.WriteString("[" + r.PkgPath + "](" + self + ":pkg/" + r.PkgPath + ") · version " + strconv.Itoa(r.Version) + "\n\n")
	b.WriteString("- source sha256: `" + r.SourceHash + "`\n")
	b.WriteString("- submitted by `" + r.Submitter.String() + "` at height " + strconv.FormatInt(r.Height, 10) + "\n")
	if r.Tool != "" {
		b.WriteString("- tool: " + r.Tool + "\n")
	}
	b.WriteString("\n| Overall | Security | State | Cost | Quality |\n|---|---|---|---|---|\n")
	b.WriteString("| " + scoreLabel(r.Overall) + " | " + strconv.Itoa(r.Security) + " | " + strconv.Itoa(r.State) +
		" | " + strconv.Itoa(r.Cost) + " | " + strconv.Itoa(r.Quality) + " |\n\n")

	if len(r.Funcs) > 0 {
		b.WriteString("## Measured cost\n\n")
		b.WriteString("| Function | Complexity | n | Gas | Gas per extra item | Storage Δ (bytes) |\n|---|---|---|---|---|---|\n")
		for _, f := range r.Funcs {
			b.WriteString("| " + f.Name + " | " + f.Class + " | " + strconv.Itoa(f.MaxN) + " | " + fmtGas(f.GasAtMaxN) +
				" | " + fmtGas(f.GasPerItem) + " | " + strconv.FormatInt(f.StorageBytes, 10) + " |\n")
		}
		b.WriteString("\n")
	}
	if len(r.Findings) > 0 {
		b.WriteString("## Findings\n\n| Rule | Severity | Location |\n|---|---|---|\n")
		for _, f := range r.Findings {
			b.WriteString("| " + f.Rule + " | " + f.Severity + " | " + f.File + ":" + strconv.Itoa(f.Line) + " |\n")
		}
		b.WriteString("\nRun `assayer explain <rule>` for the why and the fix.\n")
	}
	return b.String()
}

func renderBadge(pkgPath string) string {
	r := Latest(pkgPath)
	if r == nil {
		return "Assayer: not measured"
	}
	return "**Assayer " + strconv.Itoa(r.Overall) + "/100** · worst: " + worstFunc(r) +
		" · v" + strconv.Itoa(r.Version)
}

// ---- helpers ----

var classRank = map[string]int{
	"?": 0, "O(1)": 1, "O(log n)": 2, "O(n)": 3, "O(n log n)": 4, "O(n^2)": 5,
}

func worstFunc(r *Report) string {
	if len(r.Funcs) == 0 {
		return "—"
	}
	worst := r.Funcs[0]
	for _, f := range r.Funcs[1:] {
		if classRank[f.Class] > classRank[worst.Class] ||
			(classRank[f.Class] == classRank[worst.Class] && f.GasAtMaxN > worst.GasAtMaxN) {
			worst = f
		}
	}
	return worst.Name + " " + worst.Class
}

func scoreLabel(s int) string {
	mark := "🟢"
	if s < 50 {
		mark = "🔴"
	} else if s < 80 {
		mark = "🟡"
	}
	return mark + " " + strconv.Itoa(s)
}

func delta(prev *Report, f FuncBench) string {
	if prev == nil {
		return "—"
	}
	for _, p := range prev.Funcs {
		if p.Name != f.Name {
			continue
		}
		if p.MaxN != f.MaxN || p.GasAtMaxN == 0 {
			return "n changed"
		}
		pct := (f.GasAtMaxN - p.GasAtMaxN) * 100 / p.GasAtMaxN
		switch {
		case pct > 0:
			return "▲ +" + strconv.FormatInt(pct, 10) + "%"
		case pct < 0:
			return "▼ " + strconv.FormatInt(pct, 10) + "%"
		}
		return "="
	}
	return "new"
}

func fmtGas(g int64) string {
	switch {
	case g >= 1000000:
		return strconv.FormatInt(g/1000000, 10) + "." + strconv.FormatInt((g%1000000)/100000, 10) + "M"
	case g >= 1000:
		return strconv.FormatInt(g/1000, 10) + "." + strconv.FormatInt((g%1000)/100, 10) + "k"
	}
	return strconv.FormatInt(g, 10)
}

package sim

// Event bits, reset at the start of every Step.
const (
	EvMove uint32 = 1 << iota
	EvBump
	EvDash
	EvShove
	EvHit
	EvKill
	EvHurt
	EvFall
	EvChest
	EvGate
	EvCrumble
	EvFire
	EvWin
	EvDie
)

// Occ codes above any monster index + 1.
const (
	OccGate uint8 = 0xF0 // OccGate+k: gate k, passable only while open
	OccPit  uint8 = 0xFE // blocks monsters, not projectiles
	OccWall uint8 = 0xFF // wall or out of bounds: blocks both
)

// Runtime-only tile states, never produced by Parse.
const (
	TGateOpen     uint8 = 'o'
	TCrumbleMark  uint8 = 'm' // crumble the hero has left; becomes a pit next beat
	invAfterHit   uint8 = 2
	relicDashMax1 uint8 = 3
	relicDashMax2 uint8 = 8
	defaultDash   uint8 = 5
)

// Ent is a live monster.
type Ent struct {
	Kind   uint8
	X, Y   int8
	HP     int8
	Facing uint8
	Phase  uint8
	Alive  bool
	Wind   uint8 // brute: windup beats left; archer: aim beats left
	Aim    bool  // archer: aim line shown, shot pending
	CD     uint8 // archer: beats before it may aim again
	Under  uint8 // Occ code of its tile without it: 0, or OccGate+k on a gate
}

// Proj is an arrow, or a gargoyle fireball when Fire is set.
type Proj struct {
	X, Y, DX, DY int8
	Alive        bool
	Fire         bool
	Src          uint8 // shooter index + 1 (0 none): a projectile never hits its shooter
}

// Game is the full simulation state. It contains no pointers except M, which is
// read-only after NewGame.
type Game struct {
	M         *Map
	Tiles     [MaxTiles]uint8
	HX, HY    int8
	HIdx      uint16 // hero tile index HY*W + HX
	HP, MaxHP int8
	Inv       uint8
	DashCD    uint8
	DashMax   uint8
	Beat      uint16
	Mons      [MaxMonsters]Ent
	NMons     uint8
	Foes      uint8 // living killable (non-gargoyle) monsters, for SLAY
	// Monster schedule bitmasks (bit i = monster i). A beat visits only
	// (Tick | Sched[beat%4] | idle archers that see the hero) & Live:
	//   Tick: busy monsters that act every beat (aiming or cooling archers,
	//     winding brutes);
	//   Sched[r]: slimes, brutes and gargoyles whose acting beat has beat%4 == r.
	Live  uint16
	Tick  uint16
	Sched [4]uint16
	// Idle archers by position: IdleX[y] has bit x and IdleY[x] has bit y for an
	// idle archer at (x, y). Blocked idle archers cost nothing per beat.
	IdleX [MaxH]uint32
	IdleY [MaxW]uint16
	// Occ is what blocks each tile for monsters and projectiles: 0 free, 1-16 a
	// living monster (index + 1), OccGate+k (gate k), OccPit or OccWall (wall,
	// or the border). It is padded with a 1-tile OccWall border (row stride PW = W+2,
	// tile (x, y) at (y+1)*PW + x+1), so one read answers "in bounds, and can a
	// monster step here or what does an arrow hit" with no bounds check.
	Occ           [MaxOcc]uint8
	PW            uint8
	Projs         [MaxProjs]Proj
	NProjs        uint8 // live projectiles
	Damage, Kills uint8
	Chest, Won    bool
	Dead          bool
	Route         uint32
	Ev            uint32
	FailWhy       string

	// Gate tile indices (Validate caps them at MaxGates; NewGame walls off any
	// extra gate of an unvalidated map). Gates share one plate signal, so their
	// state is O(1) to change: gate k is open when GatesUp (a plate was held at
	// the last hazards phase) or Stuck has bit k (held open by an occupant after
	// the plates were released). GateOcc has bit k while a monster stands on gate
	// k. Tiles keeps TGate for gates; Tile reports TGateOpen when open.
	Gates   [MaxGates]uint16
	NGates  uint16
	GatesUp bool
	Stuck   uint8
	GateOcc uint8
	// Mark is the crumble tile the hero left last beat (it becomes a pit this
	// beat), or -1.
	Mark int16
	// Occ indices of plate tiles (Validate caps them at MaxPlates).
	PlateOI [MaxTiles]uint16
	NPlates uint16
	// Static wall and gate bits per row (bit x) and per column (bit y), for
	// O(1) line of sight; see solidRow/solidCol for closed gates.
	RowWall, RowGate [MaxH]uint32
	ColWall, ColGate [MaxW]uint16
}

// NewGame starts a game on m with the given relic (0 none, 1 glass, 2 bulwark)
// at full HP.
func NewGame(m *Map, relic uint8) Game {
	return NewGameFrom(m, relic, 0)
}

// NewGameFrom is NewGame with a starting hp carried in from an earlier floor.
// hp outside 1..MaxHP for the relic starts at MaxHP.
func NewGameFrom(m *Map, relic uint8, hp int8) Game {
	var g Game
	g.M = m
	g.Tiles = m.Tiles
	g.HX, g.HY = m.StartX, m.StartY
	g.HIdx = uint16(int(m.StartY)*int(m.W) + int(m.StartX))
	g.Tiles[g.HIdx] = TFloor
	w, h := int(m.W), int(m.H)
	pw := w + 2
	g.PW = uint8(pw)
	for x := 0; x < pw; x++ {
		g.Occ[x] = OccWall
		g.Occ[(h+1)*pw+x] = OccWall
	}
	for y := 0; y < h; y++ {
		g.Occ[(y+1)*pw] = OccWall
		g.Occ[(y+1)*pw+w+1] = OccWall
		for x := 0; x < w; x++ {
			i := y*w + x
			switch g.Tiles[i] {
			case TPit:
				g.Occ[(y+1)*pw+x+1] = OccPit
				continue
			case TPlate:
				g.PlateOI[g.NPlates] = uint16((y+1)*pw + x + 1)
				g.NPlates++
				continue
			case TGate:
				if g.NGates < MaxGates {
					g.Occ[(y+1)*pw+x+1] = OccGate + uint8(g.NGates)
					g.Gates[g.NGates] = uint16(i)
					g.NGates++
					g.RowGate[y] |= 1 << uint(x)
					g.ColGate[x] |= 1 << uint(y)
					continue
				}
				g.RowWall[y] |= 1 << uint(x)
				g.ColWall[x] |= 1 << uint(y)
			case TWall:
				g.RowWall[y] |= 1 << uint(x)
				g.ColWall[x] |= 1 << uint(y)
			default:
				continue
			}
			g.Occ[(y+1)*pw+x+1] = OccWall
		}
	}
	for i := 0; i < int(m.NMons) && i < MaxMonsters; i++ {
		s := m.Mons[i]
		g.Mons[i] = Ent{Kind: s.Kind, X: s.X, Y: s.Y, HP: s.HP, Facing: s.Facing, Phase: s.Phase, Alive: true}
		g.Occ[(int(s.Y)+1)*pw+int(s.X)+1] = uint8(i + 1)
		if s.Kind != KGargoyle {
			g.Foes++
		}
		bit := uint16(1) << uint(i)
		g.Live |= bit
		if s.Kind == KArcher {
			g.setIdle(int(s.X), int(s.Y), true)
		}
		for r := 0; r < 4; r++ {
			switch s.Kind {
			case KArcher:
			case KGargoyle:
				if (r+int(s.Phase))%4 == 0 {
					g.Sched[r] |= bit
				}
			default:
				if (r+int(s.Phase))%2 == 0 {
					g.Sched[r] |= bit
				}
			}
		}
		g.NMons++
	}
	g.Mark = -1
	g.MaxHP, g.DashMax = 3, defaultDash
	switch relic {
	case 1:
		g.MaxHP, g.DashMax = 2, relicDashMax1
	case 2:
		g.MaxHP, g.DashMax = 4, relicDashMax2
	}
	g.HP = g.MaxHP
	if hp >= 1 && hp <= g.MaxHP {
		g.HP = hp
	}
	g.Route = 2166136261
	return g
}

// monsterAt returns the index of a living monster on (x, y), or -1.
func (g *Game) monsterAt(x, y int) int {
	if x < 0 || y < 0 || x >= int(g.M.W) || y >= int(g.M.H) {
		return -1
	}
	o := int(g.Occ[(y+1)*int(g.PW)+x+1])
	if o == 0 || o > MaxMonsters || !g.Mons[o-1].Alive {
		return -1
	}
	return o - 1
}

// Tile returns tile i's current state: Tiles, except TGateOpen for an open gate.
// Clients read gates through it.
func (g *Game) Tile(i int) uint8 {
	t := g.Tiles[i]
	if t != TGate {
		return t
	}
	w := int(g.M.W)
	o := g.Occ[(i/w+1)*int(g.PW)+i%w+1]
	if o != 0 && o <= MaxMonsters {
		return TGateOpen // occupied, so open
	}
	if o&0xF8 == OccGate && g.gateOpen(o) {
		return TGateOpen
	}
	return TGate
}

// gateOpen reports whether gate code o (OccGate+k) is open.
func (g *Game) gateOpen(o uint8) bool {
	return g.GatesUp || g.Stuck&(1<<(o&7)) != 0
}

// closedAt reports whether (x, y), at most one tile outside the grid, is a wall,
// a closed gate or out of bounds.
func (g *Game) closedAt(x, y int) bool {
	o := g.Occ[(y+1)*int(g.PW)+x+1]
	return o == OccWall || (o&0xF8 == OccGate && !g.gateOpen(o))
}

// dirVec maps 1-4 (and 5-8) to N/E/S/W unit vectors.
func dirVec(d uint8) (int, int) {
	switch (d - 1) & 3 {
	case 0:
		return 0, -1
	case 1:
		return 1, 0
	case 2:
		return 0, 1
	}
	return -1, 0
}

// exitOpen reports whether standing on the exit wins.
func (g *Game) exitOpen() bool {
	return g.M.Obj == ObjExit || g.Foes == 0
}

// heroAct resolves the hero's action. It returns true if this beat's damage
// phase is skipped (dash invulnerability).
func (g *Game) heroAct(a uint8) bool {
	switch {
	case a >= 1 && a <= 4:
		// Flat on purpose: a step can happen every beat. Occ already says wall or
		// closed gate (OccWall) and which monster stands there.
		x, y := int(g.HX), int(g.HY)
		nx, ny := x, y
		switch a {
		case 1:
			ny--
		case 2:
			nx++
		case 3:
			ny++
		default:
			nx--
		}
		if o := g.Occ[(ny+1)*int(g.PW)+nx+1]; o == OccWall || (o&0xF8 == OccGate && !g.gateOpen(o)) {
			g.Ev |= EvBump // wall, closed gate or out of bounds
			return false
		} else if o != 0 && o <= MaxMonsters && g.Mons[o-1].Alive {
			// Bump-attack: the hero stays put.
			if !g.hitMon(int(o-1), x, y) {
				g.Ev |= EvBump
			}
			return false
		}
		g.HX, g.HY = int8(nx), int8(ny)
		g.HIdx = uint16(ny*int(g.M.W) + nx)
		g.Ev |= EvMove
	case a >= 5 && a <= 8:
		if g.DashCD != 0 {
			g.Ev |= EvBump
			return false
		}
		dx, dy := dirVec(a)
		x1, y1 := int(g.HX)+dx, int(g.HY)+dy
		if g.closedAt(x1, y1) {
			g.Ev |= EvBump
			return false
		}
		if i := g.monsterAt(x1, y1); i >= 0 {
			return g.shove(i, x1, y1, dx, dy)
		}
		x2, y2 := x1+dx, y1+dy
		if g.closedAt(x2, y2) || g.monsterAt(x2, y2) >= 0 {
			x2, y2 = x1, y1
		}
		g.HX, g.HY = int8(x2), int8(y2)
		g.HIdx = uint16(y2*int(g.M.W) + x2)
		g.DashCD = g.DashMax
		g.Ev |= EvDash
		return true
	}
	return false
}

// Step executes one beat. Order: hero, tile effects, projectiles, monsters,
// hazards, damage, death, timers.
func (g *Game) Step(a uint8) {
	g.Ev = 0
	if g.Won || g.Dead {
		return
	}
	hIdx := int(g.HIdx)
	dashInv, markIdx, moved := false, -1, false
	if a != 0 {
		pIdx := hIdx
		dashInv = g.heroAct(a)
		hIdx = int(g.HIdx)
		moved = hIdx != pIdx
		// Leaving a crumble marks it.
		if moved && g.Tiles[pIdx] == TCrumble {
			g.Tiles[pIdx] = TCrumbleMark
			markIdx = pIdx
		}
	}

	// Tile effects under the hero. The hero is always in bounds.
	switch g.Tiles[hIdx] {
	case TChest:
		g.Tiles[hIdx] = TFloor
		g.Chest = true
		g.Ev |= EvChest
	case TExit:
		if g.exitOpen() {
			g.Won = true
			g.Ev |= EvWin
			g.endBeat()
			return
		}
	}

	struck := false
	if g.NProjs != 0 {
		struck = g.projectilesPhase()
	}
	if g.Live != 0 && g.monstersPhase(moved) {
		struck = true
	}
	if markIdx >= 0 || g.Mark >= 0 || g.NGates > 0 {
		g.hazardsPhase(markIdx)
	}

	// Damage: at most one per beat, from spikes or a monster or projectile hit.
	// Read the hero's tile again: hazards may have turned it into a pit.
	ht := g.Tiles[hIdx]
	if (struck || (ht == TSpikes && (int(g.Beat)+int(g.HX)+int(g.HY))%4 >= 2)) && g.Inv == 0 && !dashInv {
		g.HP--
		g.Damage++
		g.Inv = invAfterHit + 1 // the decrement below leaves invAfterHit
		g.Ev |= EvHurt
	}

	// Death.
	if g.HP <= 0 || ht == TPit {
		g.Dead = true
		if g.HP <= 0 {
			g.Ev |= EvDie
		}
		if ht == TPit {
			g.Ev |= EvFall
		}
	}

	if g.Inv > 0 {
		g.Inv--
	}
	g.endBeat()
}

// endBeat decrements the dash cooldown, advances the beat and folds the route.
func (g *Game) endBeat() {
	if g.DashCD > 0 {
		g.DashCD--
	}
	g.Beat++
	h := g.Route
	h = (h ^ uint32(uint8(g.HX))) * 16777619
	h = (h ^ uint32(uint8(g.HY))) * 16777619
	g.Route = h
}

// hazardsPhase turns last beat's crumble mark into a pit, dropping any monster
// standing there, records this beat's mark (markIdx, or -1), and opens or closes
// gates from plate occupancy.
func (g *Game) hazardsPhase(markIdx int) {
	w := int(g.M.W)
	if g.Mark >= 0 {
		i := int(g.Mark)
		g.Tiles[i] = TPit
		g.Ev |= EvCrumble
		if o := g.monsterAt(i%w, i/w); o >= 0 {
			g.kill(o) // leaves OccPit
			g.Ev |= EvFall
		} else {
			g.Occ[(i/w+1)*int(g.PW)+i%w+1] = OccPit
		}
	}
	g.Mark = int16(markIdx)

	if g.NGates == 0 {
		return
	}
	pw := int(g.PW)
	held := g.Tiles[g.HIdx] == TPlate
	for k := 0; k < int(g.NPlates) && !held; k++ {
		held = g.Occ[g.PlateOI[k]] != 0 // only a monster can stand on a plate
	}
	if held {
		// Every gate opens; one was closed unless all were already open.
		if !g.GatesUp {
			if g.Stuck != g.allGates() {
				g.Ev |= EvGate
			}
			g.GatesUp, g.Stuck = true, 0
		}
		return
	}
	if !g.GatesUp && g.Stuck == 0 {
		return // all closed already
	}
	// Open gates close unless the hero or a monster stands on them.
	occ := g.GateOcc
	if o := g.Occ[(int(g.HY)+1)*pw+int(g.HX)+1]; o&0xF8 == OccGate {
		occ |= 1 << (o & 7)
	}
	open := g.Stuck
	if g.GatesUp {
		open = g.allGates()
	}
	if open&occ != open {
		g.Ev |= EvGate
	}
	g.GatesUp, g.Stuck = false, open&occ
}

func (g *Game) allGates() uint8 {
	return uint8(uint16(1)<<g.NGates - 1)
}

// stuckBits returns the row (byRow) or column bits of the gates held open by an
// occupant in row or column n.
func (g *Game) stuckBits(n int, byRow bool) uint32 {
	var s uint32
	w := int(g.M.W)
	for k := 0; k < int(g.NGates); k++ {
		if g.Stuck&(1<<uint(k)) == 0 {
			continue
		}
		i := int(g.Gates[k])
		if byRow && i/w == n {
			s |= 1 << uint(i%w)
		} else if !byRow && i%w == n {
			s |= 1 << uint(i/w)
		}
	}
	return s
}

// solidRow returns the wall and closed-gate bits of row y. Only gates held open
// by an occupant (rare) need the gate list.
func (g *Game) solidRow(y int) uint32 {
	switch {
	case g.GatesUp:
		return g.RowWall[y]
	case g.Stuck == 0:
		return g.RowWall[y] | g.RowGate[y]
	}
	return g.RowWall[y] | g.RowGate[y]&^g.stuckBits(y, true)
}

// solidCol is solidRow for column x (bit y).
func (g *Game) solidCol(x int) uint32 {
	switch {
	case g.GatesUp:
		return uint32(g.ColWall[x])
	case g.Stuck == 0:
		return uint32(g.ColWall[x] | g.ColGate[x])
	}
	return uint32(g.ColWall[x]|g.ColGate[x]) &^ g.stuckBits(x, false)
}

package sim

// Tile bytes. Monster glyphs appear only in source grids; they are stored as floor.
const (
	TFloor   uint8 = '.'
	TWall    uint8 = '#'
	TPit     uint8 = '~'
	TSpikes  uint8 = '^'
	TCrumble uint8 = '%'
	TPlate   uint8 = '_'
	TGate    uint8 = '|'
	TChest   uint8 = 'C'
	TStart   uint8 = '@'
	TExit    uint8 = 'E'
)

const (
	MinW, MinH, MaxW, MaxH = 7, 7, 20, 14
	MaxTiles               = 280
	MaxOcc                 = (MaxW + 2) * (MaxH + 2) // grid plus a 1-tile border
	MaxMonsters            = 16
	MaxProjs               = 8
	MaxBeats               = 240
	MaxGates               = 8 // gate toggles loop over every gate
	MaxPlates              = 4
)

const (
	KSlime    uint8 = 1
	KArcher   uint8 = 2
	KBrute    uint8 = 3
	KGargoyle uint8 = 4
)

const (
	ObjExit uint8 = 0
	ObjSlay uint8 = 1
)

// Mon is a monster's spawn data.
type Mon struct {
	Kind   uint8
	X, Y   int8
	HP     int8
	Facing uint8
	Phase  uint8
}

// Map is a parsed room. Tiles is indexed y*W + x.
type Map struct {
	W, H           uint8
	Tiles          [MaxTiles]uint8
	StartX, StartY int8
	Mons           [MaxMonsters]Mon
	NMons          uint8
	Obj            uint8
	HasChest       bool
}

// Glyph classes for Parse and Validate, one table read per byte: cTile marks a
// tile glyph, cHazard a hazard tile, and the low bits hold a monster glyph's kind.
const (
	cTile   uint8 = 0x80
	cHazard uint8 = 0x40
	cKind   uint8 = 0x07
)

var glyphClass = [256]uint8{
	TFloor: cTile, TWall: cTile, TChest: cTile, TStart: cTile, TExit: cTile,
	TPit: cTile | cHazard, TSpikes: cTile | cHazard, TCrumble: cTile | cHazard,
	TPlate: cTile | cHazard, TGate: cTile | cHazard,
	's': KSlime, 'a': KArcher, 'b': KBrute, 'g': KGargoyle,
}

func kindForGlyph(c byte) uint8 {
	return glyphClass[c] & cKind
}

func hpForKind(k uint8) int8 {
	switch k {
	case KSlime, KArcher:
		return 1
	case KBrute:
		return 2
	}
	return 0
}

func isTileGlyph(c byte) bool {
	return glyphClass[c]&cTile != 0
}

func isHazard(c uint8) bool {
	return glyphClass[c]&cHazard != 0
}

package sim

// Monster and projectile rules. Facing is 0 N, 1 E, 2 S, 3 W.
//
// Gas (measured with gno test -print-runtime-metrics): a field selector or array
// index costs about 550 gas and a call about 2k, while locals are nearly free, so
// the per-beat loops below hoist fields into locals and stay flat. Game.Occ
// answers "who or what blocks this tile" in one read and is kept current on every
// move, death, collapse and gate toggle. Monsters that do not act this beat are
// skipped by the Tick/Sched bitmasks, and blocked idle archers cost nothing:
// seenArchers finds the ones with sight from solidRow/solidCol once per beat.
// TestWorstCaseBudget pins the worst case.

const (
	windBrute  = 2
	windArcher = 2
	cdArcher   = 2
)

// bitIndex maps (b * 0x077CB531) >> 27, for a single set bit b, to its position
// (de Bruijn), so loops visit only set bits.
var bitIndex = [32]uint8{
	0, 1, 28, 2, 29, 14, 24, 3, 30, 22, 20, 15, 25, 17, 4, 8,
	31, 27, 13, 23, 21, 19, 16, 7, 26, 12, 18, 6, 11, 5, 10, 9,
}

func faceVec(f uint8) (int, int) {
	switch f & 3 {
	case 0:
		return 0, -1
	case 1:
		return 1, 0
	case 2:
		return 0, 1
	}
	return -1, 0
}

// faceToward returns the facing from (x, y) toward a different tile in the same
// row or column.
func faceToward(x, y, tx, ty int) uint8 {
	switch {
	case tx > x:
		return 1
	case tx < x:
		return 3
	case ty > y:
		return 2
	}
	return 0
}

// kill removes monster i and credits the kill.
func (g *Game) kill(i int) {
	e := &g.Mons[i]
	e.Alive = false
	g.Live &^= 1 << uint(i)
	if e.Kind == KArcher {
		g.setIdle(int(e.X), int(e.Y), false)
	}
	x, y := int(e.X), int(e.Y)
	oi := (y+1)*int(g.PW) + x + 1
	if g.Tiles[y*int(g.M.W)+x] == TPit {
		g.Occ[oi] = OccPit
	} else {
		g.Occ[oi] = e.Under
		if e.Under != 0 {
			g.GateOcc &^= 1 << (e.Under & 7)
		}
	}
	if e.Kind != KGargoyle {
		g.Foes--
	}
	g.Kills++
	g.Ev |= EvKill
}

// dmgMon deals 1 damage to monster i, ignoring shields.
func (g *Game) dmgMon(i int) {
	e := &g.Mons[i]
	e.HP--
	g.Ev |= EvHit
	if e.HP <= 0 {
		g.kill(i)
	}
}

// hitMon deals 1 damage to monster i from the tile (fx, fy). Gargoyles are
// unkillable and a brute's shield blocks hits from the tile it faces. It reports
// whether the hit landed.
func (g *Game) hitMon(i, fx, fy int) bool {
	e := &g.Mons[i]
	switch e.Kind {
	case KGargoyle:
		return false
	case KBrute:
		dx, dy := faceVec(e.Facing)
		if int(e.X)+dx == fx && int(e.Y)+dy == fy {
			return false
		}
	}
	g.dmgMon(i)
	return true
}

// moveMon moves monster i to the open tile (x, y): free, or an open gate.
func (g *Game) moveMon(i, x, y int) {
	e := &g.Mons[i]
	pw := int(g.PW)
	to := (y+1)*pw + x + 1
	g.leaveEnter(i, e, (int(e.Y)+1)*pw+int(e.X)+1, to, g.Occ[to])
	e.X, e.Y = int8(x), int8(y)
}

// leaveEnter moves monster i's Occ entry from index from to index to, whose
// code was under, keeping Under and GateOcc. Only a gate code is remembered: a
// shove can also land a monster on a pit (OccPit), where kill restores OccPit.
func (g *Game) leaveEnter(i int, e *Ent, from, to int, under uint8) {
	g.Occ[from] = e.Under
	if e.Under != 0 {
		g.GateOcc &^= 1 << (e.Under & 7)
	}
	if under&0xF8 == OccGate {
		g.GateOcc |= 1 << (under & 7)
	} else {
		under = 0
	}
	e.Under = under
	g.Occ[to] = uint8(i + 1)
}

// setIdle marks or clears an idle archer at (x, y) in IdleX/IdleY.
func (g *Game) setIdle(x, y int, on bool) {
	if on {
		g.IdleX[y] |= 1 << uint(x)
		g.IdleY[x] |= 1 << uint(y)
	} else {
		g.IdleX[y] &^= 1 << uint(x)
		g.IdleY[x] &^= 1 << uint(y)
	}
}

// visible returns the positions q on a line from which no solid (mask s) lies
// strictly between q and p. Positions that are themselves solid or beyond the
// grid may be set; callers mask them with real archer positions.
func visible(s uint32, p uint) uint32 {
	low := uint32(1)<<p - 1 // positions below p
	b := s & low
	// Smear the highest solid below p downward: b covers every position up to it.
	b |= b >> 1
	b |= b >> 2
	b |= b >> 4
	b |= b >> 8
	b |= b >> 16
	high := ^(low | uint32(1)<<p) // positions above p
	if a := s & high; a != 0 {
		high &= (a & (^a + 1)) - 1 // below the lowest solid above p
	}
	return low&^b | high
}

// seenArchers returns the bits of idle archers in the hero's row or column with
// clear sight to the hero. Sight blockers (walls, closed gates) and archer
// positions cannot change during the monster phase, so this is exact for it.
func (g *Game) seenArchers(hx, hy int) uint16 {
	var seen uint16
	pw := int(g.PW)
	if r := g.IdleX[hy]; r != 0 {
		r &= visible(g.solidRow(hy), uint(hx))
		for x := 0; r != 0; x++ {
			if r&1 != 0 {
				seen |= 1 << uint(g.Occ[(hy+1)*pw+x+1]-1)
			}
			r >>= 1
		}
	}
	if c := uint32(g.IdleY[hx]); c != 0 {
		c &= visible(g.solidCol(hx), uint(hy))
		for y := 0; c != 0; y++ {
			if c&1 != 0 {
				seen |= 1 << uint(g.Occ[(y+1)*pw+hx+1]-1)
			}
			c >>= 1
		}
	}
	return seen
}

// spawnProj puts a projectile on monster i's tile heading in its facing. Live
// projectiles are kept packed in Projs[:NProjs]. It returns false when all slots
// are live.
func (g *Game) spawnProj(i int, fire bool) bool {
	if g.NProjs >= MaxProjs {
		return false
	}
	e := &g.Mons[i]
	dx, dy := faceVec(e.Facing)
	g.Projs[g.NProjs] = Proj{X: e.X, Y: e.Y, DX: int8(dx), DY: int8(dy), Alive: true, Fire: fire, Src: uint8(i + 1)}
	g.NProjs++
	return true
}

// projectilesPhase moves every live projectile one tile. A projectile hits the
// hero when he stands on its next tile or on its current tile. Live projectiles stay
// packed in Projs[:NProjs]: a dead one is replaced by the last (not yet moved)
// one. It reports whether the hero was hit.
//
// A projectile never hits its shooter (Src). The ruling only exempts the first
// move, but the two are equivalent: shooters move only by shove (dash cooldown
// at least 3 beats), so after its first move a projectile is always ahead of its
// shooter and pulls away 1 tile per beat.
func (g *Game) projectilesPhase() bool {
	hit := false
	n := int(g.NProjs)
	pw := int(g.PW)
	hx, hy := g.HX, g.HY
	for k := 0; k < n; {
		p := &g.Projs[k]
		px, py := p.X, p.Y
		nx, ny := px+p.DX, py+p.DY
		// The hero is hit on the projectile's next tile, or on its current one if
		// he stepped into it (no passing through).
		if (nx == hx && ny == hy) || (px == hx && py == hy) {
			hit = true
		} else if o := g.Occ[(int(ny)+1)*pw+int(nx)+1]; o == 0 || o == OccPit || o == p.Src ||
			(o <= MaxMonsters && !g.Mons[o-1].Alive) || (o&0xF8 == OccGate && g.gateOpen(o)) {
			p.X, p.Y = nx, ny
			k++
			continue
		} else if o <= MaxMonsters { // else a wall, closed gate or out of bounds
			g.hitMon(int(o-1), int(px), int(py))
		}
		// The projectile is spent: move the last live one into its slot.
		n--
		g.Projs[k] = g.Projs[n]
		g.Projs[n] = Proj{}
	}
	g.NProjs = uint8(n)
	return hit
}

// monstersPhase lets the monsters scheduled this beat act in spawn order:
// slimes and brutes when (beat+phase)%2 == 0, gargoyles when (beat+phase)%4 == 0,
// busy archers and winding brutes every beat, idle archers when they see the
// hero. moved says the hero changed tile this beat. It reports whether the hero
// was hit.
func (g *Game) monstersPhase(moved bool) bool {
	hit := false
	hx, hy := int(g.HX), int(g.HY)
	pw := int(g.PW)
	// No monster stands on a gate, so a walker leaving its tile leaves 0. Safe
	// to hoist: only a monster that steps onto a gate this phase changes it, and
	// it has already acted.
	offGates := g.GateOcc == 0
	m := g.Tick | g.Sched[g.Beat&3]
	if g.IdleX[hy] != 0 || g.IdleY[hx] != 0 {
		m |= g.seenArchers(hx, hy)
	}
	m &= g.Live
	for m != 0 {
		low := m & (^m + 1)
		m ^= low
		i := int(bitIndex[(uint32(low)*0x077CB531)>>27])
		e := &g.Mons[i]
		switch e.Kind {
		case KSlime, KBrute:
			if e.Wind != 0 { // brute winding up
				e.Wind--
				if e.Wind == 0 {
					g.Tick &^= 1 << uint(i)
					if g.strike(i) {
						hit = true
					}
					m &= g.Live // the strike may have killed a later monster
				}
				continue
			}
			x, y := int(e.X), int(e.Y)
			dx, dy := hx-x, hy-y
			hf, adx, hs := uint8(1), dx, 1
			if dx < 0 {
				hf, adx, hs = 3, -dx, -1
			}
			vf, ady, vs := uint8(2), dy, 1
			if dy < 0 {
				vf, ady, vs = 0, -dy, -1
			}
			if adx+ady == 1 { // adjacent: attack or wind up
				if adx == 1 {
					e.Facing = hf
				} else {
					e.Facing = vf
				}
				if e.Kind == KBrute {
					e.Wind = windBrute
					g.Tick |= 1 << uint(i)
				} else if !moved {
					// A slime attacks only a hero who was already next to it
					// when the beat began (a hero who moved this beat cannot
					// have been: one step or dash never keeps him adjacent).
					// One who just stepped up is only faced.
					hit = true
				}
				continue
			}
			// Step along the larger axis (ties horizontal), else the other one. A
			// tile is open when its Occ is 0 (in bounds, no wall, closed gate, pit
			// or monster); the hero is not adjacent, so never the target. The
			// primary axis always has a nonzero distance. The move is inlined
			// (see moveMon): walkers can move on every acting beat.
			// An open gate (OccGate+k) is open too. Walls and pits (>= OccPit)
			// and monsters (< OccGate) settle in one or two compares.
			oi := (y+1)*pw + x + 1
			to, o, f := 0, uint8(0), uint8(0)
			if adx >= ady {
				to, f = oi+hs, hf
				if o = g.Occ[to]; o != 0 && (o >= OccPit || o < OccGate || !g.gateOpen(o)) {
					if dy == 0 {
						continue
					}
					to, f = oi+vs*pw, vf
					if o = g.Occ[to]; o != 0 && (o >= OccPit || o < OccGate || !g.gateOpen(o)) {
						continue
					}
				}
			} else {
				to, f = oi+vs*pw, vf
				if o = g.Occ[to]; o != 0 && (o >= OccPit || o < OccGate || !g.gateOpen(o)) {
					if dx == 0 {
						continue
					}
					to, f = oi+hs, hf
					if o = g.Occ[to]; o != 0 && (o >= OccPit || o < OccGate || !g.gateOpen(o)) {
						continue
					}
				}
			}
			if o == 0 && offGates {
				g.Occ[oi] = 0
				g.Occ[to] = uint8(i + 1)
			} else {
				g.leaveEnter(i, e, oi, to, o)
			}
			if f == hf {
				e.X = int8(x + hs)
			} else {
				e.Y = int8(y + vs)
			}
			e.Facing = f
		case KArcher:
			if e.CD != 0 {
				e.CD--
				if e.CD == 0 { // idle again
					g.Tick &^= 1 << uint(i)
					g.setIdle(int(e.X), int(e.Y), true)
				}
				continue
			}
			if e.Aim {
				e.Wind--
				if e.Wind == 0 {
					e.Aim = false
					e.CD = cdArcher
					if g.spawnProj(i, false) {
						g.Ev |= EvFire
					}
				}
				continue
			}
			// Idle archers are visited only when seenArchers found clear sight
			// to the hero on a shared row or column: turn and aim.
			x, y := int(e.X), int(e.Y)
			e.Facing = faceToward(x, y, hx, hy)
			e.Aim = true
			e.Wind = windArcher
			g.Tick |= 1 << uint(i)
			g.setIdle(x, y, false)
		case KGargoyle:
			if g.spawnProj(i, true) {
				g.Ev |= EvFire
			}
		}
	}
	return hit
}

// strike resolves brute i's blow on the tile it faces. It reports a hero hit.
func (g *Game) strike(i int) bool {
	e := &g.Mons[i]
	x, y := int(e.X), int(e.Y)
	dx, dy := faceVec(e.Facing)
	tx, ty := x+dx, y+dy
	if tx == int(g.HX) && ty == int(g.HY) {
		return true
	}
	if j := g.monsterAt(tx, ty); j >= 0 {
		g.hitMon(j, x, y)
	}
	return false
}

// shove resolves a dash whose first tile (x1, y1) holds monster i. It reports
// whether the dash happened (and so grants dash invulnerability).
func (g *Game) shove(i, x1, y1, dx, dy int) bool {
	if g.Mons[i].Kind == KGargoyle {
		g.Ev |= EvBump
		return false
	}
	tx, ty := x1+dx, y1+dy
	if g.closedAt(tx, ty) || g.monsterAt(tx, ty) >= 0 {
		g.Ev |= EvBump
		return false
	}
	if e := &g.Mons[i]; e.Kind == KArcher && e.CD == 0 && !e.Aim {
		g.setIdle(x1, y1, false)
		g.setIdle(tx, ty, true)
	}
	t := g.Tiles[ty*int(g.M.W)+tx]
	g.moveMon(i, tx, ty)
	g.HX, g.HY = int8(x1), int8(y1)
	g.HIdx = uint16(y1*int(g.M.W) + x1)
	g.DashCD = g.DashMax
	g.Ev |= EvShove | EvDash
	switch {
	case t == TPit:
		g.kill(i) // leaves OccPit
		g.Ev |= EvFall
	case t == TSpikes && (int(g.Beat)+tx+ty)%4 >= 2:
		g.dmgMon(i)
	}
	return true
}

package sim

func hexVal(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	}
	return -1
}

// normalize converts CRLF to LF, drops one leading newline and one trailing newline.
// Without a CR it only slices (no copy).
func normalize(s string) string {
	cr := false
	for i := 0; i < len(s); i++ {
		if s[i] == '\r' {
			cr = true
			break
		}
	}
	if !cr {
		if len(s) > 0 && s[0] == '\n' {
			s = s[1:]
		}
		if len(s) > 0 && s[len(s)-1] == '\n' {
			s = s[:len(s)-1]
		}
		return s
	}
	b := make([]byte, 0, len(s))
	for i := 0; i < len(s); i++ {
		if s[i] == '\r' && i+1 < len(s) && s[i+1] == '\n' {
			continue
		}
		b = append(b, s[i])
	}
	if len(b) > 0 && b[0] == '\n' {
		b = b[1:]
	}
	if len(b) > 0 && b[len(b)-1] == '\n' {
		b = b[:len(b)-1]
	}
	return string(b)
}

// Parse builds a Map from a grid, per-monster props (one hex char each, row-major
// spawn order: bits 3-2 facing, bits 1-0 phase) and an objective ("EXIT" or "SLAY").
// The second result is "" on success, otherwise a reason code.
func Parse(grid, props, objective string) (Map, string) {
	var m Map
	g := normalize(grid)

	w := 0
	for w < len(g) && g[w] != '\n' {
		w++
	}
	// Count rows; their widths must all match (one pass).
	h, rowStart := 1, 0
	for i := w; i < len(g); i++ {
		if g[i] == '\n' {
			if i-rowStart != w {
				return Map{}, "ragged"
			}
			h++
			rowStart = i + 1
		}
	}
	if len(g)-rowStart != w {
		return Map{}, "ragged"
	}
	if w < MinW || w > MaxW || h < MinH || h > MaxH {
		return Map{}, "size"
	}
	switch objective {
	case "EXIT":
		m.Obj = ObjExit
	case "SLAY":
		m.Obj = ObjSlay
	default:
		return Map{}, "objective"
	}
	m.W = uint8(w)
	m.H = uint8(h)

	nmons := 0
	var cnt tileCounts
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			c := g[y*(w+1)+x]
			cl := glyphClass[c]
			if k := cl & cKind; k != 0 {
				if nmons < MaxMonsters {
					m.Mons[nmons] = Mon{Kind: k, X: int8(x), Y: int8(y), HP: hpForKind(k)}
				}
				nmons++
				m.Tiles[y*w+x] = TFloor
				continue
			}
			if cl&cTile == 0 {
				return Map{}, "glyph"
			}
			m.Tiles[y*w+x] = c
			if c == TFloor || c == TWall {
				continue
			}
			if c == TStart {
				m.StartX, m.StartY = int8(x), int8(y)
			}
			cnt.add(c, cl)
		}
	}
	if nmons > MaxMonsters {
		return Map{}, "monsters"
	}
	if len(props) != nmons {
		return Map{}, "props"
	}
	for i := 0; i < nmons; i++ {
		v := hexVal(props[i])
		if v < 0 {
			return Map{}, "props"
		}
		m.Mons[i].Facing = uint8(v>>2) & 3
		m.Mons[i].Phase = uint8(v) & 3
	}
	m.NMons = uint8(nmons)

	// The same checks as Validate, on the counts gathered above (no second pass).
	if reason := m.checkHeader(); reason != "" {
		return Map{}, reason
	}
	if reason := cnt.check(m.NMons); reason != "" {
		return Map{}, reason
	}
	m.HasChest = cnt.chests == 1
	return m, ""
}

// tileCounts tallies the special tiles Validate checks.
type tileCounts struct {
	starts, exits, chests, hazards, gates, plates int
}

// add counts tile c of glyph class cl; floor and wall need not be added.
func (n *tileCounts) add(c, cl uint8) {
	switch c {
	case TStart:
		n.starts++
	case TExit:
		n.exits++
	case TChest:
		n.chests++
	case TGate:
		n.gates++
	case TPlate:
		n.plates++
	}
	if cl&cHazard != 0 {
		n.hazards++
	}
}

// check applies the per-tile rules in Validate's order.
func (n *tileCounts) check(nmons uint8) string {
	switch {
	case n.starts != 1:
		return "start"
	case n.exits < 1:
		return "exit"
	case n.chests > 1:
		return "chest"
	case n.gates > MaxGates || n.plates > MaxPlates:
		return "gates"
	case nmons == 0 && n.hazards == 0:
		return "dull"
	}
	return ""
}

// checkHeader checks size, monster count and objective.
func (m *Map) checkHeader() string {
	w, h := int(m.W), int(m.H)
	switch {
	case w < MinW || w > MaxW || h < MinH || h > MaxH:
		return "size"
	case m.NMons > MaxMonsters:
		return "monsters"
	case m.Obj != ObjExit && m.Obj != ObjSlay:
		return "objective"
	}
	return ""
}

// Validate checks caps, exactly one start, at least one exit, at most one chest,
// at most MaxGates gates and MaxPlates plates ("gates"), at least one monster or
// hazard tile, and that every monster can be placed: in bounds on its own floor
// tile, of kind 1-4 with that kind's HP ("monsters"). It returns "" or a reason
// code.
func Validate(m *Map) string {
	if reason := m.checkHeader(); reason != "" {
		return reason
	}
	var cnt tileCounts
	for i := 0; i < int(m.W)*int(m.H); i++ {
		t := m.Tiles[i]
		cl := glyphClass[t]
		if cl&cTile == 0 {
			return "glyph"
		}
		if t != TFloor && t != TWall {
			cnt.add(t, cl)
		}
	}
	if reason := m.checkMons(); reason != "" {
		return reason
	}
	return cnt.check(m.NMons)
}

// checkMons rejects monsters NewGame cannot place. Parse only builds valid ones
// (each on the floor tile its glyph became), so only Validate runs it.
func (m *Map) checkMons() string {
	w, h := int(m.W), int(m.H)
	for i := 0; i < int(m.NMons); i++ {
		s := m.Mons[i]
		x, y := int(s.X), int(s.Y)
		if s.Kind < KSlime || s.Kind > KGargoyle || s.HP != hpForKind(s.Kind) ||
			x < 0 || y < 0 || x >= w || y >= h || m.Tiles[y*w+x] != TFloor {
			return "monsters"
		}
		for j := 0; j < i; j++ {
			if m.Mons[j].X == s.X && m.Mons[j].Y == s.Y {
				return "monsters"
			}
		}
	}
	return ""
}

func fnvByte(h uint32, b uint8) uint32 {
	h ^= uint32(b)
	return h * 16777619
}

// CanonHash is FNV-1a over W, H, tiles, monsters and objective.
func CanonHash(m *Map) uint32 {
	h := uint32(2166136261)
	h = fnvByte(h, m.W)
	h = fnvByte(h, m.H)
	for i := 0; i < int(m.W)*int(m.H); i++ {
		h = fnvByte(h, m.Tiles[i])
	}
	for i := 0; i < int(m.NMons); i++ {
		mon := m.Mons[i]
		h = fnvByte(h, mon.Kind)
		h = fnvByte(h, uint8(mon.X))
		h = fnvByte(h, uint8(mon.Y))
		h = fnvByte(h, mon.Facing)
		h = fnvByte(h, mon.Phase)
	}
	return fnvByte(h, m.Obj)
}

package sim

// Result is the verdict of replaying a log.
type Result struct {
	Cleared   bool
	Beats     uint16
	Damage    uint8
	Kills     uint8
	Chest     bool
	RouteHash uint32
	FailBeat  uint16
	Reason    string
}

// Run replays log (one char '0'..'8' per beat) on m. FailBeat is the number of
// beats elapsed when the run failed (the Beat counter after the failing step).
func Run(m *Map, relic uint8, log string) Result {
	return RunFrom(m, relic, 0, log)
}

// RunFrom is Run starting at hp (see NewGameFrom). HP left after a clear is
// hp - int8(Result.Damage).
func RunFrom(m *Map, relic uint8, hp int8, log string) Result {
	if len(log) == 0 {
		return Result{Reason: "empty"}
	}
	if len(log) > MaxBeats {
		return Result{Reason: "long"}
	}
	n := len(log)
	for i := 0; i < n; i++ {
		if c := log[i]; c < '0' || c > '8' {
			return Result{Reason: "char"}
		}
	}
	g := NewGameFrom(m, relic, hp)
	reason := "unfinished"
	for i := 0; i < n; i++ {
		g.Step(log[i] - '0')
		if g.Dead || g.Won {
			switch {
			case g.Dead:
				reason = "dead"
			case i == n-1:
				reason = "ok"
			default:
				reason = "trailing"
			}
			break
		}
	}
	r := Result{
		Beats:     g.Beat,
		Damage:    g.Damage,
		Kills:     g.Kills,
		Chest:     g.Chest,
		RouteHash: g.Route,
		Reason:    reason,
	}
	if reason == "ok" {
		r.Cleared = true
	} else {
		r.FailBeat = g.Beat
	}
	return r
}

package sim

func fnvBool(h uint32, b bool) uint32 {
	if b {
		return fnvByte(h, 1)
	}
	return fnvByte(h, 0)
}

// StateHash is FNV-1a 32 over the observable game state: Beat, hero position, HP,
// invulnerability and dash cooldown, gate state, Chest, Damage, Kills, every
// current tile (crumble marks, pits, picked-up chest), every live monster in index
// order, every live projectile in slot order, then Won and Dead. Both builds of
// the sim must produce the same value on every beat (the parity vectors check it).
func (g *Game) StateHash() uint32 {
	h := uint32(2166136261)
	h = fnvByte(h, uint8(g.Beat))
	h = fnvByte(h, uint8(g.Beat>>8))
	h = fnvByte(h, uint8(g.HX))
	h = fnvByte(h, uint8(g.HY))
	h = fnvByte(h, uint8(g.HP))
	h = fnvByte(h, g.Inv)
	h = fnvByte(h, g.DashCD)
	h = fnvBool(h, g.GatesUp)
	h = fnvByte(h, g.Stuck)
	h = fnvBool(h, g.Chest)
	h = fnvByte(h, g.Damage)
	h = fnvByte(h, g.Kills)
	for i, n := 0, int(g.M.W)*int(g.M.H); i < n; i++ {
		h = fnvByte(h, g.Tiles[i])
	}
	for i := 0; i < MaxMonsters; i++ {
		e := &g.Mons[i]
		if !e.Alive {
			continue
		}
		h = fnvByte(h, uint8(i))
		h = fnvByte(h, uint8(e.X))
		h = fnvByte(h, uint8(e.Y))
		h = fnvByte(h, uint8(e.HP))
		h = fnvByte(h, e.Wind)
		h = fnvBool(h, e.Aim)
		h = fnvByte(h, e.CD)
		h = fnvByte(h, e.Facing)
	}
	for i := 0; i < MaxProjs; i++ {
		p := &g.Projs[i]
		if !p.Alive {
			continue
		}
		h = fnvByte(h, uint8(p.X))
		h = fnvByte(h, uint8(p.Y))
		h = fnvByte(h, uint8(p.DX))
		h = fnvByte(h, uint8(p.DY))
		h = fnvBool(h, p.Fire)
	}
	h = fnvBool(h, g.Won)
	return fnvBool(h, g.Dead)
}

// Package commit is a small commit-reveal helper. A caller stores only the
// hash of a value in one transaction and reveals the value in a later block, so
// the value cannot be copied out of the mempool before it lands.
package commit

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
)

// Version prefixes every preimage so a hash from another scheme never collides.
const Version = "torchbeat/v1"

// Entry is a stored commitment: the hash and the block height it was made at.
type Entry struct {
	Hash   string
	Height int64
}

// Preimage returns "torchbeat/v1|owner|roomID|relic|log|salt" with relic in decimal.
func Preimage(owner, roomID string, relic int, log, salt string) string {
	return Version + "|" + owner + "|" + roomID + "|" + strconv.Itoa(relic) + "|" + log + "|" + salt
}

// Hash returns the lowercase hex sha256 of Preimage. It does not validate salt;
// callers that need a 32 lowercase hex salt must check it themselves.
func Hash(owner, roomID string, relic int, log, salt string) string {
	sum := sha256.Sum256([]byte(Preimage(owner, roomID, relic, log, salt)))
	return hex.EncodeToString(sum[:])
}

// CheckReveal reports whether a reveal at height may proceed against e. It
// returns "" when it may, else the first failing reason in this order:
// "none" (no commitment), "early" (height <= commit height, same block or
// earlier), "expired" (height > e.Height+maxAge), "mismatch" (got != e.Hash).
func CheckReveal(e Entry, height int64, maxAge int64, got string) string {
	switch {
	case e.Hash == "":
		return "none"
	case height <= e.Height:
		return "early"
	case height > e.Height+maxAge:
		return "expired"
	case got != e.Hash:
		return "mismatch"
	}
	return ""
}

package gen

// DescentMaxBeats is the longest log the descent realm replays for one floor.
// It bounds a reveal's gas: the costliest Layout+Parse plus this many beats of
// the costliest replay stays under the realm's budget (pinned by the descent
// realm's gas filetests). Every witness is at most 120 beats, so every proven
// floor stays clearable. Clients share it to end a floor run "out of time".
const DescentMaxBeats = 240

// ChestRelic is the relic a day's descent chest holds: 1 (Featherboots) on
// even days, 2 (Ironheart) on odd days. It draws nothing from the floor PRNG,
// so it never changes a floor.
func ChestRelic(day uint32) uint8 {
	if day%2 == 0 {
		return 1
	}
	return 2
}

// Package gen builds the Daily Descent: ten floors per UTC day, each made from
// (day, floor) alone, each with a witness route that proves it can be cleared.
//
// A floor is a chain of rooms on a small grid of cells (two to six cells, some
// merged into halls). The route runs room to room through one-tile doors; each
// room holds one pattern (a spike run, a dash gap, an archer gallery...) drawn
// in a canonical frame where the route enters from the west, then rotated and
// mirrored onto the room.
//
// Layout draws the floor without running the engine, cheaply enough for a
// realm to call on every reveal. Make adds the witness: the generator walks the
// plan the patterns left (waypoints, dashes, the beat to set off on) on the
// real engine, beat by beat, trying actions on a copy of the game and keeping
// the first that costs no HP. That walk costs a few times what replaying its
// log does, which is why the realm uses Layout and only clients and the range
// proof use Make.
package gen

import (
	"strconv"
	"strings"

	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/sim"
)

// Floors is the number of floors in a day's descent.
const Floors = 10

// Floor is one generated floor: what sim.Parse takes, plus the witness log that
// clears it with zero damage under every relic (Make only; Layout leaves it
// empty), the floor's main pattern and whether it holds the day's chest.
type Floor struct {
	Grid, Props, Objective, Witness string
	Pattern                         uint8
	HasChest                        bool
}

// DayOf returns the UTC day number of a unix time (seconds since 1970-01-01).
// Times before 1970 map to day 0.
func DayOf(unix int64) uint32 {
	if unix < 0 {
		return 0
	}
	return uint32(unix / 86400)
}

// RoomID names one floor of one attempt for the commit-reveal helper:
// prefix:day:n:attempt in decimal. The commit preimage separates its fields
// with '|', so a prefix holding one panics.
func RoomID(prefix string, day uint32, n uint8, attempt uint32) string {
	if strings.Contains(prefix, "|") {
		panic("gen: RoomID prefix contains |")
	}
	return prefix + ":" + strconv.FormatUint(uint64(day), 10) + ":" +
		strconv.FormatUint(uint64(n), 10) + ":" + strconv.FormatUint(uint64(attempt), 10)
}

// A layout whose main pattern fits no room is drawn again, up to maxTries
// times; then up to maxFallbacks fallback layouts (the main pattern at its
// lightest, minors only as the band's monster floor needs).
const (
	maxTries     = 6
	maxFallbacks = 10
	walkTrials   = 40000000 // trial beats Make's walk may play: bounds its run time
)

// Layout builds floor n (1..Floors) of the given day without its witness. It
// is what a realm calls: it never runs the engine. It panics outside
// 1..Floors.
func Layout(day uint32, n uint8) Floor {
	f, _ := layout(day, n)
	return f
}

// Make is Layout plus the witness. Witness is empty if the walk fails, which
// the range proof rules out for every day it covers.
func Make(day uint32, n uint8) Floor {
	f, b := layout(day, n)
	m := b.simMap()
	k := &walker{limit: walkTrials}
	if w, ok := k.walk(b, &m); ok {
		f.Witness = w
	}
	return f
}

// ChestWitness returns a log that opens the floor's chest and still clears
// the floor with zero damage under every relic, or "" when the floor has no
// chest or the walk finds no such route. The range proof uses it to show no
// chest strands the hero; it is not the floor's witness.
func ChestWitness(day uint32, n uint8) string {
	f, b := layout(day, n)
	if !f.HasChest {
		return ""
	}
	m := b.simMap()
	k := &walker{limit: walkTrials, chest: b.roomAt(b.chestOut) + 1}
	w, ok := k.walk(b, &m)
	if !ok || !k.cur().Chest {
		return ""
	}
	return w
}

// roomAt returns the room whose interior or entry door holds tile i (0 if
// none does).
func (b *builder) roomAt(i int) int {
	x, y := i%b.w, i/b.w
	for ri := 0; ri < b.nrooms; ri++ {
		r := &b.rooms[ri]
		if x >= r.x0 && y >= r.y0 && x < r.x0+r.aw && y < r.y0+r.ah || ri > 0 && r.in == i {
			return ri
		}
	}
	return 0
}

// layout draws layouts until one places its main pattern, and returns it with
// its builder (which holds the plan the walk follows).
func layout(day uint32, n uint8) (Floor, *builder) {
	if n < 1 || n > Floors {
		panic("gen: floor out of range")
	}
	pats, chest := dayPlan(day)
	r := newRng(day, n)
	var b *builder
	placed := false
	for try := 0; try < maxTries+maxFallbacks && !placed; try++ {
		b = &builder{}
		b.init(&r, n, pats[n-1], n == chest, try >= maxTries)
		placed = b.place()
	}
	if !placed {
		// Never seen in the proven range. Say so rather than name a main
		// pattern the floor does not hold: the range proof fails on it.
		b.pat = patPlain
	}
	obj := "EXIT"
	if b.slay {
		obj = "SLAY"
	}
	return Floor{
		Grid:      b.render(),
		Props:     b.props(),
		Objective: obj,
		Pattern:   b.pat,
		HasChest:  b.chest,
	}, b
}

// bandOf maps a floor to its band: 0 warmup (1-3), 1 combinations (4-7), 2 hard
// (8-9), 3 the SLAY finale (10).
func bandOf(n uint8) int {
	switch {
	case n <= 3:
		return 0
	case n <= 7:
		return 1
	case n <= 9:
		return 2
	}
	return 3
}

// numPairs is the number of unordered pattern pairs. A day leaves one pair out,
// so it plays NumPatterns-2 = Floors patterns, one per floor.
const numPairs = int(NumPatterns) * (int(NumPatterns) - 1) / 2

// dayPlan returns each floor's main pattern (index n-1) and the floor holding the
// chest. The left-out pair's index has the day's parity, so two consecutive days
// always leave out different pairs and play different pattern sets.
func dayPlan(day uint32) ([Floors]uint8, uint8) {
	r := newRng(day, 0)
	k := 2*r.intn(numPairs/2) + int(day%2)
	var used uint32
	for i := uint8(0); i < NumPatterns; i++ {
		for j := i + 1; j < NumPatterns; j++ {
			if k == 0 {
				used = uint32(1)<<i | uint32(1)<<j
			}
			k--
		}
	}
	var pats [Floors]uint8
	pats[Floors-1] = pickPattern(&r, &used, fSlay)
	for n := 0; n < 3; n++ {
		pats[n] = pickPattern(&r, &used, fWarm)
	}
	for n := 3; n < Floors-1; n++ {
		pats[n] = pickPattern(&r, &used, 0)
	}
	return pats, uint8(4 + r.intn(4))
}

// pickPattern draws an unused pattern carrying every bit of flag.
func pickPattern(r *rng, used *uint32, flag uint8) uint8 {
	var cand [NumPatterns]uint8
	nc := 0
	for p := uint8(0); p < NumPatterns; p++ {
		if *used&(uint32(1)<<p) == 0 && patFlags[p]&flag == flag {
			cand[nc] = p
			nc++
		}
	}
	p := cand[r.intn(nc)]
	*used |= uint32(1) << p
	return p
}

// bandCfg is a floor's cell grid: c x r cells with interiors cw x rh, and the
// walks the route may take through it. A walk starts in cell (0, 0) (before
// the floor is mirrored) and moves N/E/S/W; an upper-case move crosses a door,
// a lower-case move merges the next cell into the same room.
type bandCfg struct {
	c, r, wlo, whi, hlo, hhi int
	walks                    []string
}

var bands = [Floors]bandCfg{
	{2, 1, 5, 6, 5, 5, []string{"E"}},
	{3, 1, 4, 5, 5, 5, []string{"EE", "eE", "Ee"}},
	{2, 2, 5, 6, 3, 4, []string{"SE", "ES"}},
	{3, 2, 4, 5, 3, 4, []string{"EES", "ESE", "SEE", "SENE", "ESEN", "SEEN"}},
	{3, 2, 4, 5, 3, 4, []string{"EES", "ESE", "SEE", "SENE", "ESEN", "SEEN"}},
	{3, 2, 5, 5, 3, 4, []string{"SENE", "ESEN", "SEEN", "SENES", "eSE", "SEe"}},
	{3, 2, 5, 5, 3, 4, []string{"SENE", "ESEN", "SEEN", "SENES", "eSE", "SEe"}},
	{3, 2, 5, 6, 4, 5, []string{"SENES", "SENE", "ESEN", "SEEN", "eSEN"}},
	{3, 2, 5, 6, 4, 5, []string{"SENES", "SENE", "ESEN", "SEEN", "eSEN"}},
	{3, 2, 5, 6, 5, 6, []string{"SEe", "ESe", "EEs", "SENe"}},
}

// Sides and facings: 0 N, 1 E, 2 S, 3 W. A sim move action is side+1.
func sideVec(s int) (int, int) {
	switch s & 3 {
	case 0:
		return 0, -1
	case 1:
		return 1, 0
	case 2:
		return 0, 1
	}
	return -1, 0
}

func vecSide(dx, dy int) int {
	switch {
	case dy < 0:
		return 0
	case dx > 0:
		return 1
	case dy > 0:
		return 2
	}
	return 3
}

func sideOf(c byte) int {
	switch c {
	case 'N', 'n':
		return 0
	case 'E', 'e':
		return 1
	case 'S', 's':
		return 2
	}
	return 3
}

const (
	maxCells  = 6
	maxRooms  = 6
	maxSteps  = 8
	maxRoute  = 40
	tileFloor = byte('.')
	tileWall  = byte('#')
	tilePit   = byte('~')
	tileSpike = byte('^')
	tileCrum  = byte('%')
	tilePlate = byte('_')
	tileGate  = byte('|')
	tileChest = byte('C')
	tileStart = byte('@')
	tileExit  = byte('E')
)

// Plan step ops, run by the walker in order, room by room.
const (
	opGoto  uint8 = iota + 1 // walk to tile at
	opDash                   // dash toward side dir, landing on at
	opHunt                   // SLAY: kill every foe left
	opCross                  // dash over the trench toward side dir, from any tile of its near bank
)

type step struct {
	op  uint8
	at  int
	dir int
}

type mon struct {
	kind, facing, phase uint8
	at                  int
}

// builder holds one layout attempt.
type builder struct {
	r        *rng
	n        uint8
	lvl      int
	pat      uint8
	chest    bool
	fallback bool
	slay     bool

	w, h        int
	cols, rows  int
	cw, rh      [3]int
	xs, ys      [3]int
	tiles       [sim.MaxTiles]byte
	mons        [sim.MaxMonsters]mon
	nmons       int
	monCap      int
	gates       int
	start, exit int
	// The chest's tile and the tile outside its room's door (both the chest
	// tile when it sits in a room), for the chest route.
	chestAt, chestOut int
	chestBox          [4]int // the chest's side room and door: x0, y0, x1, y1

	cellC, cellR [maxCells]int
	cellRoom     [maxCells]int
	ncells       int
	used         [3][3]bool
	rooms        [maxRooms]room
	nrooms       int

	// The current room's route (canonical), and route marks: rmark[i] ==
	// stamp for its tiles.
	cur      *room
	rtx, rty [maxRoute]int
	rn       int
	rmark    [sim.MaxTiles]int
	stamp    int
}

func (b *builder) init(r *rng, n uint8, pat uint8, chest, fallback bool) {
	b.r, b.n, b.pat, b.chest, b.fallback = r, n, pat, chest, fallback
	b.lvl = bandOf(n)
	b.slay = n == Floors
	b.monCap = [4]int{3, 6, 7, 10}[b.lvl]
}

// place lays the floor out: cells, rooms, patterns and the chest. It reports
// false when the main pattern fits no room, or the floor would hold nothing
// the engine counts as a hazard or monster.
func (b *builder) place() bool {
	b.layout()
	if !b.placePatterns() {
		return false
	}
	// Patterns draw over whole rooms; the start stays the start.
	b.tiles[b.start] = tileStart
	if b.chest {
		b.placeChest()
	}
	if b.nmons > 0 {
		return true
	}
	for i := 0; i < b.w*b.h; i++ {
		switch b.tiles[i] {
		case tilePit, tileSpike, tileCrum, tilePlate, tileGate:
			return true
		}
	}
	return false
}

// layout sizes the cell grid, picks and mirrors a walk, carves the rooms and
// doors and places the start and the exit.
func (b *builder) layout() {
	cfg := &bands[b.n-1]
	b.cols, b.rows = cfg.c, cfg.r
	sumW, sumH := 0, 0
	for i := 0; i < b.cols; i++ {
		b.cw[i] = b.r.span(cfg.wlo, cfg.whi)
		sumW += b.cw[i]
	}
	for i := 0; i < b.rows; i++ {
		b.rh[i] = b.r.span(cfg.hlo, cfg.hhi)
		sumH += b.rh[i]
	}
	// Trim to the engine's 20 x 14.
	for sumW+b.cols+1 > sim.MaxW {
		i := b.r.intn(b.cols)
		if b.cw[i] > cfg.wlo {
			b.cw[i]--
			sumW--
		}
	}
	for sumH+b.rows+1 > sim.MaxH {
		i := b.r.intn(b.rows)
		if b.rh[i] > cfg.hlo {
			b.rh[i]--
			sumH--
		}
	}
	b.w, b.h = sumW+b.cols+1, sumH+b.rows+1
	b.xs[0], b.ys[0] = 1, 1
	for i := 1; i < b.cols; i++ {
		b.xs[i] = b.xs[i-1] + b.cw[i-1] + 1
	}
	for i := 1; i < b.rows; i++ {
		b.ys[i] = b.ys[i-1] + b.rh[i-1] + 1
	}
	for i := 0; i < b.w*b.h; i++ {
		b.tiles[i] = tileWall
	}

	walk := b.pickWalk(cfg)
	mx, my := b.r.coin(), b.rows > 1 && b.r.coin()
	c, rr := 0, 0
	if mx {
		c = b.cols - 1
	}
	if my {
		rr = b.rows - 1
	}
	var moves [maxCells]int
	var doors [maxCells]bool
	b.ncells = 0
	b.addCell(c, rr, 0)
	for i := 0; i < len(walk); i++ {
		s := sideOf(walk[i])
		if (s == 1 || s == 3) && mx || (s == 0 || s == 2) && my {
			s ^= 2
		}
		dx, dy := sideVec(s)
		c, rr = c+dx, rr+dy
		room := b.cellRoom[b.ncells-1]
		upper := walk[i] < 'a'
		if upper {
			room++
		}
		moves[b.ncells] = s
		doors[b.ncells] = upper
		b.addCell(c, rr, room)
	}
	b.nrooms = b.cellRoom[b.ncells-1] + 1

	// Room rectangles: the union of their cells, walls between merged cells
	// included.
	for k := 0; k < b.nrooms; k++ {
		rm := &b.rooms[k]
		x0, y0, x1, y1 := 99, 99, -1, -1
		for i := 0; i < b.ncells; i++ {
			if b.cellRoom[i] != k {
				continue
			}
			cx0, cy0 := b.xs[b.cellC[i]], b.ys[b.cellR[i]]
			cx1, cy1 := cx0+b.cw[b.cellC[i]]-1, cy0+b.rh[b.cellR[i]]-1
			if cx0 < x0 {
				x0 = cx0
			}
			if cy0 < y0 {
				y0 = cy0
			}
			if cx1 > x1 {
				x1 = cx1
			}
			if cy1 > y1 {
				y1 = cy1
			}
		}
		rm.x0, rm.y0, rm.aw, rm.ah = x0, y0, x1-x0+1, y1-y0+1
		for y := y0; y <= y1; y++ {
			for x := x0; x <= x1; x++ {
				b.tiles[y*b.w+x] = tileFloor
			}
		}
	}

	// Doors, the start and the exit. Room k is entered on side in and left on
	// side out; in/out hold the wall tile on that side (a door, the wall behind
	// the start, or the exit).
	var sIn, sOut [maxRooms]int
	var tIn, tOut [maxRooms]int
	first := (moves[1] + 2) & 3
	sIn[0], tIn[0] = first, b.wallTile(0, first)
	for i := 1; i < b.ncells; i++ {
		if !doors[i] {
			continue
		}
		k := b.cellRoom[i]
		t := b.wallTile(i-1, moves[i])
		b.tiles[t] = tileFloor
		sOut[k-1], tOut[k-1] = moves[i], t
		sIn[k], tIn[k] = (moves[i]+2)&3, t
	}
	lastCell := b.ncells - 1
	last := b.nrooms - 1
	exitSide := moves[lastCell]
	if !b.onBorder(lastCell, exitSide) {
		for s := 0; s < 4; s++ {
			if s != sIn[last] && b.onBorder(lastCell, s) {
				exitSide = s
				break
			}
		}
	}
	sOut[last], tOut[last] = exitSide, b.wallTile(lastCell, exitSide)
	b.exit = tOut[last]
	b.tiles[b.exit] = tileExit
	dx, dy := sideVec(first)
	b.start = tIn[0] - dx - dy*b.w
	b.tiles[b.start] = tileStart

	for k := 0; k < b.nrooms; k++ {
		b.rooms[k].orient(b, sIn[k], sOut[k], tIn[k], tOut[k], b.r.coin())
	}
}

// pickWalk draws a walk; the chest floor needs one that leaves a cell spare.
func (b *builder) pickWalk(cfg *bandCfg) string {
	for {
		w := cfg.walks[b.r.intn(len(cfg.walks))]
		if !b.chest || len(w)+1 < cfg.c*cfg.r {
			return w
		}
	}
}

func (b *builder) addCell(c, r, room int) {
	b.cellC[b.ncells], b.cellR[b.ncells] = c, r
	b.cellRoom[b.ncells] = room
	b.used[c][r] = true
	b.ncells++
}

func (b *builder) onBorder(cell, side int) bool {
	c, r := b.cellC[cell], b.cellR[cell]
	switch side {
	case 0:
		return r == 0
	case 1:
		return c == b.cols-1
	case 2:
		return r == b.rows-1
	}
	return c == 0
}

// wallTile picks a tile of the wall on side s of cell i, at a random offset along
// the cell.
func (b *builder) wallTile(cell, s int) int {
	return b.wallTileAt(b.cellC[cell], b.cellR[cell], s, -1)
}

// wallTileAt is wallTile for cell (c, r); off < 0 draws the offset.
func (b *builder) wallTileAt(c, r, s, off int) int {
	x0, y0, cw, ch := b.xs[c], b.ys[r], b.cw[c], b.rh[r]
	if off < 0 {
		if s == 0 || s == 2 {
			off = b.r.intn(cw)
		} else {
			off = b.r.intn(ch)
		}
	}
	switch s {
	case 0:
		return (y0-1)*b.w + x0 + off
	case 1:
		return (y0+off)*b.w + x0 + cw
	case 2:
		return (y0+ch)*b.w + x0 + off
	}
	return (y0+off)*b.w + x0 - 1
}

// monHP is each monster kind's spawn HP, as sim.Parse gives it.
var monHP = [5]int8{0, 1, 1, 2, 0}

// simMap builds the map sim.Parse makes of the floor's grid, props and
// objective, without rendering and parsing it. TestSimMapMatchesParse checks
// it against Parse.
func (b *builder) simMap() sim.Map {
	var m sim.Map
	m.W, m.H = uint8(b.w), uint8(b.h)
	n := b.w * b.h
	for i := 0; i < n; i++ {
		m.Tiles[i] = b.tiles[i]
	}
	m.StartX, m.StartY = int8(b.start%b.w), int8(b.start/b.w)
	for i := 0; i < b.nmons; i++ {
		e := b.mons[i]
		m.Mons[i] = sim.Mon{Kind: e.kind, X: int8(e.at % b.w), Y: int8(e.at / b.w),
			HP: monHP[e.kind], Facing: e.facing, Phase: e.phase}
	}
	m.NMons = uint8(b.nmons)
	if b.slay {
		m.Obj = sim.ObjSlay
	}
	m.HasChest = b.chest
	return m
}

// render draws the grid with monsters and the start.
func (b *builder) render() string {
	out := make([]byte, 0, b.h*(b.w+1))
	mi := 0
	for y := 0; y < b.h; y++ {
		if y > 0 {
			out = append(out, '\n')
		}
		for x := 0; x < b.w; x++ {
			i := y*b.w + x
			c := b.tiles[i]
			if mi < b.nmons && b.mons[mi].at == i {
				c = " sabg"[b.mons[mi].kind]
				mi++
			}
			out = append(out, c)
		}
	}
	return string(out)
}

// props returns one hex digit per monster in row-major order: facing<<2 | phase.
// Monsters are kept sorted by tile, which is Parse's spawn order.
func (b *builder) props() string {
	out := make([]byte, b.nmons)
	for i := 0; i < b.nmons; i++ {
		out[i] = "0123456789abcdef"[b.mons[i].facing<<2|b.mons[i].phase&3]
	}
	return string(out)
}

// startClear is how far from the start a slime or brute must begin.
const startClear = 6

// addMon places a monster on floor tile i unless the floor's monster budget is
// spent, the tile is taken or it is too near the start. Monsters stay sorted
// by tile.
func (b *builder) addMon(kind uint8, i int, facing, phase uint8) bool {
	if b.nmons >= b.monCap || b.tiles[i] != tileFloor || b.monAt(i) {
		return false
	}
	// No monster starts within two tiles (Chebyshev) of the start, and nothing
	// that chases within startClear steps of it.
	dx, dy := abs(i%b.w-b.start%b.w), abs(i/b.w-b.start/b.w)
	if dx <= 2 && dy <= 2 || (kind == sim.KSlime || kind == sim.KBrute) && dx+dy < startClear {
		return false
	}
	j := b.nmons
	for j > 0 && b.mons[j-1].at > i {
		b.mons[j] = b.mons[j-1]
		j--
	}
	b.mons[j] = mon{kind: kind, facing: facing & 3, phase: phase & 3, at: i}
	b.nmons++
	return true
}

func (b *builder) monAt(i int) bool {
	for j := 0; j < b.nmons; j++ {
		if b.mons[j].at == i {
			return true
		}
	}
	return false
}

// placeChest opens a spare cell next to the route as a side room with the
// chest in its far corner, behind one spike tile in the doorway. Every spare
// cell and side is tried, from a random start, for a door whose outer tile is
// plain floor with another open, non-crumble tile beside it: the way in must
// still be there on the way out (a crumble there falls once crossed). If no
// spare cell can take such a door, the chest goes on a free floor tile of a
// room with the most walls around it; if there is none, the floor holds no
// chest and says so.
func (b *builder) placeChest() {
	n := b.cols * b.rows * 4
	o0 := b.r.intn(n)
	for o := 0; o < n; o++ {
		v := (o0 + o) % n
		c, r, s := v/4%b.cols, v/4/b.cols, v%4
		if b.used[c][r] {
			continue
		}
		dx, dy := sideVec(s)
		nc, nr := c+dx, r+dy
		if nc < 0 || nr < 0 || nc >= b.cols || nr >= b.rows || !b.used[nc][nr] {
			continue
		}
		span := b.rh[r]
		if s == 0 || s == 2 {
			span = b.cw[c]
		}
		off0 := b.r.intn(span)
		for k := 0; k < span; k++ {
			door := b.wallTileAt(c, r, s, (off0+k)%span)
			out := door + dx + dy*b.w
			if b.tiles[out] != tileFloor || b.monAt(out) || !b.firmNeighbor(out, door) {
				continue
			}
			best, bd := -1, -1
			for y := b.ys[r]; y < b.ys[r]+b.rh[r]; y++ {
				for x := b.xs[c]; x < b.xs[c]+b.cw[c]; x++ {
					b.tiles[y*b.w+x] = tileFloor
					d := abs(x-door%b.w) + abs(y-door/b.w)
					if d > bd {
						best, bd = y*b.w+x, d
					}
				}
			}
			b.tiles[door] = tileSpike
			b.tiles[best] = tileChest
			b.chestAt, b.chestOut = best, out
			// The side room and its door, for the chest route's search.
			b.chestBox = [4]int{b.xs[c], b.ys[r], b.xs[c] + b.cw[c] - 1, b.ys[r] + b.rh[r] - 1}
			if dx < 0 || dy < 0 {
				b.chestBox[0], b.chestBox[1] = door%b.w, door/b.w
				if dy < 0 {
					b.chestBox[0] = b.xs[c]
				} else {
					b.chestBox[1] = b.ys[r]
				}
			} else {
				b.chestBox[2], b.chestBox[3] = door%b.w, door/b.w
				if dy > 0 {
					b.chestBox[2] = b.xs[c] + b.cw[c] - 1
				} else {
					b.chestBox[3] = b.ys[r] + b.rh[r] - 1
				}
			}
			return
		}
	}
	best, bw := -1, -1
	for i := b.w; i < b.w*(b.h-1); i++ {
		if b.tiles[i] != tileFloor || b.monAt(i) || i == b.start {
			continue
		}
		walls := 0
		for s := 0; s < 4; s++ {
			dx, dy := sideVec(s)
			if b.tiles[i+dx+dy*b.w] == tileWall {
				walls++
			}
		}
		if walls > bw && walls < 3 {
			best, bw = i, walls
		}
	}
	if best < 0 {
		b.chest = false
		return
	}
	b.tiles[best] = tileChest
	b.chestAt, b.chestOut = best, best
	b.chestBox = [4]int{best % b.w, best / b.w, best % b.w, best / b.w}
}

// firmNeighbor reports whether tile i has an open tile beside it, other than
// tile from, that is not a pit, wall or crumble.
func (b *builder) firmNeighbor(i, from int) bool {
	for s := 0; s < 4; s++ {
		dx, dy := sideVec(s)
		j := i + dx + dy*b.w
		if j == from || j < 0 || j >= b.w*b.h {
			continue
		}
		switch b.tiles[j] {
		case tileWall, tilePit, tileCrum, tileGate:
		default:
			return true
		}
	}
	return false
}

func abs(v int) int {
	if v < 0 {
		return -v
	}
	return v
}

package gen

import "gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/sim"

// Patterns. Each is drawn into one room in its canonical frame (entered from
// the west at A = (0, ay), left at B) and adds the plan steps the walk follows
// there. A pattern returns false when the room cannot hold it, leaving the room
// plain floor with no monsters or steps added. lv is 0 (light), 1 or 2 (full).
// The order of this list is part of the generator: reordering it changes every
// floor.
const (
	PatSpikes    uint8 = iota // spike run: spikes timed to the 4-beat wave
	PatGap                    // dash gap: a pit trench crossed with a dash
	PatCrumble                // crumble bridge over a chasm, a gargoyle across it
	PatGate                   // plate and gate: dash from the plate through the door before it shuts
	PatArchers                // archer gallery: aim lines across the room
	PatSlimes                 // slime pen: slimes close in, keep moving
	PatBrute                  // brute choke: brutes pace the far bank of a trench
	PatGargoyle               // gargoyle lanes: fireballs across the route
	PatFireRun                // fire run: a gargoyle fires down the corridor behind you
	PatShove                  // shove pit: slimes on a ledge path over a chasm
	PatChase                  // crumble chase: slimes follow you across a crumbling floor
	PatCrossfire              // crossfire: two archers face each other across your path
	NumPatterns

	patPlain uint8 = 255 // an empty room (minor rooms only)
)

var patNames = [NumPatterns]string{
	"spike run", "dash gap", "crumble bridge", "plate and gate", "archer gallery", "slime pen",
	"brute choke", "gargoyle lanes", "fire run", "shove pit", "crumble chase", "crossfire",
}

// PatternName returns a pattern's display name.
func PatternName(p uint8) string {
	if p >= NumPatterns {
		return "plain"
	}
	return patNames[p]
}

// Pattern flags: fWarm fits floors 1-3, fSlay holds foes for the SLAY finale.
const (
	fWarm uint8 = 1
	fSlay uint8 = 2
)

var patFlags = [NumPatterns]uint8{
	PatSpikes:    fWarm | fSlay, // the arena: stepping stones among spikes, slimes closing in
	PatGap:       fWarm,
	PatCrumble:   fWarm,
	PatGate:      fWarm,
	PatArchers:   fWarm | fSlay,
	PatSlimes:    fWarm | fSlay,
	PatBrute:     0,
	PatGargoyle:  fWarm | fSlay, // the arena's foes are its slimes; gargoyles never count for SLAY
	PatFireRun:   0,
	PatShove:     fWarm | fSlay,
	PatChase:     0, // a collapsing trail can strand a slime, so never a SLAY arena
	PatCrossfire: fSlay,
}

// Minor rooms per band: bit p set means pattern p may fill a room that is not
// the main one. The finale keeps its foes in the arena, so its minors hold
// none.
var minorPool = [4]uint32{
	uint32(1)<<PatSpikes | uint32(1)<<PatGap | uint32(1)<<PatCrumble | uint32(1)<<PatGargoyle,
	uint32(1)<<PatSpikes | uint32(1)<<PatGap | uint32(1)<<PatCrumble | uint32(1)<<PatGate | uint32(1)<<PatArchers | uint32(1)<<PatSlimes |
		uint32(1)<<PatGargoyle | uint32(1)<<PatFireRun | uint32(1)<<PatShove | uint32(1)<<PatChase | uint32(1)<<PatCrossfire,
	uint32(1)<<NumPatterns - 1,
	uint32(1)<<PatSpikes | uint32(1)<<PatGap | uint32(1)<<PatCrumble | uint32(1)<<PatGate | uint32(1)<<PatGargoyle | uint32(1)<<PatFireRun,
}

// finaleFoes is the fewest foes the SLAY arena holds; slimes make up the
// difference after its pattern.
const finaleFoes = 5

func (b *builder) foes() int {
	n := 0
	for i := 0; i < b.nmons; i++ {
		if b.mons[i].kind != sim.KGargoyle {
			n++
		}
	}
	return n
}

// inArcherLine reports whether an archer has a clear line to tile i.
func (b *builder) inArcherLine(i int) bool {
	for j := 0; j < b.nmons; j++ {
		if b.mons[j].kind == sim.KArcher && b.line(b.mons[j].at, i) {
			return true
		}
	}
	return false
}

// chaserPool holds the patterns with slimes or brutes, which chase the hero.
const chaserPool uint32 = uint32(1)<<PatSlimes | uint32(1)<<PatBrute | uint32(1)<<PatShove |
	uint32(1)<<PatChase | uint32(1)<<PatCrossfire

// minMons is the fewest monsters a floor of each band should hold.
var minMons = [4]int{0, 1, 3, 3}

// monsterPool holds the patterns that always place a monster.
const monsterPool uint32 = uint32(1)<<PatArchers | uint32(1)<<PatSlimes | uint32(1)<<PatBrute | uint32(1)<<PatGargoyle |
	uint32(1)<<PatFireRun | uint32(1)<<PatShove | uint32(1)<<PatChase | uint32(1)<<PatCrossfire

// placePatterns puts the main pattern in the first room that holds it (the
// arena, the last room, on the finale; otherwise the largest rooms first) and
// fills the other rooms with minors. It reports false when no room holds the
// main pattern.
func (b *builder) placePatterns() bool {
	lv := b.lvl
	if lv > 2 {
		lv = 2
	}
	if b.fallback {
		lv = 0
	}
	var order [maxRooms]int
	no := 0
	if b.slay {
		order[0] = b.nrooms - 1
		no = 1
	} else {
		for k := 0; k < b.nrooms; k++ {
			order[no] = k
			no++
		}
		// Largest first, ties in random order.
		for i := no - 1; i > 0; i-- {
			j := b.r.intn(i + 1)
			order[i], order[j] = order[j], order[i]
		}
		for i := 1; i < no; i++ {
			for j := i; j > 0 && b.area(order[j]) > b.area(order[j-1]); j-- {
				order[j], order[j-1] = order[j-1], order[j]
			}
		}
	}
	b.rooms[b.nrooms-1].last = true
	b.rooms[0].cp = b.start
	main := -1
	for i := 0; i < no && main < 0; i++ {
		if b.runPattern(&b.rooms[order[i]], b.pat, lv) {
			main = order[i]
		}
	}
	if main < 0 {
		return false
	}
	if b.slay {
		// The exit opens once every foe is dead: walk the pattern's route,
		// then hunt down what is left, then take the exit.
		r := &b.rooms[main]
		b.cur = r
		// The hunt starts where the pattern's route ends, short of its walk to
		// the exit: crossing the arena first only to come back for the foes
		// wastes beats.
		if l := &r.steps[r.ns-1]; l.op == opGoto && l.at == r.out {
			r.ns--
		}
		// Every arena tile, from a random one on, until the arena has its foes.
		n := r.w * r.h
		o := b.r.intn(n)
		for k := 0; k < n && b.foes() < finaleFoes; k++ {
			x, y := (o+k)%n%r.w, (o+k)%n/r.w
			i := r.at(b, x, y)
			if r.fromA(x, y) < 4 || b.inArcherLine(i) {
				continue
			}
			// A spike arena has little plain floor: a slime may start on a
			// spike tile off the route, which becomes floor under it.
			spiked := b.tiles[i] == tileSpike && !b.onRoute(x, y)
			if spiked {
				b.tiles[i] = tileFloor
			}
			if !b.monL(r, sim.KSlime, x, y, 3, uint8(b.r.intn(4))) && spiked {
				b.tiles[i] = tileSpike
			}
		}
		r.addStep(opHunt, 0, 0)
		b.gotoOut(r)
	}
	mlv := b.lvl - 1
	if mlv < 0 {
		mlv = 0
	}
	if mlv > 1 {
		mlv = 1
	}
	pool := minorPool[b.lvl] &^ (uint32(1) << b.pat)
	// Floor 1 is one pattern, or two half the time (its layouts are few, and
	// a second pattern keeps them from repeating).
	if b.n == 1 && b.r.coin() {
		pool = 0
	}
	if b.fallback {
		// Plain rooms, except what the band's monster floor needs.
		pool &= monsterPool
		mlv = 0
	}
	for k := 0; k < b.nrooms; k++ {
		if k == main {
			continue
		}
		r := &b.rooms[k]
		placed := false
		// The finale's arena door: the room before the arena ends in a plate
		// and gate with a pit before it, so the arena's foes cannot come out;
		// the hero dashes in from the plate.
		if b.slay && k == main-1 {
			if !b.runPattern(r, PatGate, 1) {
				return false
			}
			continue
		}
		// Below the band's monster floor, minors must bring monsters.
		use := pool
		// Chasers in two rooms side by side on the route pile up on the hero.
		if k > 0 && chaserPool&(uint32(1)<<b.rooms[k-1].pat) != 0 ||
			k+1 < b.nrooms && chaserPool&(uint32(1)<<b.rooms[k+1].pat) != 0 {
			use &^= chaserPool
		}
		if b.nmons < minMons[b.lvl] {
			use = pool & monsterPool
		} else if b.fallback {
			use = 0
		}
		if !placed && use != 0 && !(b.lvl == 1 && use == pool && b.r.intn(6) == 0) {
			var cand [NumPatterns]uint8
			nc := 0
			for p := uint8(0); p < NumPatterns; p++ {
				if use&(uint32(1)<<p) != 0 {
					cand[nc] = p
					nc++
				}
			}
			for nc > 0 && !placed {
				j := b.r.intn(nc)
				if b.runPattern(r, cand[j], mlv) {
					placed = true
				}
				nc--
				cand[j] = cand[nc]
			}
		}
		if !placed {
			b.runPattern(r, patPlain, 0)
		}
	}
	return true
}

func (b *builder) area(k int) int {
	return b.rooms[k].aw * b.rooms[k].ah
}

func (b *builder) runPattern(r *room, p uint8, lv int) bool {
	// Nothing chases the hero from the start: the first room holds no slimes
	// or brutes.
	if r.cp == b.start && p < NumPatterns && chaserPool&(uint32(1)<<p) != 0 {
		return false
	}
	b.cur = r
	ok := true
	switch p {
	case PatSpikes:
		ok = b.patSpikes(r, lv)
	case PatGap:
		ok = b.patGap(r, lv)
	case PatCrumble:
		ok = b.patCrumble(r, lv)
	case PatGate:
		ok = b.patGate(r, lv)
	case PatArchers:
		ok = b.patArchers(r, lv)
	case PatSlimes:
		ok = b.patSlimes(r, lv)
	case PatBrute:
		ok = b.patBrute(r, lv)
	case PatGargoyle:
		ok = b.patGargoyle(r, lv)
	case PatFireRun:
		ok = b.patFireRun(r, lv)
	case PatShove:
		ok = b.patShove(r, lv)
	case PatChase:
		ok = b.patChase(r, lv)
	case PatCrossfire:
		ok = b.patCrossfire(r, lv)
	default:
		b.gotoOut(r)
	}
	if ok {
		r.pat = p
	}
	return ok
}

// spare reports how many more monsters the floor's budget allows.
func (b *builder) spare() int {
	return b.monCap - b.nmons
}

// patSpikes: spikes timed to the 4-beat wave. Spikes are up when
// (beat + x + y) % 4 >= 2. A step west or north lowers x + y as the beat
// rises, so it keeps pace with the wave: a run of spikes walked that way is
// down all along once it is down underfoot. A step east or south does not, so
// two spikes walked that way in a row can never both be down. The route's
// spikes follow that rule, and every stretch of them starts from a floor tile
// where the walk can stand and wait for the wave; whatever beat the walk
// arrives on, it can cross. Light: a one-wide corridor. Full: the rest of the
// room is spikes too.
func (b *builder) patSpikes(r *room, lv int) bool {
	if r.w*r.h < 6 {
		return false
	}
	b.wroute(r)
	if lv == 0 {
		b.fill(r, tileWall)
		for i := 0; i < b.rn; i++ {
			b.put(r, b.rtx[i], b.rty[i], tileFloor)
		}
	} else {
		for y := 0; y < r.h; y++ {
			for x := 0; x < r.w; x++ {
				if !b.onRoute(x, y) {
					b.put(r, x, y, tileSpike)
				}
			}
		}
	}
	prev := false // tile i-1 is spikes
	stones := b.r.intn(2)
	for i := 1; i < b.rn; i++ {
		j := r.at(b, b.rtx[i], b.rty[i])
		d := j - r.at(b, b.rtx[i-1], b.rty[i-1])
		withWave := d == -1 || d == -b.w
		spike := !prev || withWave
		if spike && !withWave {
			// Across the wave: every other tile, from a random first one.
			spike = (i+stones)%2 == 0
		}
		if spike {
			b.tiles[j] = tileSpike
		}
		prev = spike
	}
	b.cornerSteps(r)
	b.gotoOut(r)
	return true
}

// timeRoute lays spikes on the current route's tiles from index from on: those
// the walk is on while they are down, if it sets off from r's checkpoint on a
// beat that is q mod 4 and reaches route tile i i beats later (i-1 from the
// start, which is A itself), for the q among those in mask (bit c: q == c)
// that lays the most.
func (b *builder) timeRoute(r *room, from, mask int) {
	off := 0
	if r.cp == b.start {
		off = -1
	}
	q, best := 0, -1
	for c := 0; c < 4; c++ {
		if mask&(1<<uint(c)) == 0 {
			continue
		}
		n := 0
		for i := from; i < b.rn; i++ {
			j := r.at(b, b.rtx[i], b.rty[i])
			if (c+i+off+j%b.w+j/b.w)%4 < 2 {
				n++
			}
		}
		if n > best {
			best, q = n, c
		}
	}
	for i := from; i < b.rn; i++ {
		j := r.at(b, b.rtx[i], b.rty[i])
		if (q+i+off+j%b.w+j/b.w)%4 < 2 {
			b.tiles[j] = tileSpike
		}
	}
}

// cornerSteps adds a goto to every bend of the current route, so the walk
// follows it exactly (in a spike field the straight runs between bends are the
// only shortest paths).
func (b *builder) cornerSteps(r *room) {
	for i := 1; i+1 < b.rn; i++ {
		dx0, dy0 := b.rtx[i]-b.rtx[i-1], b.rty[i]-b.rty[i-1]
		dx1, dy1 := b.rtx[i+1]-b.rtx[i], b.rty[i+1]-b.rty[i]
		// Leave room for the exit goto and the finale's hunt and goto.
		if (dx0 != dx1 || dy0 != dy1) && r.ns < maxSteps-3 {
			b.gotoL(r, b.rtx[i], b.rty[i])
		}
	}
}

// patGap: a trench of pits across the room, crossed with a dash. Full: the
// trench is two wide except at two rows, where the dash must cross. Monsters
// cannot cross pits, so anything chasing stays behind.
func (b *builder) patGap(r *room, lv int) bool {
	endx := r.w - 1
	if r.turn {
		endx = r.bx
	}
	if endx < 2 {
		return false
	}
	gx := 1 + b.r.intn(endx-1)
	wide := lv >= 1 && gx+2 <= endx && r.h >= 3
	cr := b.r.intn(r.h)
	// The wide trench narrows at two rows, so one monster on the far bank
	// cannot hold the only landing.
	cr2 := (cr + 1 + b.r.intn(r.h-1)) % r.h
	for y := 0; y < r.h; y++ {
		b.put(r, gx, y, tilePit)
		if wide && y != cr && y != cr2 {
			b.put(r, gx+1, y, tilePit)
		}
	}
	b.gotoL(r, gx-1, cr)
	r.addStep(opCross, r.out, r.face(1))
	b.gotoOut(r)
	return true
}

// patCrumble: a chasm with a crumble bridge along the route; each tile falls
// the beat after you leave it. Full: a gargoyle at the chasm's edge fires
// across the bridge.
func (b *builder) patCrumble(r *room, lv int) bool {
	if r.w < 3 || r.w*r.h < 8 {
		return false
	}
	b.wroute(r)
	b.fill(r, tilePit)
	for i := 0; i < b.rn; i++ {
		b.put(r, b.rtx[i], b.rty[i], tileCrum)
	}
	b.put(r, 0, r.ay, tileFloor)
	b.put(r, b.rtx[b.rn-1], b.rty[b.rn-1], tileFloor)
	if lv >= 1 {
		n := 1
		if lv >= 2 && b.r.coin() {
			n = 2
		}
		b.laneGargoyles(r, n, true)
	}
	b.gotoOut(r)
	return true
}

// patGate: the exit door is a gate, opened while a plate is held. The plate is
// two tiles before the door: stand on it, then dash, landing on the gate before
// it shuts (walking off the plate shuts it at once). Full: the tile between is
// a pit.
func (b *builder) patGate(r *room, lv int) bool {
	if b.gates > 0 || r.last {
		return false
	}
	var px, py, qx, qy, side int
	if r.turn {
		// The plate and the tile beyond it must not be A, the way in.
		if r.h < 3 || r.bx == 0 && r.ay <= 1 {
			return false
		}
		px, py, qx, qy, side = r.bx, 1, r.bx, 0, 0
	} else {
		if r.w < 3 {
			return false
		}
		px, py, qx, qy, side = r.w-2, r.by, r.w-1, r.by, 1
	}
	b.put(r, px, py, tilePlate)
	if lv >= 1 {
		b.put(r, qx, qy, tilePit)
	}
	b.tiles[r.out] = tileGate
	b.gates++
	b.gotoL(r, px, py)
	b.dashL(r, side, qx+(qx-px), qy+(qy-py))
	return true
}

// patArchers: archers whose rows and columns cross the route; never stand in
// a line. Full: pillars break some lines and give cover.
func (b *builder) patArchers(r *room, lv int) bool {
	if r.w < 3 || r.h < 3 || b.spare() < 1 {
		return false
	}
	b.zroute(r, b.r.intn(r.w))
	if lv >= 1 {
		b.pillars(r, lv)
	}
	n := 1 + lv
	if b.slay {
		n++
	}
	// Every tile, from a random one on, until the gallery has its archers.
	placed, cells := 0, r.w*r.h
	o := b.r.intn(cells)
	for k := 0; k < cells && placed < n; k++ {
		x, y := (o+k)%cells%r.w, (o+k)%cells/r.w
		i := r.at(b, x, y)
		if y == r.ay || r.fromA(x, y) < 2 || b.onRoute(x, y) || !b.seesRoute(i) ||
			b.line(i, r.cp) || b.line(i, r.out) || b.nearArcher(i) {
			continue
		}
		if b.monL(r, sim.KArcher, x, y, 3, 0) {
			placed++
		}
	}
	if placed == 0 {
		b.unplace(r)
		return false
	}
	b.gotoOut(r)
	return true
}

// patSlimes: slimes that close in from the far side. A slime only strikes a
// hero who stands still next to it, so keep moving and bump the ones in the
// way. Full: holes in the floor to shove them into.
func (b *builder) patSlimes(r *room, lv int) bool {
	if r.w*r.h < 9 || b.spare() < 1 {
		return false
	}
	b.zroute(r, b.r.intn(r.w))
	if lv >= 1 {
		for k := 0; k < lv+1; k++ {
			x, y := b.r.intn(r.w), b.r.intn(r.h)
			if !b.nearRoute(x, y) && r.fromA(x, y) >= 2 {
				b.put(r, x, y, tilePit)
			}
		}
	}
	n := 2 + lv
	if b.slay {
		n += 2
	}
	if b.lvl == 0 {
		n = 2
	}
	placed := 0
	for k := 0; k < n; k++ {
		if b.farMon(r, sim.KSlime, 3) {
			placed++
		}
	}
	if placed == 0 {
		b.unplace(r)
		return false
	}
	b.gotoOut(r)
	return true
}

// patBrute: a trench splits the room and a brute paces the far bank. It
// cannot cross pits, so it keeps opposite the hero; walk along the near bank to
// draw it off the landing, then dash across and keep moving while it winds up
// (two beats) before its blow. Full: a second brute on the far bank (not in
// the finale's arena).
func (b *builder) patBrute(r *room, lv int) bool {
	gx, ok := b.trench(r, 2)
	if !ok || r.h < 3 || b.spare() < 1 {
		return false
	}
	// The brute starts on the far bank, away from the entry row.
	by := r.h - 1
	if r.ay >= r.h/2 {
		by = 0
	}
	if !b.monL(r, sim.KBrute, gx+1, by, 3, uint8(b.r.intn(2))) {
		return false
	}
	for y := 0; y < r.h; y++ {
		b.put(r, gx, y, tilePit)
	}
	// Full: a second brute. Not in the finale's arena, where every brute must
	// be killed; slimes fill it instead.
	if lv >= 1 && !b.slay {
		b.monL(r, sim.KBrute, r.w-1, r.h-1-by, 3, uint8(b.r.intn(2)))
	}
	b.gotoL(r, gx-1, r.ay)
	r.addStep(opCross, r.out, r.face(1))
	b.gotoOut(r)
	return true
}

// trench picks a column gx for a full-height trench with the entry on its
// near side and at least far columns, B included, beyond it.
func (b *builder) trench(r *room, far int) (int, bool) {
	hi := r.w - 1 - far
	if r.turn && r.bx-1 < hi {
		hi = r.bx - 1
	}
	if hi < 1 {
		return 0, false
	}
	return 1 + b.r.intn(hi), true
}

// patGargoyle: gargoyles at the room's edge fire across the route every four
// beats; cross each lane between fireballs.
func (b *builder) patGargoyle(r *room, lv int) bool {
	if r.h < 3 || b.spare() < 1 {
		return false
	}
	b.zroute(r, b.r.intn(r.w))
	if b.laneGargoyles(r, 1+lv, false) == 0 {
		return false
	}
	b.gotoOut(r)
	return true
}

// patFireRun: a corridor with a gargoyle at its mouth firing down it. Enter
// just behind a fireball and keep moving: the next one follows four tiles back.
// Full: the corridor is spikes, laid for the walk's beat, so stopping is never
// free.
func (b *builder) patFireRun(r *room, lv int) bool {
	if b.spare() < 1 {
		return false
	}
	end := r.w - 1
	if r.turn {
		end = r.bx
	}
	if end < 4 || r.h < 2 {
		return false
	}
	var rows [16]int
	nr := 0
	for y := 0; y < r.h; y++ {
		if y == r.ay || !r.turn && y == r.by || r.turn && y == 0 {
			continue
		}
		rows[nr] = y
		nr++
	}
	if nr == 0 {
		return false
	}
	lane := rows[b.r.intn(nr)]
	b.fill(r, tileWall)
	b.put(r, 0, r.ay, tileFloor)
	b.vline(r, 1, r.ay, lane)
	for x := 0; x <= end; x++ {
		b.put(r, x, lane, tileFloor)
	}
	if r.turn {
		b.vline(r, end, lane, 0)
	} else {
		b.vline(r, end, lane, r.by)
	}
	phase := b.r.intn(4)
	b.monL(r, sim.KGargoyle, 0, lane, 1, uint8(phase))
	// The route, for timing: A, the column down to the lane, the lane.
	b.cur, b.rn = r, 0
	b.rpush(0, r.ay)
	for y, d := r.ay, 1; ; y += d {
		if lane < r.ay {
			d = -1
		}
		b.rpush(1, y)
		if y == lane {
			break
		}
	}
	for x := 2; x <= end; x++ {
		b.rpush(x, lane)
	}
	// The gargoyle fires on beats f = -phase mod 4. A fireball fired on beat f
	// is on lane tile x on beat f+x; the walk is on it on beat te+x-1, where te
	// is the beat it steps into the lane at x = 1. It is safe when te is f or
	// f+3 mod 4: it then keeps pace one tile behind a fireball, or ahead of
	// one. Spikes (Full) are laid for the better of the two, so one beat to
	// set off on clears both the fire and the spikes.
	f := (4 - phase) % 4
	safe := 1<<uint((f)%4) | 1<<uint((f+3)%4)
	// timeRoute counts in start beats; te is route index 1+|lane-ay| later.
	k := 1 + abs(lane-r.ay)
	off := 0
	if r.cp == b.start {
		off = -1
	}
	mask := 0
	for c := 0; c < 4; c++ {
		if safe&(1<<uint((c+k+off+4)%4)) != 0 {
			mask |= 1 << uint(c)
		}
	}
	// The walk finds the beat by waiting at the door (see walker.room).
	if lv >= 1 {
		b.timeRoute(r, k+1, mask)
	}
	b.gotoOut(r)
	return true
}

// patShove: a one-wide ledge path over a chasm with slimes coming along it.
// Bump them, or dash into one at a bend and shove it into the drop.
func (b *builder) patShove(r *room, lv int) bool {
	if r.w < 4 || r.h < 2 || b.spare() < 1 {
		return false
	}
	b.wroute(r)
	b.fill(r, tilePit)
	for i := 0; i < b.rn; i++ {
		b.put(r, b.rtx[i], b.rty[i], tileFloor)
	}
	n := 1
	if lv >= 1 {
		n = 2
	}
	if b.slay {
		n++
	}
	placed := 0
	for k := b.rn - 1; k > 0 && placed < n; k-- {
		if r.fromA(b.rtx[k], b.rty[k]) >= 4 && b.monL(r, sim.KSlime, b.rtx[k], b.rty[k], 3, uint8(b.r.intn(2))) {
			placed++
			k -= 2
		}
	}
	if placed == 0 {
		b.unplace(r)
		return false
	}
	b.gotoOut(r)
	return true
}

// patChase: a crumbling floor with slimes behind it. The tiles you leave fall,
// and a slime following on them falls with them.
func (b *builder) patChase(r *room, lv int) bool {
	if r.w*r.h < 12 || b.spare() < 1 {
		return false
	}
	b.zroute(r, b.r.intn(r.w))
	n := 2
	if lv >= 2 || b.slay {
		n = 3
	}
	placed := 0
	for k := 0; k < n; k++ {
		if b.farMon(r, sim.KSlime, 3) {
			placed++
		}
	}
	if placed == 0 {
		return false
	}
	for y := 0; y < r.h; y++ {
		for x := 0; x < r.w; x++ {
			i := r.at(b, x, y)
			if b.tiles[i] == tileFloor && !b.monAt(i) && !(x == 0 && y == r.ay) {
				b.tiles[i] = tileCrum
			}
		}
	}
	b.put(r, b.rtx[b.rn-1], b.rty[b.rn-1], tileFloor)
	b.gotoOut(r)
	return true
}

// patCrossfire: two archers face each other along a row the route crosses.
// Step into the row and out again: both draw on you, and their arrows cross
// the empty row into each other.
func (b *builder) patCrossfire(r *room, lv int) bool {
	if r.w < 3 || b.spare() < 2 {
		return false
	}
	var cx, ylo, yhi int
	if r.turn {
		if r.bx < 1 || r.bx > r.w-2 || r.ay < 2 {
			return false
		}
		cx, ylo, yhi = r.bx, 0, r.ay
	} else {
		ylo, yhi = r.ay, r.by
		if ylo > yhi {
			ylo, yhi = yhi, ylo
		}
		if yhi-ylo < 2 {
			return false
		}
		cx = 1 + b.r.intn(r.w-2)
	}
	b.zroute(r, cx)
	row := ylo + 1 + b.r.intn(yhi-ylo-1)
	b.monL(r, sim.KArcher, 0, row, 1, 0)
	b.monL(r, sim.KArcher, r.w-1, row, 3, 0)
	// Shield each archer's column from the route's runs where there is room.
	b.shield(r, 0, row)
	b.shield(r, r.w-1, row)
	// Slimes to keep the crossing honest, off the archers' row so the arrows
	// still meet.
	n := 0
	if lv >= 2 {
		n = 1
	}
	if b.slay {
		n += 2
	}
	for try := 0; try < 16 && n > 0 && b.spare() > 0; try++ {
		x, y := r.w-1-b.r.intn((r.w+1)/2), b.r.intn(r.h)
		if y != row && r.fromA(x, y) >= 4 && b.monL(r, sim.KSlime, x, y, 3, uint8(b.r.intn(4))) {
			n--
		}
	}
	b.gotoOut(r)
	return true
}

// nearArcher reports whether an archer already placed shares a row or column
// with tile i (they would only shoot each other, and their lines would cover
// each other's approach), or touches it.
func (b *builder) nearArcher(i int) bool {
	x, y := i%b.w, i/b.w
	for j := 0; j < b.nmons; j++ {
		if b.mons[j].kind != sim.KArcher {
			continue
		}
		ax, ay := b.mons[j].at%b.w, b.mons[j].at/b.w
		if ax == x || ay == y || abs(ax-x) <= 1 && abs(ay-y) <= 1 {
			return true
		}
	}
	return false
}

// shield walls the tiles next to (x, y) in its column, toward each route run,
// where that leaves the route whole, so the archer there sees only its row.
func (b *builder) shield(r *room, x, y int) {
	for _, d := range []int{-1, 1} {
		for yy := y + d; yy >= 0 && yy < r.h; yy += d {
			if b.onRoute(x, yy) {
				if yy != y+d {
					b.put(r, x, y+d, tileWall)
				}
				break
			}
		}
	}
}

// laneGargoyles puts up to n gargoyles on the room's top or bottom edge, each
// firing down a column the route crosses at least two tiles away. On a chasm
// (onPit) the gargoyle's tile is raised from the pit. It returns how many it
// placed.
func (b *builder) laneGargoyles(r *room, n int, onPit bool) int {
	placed := 0
	var lanes [4]int
	for try := 0; try < 16 && placed < n && b.spare() > 0; try++ {
		x := 1 + b.r.intn(r.w-1)
		if r.turn && x == r.bx {
			continue
		}
		// A tile between lanes, or they are one wall of fire.
		apart := true
		for k := 0; k < placed; k++ {
			apart = apart && abs(x-lanes[k]) >= 2
		}
		if !apart {
			continue
		}
		// The lane must cross the route at exactly one tile: a lane running
		// along the route would fire straight down it.
		ry, on := -1, 0
		for y := 0; y < r.h; y++ {
			if b.onRoute(x, y) {
				ry = y
				on++
			}
		}
		if on != 1 {
			continue
		}
		gy, face := 0, 2
		if ry < r.h/2 {
			gy, face = r.h-1, 0
		}
		if b.onRoute(x, gy) || gy-ry < 2 && ry-gy < 2 || b.gargoyleNear(r.at(b, x, gy)) {
			continue
		}
		if onPit {
			b.put(r, x, gy, tileFloor)
		}
		if b.monL(r, sim.KGargoyle, x, gy, face, uint8(b.r.intn(4))) {
			lanes[placed] = x
			placed++
		} else if onPit {
			b.put(r, x, gy, tilePit)
		}
	}
	return placed
}

// gargoyleNear reports a gargoyle on a tile touching tile i (diagonals too).
func (b *builder) gargoyleNear(i int) bool {
	for j := 0; j < b.nmons; j++ {
		g := b.mons[j]
		if g.kind == sim.KGargoyle && abs(g.at%b.w-i%b.w) <= 1 && abs(g.at/b.w-i/b.w) <= 1 {
			return true
		}
	}
	return false
}

// pillars walls a few tiles off the route, away from the doors.
func (b *builder) pillars(r *room, n int) {
	for k := 0; k < n*3 && n > 0; k++ {
		x, y := b.r.intn(r.w), b.r.intn(r.h)
		if b.nearRoute(x, y) || b.get(r, x, y) != tileFloor || b.monAt(r.at(b, x, y)) {
			continue
		}
		b.put(r, x, y, tileWall)
		n--
	}
}

// farMon places a monster on a free floor tile at least minD from A, trying
// the far tiles first. It reports whether it placed one.
func (b *builder) farMon(r *room, kind uint8, minD int) bool {
	for try := 0; try < 12; try++ {
		x, y := r.w-1-b.r.intn((r.w+1)/2), b.r.intn(r.h)
		if r.fromA(x, y) >= minD && b.monL(r, kind, x, y, 3, uint8(b.r.intn(4))) {
			return true
		}
	}
	return false
}

// unplace undoes walls a pattern drew into r before finding it could not
// place its monsters: the room goes back to plain floor.
func (b *builder) unplace(r *room) {
	b.fill(r, tileFloor)
}

func (b *builder) vline(r *room, x, y0, y1 int) {
	if y0 > y1 {
		y0, y1 = y1, y0
	}
	for y := y0; y <= y1; y++ {
		b.put(r, x, y, tileFloor)
	}
}

// line reports a clear row or column line between tiles i and j (no wall or
// gate strictly between).
func (b *builder) line(i, j int) bool {
	xi, yi, xj, yj := i%b.w, i/b.w, j%b.w, j/b.w
	st := 0
	switch {
	case yi == yj && xi < xj:
		st = 1
	case yi == yj && xi > xj:
		st = -1
	case xi == xj && yi < yj:
		st = b.w
	case xi == xj && yi > yj:
		st = -b.w
	default:
		return false
	}
	for k := i + st; k != j; k += st {
		if c := b.tiles[k]; c == tileWall || c == tileGate {
			return false
		}
	}
	return true
}

// seesRoute reports whether tile i has a clear row or column line to a tile of
// the current route.
func (b *builder) seesRoute(i int) bool {
	x0, y0 := i%b.w, i/b.w
	for s := 0; s < 4; s++ {
		dx, dy := sideVec(s)
		for x, y := x0+dx, y0+dy; x >= 0 && y >= 0 && x < b.w && y < b.h; x, y = x+dx, y+dy {
			k := y*b.w + x
			if c := b.tiles[k]; c == tileWall || c == tileGate {
				break
			}
			if b.rmark[k] == b.stamp {
				return true
			}
		}
	}
	return false
}

package gen

// rng is splitmix64, the generator's only source of randomness. Every floor
// seeds its own from (day, floor) and the day plan seeds one from (day, 0), so
// a floor depends on nothing but its own seed.
type rng struct{ s uint64 }

// seedMix is xor'd into day<<8 | floor so that day 0 floor 0 is not seed 0.
const seedMix uint64 = 0x5dee7f1a2b3c4d59

func newRng(day uint32, n uint8) rng {
	return rng{s: (uint64(day)<<8 | uint64(n)) ^ seedMix}
}

func (r *rng) next() uint64 {
	r.s += 0x9e3779b97f4a7c15
	z := r.s
	z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9
	z = (z ^ (z >> 27)) * 0x94d049bb133111eb
	return z ^ (z >> 31)
}

// intn returns a value in [0, n). n is tiny, so the modulo bias is negligible.
func (r *rng) intn(n int) int {
	if n <= 1 {
		return 0
	}
	return int(r.next() % uint64(n))
}

// span returns a value in [lo, hi].
func (r *rng) span(lo, hi int) int {
	return lo + r.intn(hi-lo+1)
}

func (r *rng) coin() bool {
	return r.next()&1 == 1
}

package gen

// room is one room of the chain, with the canonical frame its pattern is drawn
// in: w x h tiles, entered from the west at A = (0, ay) through a door at
// (-1, ay), left at B, the tile before the exit door: (w-1, by) through (w, by)
// when the room runs straight, (bx, 0) through (bx, -1) when it turns. The
// frame maps onto the room's real rectangle by an optional transpose (tr) and
// mirrors (fx, fy), chosen so that canonical west is the side the route enters.
type room struct {
	x0, y0, aw, ah int // interior rectangle on the floor
	tr, fx, fy     bool
	w, h           int
	ay             int
	turn           bool
	bx, by         int
	base, sx, sy   int // tile index of canonical (lx, ly) is base + lx*sx + ly*sy
	in, out        int // wall tiles the route enters and leaves by
	cp             int // where the walk waits before the room: its entry door, or the start
	last           bool
	pat            uint8
	steps          [maxSteps]step
	ns             int
}

// orient sets the frame from the entry side sIn and exit side sOut (0 N, 1 E,
// 2 S, 3 W) and the entry and exit wall tiles; flip picks the free mirror of a
// straight room.
func (r *room) orient(b *builder, sIn, sOut, tIn, tOut int, flip bool) {
	switch sIn {
	case 3:
		r.tr, r.fx, r.fy = false, false, flip
	case 1:
		r.tr, r.fx, r.fy = false, true, flip
	case 0:
		r.tr, r.fx, r.fy = true, flip, false
	default:
		r.tr, r.fx, r.fy = true, flip, true
	}
	r.turn = sOut != (sIn+2)&3
	if r.turn {
		// Canonical north must land on sOut.
		if r.tr {
			r.fx = sOut == 1
		} else {
			r.fy = sOut == 2
		}
	}
	r.w, r.h = r.aw, r.ah
	if r.tr {
		r.w, r.h = r.ah, r.aw
	}
	// at() as strides: a step in canonical x or y is a fixed index step.
	du, dv := 1, b.w
	r.base = r.y0*b.w + r.x0
	if r.fx {
		du = -1
		r.base += r.aw - 1
	}
	if r.fy {
		dv = -b.w
		r.base += (r.ah - 1) * b.w
	}
	r.sx, r.sy = du, dv
	if r.tr {
		r.sx, r.sy = dv, du
	}
	r.in, r.out, r.cp = tIn, tOut, tIn
	_, r.ay = r.local(b, tIn)
	ex, ey := r.local(b, tOut)
	if r.turn {
		r.bx, r.by = ex, 0
	} else {
		r.bx, r.by = r.w-1, ey
	}
}

// at maps canonical (lx, ly) to a tile index; -1 and w/h reach the walls.
func (r *room) at(b *builder, lx, ly int) int {
	return r.base + lx*r.sx + ly*r.sy
}

// local is the inverse of at.
func (r *room) local(b *builder, i int) (int, int) {
	u, v := i%b.w-r.x0, i/b.w-r.y0
	if r.fx {
		u = r.aw - 1 - u
	}
	if r.fy {
		v = r.ah - 1 - v
	}
	if r.tr {
		return v, u
	}
	return u, v
}

// face maps a canonical side or facing (0 N, 1 E, 2 S, 3 W) onto the floor.
func (r *room) face(s int) int {
	dx, dy := sideVec(s)
	if r.tr {
		dx, dy = dy, dx
	}
	if r.fx {
		dx = -dx
	}
	if r.fy {
		dy = -dy
	}
	return vecSide(dx, dy)
}

func (r *room) in2(lx, ly int) bool {
	return lx >= 0 && ly >= 0 && lx < r.w && ly < r.h
}

// fromA is the walking distance from A ignoring obstacles.
func (r *room) fromA(lx, ly int) int {
	d := ly - r.ay
	if d < 0 {
		d = -d
	}
	return lx + d
}

// addStep appends a plan step. More than maxSteps is a pattern bug: it panics.
func (r *room) addStep(op uint8, at, dir int) {
	if r.ns >= maxSteps {
		panic("gen: more than maxSteps plan steps in a room")
	}
	r.steps[r.ns] = step{op: op, at: at, dir: dir}
	r.ns++
}

// Canonical drawing helpers. Each takes the room by pointer and works in its
// frame.

func (b *builder) put(r *room, lx, ly int, c byte) {
	i := r.at(b, lx, ly)
	b.tiles[i] = c
}

func (b *builder) get(r *room, lx, ly int) byte {
	return b.tiles[r.at(b, lx, ly)]
}

// fill sets every interior tile of r to c.
func (b *builder) fill(r *room, c byte) {
	for y := r.y0; y < r.y0+r.ah; y++ {
		for i := y*b.w + r.x0; i < y*b.w+r.x0+r.aw; i++ {
			b.tiles[i] = c
		}
	}
}

func (b *builder) monL(r *room, kind uint8, lx, ly, facing int, phase uint8) bool {
	return b.addMon(kind, r.at(b, lx, ly), uint8(r.face(facing)), phase)
}

func (b *builder) gotoL(r *room, lx, ly int) {
	r.addStep(opGoto, r.at(b, lx, ly), 0)
}

// dashL dashes toward canonical side s, landing on canonical (lx, ly).
func (b *builder) dashL(r *room, s, lx, ly int) {
	r.addStep(opDash, r.at(b, lx, ly), r.face(s))
}

func (b *builder) gotoOut(r *room) {
	r.addStep(opGoto, r.out, 0)
}

// zroute lays the default route from A to B in b.rtx/b.rty: east along the
// entry row to column cx, then along column cx to B's row, then east to B. A
// turning room goes east to bx, then north to B.
func (b *builder) zroute(r *room, cx int) {
	b.cur = r
	b.rn = 0
	if r.turn {
		for x := 0; x <= r.bx; x++ {
			b.rpush(x, r.ay)
		}
		for y := r.ay - 1; y >= 0; y-- {
			b.rpush(r.bx, y)
		}
		return
	}
	for x := 0; x <= cx; x++ {
		b.rpush(x, r.ay)
	}
	for y := r.ay + 1; y <= r.by; y++ {
		b.rpush(cx, y)
	}
	for y := r.ay - 1; y >= r.by; y-- {
		b.rpush(cx, y)
	}
	for x := cx + 1; x < r.w; x++ {
		b.rpush(x, r.by)
	}
}

// wroute lays a winding route from A to B: east along the entry row, a jog to
// a random middle row, east again, then a jog to B's row (a turning room ends
// with its climb to B). Each jog sits on its own column, so the route bends up
// to four times. Rooms too narrow for two jogs get the plain zroute.
func (b *builder) wroute(r *room) {
	end := r.w - 1
	if r.turn {
		end = r.bx
	}
	if end < 3 || r.h < 3 {
		b.zroute(r, b.r.intn(r.w))
		return
	}
	b.cur = r
	b.rn = 0
	c1 := b.r.intn(end - 1)
	c2 := c1 + 2 + b.r.intn(end-c1-1)
	if c2 > end {
		c2 = end
	}
	mid := b.r.intn(r.h)
	if r.turn && mid == 0 {
		mid = r.h - 1
	}
	if mid == r.ay {
		mid = (mid + 1 + b.r.intn(r.h-1)) % r.h
		if r.turn && mid == 0 {
			mid = 1
		}
	}
	y := r.ay
	b.rpush(0, y)
	for x := 0; x <= end; x++ {
		if x > 0 {
			b.rpush(x, y)
		}
		to := -1
		switch {
		case x == c1:
			to = mid
		case x == c2 && !r.turn:
			to = r.by
		case x == end && r.turn:
			to = 0
		}
		for to >= 0 && y != to {
			if y < to {
				y++
			} else {
				y--
			}
			b.rpush(x, y)
		}
	}
}

func (b *builder) rpush(x, y int) {
	if b.rn == 0 {
		b.stamp++
	}
	b.rtx[b.rn], b.rty[b.rn] = x, y
	b.rn++
	b.rmark[b.cur.at(b, x, y)] = b.stamp
}

// onRoute reports whether canonical (x, y) of the current room is on its route.
func (b *builder) onRoute(x, y int) bool {
	return b.cur.in2(x, y) && b.rmark[b.cur.at(b, x, y)] == b.stamp
}

// nearRoute reports whether (x, y) is on the route or next to it. Route marks
// sit on tile indices, and the room's walls are never marked, so the four
// neighbors need no bounds check.
func (b *builder) nearRoute(x, y int) bool {
	i := b.cur.at(b, x, y)
	st := b.stamp
	return b.rmark[i] == st || b.rmark[i-1] == st || b.rmark[i+1] == st ||
		b.rmark[i-b.w] == st || b.rmark[i+b.w] == st
}

package gen

import "gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/sim"

// The walker plays the witness on the engine itself. Every beat it tries
// actions in order of preference on a copy of the game (sim.Game holds no
// pointers but the map, so a copy is a full snapshot) and keeps the first that
// costs no HP: the planned step, then waiting, then striking, a side step or
// a dash. A room that cannot be crossed is replayed from its door with one
// more beat of waiting there first, which shifts every timed hazard by a beat.
// When no wait works, a beam search over the engine's states takes over: from
// the room's door, then from the doors of the rooms before it (a chaser picked
// up earlier can doom a room), then over the whole floor from the start.
//
// Walking with Ironheart, whose dash cooldown is the longest, makes every
// dash the witness takes wait out the 8-beat cooldown, so the log clears the
// same with any relic (the relics differ in nothing else a flawless log meets).
const (
	walkRelic = 2
	maxWaits  = 7   // extra beats of waiting tried at one door
	roomBeats = 60  // beats one plan step may take
	huntBeats = 120 // beats the finale's hunt may take
	huntStall = 30  // beats the hunt may go without a kill
)

type walker struct {
	b    *builder
	g    [2]sim.Game // the current game is g[ci]; the other is the trial
	ci   int
	log  [sim.MaxBeats]byte
	n    int
	side int    // side of the last move, tried first
	off  [4]int // tile offset of each side

	trials int // trial beats played
	limit  int // trial budget (see walkTrials)

	cp    sim.Game // a room's door, after the waits tried so far
	cpN   int
	doors [maxRooms]sim.Game // the game as the hero reached each room's door
	doorN [maxRooms]int

	// Distance fields: the one in use, and a small cache keyed by target and
	// box (target -1: not reusable).
	dist   *[sim.MaxTiles]uint8
	fields [3][sim.MaxTiles]uint8
	keys   [3][5]int
	nextF  int
	q      [sim.MaxTiles]int

	// The hunt's target, for rebuilding its field only when needed.
	hTile, hMon int
	hFoes       uint8

	// For the search: each room's distance field to its exit, and the room
	// each tile belongs to (a door belongs to the room it opens into).
	rdist  [maxRooms][sim.MaxTiles]uint8
	roomOf [sim.MaxTiles]int8
	rdone  bool
	// huntLight scores the finale's arena by the exit plus a little per foe
	// left, as cmd/solve does, instead of by foes and the nearest one.
	huntLight bool
	// chest is the room (index+1) whose door leads to the chest, when the walk
	// must take it (ChestWitness); 0 for the floor's own witness.
	chest int
}

const far = uint8(255)

func (k *walker) cur() *sim.Game {
	return &k.g[k.ci]
}

// walk plays the floor's plan room by room and returns the log and whether it
// cleared with zero damage.
func (k *walker) walk(b *builder, m *sim.Map) (string, bool) {
	k.b = b
	k.off = [4]int{-b.w, 1, b.w, -1}
	for i := 0; i < len(k.keys); i++ {
		k.keys[i][0] = -1
	}
	k.g[0] = sim.NewGame(m, walkRelic)
	ok := true
	for ri := 0; ri < b.nrooms && ok; ri++ {
		ok = k.room(ri)
	}
	if !ok {
		// Last resort: a wide search over the whole floor from the start,
		// then one that weighs foes as cmd/solve does, then a wider one.
		for pass := 0; pass < 3 && !ok; pass++ {
			k.g[k.ci] = k.doors[0]
			k.n = 0
			k.huntLight = pass >= 1
			width := beamFloor
			if pass == 2 {
				width = beamFloorWide
			}
			ok = k.search(0, b.nrooms-1, width)
		}
	}
	g := k.cur()
	return string(k.log[:k.n]), ok && g.Won && g.Damage == 0
}

// room crosses room ri, retrying from its door with one more beat of waiting
// each time a step of its plan fails. When every wait fails, it searches for a
// way to the room's exit from its door, then from the doors of the one or two
// rooms before it (a chaser picked up earlier can doom a room from its door).
func (k *walker) room(ri int) bool {
	r := &k.b.rooms[ri]
	k.save()
	k.doors[ri] = k.cp
	k.doorN[ri] = k.n
	for w := 0; ; w++ {
		if k.steps(r) {
			return true
		}
		if w == maxWaits || k.trials >= k.limit {
			break
		}
		k.restore()
		if !k.try(0, int(k.cur().HIdx)) {
			break
		}
		k.save()
	}
	for from := ri; from >= 0 && from >= ri-2; from-- {
		k.g[k.ci] = k.doors[from]
		k.n = k.doorN[from]
		if k.search(from, ri, beamWidth) {
			return true
		}
	}
	return false
}

func (k *walker) save() {
	k.cp = k.g[k.ci]
	k.cpN = k.n
}

func (k *walker) restore() {
	k.g[k.ci] = k.cp
	k.n = k.cpN
}

func (k *walker) steps(r *room) bool {
	// The chest detour: into the chest room and back out, then the plan.
	if k.chest > 0 && r == &k.b.rooms[k.chest-1] && !k.cur().Chest {
		b := k.b
		if !k.goToBox(0, 0, b.w-1, b.h-1, b.chestAt) || !k.goToBox(0, 0, b.w-1, b.h-1, b.chestOut) {
			return false
		}
	}
	for i := 0; i < r.ns; i++ {
		s := r.steps[i]
		ok := false
		switch s.op {
		case opGoto:
			ok = k.goTo(r, s.at)
		case opDash:
			ok = k.dash(s.dir, s.at)
		case opHunt:
			ok = k.hunt(r)
		case opCross:
			ok = k.cross(r, s.dir, s.at)

		}
		if !ok {
			return false
		}
	}
	return true
}

// trial plays action a on a copy of the current game and returns the copy.
// Once the walk's trial budget is spent every trial comes back dead, which
// fails the walk at once.
func (k *walker) trial(a uint8) *sim.Game {
	t := &k.g[1-k.ci]
	*t = k.g[k.ci]
	if k.trials >= k.limit {
		t.Dead = true
		return t
	}
	t.Step(a)
	k.trials++
	return t
}

func clean(t *sim.Game) bool {
	return !t.Dead && t.Damage == 0
}

// commit makes the last trial (action a) current.
func (k *walker) commit(a uint8) {
	k.ci = 1 - k.ci
	k.log[k.n] = '0' + a
	k.n++
	if a >= 1 && a <= 8 {
		k.side = int(a-1) & 3
	}
}

// viable reports whether game t (a trial's result) leaves the hero some
// action next beat that looks safe: a step or a wait, a bump that kills the
// monster it hits, or a dash (a dash beat cannot be hurt). Rejecting moves
// into a dead end, such as the gap between two fireball lanes, spares the walk
// replaying a whole room.
func (k *walker) viable(t *sim.Game) bool {
	// The dead ends it guards against come from projectiles, and only one in
	// the hero's row or column can reach him next beat.
	hx, hy := t.HX, t.HY
	near := false
	for j := 0; j < int(t.NProjs) && !near; j++ {
		near = t.Projs[j].X == hx || t.Projs[j].Y == hy
	}
	if !near {
		return true
	}
	for a := uint8(0); a <= 4; a++ {
		skip := -1
		j := -1
		if a > 0 {
			j = k.neighbor(int(t.HIdx), int(a-1))
		}
		if j >= 0 {
			o := int(t.Occ[k.oi(j)])
			if o >= 1 && o <= sim.MaxMonsters && t.Mons[o-1].Alive && t.Mons[o-1].HP == 1 {
				skip = o - 1
			}
		}
		if k.safeOn(t, a, skip) {
			return true
		}
	}
	return t.DashCD == 0
}

// safeOn screens action a on game g without playing it: it reports false
// when the beat surely costs HP or a life (spikes up under the hero's step, a
// pit, a crumble that falls this beat, a projectile on or entering his tile,
// an acting slime next to a hero who stays put, a brute's blow landing on his
// tile). It never rejects a safe action, as it reads the same state the engine
// will. Monster skip is ignored (the action kills it before it acts). Dashes
// are left to a trial: a dash beat cannot be hurt.
func (k *walker) safeOn(g *sim.Game, a uint8, skip int) bool {
	if a >= 5 {
		return true
	}
	pw := int(g.PW)
	i := int(g.HIdx)
	moved := false
	j := -1
	if a >= 1 {
		j = k.neighbor(i, int(a-1))
	}
	if j >= 0 {
		o := g.Occ[k.oi(j)]
		if o == 0 || o == sim.OccPit || o&0xF8 == sim.OccGate && (g.GatesUp || g.Stuck&(1<<(o&7)) != 0) ||
			o >= 1 && o <= sim.MaxMonsters && !g.Mons[o-1].Alive {
			i, moved = j, true
		}
	}
	t := g.Tiles[i]
	if t == sim.TPit || int(g.Mark) == i {
		return false
	}
	if g.Inv != 0 {
		return true
	}
	x, y := i%k.b.w, i/k.b.w
	if t == sim.TSpikes && (int(g.Beat)+x+y)%4 >= 2 {
		return false
	}
	for j := 0; j < int(g.NProjs); j++ {
		p := &g.Projs[j]
		px, py := int(p.X), int(p.Y)
		if px == x && py == y || px+int(p.DX) == x && py+int(p.DY) == y {
			return false
		}
	}
	// Melee comes only from the four tiles around the hero: a slime acting
	// this beat strikes a hero who stays put, a brute ending its wind-up
	// strikes the tile it faces.
	acting := g.Tick | g.Sched[g.Beat&3]
	oc := (y+1)*pw + x + 1
	for s := 0; s < 4; s++ {
		var o int
		switch s {
		case 0:
			o = int(g.Occ[oc-pw])
		case 1:
			o = int(g.Occ[oc+1])
		case 2:
			o = int(g.Occ[oc+pw])
		default:
			o = int(g.Occ[oc-1])
		}
		if o < 1 || o > sim.MaxMonsters || o-1 == skip || acting&(1<<uint(o-1)) == 0 {
			continue
		}
		e := &g.Mons[o-1]
		if !e.Alive {
			continue
		}
		switch e.Kind {
		case sim.KSlime:
			if !moved {
				return false
			}
		case sim.KBrute:
			// The brute is on side s of the hero and must face him: its
			// facing is the opposite side.
			if e.Wind == 1 && int(e.Facing) == (s+2)&3 {
				return false
			}
		}
	}
	return true
}

// oi is the Occ index of tile i (Occ has a one-tile border).
func (k *walker) oi(i int) int {
	return i + 2*(i/k.b.w) + k.b.w + 3
}

// dashLanding returns the tile a dash toward side s would land on, as the
// engine resolves it, or -1 when it would not happen (cooldown, a wall in the
// way) or would shove a monster, or would end in a pit or a falling crumble.
func (k *walker) dashLanding(s int) int {
	g := k.cur()
	if g.DashCD != 0 {
		return -1
	}
	pw := int(g.PW)
	dx, dy := sideVec(s)
	x1, y1 := int(g.HX)+dx, int(g.HY)+dy
	blocks := func(x, y int) (bool, bool) { // closed, monster
		o := g.Occ[(y+1)*pw+x+1]
		closed := o == sim.OccWall || o&0xF8 == sim.OccGate && !(g.GatesUp || g.Stuck&(1<<(o&7)) != 0)
		mon := o >= 1 && o <= sim.MaxMonsters && g.Mons[o-1].Alive
		return closed, mon
	}
	if c, m := blocks(x1, y1); c || m {
		return -1
	}
	x2, y2 := x1+dx, y1+dy
	if c, m := blocks(x2, y2); c || m {
		x2, y2 = x1, y1
	}
	i := y2*k.b.w + x2
	if g.Tiles[i] == sim.TPit || int(g.Mark) == i {
		return -1
	}
	return i
}

// try plays a and keeps it when it is clean and the hero ends on tile want.
func (k *walker) try(a uint8, want int) bool {
	if k.n >= sim.MaxBeats {
		return false
	}
	t := k.trial(a)
	if !clean(t) || int(t.HIdx) != want || t.Ev&sim.EvShove != 0 || !t.Won && !k.viable(t) {
		return false
	}
	k.commit(a)
	return true
}

// monAt returns the index of a live monster on tile i, or -1.
func (k *walker) monAt(g *sim.Game, i int) int {
	o := int(g.Occ[k.oi(i)])
	if o >= 1 && o <= sim.MaxMonsters && g.Mons[o-1].Alive {
		return o - 1
	}
	return -1
}

// neighbor returns the tile next to i on side s, or -1 past the floor's edge
// (the walk can stand on the exit, which is in the border wall).
func (k *walker) neighbor(i, s int) int {
	w := k.b.w
	switch s {
	case 0:
		if i < w {
			return -1
		}
	case 1:
		if i%w == w-1 {
			return -1
		}
	case 2:
		if i >= w*(k.b.h-1) {
			return -1
		}
	default:
		if i%w == 0 {
			return -1
		}
	}
	return i + k.off[s]
}

// strike attacks the monster on the tile toward side s: a dash that shoves it
// into a pit when one lies behind it, else a bump. It reports whether a clean
// blow landed (a bump on a brute's shield does not count).
func (k *walker) strike(s int) bool {
	if k.n >= sim.MaxBeats {
		return false
	}
	g := k.cur()
	nb := k.neighbor(int(g.HIdx), s)
	if nb < 0 {
		return false
	}
	mi := k.monAt(g, nb)
	if mi < 0 || g.Mons[mi].Kind == sim.KGargoyle {
		return false
	}
	if g.DashCD == 0 {
		if pb := k.neighbor(nb, s); pb >= 0 && g.Tiles[pb] == sim.TPit {
			t := k.trial(uint8(s + 5))
			if clean(t) && t.Ev&sim.EvFall != 0 {
				k.commit(uint8(s + 5))
				return true
			}
		}
	}
	t := k.trial(uint8(s + 1))
	if clean(t) && t.Ev&sim.EvHit != 0 {
		k.commit(uint8(s + 1))
		return true
	}
	return false
}

// goTo walks to tile target along r's distance field.
func (k *walker) goTo(r *room, target int) bool {
	x0, y0 := r.x0-1, r.y0-1
	return k.goToBox(x0, y0, x0+r.aw+1, y0+r.ah+1, target)
}

// goToBox is goTo over the box [x0, x1] x [y0, y1].
func (k *walker) goToBox(x0, y0, x1, y1, target int) bool {
	k.bfs(x0, y0, x1, y1, target, nil)
	best, stall := far, 0
	for beat := 0; beat < roomBeats; beat++ {
		h := int(k.cur().HIdx)
		if h == target {
			return true
		}
		if d := k.dist[h]; d < best {
			best, stall = d, 0
		} else if stall++; stall > maxStall {
			return false // replay the room from its door, a beat later
		}
		if stall >= 4 && k.dashCloser() {
			continue
		}
		if stall == 0 && k.stepFast(h) {
			continue
		}
		if !k.advance() {
			return false
		}
	}
	return false
}

// stepFast is advance's common case, kept lean because Gno charges for every
// operation: one step to a free tile one closer (the last direction first),
// kept if the beat is clean. It reports false, having committed nothing, when
// that does not work out.
func (k *walker) stepFast(h int) bool {
	d := k.dist[h] - 1
	s := k.side
	nb := k.neighbor(h, s)
	if nb < 0 || k.dist[nb] != d {
		for s = 0; s < 4; s++ {
			if nb = k.neighbor(h, s); nb >= 0 && k.dist[nb] == d {
				break
			}
		}
		if s == 4 {
			return false
		}
	}
	g := &k.g[k.ci]
	if g.Occ[nb+2*(nb/k.b.w)+k.b.w+3] != 0 || k.n >= sim.MaxBeats {
		return false
	}
	t := k.trial(uint8(s + 1))
	if t.Dead || t.Damage != 0 || int(t.HIdx) != nb || t.NProjs != 0 && !t.Won && !k.viable(t) {
		return false
	}
	k.commit(uint8(s + 1))
	return true
}

// maxStall is how many beats goTo may go without getting closer.
const maxStall = 12

// dashCloser dashes to a tile closer to the goal when one is in reach and the
// dash is clean: the way past a hazard that walking cannot time (two fireball
// lanes side by side), since a dash beat cannot be hurt.
func (k *walker) dashCloser() bool {
	if k.n >= sim.MaxBeats {
		return false
	}
	d := k.dist[k.cur().HIdx]
	for s := 0; s < 4; s++ {
		l := k.dashLanding(s)
		if l < 0 || k.dist[l] >= d {
			continue
		}
		t := k.trial(uint8(s + 5))
		if clean(t) && t.Ev&sim.EvShove == 0 && k.viable(t) {
			k.commit(uint8(s + 5))
			return true
		}
	}
	return false
}

// advance plays one beat toward lower distance: a step that gets closer (or a
// blow on the monster in the way), else waiting, else a side step, a step
// back or a dash that gets closer. Off the distance field (in an archer's line
// while hunting) it steps back onto it. It reports false when every one of
// them costs HP.
func (k *walker) advance() bool {
	g := k.cur()
	h := int(g.HIdx)
	d := k.dist[h]
	if d == far {
		return k.escape()
	}
	blocked := false
	for o := 0; o < 4; o++ {
		s := (k.side + o) & 3
		nb := k.neighbor(h, s)
		if nb < 0 || k.dist[nb] != d-1 {
			continue
		}
		if k.monAt(g, nb) >= 0 {
			if k.strike(s) {
				return true
			}
			blocked = true
			continue
		}
		if k.try(uint8(s+1), nb) {
			return true
		}
	}
	// A monster that cannot be struck (a brute's shield, a gargoyle) stands
	// in the way: go round it before it winds up.
	if blocked && k.sidestep(d) {
		return true
	}
	return k.dodge(d)
}

// escape steps onto the tile of the distance field nearest the goal, or waits.
func (k *walker) escape() bool {
	g := k.cur()
	h := int(g.HIdx)
	for best := uint8(0); best < far; {
		bs, bd := -1, far
		for s := 0; s < 4; s++ {
			nb := k.neighbor(h, s)
			if nb >= 0 && k.dist[nb] >= best && k.dist[nb] < bd && k.monAt(g, nb) < 0 {
				bs, bd = s, k.dist[nb]
			}
		}
		if bs < 0 {
			break
		}
		if k.try(uint8(bs+1), k.neighbor(h, bs)) {
			return true
		}
		best = bd + 1
	}
	// Boxed in by closed tiles: any clean step, else the usual fallbacks.
	for s := 0; s < 4; s++ {
		nb := k.neighbor(h, s)
		if nb < 0 || k.monAt(g, nb) >= 0 {
			continue
		}
		if c := k.b.tiles[nb]; c == tileWall || c == tilePit || nb == k.b.exit {
			continue
		}
		if k.try(uint8(s+1), nb) {
			return true
		}
	}
	return k.dodge(far)
}

// sidestep steps to a free tile no farther from the goal than d+1.
func (k *walker) sidestep(d uint8) bool {
	g := k.cur()
	h := int(g.HIdx)
	if g.Tiles[h] == sim.TCrumble {
		return false
	}
	for s := 0; s < 4; s++ {
		nb := k.neighbor(h, s)
		if nb < 0 || k.dist[nb] == far || k.dist[nb] < d || k.dist[nb] > d+1 || k.monAt(g, nb) >= 0 {
			continue
		}
		if k.try(uint8(s+1), nb) {
			return true
		}
	}
	return false
}

// dodge is advance's fallback: wait, fight what is adjacent, step aside or
// back, or dash closer. In the hunt (d == far) any clean step will do.
func (k *walker) dodge(d uint8) bool {
	g := k.cur()
	h := int(g.HIdx)
	if k.try(0, h) {
		return true
	}
	for s := 0; s < 4; s++ {
		if k.strike(s) {
			return true
		}
	}
	// Leaving a crumble tile drops it: on one, only ever move closer.
	onCrumble := g.Tiles[h] == sim.TCrumble
	for s := 0; s < 4 && !onCrumble; s++ {
		nb := k.neighbor(h, s)
		if nb < 0 || k.monAt(g, nb) >= 0 || d != far && (k.dist[nb] == far || k.dist[nb] < d) {
			continue
		}
		if c := k.b.tiles[nb]; c == tileWall || c == tilePit {
			continue
		}
		if k.try(uint8(s+1), nb) {
			return true
		}
	}
	if g.DashCD == 0 && k.n < sim.MaxBeats {
		for s := 0; s < 4; s++ {
			l := k.dashLanding(s)
			if l < 0 || d != far && k.dist[l] >= d {
				continue
			}
			t := k.trial(uint8(s + 5))
			if clean(t) && t.Ev&sim.EvShove == 0 {
				k.commit(uint8(s + 5))
				return true
			}
		}
	}
	return false
}

// cross gets over a trench toward side s: dash across when the far bank is
// free and the beat is clean, else walk along the near bank away from the
// nearest monster across (a brute mirrors the hero at half speed, so this
// draws it off the landing), else wait. The far side is what the distance
// field to the exit (tile out) reaches without crossing a pit.
func (k *walker) cross(r *room, s, out int) bool {
	x0, y0 := r.x0-1, r.y0-1
	k.bfs(x0, y0, x0+r.aw+1, y0+r.ah+1, out, nil)
	along := (s + 1) & 3
	for beat := 0; beat < roomBeats && k.n < sim.MaxBeats; beat++ {
		g := k.cur()
		h := int(g.HIdx)
		if k.dist[h] != far {
			return true
		}
		if l := k.dashLanding(s); l >= 0 && k.dist[l] != far {
			t := k.trial(uint8(s + 5))
			if clean(t) && t.Ev&sim.EvShove == 0 {
				k.commit(uint8(s + 5))
				return true
			}
		}
		// Walk the bank: keep the current direction while the bank goes on.
		moved := false
		for o := 0; o < 2 && !moved; o++ {
			a := along
			if o == 1 {
				a = (along + 2) & 3
			}
			nb := k.neighbor(h, a)
			if nb < 0 || k.monAt(g, nb) >= 0 {
				continue
			}
			if c := k.b.tiles[nb]; c == tileWall || c == tilePit {
				continue
			}
			if pb := k.neighbor(nb, s); pb < 0 || k.b.tiles[pb] != tilePit {
				continue // not the bank
			}
			if k.try(uint8(a+1), nb) {
				along, moved = a, true
			}
		}
		if moved {
			continue
		}
		along = (along + 2) & 3
		if !k.dodge(far) {
			return false
		}
	}
	return false
}

// dash waits for the cooldown, then dashes toward side s and must land on
// tile at.
func (k *walker) dash(s, at int) bool {
	for beat := 0; beat < roomBeats && k.n < sim.MaxBeats; beat++ {
		g := k.cur()
		if k.dashLanding(s) == at {
			t := k.trial(uint8(s + 5))
			if clean(t) && int(t.HIdx) == at && t.Ev&sim.EvShove == 0 {
				k.commit(uint8(s + 5))
				return true
			}
		}
		if k.try(0, int(g.HIdx)) {
			continue
		}
		hit := false
		for o := 0; o < 4 && !hit; o++ {
			hit = k.strike(o)
		}
		if !hit {
			return false
		}
	}
	return false
}

// hunt kills every foe left (the SLAY finale). Foes next to the hero are
// struck; slimes and brutes come to the hero, so the walk waits for them, and
// walks to an archer, or to a foe that has stopped coming, by a distance field
// over the arena that keeps out of the archers' lines until the last step.
func (k *walker) hunt(r *room) bool {
	k.hMon = -1
	idle, since, foes := 0, 0, k.cur().Foes
	for beat := 0; beat < huntBeats; beat++ {
		g := k.cur()
		if g.Foes == 0 {
			return true
		}
		if g.Foes < foes {
			foes, since = g.Foes, 0
		} else if since++; since > huntStall {
			return false // replay the room from its door, a beat later
		}
		struck := false
		h := int(g.HIdx)
		for s := 0; s < 4 && !struck; s++ {
			if nb := k.neighbor(h, s); nb >= 0 && k.monAt(g, nb) >= 0 && g.Mons[k.monAt(g, nb)].Kind != sim.KGargoyle {
				struck = k.strike(s)
			}
		}
		if struck {
			idle = 0
			continue
		}
		t := k.nearestFoe(g)
		if t < 0 {
			return false
		}
		e := g.Mons[t]
		ti := int(e.Y)*k.b.w + int(e.X)
		if e.Kind == sim.KArcher || idle >= 4 {
			// The field is the arena's; rebuild it for a new target or after a
			// kill (an archer's lines may be gone). A walking target is chased
			// to where it was: it is coming this way anyway.
			if t != k.hMon || k.hFoes != g.Foes {
				k.hMon, k.hTile, k.hFoes = t, ti, g.Foes
				x0, y0 := r.x0-1, r.y0-1
				k.bfs(x0, y0, x0+r.aw+1, y0+r.ah+1, ti, g)
			}
			if !k.advance() {
				return false
			}
		} else if !k.dodge(far) {
			return false
		}
		idle++
	}
	return false
}

// nearestFoe returns the live killable monster nearest the hero, or -1.
func (k *walker) nearestFoe(g *sim.Game) int {
	best, bd := -1, 1<<30
	for i := 0; i < int(g.NMons); i++ {
		e := &g.Mons[i]
		if !e.Alive || e.Kind == sim.KGargoyle {
			continue
		}
		dx, dy := int(e.X)-int(g.HX), int(e.Y)-int(g.HY)
		if dx < 0 {
			dx = -dx
		}
		if dy < 0 {
			dy = -dy
		}
		if dx+dy < bd {
			best, bd = i, dx+dy
		}
	}
	return best
}

// bfs fills dist with the walking distance to tile target over the box
// [x0, x1] x [y0, y1] (clipped to the floor), through any tile but walls and
// pits; everything else is far. With g set (the hunt), the lines of every live
// archer are closed (an archer sees along its row and column until a wall),
// and when the target is itself an archer the distance is to the tiles next to
// it, so the walk steps into an archer's line only to strike it.
func (k *walker) bfs(x0, y0, x1, y1, target int, g *sim.Game) {
	b := k.b
	if x0 < 0 {
		x0 = 0
	}
	if y0 < 0 {
		y0 = 0
	}
	if x1 >= b.w {
		x1 = b.w - 1
	}
	if y1 >= b.h {
		y1 = b.h - 1
	}
	// A field over the static floor depends only on its target and box, so a
	// room replayed from its door reuses the fields it built before.
	key := [5]int{target, x0, y0, x1, y1}
	if g == nil {
		for i := 0; i < len(k.keys); i++ {
			if k.keys[i] == key {
				k.dist = &k.fields[i]
				return
			}
		}
	}
	slot := k.nextF
	k.nextF = (k.nextF + 1) % len(k.fields)
	k.keys[slot] = key
	if g != nil {
		k.keys[slot][0] = -1 // a hunt field depends on the game too
	}
	k.dist = &k.fields[slot]
	for y := y0; y <= y1; y++ {
		for x := x0; x <= x1; x++ {
			k.dist[y*b.w+x] = far
		}
	}
	const closed = far - 1
	// Gargoyles never move and cannot be struck or shoved: walls to a walk.
	for i := 0; i < b.nmons; i++ {
		if b.mons[i].kind == sim.KGargoyle && b.mons[i].at != target {
			k.dist[b.mons[i].at] = closed
		}
	}
	head, tail := 0, 0
	tm := -1
	if g != nil {
		tm = k.monAt(g, target)
		for i := 0; i < int(g.NMons); i++ {
			e := &g.Mons[i]
			if !e.Alive || e.Kind != sim.KArcher {
				continue
			}
			for s := 0; s < 4; s++ {
				dx, dy := sideVec(s)
				x, y := int(e.X)+dx, int(e.Y)+dy
				for n := 0; x >= x0 && y >= y0 && x <= x1 && y <= y1; n++ {
					j := y*b.w + x
					if c := b.tiles[j]; c == tileWall || c == tileGate {
						break
					}
					if n > 0 || i != tm {
						k.dist[j] = closed
					}
					x, y = x+dx, y+dy
				}
			}
			k.dist[int(e.Y)*b.w+int(e.X)] = closed
		}
	}
	if tm >= 0 && g.Mons[tm].Kind == sim.KArcher {
		for s := 0; s < 4; s++ {
			if j := k.neighbor(target, s); j >= 0 && k.dist[j] == far {
				if c := b.tiles[j]; c != tileWall && c != tilePit {
					k.dist[j] = 0
					k.q[tail] = j
					tail++
				}
			}
		}
	} else {
		k.dist[target] = 0
		k.q[tail] = target
		tail++
	}
	// The neighbor loop is unrolled: in Gno a call or an array read costs far
	// more than arithmetic, and this loop is the walk's hottest.
	w := b.w
	for head < tail {
		i := k.q[head]
		head++
		d := k.dist[i] + 1
		x, y := i%w, i/w
		if y > y0 {
			if j := i - w; k.dist[j] == far {
				if c := b.tiles[j]; c != tileWall && c != tilePit {
					k.dist[j] = d
					k.q[tail] = j
					tail++
				}
			}
		}
		if x < x1 {
			if j := i + 1; k.dist[j] == far {
				if c := b.tiles[j]; c != tileWall && c != tilePit {
					k.dist[j] = d
					k.q[tail] = j
					tail++
				}
			}
		}
		if y < y1 {
			if j := i + w; k.dist[j] == far {
				if c := b.tiles[j]; c != tileWall && c != tilePit {
					k.dist[j] = d
					k.q[tail] = j
					tail++
				}
			}
		}
		if x > x0 {
			if j := i - 1; k.dist[j] == far {
				if c := b.tiles[j]; c != tileWall && c != tilePit {
					k.dist[j] = d
					k.q[tail] = j
					tail++
				}
			}
		}
	}
	for y := y0; y <= y1; y++ {
		for x := x0; x <= x1; x++ {
			if k.dist[y*b.w+x] == closed {
				k.dist[y*b.w+x] = far
			}
		}
	}
}

// Beam search bounds: states kept per beat (rooms, then the whole floor), and
// beats searched per room.
const (
	beamWidth     = 48
	beamFloor     = 2000 // the whole floor from the start, when all else fails
	beamFloorWide = 8000 // and once more, wider
	beamDepth     = 64
)

// node is one state of the search: game, the node it came from (index into
// the search's history) and the action that led here.
type node struct {
	g      sim.Game
	parent int
	act    uint8
	cost   int
}

// search is the fallback: a beam search over the engine's states from room
// from's door to room to's exit (or the floor won). Every action is tried each
// beat; states that cost HP are dropped, so are states seen before (state hash
// with the beat mod 4), and the width states with the least way left (rooms
// to go, then the distance to the current room's exit) are kept. On success
// the path is committed.
func (k *walker) search(from, to, width int) bool {
	b := k.b
	k.fields4Search()
	goal := b.rooms[to].out
	last := b.rooms[to].last
	var past []trace
	seen := map[uint32]bool{}
	layer := []node{{g: k.g[k.ci], parent: -1}}
	depth := beamDepth * (to - from + 1)
	if last || depth > sim.MaxBeats {
		depth = sim.MaxBeats // the finale's hunt can run long
	}
	for d := 0; d < depth && len(layer) > 0 && k.n+d < sim.MaxBeats; d++ {
		var next []node
		for li := range layer {
			for a := uint8(0); a <= 8; a++ {
				if k.trials >= k.limit {
					return false
				}
				t := layer[li].g
				t.Step(a)
				k.trials++
				if t.Dead || t.Damage != 0 {
					continue
				}
				done := (t.Won || int(t.HIdx) == goal && !last) && (k.chest == 0 || to < k.chest-1 || t.Chest)
				c := t
				c.Beat &= 3
				hsh := c.StateHash()
				if seen[hsh] && !done {
					continue
				}
				seen[hsh] = true
				past = append(past, trace{parent: layer[li].parent, act: a})
				if done {
					return k.replay(past, len(past)-1)
				}
				next = append(next, node{g: t, parent: len(past) - 1, cost: k.wayLeft(&t, to)})
			}
		}
		layer = cheapest(next, width)
	}
	return false
}

// maxCost caps a node's cost for cheapest's histogram.
const maxCost = 2047

// cheapest keeps the width cheapest nodes, ties in the order they came: a
// counting selection, linear in the layer, where a sort would cost its square.
func cheapest(next []node, width int) []node {
	if len(next) <= width {
		return next
	}
	var hist [maxCost + 1]int
	for i := range next {
		if next[i].cost > maxCost {
			next[i].cost = maxCost
		}
		hist[next[i].cost]++
	}
	cut, n := 0, 0
	for ; cut <= maxCost && n+hist[cut] < width; cut++ {
		n += hist[cut]
	}
	room := width - n // nodes of cost cut that still fit
	keep := next[:0]
	for i := range next {
		c := next[i].cost
		if c < cut || c == cut && room > 0 {
			if c == cut {
				room--
			}
			keep = append(keep, next[i])
		}
	}
	return keep
}

// wayLeft scores how far game t is from room to's exit: rooms still to cross,
// then the distance to the exit of the room the hero is in (a trench's near
// side, off the field, counts as a little more than its far edge). In the
// finale's arena, while foes are left, it is the foes left, then the distance
// to the nearest one: the exit stays shut until they are dead.
func (k *walker) wayLeft(t *sim.Game, to int) int {
	h := int(t.HIdx)
	ri := int(k.roomOf[h])
	if ri == to && t.Foes > 0 && t.M.Obj == sim.ObjSlay && !k.huntLight {
		near := 99
		for i := 0; i < int(t.NMons); i++ {
			e := &t.Mons[i]
			if e.Alive && e.Kind != sim.KGargoyle {
				if d := abs(int(e.X)-int(t.HX)) + abs(int(e.Y)-int(t.HY)); d < near {
					near = d
				}
			}
		}
		return 100*int(t.Foes) + near
	}
	// On the chest route, from the chest's room on and until it is taken, the
	// way left is the way to the chest.
	if k.chest > 0 && !t.Chest && ri >= k.chest-1 {
		c := k.b.chestAt
		return (to-k.chest+1)*200 + 100 + abs(h%k.b.w-c%k.b.w) + abs(h/k.b.w-c/k.b.w)
	}
	d := int(k.rdist[ri][h])
	if d == int(far) {
		d = 40
	}
	return (to-ri)*200 + d + 4*int(t.Foes)
}

// fields4Search fills rdist and roomOf once per walk.
func (k *walker) fields4Search() {
	if k.rdone {
		return
	}
	k.rdone = true
	b := k.b
	for i := range k.roomOf {
		k.roomOf[i] = 0
	}
	for ri := 0; ri < b.nrooms; ri++ {
		r := &b.rooms[ri]
		for y := r.y0; y < r.y0+r.ah; y++ {
			for x := r.x0; x < r.x0+r.aw; x++ {
				k.roomOf[y*b.w+x] = int8(ri)
			}
		}
		if ri > 0 {
			k.roomOf[r.in] = int8(ri)
		}
		x0, y0 := r.x0-1, r.y0-1
		k.bfs(x0, y0, x0+r.aw+1, y0+r.ah+1, r.out, nil)
		k.rdist[ri] = *k.dist
	}
	// The chest's side room belongs to the room its door opens from.
	if k.chest > 0 {
		x0, y0, x1, y1 := b.chestBox[0], b.chestBox[1], b.chestBox[2], b.chestBox[3]
		for y := y0; y <= y1; y++ {
			for x := x0; x <= x1; x++ {
				k.roomOf[y*b.w+x] = int8(k.chest - 1)
			}
		}
	}
}

// trace is one step of the search's history: the step it came from and the
// action taken.
type trace struct {
	parent int
	act    uint8
}

// replay commits the actions on the search's history path ending at i.
func (k *walker) replay(past []trace, i int) bool {
	var acts []uint8
	for ; i >= 0; i = past[i].parent {
		acts = append(acts, past[i].act)
	}
	for j := len(acts) - 1; j >= 0; j-- {
		t := k.trial(acts[j])
		if !clean(t) {
			return false
		}
		k.commit(acts[j])
	}
	return true
}

package torchbeat

import (
	"strconv"
	"strings"

	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/sim"
)

// Verify runs Reveal's checks and replay for a run without a commit and
// without writing anything. With owner set it also checks that owner holds the
// relic and has unlocked the room; with owner "" only the relic's range is
// checked. An owner that is not a valid lowercase address fails first with
// "owner". It never panics and returns
// {"ok":true,"beats":N,"damage":D,"stars":S,"route":"hex"}, S being the star
// bits this run earns, or {"ok":false,"reason":"<code>","beat":N} with Reveal's
// reason code (or "owner") and, for a failed run, the beat it failed on (else
// 0).
func Verify(roomID, log string, relic int, owner string) string {
	var res sim.Result
	var r *Room
	why := ""
	if owner != "" && (owner != strings.ToLower(owner) || !address(owner).IsValid()) {
		why = "owner"
	}
	if why == "" {
		r, why = playable(roomID, log)
	}
	if why == "" {
		res, why = replay(r, owner, log, relic)
	}
	if why != "" {
		b := []byte(`{"ok":false`)
		b = appendField(b, "reason", false)
		b = appendQuoted(b, why)
		b = appendField(b, "beat", false)
		b = appendInt(b, int(res.FailBeat))
		return string(append(b, '}'))
	}
	b := []byte(`{"ok":true`)
	b = appendField(b, "beats", false)
	b = appendInt(b, int(res.Beats))
	b = appendField(b, "damage", false)
	b = appendInt(b, int(res.Damage))
	b = appendField(b, "stars", false)
	b = appendInt(b, int(starsFor(r, res)))
	b = appendField(b, "route", false)
	b = appendQuoted(b, routeHex(res.RouteHash))
	return string(append(b, '}'))
}

// PlayerData returns a player's totals and per-room records as JSON:
// {"renown":..,"relics":..,"stars":..,"cleared":N,"rooms":[{"id":..,"best":..,"damage":..,"stars":..}]}
// with rooms sorted by ID. An unknown or invalid address reads as all zeros.
func PlayerData(addr string) string {
	var p Player
	valid := address(addr).IsValid()
	if valid {
		if v := playerOf(addr, false); v != nil {
			p = *v
		}
	}
	b := []byte{'{'}
	b = appendField(b, "renown", true)
	b = appendInt(b, p.Renown)
	b = appendField(b, "relics", false)
	b = appendInt(b, p.Relics)
	b = appendField(b, "stars", false)
	b = appendInt(b, p.Stars)
	b = appendField(b, "cleared", false)
	b = appendInt(b, p.Cleared)
	b = appendField(b, "rooms", false)
	b = append(b, '[')
	if valid && p.Cleared > 0 {
		prefix := progressKey(addr, "")
		// '}' is the byte after '|', so the range holds exactly this prefix.
		progress.Iterate(prefix, addr+"}", func(k string, v any) bool {
			pr := v.(*Progress)
			if b[len(b)-1] != '[' {
				b = append(b, ',')
			}
			b = append(b, '{')
			b = appendField(b, "id", true)
			b = appendQuoted(b, strings.TrimPrefix(k, prefix))
			b = appendField(b, "best", false)
			b = appendInt(b, int(pr.Best))
			b = appendField(b, "damage", false)
			b = appendInt(b, int(pr.Damage))
			b = appendField(b, "stars", false)
			b = appendInt(b, int(pr.Stars))
			b = append(b, '}')
			return false
		})
	}
	return string(append(b, ']', '}'))
}

// Board returns roomID's top runs, best first, as a JSON array:
// [{"owner":..,"beats":..,"damage":..,"route":"hex","log":..,"height":..,"relic":..}].
// An unknown room or an empty board is [].
func Board(roomID string) string {
	b := []byte{'['}
	if v := boards.Get(roomID); v != nil {
		for i, e := range v.([]Run) {
			if i > 0 {
				b = append(b, ',')
			}
			b = append(b, '{')
			b = appendField(b, "owner", true)
			b = appendQuoted(b, e.Owner.String())
			b = appendField(b, "beats", false)
			b = appendInt(b, int(e.Beats))
			b = appendField(b, "damage", false)
			b = appendInt(b, int(e.Damage))
			b = appendField(b, "route", false)
			b = appendQuoted(b, routeHex(e.Route))
			b = appendField(b, "log", false)
			b = appendQuoted(b, e.Log)
			b = appendField(b, "height", false)
			b = append(b, strconv.FormatInt(e.Height, 10)...)
			b = appendField(b, "relic", false)
			b = appendInt(b, int(e.Relic))
			b = append(b, '}')
		}
	}
	return string(append(b, ']'))
}

// HasCleared reports whether addr has cleared roomID.
func HasCleared(addr address, roomID string) bool {
	return progress.Has(progressKey(addr.String(), roomID))
}

// RoomsCleared returns how many rooms addr has cleared.
func RoomsCleared(addr address) int {
	if p := playerOf(addr.String(), false); p != nil {
		return p.Cleared
	}
	return 0
}

// Renown returns the number of unique clearers, addr itself excluded, over the
// rooms addr authored.
func Renown(addr address) int {
	if p := playerOf(addr.String(), false); p != nil {
		return p.Renown
	}
	return 0
}

// RoomCounts returns roomID's clears and unique clearers, or (0, 0) for an
// unknown room.
func RoomCounts(roomID string) (clears, uniques int) {
	if v := rooms.Get(roomID); v != nil {
		r := v.(*Room)
		return r.Clears, r.Uniques
	}
	return 0, 0
}

// Package torchbeat is the Torchbeat hub: the shared world map that room realms
// publish onto, and its read API.
package torchbeat

import (
	"chain"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/sim"
)

// RoomStatic is what a room fixes at publish time. It sits behind a pointer so
// that updating a room's counters does not rewrite it.
type RoomStatic struct {
	Map                    sim.Map
	Grid, Props, Objective string
	Par                    uint16 // beats of the author's proof
	Proof                  string
	Chest                  int // relic in the chest: 0 none, 1 or 2
	Canon                  uint32
}

// Room is a published room: its static data plus counters.
type Room struct {
	ID, Name        string // ID is the room realm's package path
	Author          address
	Static          *RoomStatic
	Clears, Uniques int
	Hidden          bool
	X, Y            int8
	Opened          int64 // block height
}

var (
	owner  *ownable.Ownable
	rooms  = avl.NewTree() // room ID -> *Room
	world  = avl.NewTree() // cellKey(x, y) -> room ID
	canons = avl.NewTree() // canonKey(hash) -> room ID
	newest = avl.NewTree() // pad4(publish sequence) -> room ID
	// hiddenRooms holds the IDs of hidden rooms, so the home page can list
	// them without walking every room.
	hiddenRooms = avl.NewTree() // room ID -> nil
)

func init(cur realm) {
	owner = ownable.NewWithAddress(cur.Previous().Address())
}

// SetHidden hides or shows a room on the map (admin only). A hidden room keeps
// its cell, still counts for adjacency, and is listed on the home page.
func SetHidden(cur realm, roomID string, hidden bool) {
	owner.AssertOwnedBy(cur.Previous().Address())
	v := rooms.Get(roomID)
	if v == nil {
		panic("unknown")
	}
	v.(*Room).Hidden = hidden
	flag := "false"
	if hidden {
		flag = "true"
		hiddenRooms.Set(roomID, nil)
	} else {
		hiddenRooms.Remove(roomID)
	}
	chain.Emit("RoomHidden", "room", roomID, "hidden", flag)
}

// Admin is the hub admin's address. The web client reads it so that it never
// makes a browser session key for the admin, whose key can hide rooms and hand
// the role on.
func Admin() string {
	return owner.Owner().String()
}

// TransferAdmin hands the admin role to newOwner (admin only).
func TransferAdmin(cur realm, newOwner address) {
	if err := owner.TransferOwnership(0, cur, newOwner); err != nil {
		panic(err)
	}
}

package torchbeat

const hexDigits = "0123456789abcdef"

// appendQuoted appends s as a JSON string: quote and backslash are
// backslash-escaped, control characters become \u00XX, other bytes pass
// through unchanged.
func appendQuoted(b []byte, s string) []byte {
	b = append(b, '"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"' || c == '\\':
			b = append(b, '\\', c)
		case c < 0x20:
			b = append(b, '\\', 'u', '0', '0', hexDigits[c>>4], hexDigits[c&0xf])
		default:
			b = append(b, c)
		}
	}
	return append(b, '"')
}

// appendField appends `"key":` (key must need no escaping), preceded by a comma
// unless it is the object's first field.
func appendField(b []byte, key string, first bool) []byte {
	if !first {
		b = append(b, ',')
	}
	b = append(b, '"')
	b = append(b, key...)
	return append(b, '"', ':')
}

// appendInt appends n in decimal without strconv (much cheaper for the small
// numbers SVG coordinates are).
func appendInt(b []byte, n int) []byte {
	if n < 0 {
		b = append(b, '-')
		n = -n
	}
	switch {
	case n < 10:
		return append(b, byte('0'+n))
	case n < 100:
		return append(b, byte('0'+n/10), byte('0'+n%10))
	case n < 1000:
		return append(b, byte('0'+n/100), byte('0'+n/10%10), byte('0'+n%10))
	}
	r := n % 1000
	return append(appendInt(b, n/1000), byte('0'+r/100), byte('0'+r/10%10), byte('0'+r%10))
}

func appendBool(b []byte, v bool) []byte {
	if v {
		return append(b, "true"...)
	}
	return append(b, "false"...)
}

package torchbeat

import (
	"chain"
	"chain/runtime"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/commit"
	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/sim"
)

const (
	revealWindow = 600 // blocks a commit stays revealable
	boardSize    = 3
)

// Star bits a run earns on a room.
const (
	starCleared  uint8 = 1
	starFlawless uint8 = 2 // no damage taken
	starPar      uint8 = 4 // beats <= the room's par
)

// Pending is a player's one outstanding commit.
type Pending struct {
	Entry commit.Entry
	Room  string
}

// Player is a player's (or author's) totals.
type Player struct {
	Renown  int // unique clearers, other than itself, of rooms this address authored
	Relics  int // bitmask: bit r set when relic r is owned
	Cleared int // rooms cleared at least once
	Stars   int // sum of star bits over every room
}

// Progress is a player's record on one room.
type Progress struct {
	Best   uint16 // fewest beats; ties keep the lower damage
	Damage uint8  // damage of the Best run
	Stars  uint8  // union of star bits over every clear
}

// Run is a board entry.
type Run struct {
	Owner  address
	Beats  uint16
	Damage uint8
	Route  uint32
	Log    string
	Height int64 // the run's commit height
	Relic  uint8 // the relic the run was played with
}

var (
	commits  = avl.NewTree() // addr -> *Pending
	players  = avl.NewTree() // addr -> *Player
	progress = avl.NewTree() // progressKey(addr, room ID) -> *Progress
	boards   = avl.NewTree() // room ID -> []Run, best first, at most boardSize
	// explorers indexes every player with a clear by explorerKey, so in-order
	// iteration lists the top explorers first. Its size is the number of
	// unique explorers.
	explorers = avl.NewTree()

	totalClears int // every cleared run, all rooms
)

// Commit records hash = commit.Hash(caller, roomID, relic, log, salt) as the
// caller's pending run, replacing any earlier one. User calls only. It panics
// with caller, hash, unknown, or hidden (a hidden room cannot be revealed, so
// a commit to it would only hold storage).
func Commit(cur realm, roomID, hash string) {
	caller := userCaller(cur)
	if !isLowerHex(hash, 64) {
		panic("hash")
	}
	v := rooms.Get(roomID)
	if v == nil {
		panic("unknown")
	}
	if v.(*Room).Hidden {
		panic("hidden")
	}
	commits.Set(caller.String(), &Pending{
		Entry: commit.Entry{Hash: hash, Height: runtime.ChainHeight()},
		Room:  roomID,
	})
}

// Cancel drops the caller's pending commit, if any. User calls only.
func Cancel(cur realm) {
	commits.Remove(userCaller(cur).String())
}

// Reveal replays the caller's committed run on roomID and, if it clears,
// records it and emits Clear. User calls only. It panics with a reason code:
// caller, salt, log, unknown, hidden, none, early, expired, mismatch, relic,
// locked, or "run:" + the sim reason. The commit is kept unless the run clears.
func Reveal(cur realm, roomID, log string, relic int, salt string) {
	player := userCaller(cur)
	if !isLowerHex(salt, 32) {
		panic("salt")
	}
	r, why := playable(roomID, log)
	if why != "" {
		panic(why)
	}
	who := player.String()
	var e commit.Entry
	if v := commits.Get(who); v != nil && v.(*Pending).Room == roomID {
		e = v.(*Pending).Entry
	}
	if why := commit.CheckReveal(e, runtime.ChainHeight(), revealWindow, commit.Hash(who, roomID, relic, log, salt)); why != "" {
		panic(why)
	}
	res, why := replay(r, who, log, relic)
	if why != "" {
		panic(why)
	}
	commits.Remove(who)
	first := record(r, who, res)
	enterBoard(roomID, Run{Owner: player, Beats: res.Beats, Damage: res.Damage, Route: res.RouteHash, Log: log, Height: e.Height, Relic: uint8(relic)})
	chain.Emit("Clear", "room", roomID, "player", who, "beats", strconv.Itoa(int(res.Beats)),
		"route", routeHex(res.RouteHash), "first", strconv.FormatBool(first))
}

func userCaller(cur realm) address {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("caller")
	}
	return prev.Address()
}

// playable checks a log's charset and length and that roomID is a visible room.
func playable(roomID, log string) (*Room, string) {
	if !validLog(log) {
		return nil, "log"
	}
	v := rooms.Get(roomID)
	if v == nil {
		return nil, "unknown"
	}
	r := v.(*Room)
	if r.Hidden {
		return nil, "hidden"
	}
	return r, ""
}

// replay checks the relic and adjacency for player who (skipped when who is
// "", except the relic's range) and runs log. It returns the cleared result or
// a reason code.
func replay(r *Room, who, log string, relic int) (sim.Result, string) {
	if relic < 0 || relic > 2 {
		return sim.Result{}, "relic"
	}
	if who != "" {
		if relic != 0 && relicsOf(who)&(1<<uint(relic)) == 0 {
			return sim.Result{}, "relic"
		}
		x, y := int(r.X), int(r.Y)
		if !reached(who, x+1, y) && !reached(who, x-1, y) && !reached(who, x, y+1) && !reached(who, x, y-1) {
			return sim.Result{}, "locked"
		}
	}
	res := sim.Run(&r.Static.Map, uint8(relic), log)
	if !res.Cleared {
		return res, "run:" + res.Reason
	}
	return res, ""
}

// reached reports whether (x, y) is the hub or a room who has cleared.
func reached(who string, x, y int) bool {
	if x == 0 && y == 0 {
		return true
	}
	v := world.Get(cellKey(x, y))
	return v != nil && progress.Has(progressKey(who, v.(string)))
}

// record applies a cleared run's rewards, keeps the explorers index in step,
// and reports whether it was who's first clear of r.
func record(r *Room, who string, res sim.Result) bool {
	r.Clears++
	totalClears++
	p := playerOf(who, true)
	old := explorerKey(who, p.Cleared, p.Stars)
	first := credit(r, p, who, res)
	if k := explorerKey(who, p.Cleared, p.Stars); k != old {
		if old != "" {
			explorers.Remove(old)
		}
		explorers.Set(k, nil)
	}
	return first
}

// explorerKey is who's key in the explorers index, or "" for a player without
// a clear: 4 digits of 9999 - cleared, 4 of 9999 - stars, then the address, so
// more rooms sort first, then more stars, then the lower address. Counts are
// clamped to 9999 (at most 1088 rooms exist, so they never reach it).
func explorerKey(who string, cleared, stars int) string {
	if cleared <= 0 {
		return ""
	}
	return pad4(9999-min9999(cleared)) + pad4(9999-min9999(stars)) + who
}

func min9999(n int) int {
	if n > 9999 {
		return 9999
	}
	return n
}

// pad4 formats 0 <= n <= 9999 as 4 digits. Its callers stay in range: the
// explorer counts are clamped, and the publish sequence (the newest index)
// stays below the 1088 cells a world has (33x33 minus the hub), far under
// 10000.
func pad4(n int) string {
	s := strconv.Itoa(n)
	return "0000"[len(s):] + s
}

// credit applies a cleared run to r and p and reports whether it was who's
// first clear of r. A first clear counts toward Uniques and, unless who is the
// author, the author's renown. Opening the chest grants its relic on any clear.
func credit(r *Room, p *Player, who string, res sim.Result) bool {
	if c := r.Static.Chest; c != 0 && res.Chest {
		p.Relics |= 1 << uint(c)
	}
	earned := starsFor(r, res)
	key := progressKey(who, r.ID)
	v := progress.Get(key)
	if v == nil {
		progress.Set(key, &Progress{Best: res.Beats, Damage: res.Damage, Stars: earned})
		p.Cleared++
		p.Stars += popcount(earned)
		r.Uniques++
		if author := r.Author.String(); author != who {
			playerOf(author, true).Renown++
		}
		return true
	}
	pr := v.(*Progress)
	p.Stars += popcount(earned &^ pr.Stars)
	pr.Stars |= earned
	if res.Beats < pr.Best || (res.Beats == pr.Best && res.Damage < pr.Damage) {
		pr.Best, pr.Damage = res.Beats, res.Damage
	}
	return false
}

func starsFor(r *Room, res sim.Result) uint8 {
	s := starCleared
	if res.Damage == 0 {
		s |= starFlawless
	}
	if res.Beats <= r.Static.Par {
		s |= starPar
	}
	return s
}

func popcount(b uint8) int {
	n := 0
	for ; b != 0; b &= b - 1 {
		n++
	}
	return n
}

// enterBoard stores run on roomID's board if it ranks.
func enterBoard(roomID string, run Run) {
	var b []Run
	if v := boards.Get(roomID); v != nil {
		b = v.([]Run)
	}
	if nb, ok := rankRun(b, run); ok {
		boards.Set(roomID, nb)
	}
}

// rankRun returns b with run placed in rank order and cut to boardSize, and
// true; or b and false when run does not enter. An owner holds at most one
// slot: their run replaces their entry only when it is better, else it is
// ignored. A route on b belongs to its first finder, so another owner's run on
// it never enters. A newcomer to a full board must beat its worst entry. b is
// never modified.
func rankRun(b []Run, run Run) ([]Run, bool) {
	mine := -1
	for i, e := range b {
		if e.Owner == run.Owner {
			mine = i
		} else if e.Route == run.Route {
			return b, false
		}
	}
	rest := b
	if mine >= 0 {
		if !better(run, b[mine]) {
			return b, false
		}
		rest = make([]Run, 0, len(b)-1)
		rest = append(rest, b[:mine]...)
		rest = append(rest, b[mine+1:]...)
	} else if len(b) >= boardSize && !better(run, b[len(b)-1]) {
		return b, false
	}
	i := 0
	for i < len(rest) && !better(run, rest[i]) {
		i++
	}
	n := len(rest) + 1
	if n > boardSize {
		n = boardSize
	}
	nb := make([]Run, 0, n)
	nb = append(nb, rest[:i]...)
	nb = append(nb, run)
	for j := i; j < len(rest) && len(nb) < n; j++ {
		nb = append(nb, rest[j])
	}
	return nb, true
}

// better ranks by beats, then damage, then commit height, all ascending.
func better(a, b Run) bool {
	if a.Beats != b.Beats {
		return a.Beats < b.Beats
	}
	if a.Damage != b.Damage {
		return a.Damage < b.Damage
	}
	return a.Height < b.Height
}

// playerOf returns who's record, creating it if create is set (else nil when
// absent).
func playerOf(who string, create bool) *Player {
	if v := players.Get(who); v != nil {
		return v.(*Player)
	}
	if !create {
		return nil
	}
	p := &Player{}
	players.Set(who, p)
	return p
}

func relicsOf(who string) int {
	if p := playerOf(who, false); p != nil {
		return p.Relics
	}
	return 0
}

// progressKey is "addr|roomID"; '|' sorts after every bech32 character, so
// one player's rooms form a contiguous range.
func progressKey(who, roomID string) string {
	return who + "|" + roomID
}

// validLog accepts 1 to sim.MaxBeats chars of '0'..'8'.
func validLog(log string) bool {
	if len(log) == 0 || len(log) > sim.MaxBeats {
		return false
	}
	for i := 0; i < len(log); i++ {
		if log[i] < '0' || log[i] > '8' {
			return false
		}
	}
	return true
}

func isLowerHex(s string, n int) bool {
	if len(s) != n {
		return false
	}
	for i := 0; i < n; i++ {
		c := s[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

// routeHex is h as 8 lowercase hex chars.
func routeHex(h uint32) string {
	var b [8]byte
	for i := 7; i >= 0; i-- {
		b[i] = hexDigits[h&0xf]
		h >>= 4
	}
	return string(b[:])
}

package torchbeat

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/sim"
	"gno.land/r/sys/names"
)

const (
	maxCoord    = 16 // cells lie in [-16, 16] on both axes
	minPar      = 12 // the proof must take at least this many beats
	realmPrefix = "gno.land/r/"
)

// Publish puts the calling room realm on the world map. A user calls a crossing
// function of the room realm, which calls Publish; the room's package path is
// its ID and the user is its author. It panics with a reason code (see check).
func Publish(cur realm, name, objective, grid, props string, cellX, cellY, chestRelic int, proofLog string) {
	prev := cur.Previous()
	if !prev.IsCode() || prev.Subpath() != "" {
		panic("caller")
	}
	pp := prev.Previous()
	if !pp.IsUserCall() {
		panic("caller")
	}
	if why := publish(pp.Address(), prev.PkgPath(), name, objective, grid, props, cellX, cellY, chestRelic, proofLog); why != "" {
		panic(why)
	}
}

// CheckRoom runs Publish's checks for roomID without writing anything and
// returns "" or the reason code Publish would give. The caller is unknown, so
// the namespace is not checked against an author and the launch ring (reserved
// for the hub admin) always reads "cell".
func CheckRoom(roomID, name, objective, grid, props string, cellX, cellY, chestRelic int, proofLog string) string {
	_, why := check("", roomID, name, objective, grid, props, cellX, cellY, chestRelic, proofLog)
	return why
}

// publish checks a room for author and, if it passes, stores it and emits
// RoomOpened. It returns "" or a reason code.
func publish(author address, roomID, name, objective, grid, props string, cellX, cellY, chestRelic int, proofLog string) string {
	st, why := check(author, roomID, name, objective, grid, props, cellX, cellY, chestRelic, proofLog)
	if why != "" {
		return why
	}
	rooms.Set(roomID, &Room{
		ID:     roomID,
		Name:   name,
		Author: author,
		Static: st,
		X:      int8(cellX),
		Y:      int8(cellY),
		Opened: runtime.ChainHeight(),
	})
	world.Set(cellKey(cellX, cellY), roomID)
	canons.Set(canonKey(st.Canon), roomID)
	// Rooms are never removed, so the tree's size is the publish sequence.
	newest.Set(pad4(newest.Size()), roomID)
	chain.Emit("RoomOpened", "room", roomID, "author", author.String(),
		"x", strconv.Itoa(cellX), "y", strconv.Itoa(cellY))
	return ""
}

// check runs every Publish check after the caller's, in order: namespace, dup,
// name, objective, the sim parse/validate codes, cell, canon, chest, proof,
// par. An empty author is an anonymous caller (CheckRoom).
func check(author address, roomID, name, objective, grid, props string, cellX, cellY, chestRelic int, proofLog string) (*RoomStatic, string) {
	ns := namespace(roomID)
	if ns == "" || (author != "" && !names.IsAuthorizedAddressForNamespace(author, ns)) {
		return nil, "namespace"
	}
	if rooms.Has(roomID) {
		return nil, "dup"
	}
	if !validName(name) {
		return nil, "name"
	}
	if objective != "EXIT" && objective != "SLAY" {
		return nil, "objective"
	}
	m, why := sim.Parse(grid, props, objective)
	if why == "" {
		why = sim.Validate(&m)
	}
	if why != "" {
		return nil, why
	}
	if !cellOpen(author, cellX, cellY) {
		return nil, "cell"
	}
	h := sim.CanonHash(&m)
	if canons.Has(canonKey(h)) {
		return nil, "canon"
	}
	if m.HasChest {
		if chestRelic != 1 && chestRelic != 2 {
			return nil, "chest"
		}
	} else if chestRelic != 0 {
		return nil, "chest"
	}
	r := sim.Run(&m, 0, proofLog)
	if !r.Cleared {
		return nil, "proof"
	}
	if r.Beats < minPar {
		return nil, "par"
	}
	return &RoomStatic{
		Map:       m,
		Grid:      normGrid(grid),
		Props:     props,
		Objective: objective,
		Par:       r.Beats,
		Proof:     proofLog,
		Chest:     chestRelic,
		Canon:     h,
	}, ""
}

// normGrid normalizes a grid as sim.Parse does: CRLF becomes LF, then one
// leading and one trailing newline are dropped. Parse rejects any other CR, so
// a stored grid never holds one.
func normGrid(s string) string {
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.TrimPrefix(s, "\n")
	return strings.TrimSuffix(s, "\n")
}

// namespace returns <ns> from "gno.land/r/<ns>/<rest>", or "" for any other
// shape.
func namespace(roomID string) string {
	if !strings.HasPrefix(roomID, realmPrefix) {
		return ""
	}
	rest := roomID[len(realmPrefix):]
	i := strings.IndexByte(rest, '/')
	if i <= 0 || i == len(rest)-1 {
		return ""
	}
	return rest[:i]
}

// validName accepts 3 to 24 chars of [A-Za-z0-9 -], not starting or ending
// with a space.
func validName(s string) bool {
	n := len(s)
	if n < 3 || n > 24 || s[0] == ' ' || s[n-1] == ' ' {
		return false
	}
	for i := 0; i < n; i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == ' ' || c == '-') {
			return false
		}
	}
	return true
}

// cellOpen reports whether author may open a room at (x, y): in bounds, not the
// hub, free, orthogonally next to the hub or a room (hidden ones included), and
// outside the launch ring (the 8 cells around the hub) unless author is the
// hub admin.
func cellOpen(author address, x, y int) bool {
	if x < -maxCoord || x > maxCoord || y < -maxCoord || y > maxCoord || (x == 0 && y == 0) {
		return false
	}
	if world.Has(cellKey(x, y)) {
		return false
	}
	if x >= -1 && x <= 1 && y >= -1 && y <= 1 && (author == "" || !owner.OwnedBy(author)) {
		return false
	}
	return occupied(x+1, y) || occupied(x-1, y) || occupied(x, y+1) || occupied(x, y-1)
}

// occupied reports whether (x, y) is the hub or holds a room.
func occupied(x, y int) bool {
	return (x == 0 && y == 0) || world.Has(cellKey(x, y))
}

func cellKey(x, y int) string {
	return strconv.Itoa(x) + "," + strconv.Itoa(y)
}

func canonKey(h uint32) string {
	return strconv.FormatUint(uint64(h), 16)
}

// World returns every room as a JSON array sorted by ID:
// [{"id":..,"name":..,"x":..,"y":..,"clears":..,"hidden":..}].
func World() string {
	b := []byte{'['}
	rooms.Iterate("", "", func(_ string, v any) bool {
		r := v.(*Room)
		if len(b) > 1 {
			b = append(b, ',')
		}
		b = append(b, '{')
		b = appendField(b, "id", true)
		b = appendQuoted(b, r.ID)
		b = appendField(b, "name", false)
		b = appendQuoted(b, r.Name)
		b = appendField(b, "x", false)
		b = appendInt(b, int(r.X))
		b = appendField(b, "y", false)
		b = appendInt(b, int(r.Y))
		b = appendField(b, "clears", false)
		b = appendInt(b, r.Clears)
		b = appendField(b, "hidden", false)
		b = appendBool(b, r.Hidden)
		b = append(b, '}')
		return false
	})
	return string(append(b, ']'))
}

// RoomData returns a room as JSON (grid, props, objective, par, author, x, y,
// clears, uniques, chest), or "{}" for an unknown room.
func RoomData(roomID string) string {
	v := rooms.Get(roomID)
	if v == nil {
		return "{}"
	}
	r := v.(*Room)
	s := r.Static
	b := []byte{'{'}
	b = appendField(b, "grid", true)
	b = appendQuoted(b, s.Grid)
	b = appendField(b, "props", false)
	b = appendQuoted(b, s.Props)
	b = appendField(b, "objective", false)
	b = appendQuoted(b, s.Objective)
	b = appendField(b, "par", false)
	b = appendInt(b, int(s.Par))
	b = appendField(b, "author", false)
	b = appendQuoted(b, r.Author.String())
	b = appendField(b, "x", false)
	b = appendInt(b, int(r.X))
	b = appendField(b, "y", false)
	b = appendInt(b, int(r.Y))
	b = appendField(b, "clears", false)
	b = appendInt(b, r.Clears)
	b = appendField(b, "uniques", false)
	b = appendInt(b, r.Uniques)
	b = appendField(b, "chest", false)
	b = appendInt(b, s.Chest)
	return string(append(b, '}'))
}

package torchbeat

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/sys/users"
)

const (
	hubPath = "/r/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/v1" // deploy rewrites the namespace
	playURL = "https://torchbeat.vercel.app"

	topExplorersShown = 10
	newestShown       = 5
	hiddenShown       = 32 // hidden rooms listed on the home page; the rest are counted
)

// Render serves the hub's pages: "" (home and world map), "room/<id>" (a room
// with its best run replayed) and "player/<addr>". A query string is ignored.
// Every page is bounded: the map has at most 1089 cells, lists are capped, and
// a room page replays one run of at most sim.MaxBeats beats.
func Render(path string) string {
	if i := strings.IndexByte(path, '?'); i >= 0 {
		path = path[:i]
	}
	switch {
	case path == "":
		return renderHome()
	case strings.HasPrefix(path, "room/"):
		if v := rooms.Get(path[len("room/"):]); v != nil {
			return renderRoom(v.(*Room))
		}
	case strings.HasPrefix(path, "player/"):
		// bech32 is case-insensitive but every key here is lowercase, so an
		// uppercase address renders the canonical page.
		if a := strings.ToLower(path[len("player/"):]); address(a).IsValid() {
			return renderPlayer(a)
		}
	}
	return "# Not found\n\n" + playLine("") + "Nothing lives at this path. [Back to the world map](" + hubPath + ").\n"
}

// mdText escapes s for inline Markdown (headings, link text).
func mdText(s string) string { return sanitize.InlineText(s) }

// mdCell escapes s for a Markdown table cell.
func mdCell(s string) string { return sanitize.TableCell(s) }

// shortAddr shortens a bech32 address to g1abcd…wxyz.
func shortAddr(a string) string {
	if len(a) <= 10 {
		return a
	}
	return a[:6] + "…" + a[len(a)-4:]
}

func roomLink(r *Room) string {
	return "[" + mdText(r.Name) + "](" + hubPath + ":room/" + r.ID + ")"
}

// displayName is a's r/sys/users name as "@name", or the shortened address
// when it has none (or the user was deleted). Callers escape it.
func displayName(a string) string {
	if u := users.ResolveAddress(address(a)); u != nil {
		return "@" + u.Name()
	}
	return shortAddr(a)
}

// playerLink links a's player page by address, shown by displayName.
func playerLink(a string) string {
	return "[" + mdText(displayName(a)) + "](" + hubPath + ":player/" + a + ")"
}

// playLine is the primary Play link, plus extra links, as a paragraph.
func playLine(extra string) string {
	return "**[Play Torchbeat](" + playURL + ")**" + extra + "\n\n"
}

func image(alt string, svg []byte) string {
	return "![" + mdText(alt) + "](" + dataURI(svg) + ")\n\n"
}

// pageSlack is room for a page's text besides its one image: a Builder grows
// by recopying, so each page sizes it up front.
const pageSlack = 8 << 10

func bold(n int) string { return "**" + strconv.Itoa(n) + "**" }

var relicNames = [3]string{"", "Featherboots", "Ironheart"}

// ---- Home ----

type explorer struct {
	addr           string
	cleared, stars int
}

// topExplorers returns the first n entries of the explorers index.
func topExplorers(n int) []explorer {
	var out []explorer
	explorers.IterateByOffset(0, n, func(k string, _ any) bool {
		c, _ := strconv.Atoi(k[0:4])
		s, _ := strconv.Atoi(k[4:8])
		out = append(out, explorer{k[8:], 9999 - c, 9999 - s})
		return false
	})
	return out
}

// newestRooms returns up to n visible rooms, newest first.
func newestRooms(n int) []*Room {
	var out []*Room
	newest.ReverseIterate("", "", func(_ string, v any) bool {
		r := rooms.Get(v.(string)).(*Room)
		if !r.Hidden {
			out = append(out, r)
		}
		return len(out) >= n
	})
	return out
}

func renderHome() string {
	img := image("World map: the hub in gold, rooms brighter with more clears, the newest pulsing", worldSVG(false, nil))
	var b strings.Builder
	b.Grow(len(img) + pageSlack)
	b.WriteString("# Torchbeat\n\n*A dungeon the gno.land community digs together.*\n\n")
	b.WriteString(playLine(""))
	b.WriteString(img)

	b.WriteString(bold(rooms.Size()) + " rooms · " + bold(explorers.Size()) + " explorers · " + bold(totalClears) + " clears\n\n")

	b.WriteString("## Top explorers\n\n")
	if top := topExplorers(topExplorersShown); len(top) == 0 {
		b.WriteString("No clears yet. Be the first.\n\n")
	} else {
		b.WriteString("| # | Explorer | Rooms | Stars |\n| ---: | --- | ---: | ---: |\n")
		for i, e := range top {
			b.WriteString("| " + strconv.Itoa(i+1) + " | " + playerLink(e.addr) + " | " +
				strconv.Itoa(e.cleared) + " | " + strconv.Itoa(e.stars) + " |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Newest rooms\n\n")
	if nr := newestRooms(newestShown); len(nr) == 0 {
		b.WriteString("No rooms yet.\n")
	} else {
		for _, r := range nr {
			b.WriteString("- " + roomLink(r) + " by " + playerLink(r.Author.String()) +
				" at (" + strconv.Itoa(int(r.X)) + ", " + strconv.Itoa(int(r.Y)) + ")\n")
		}
	}

	b.WriteString("\n## Hidden rooms\n\n")
	writeHiddenRooms(&b)

	b.WriteString("\n## How to play\n\n")
	b.WriteString("1. [Open the game](" + playURL + "): hold a direction to glide tile to tile on the beat, Shift or Space to dash.\n")
	b.WriteString("2. Clear a room next to one you have cleared (the hub counts) to open it on your map.\n")
	b.WriteString("3. Sign in to keep a clear: the chain replays your inputs beat by beat, and only a replayed clear counts.\n")

	b.WriteString("\n## Build a room\n\n")
	b.WriteString("1. Paint and test-play a room in the [Forge](" + playURL + "); your clear becomes its proof and par.\n")
	b.WriteString("2. Deploy the exported `room.gno` to your own namespace with `gnokey maketx addpkg`.\n")
	b.WriteString("3. Call its `Publish` with `gnokey maketx call` and it opens on this map, next to a room that is already here.\n")
	return b.String()
}

// writeHiddenRooms lists the first hiddenShown hidden rooms by ID, each linked
// to its room page, and counts the rest.
func writeHiddenRooms(b *strings.Builder) {
	n := hiddenRooms.Size()
	if n == 0 {
		b.WriteString("No room is hidden.\n")
		return
	}
	noun := " rooms"
	if n == 1 {
		noun = " room"
	}
	b.WriteString("The admin has hidden " + bold(n) + noun + ". A hidden room keeps its cell but cannot be cleared.\n\n")
	hiddenRooms.IterateByOffset(0, hiddenShown, func(id string, _ any) bool {
		b.WriteString("- [" + mdText(id) + "](" + hubPath + ":room/" + id + "), hidden by the admin\n")
		return false
	})
	if n > hiddenShown {
		b.WriteString("\n...and " + strconv.Itoa(n-hiddenShown) + " more (`World()` lists every room with its hidden flag).\n")
	}
}

// ---- Room ----

func renderRoom(r *Room) string {
	cell := "(" + strconv.Itoa(int(r.X)) + ", " + strconv.Itoa(int(r.Y)) + ")"
	if r.Hidden {
		return "# Hidden room\n\n" + playLine(" · [World map]("+hubPath+")") +
			"The hub admin hid this room. It keeps its cell " + cell + " on the map.\n"
	}
	s := r.Static
	var board []Run
	if v := boards.Get(r.ID); v != nil {
		board = v.([]Run)
	}

	var img string
	if len(board) == 0 {
		img = image(r.Name, roomSVG(r, nil))
	} else {
		top := board[0]
		img = image(r.Name+", its best run replayed by the chain", roomSVG(r, &top))
	}
	var b strings.Builder
	b.Grow(len(img) + pageSlack)
	b.WriteString("# " + mdText(r.Name) + "\n\n")
	extra := ""
	if len(board) > 0 {
		// The relic rides along: a log replays only with the relic it was played with.
		extra = " · [Race this run](" + playURL + "/#/dare/" + r.ID + "/" + strconv.Itoa(int(board[0].Relic)) + "/" + board[0].Log + ")"
	}
	b.WriteString(playLine(extra + " · [World map](" + hubPath + ")"))

	objective := "reach the exit"
	if s.Objective == "SLAY" {
		objective = "slay every foe"
	}
	b.WriteString("By " + playerLink(r.Author.String()) + " · cell " + cell + " · " + objective +
		" · par " + bold(int(s.Par)) + " beats · " + bold(r.Clears) + " clears · " + bold(r.Uniques) + " explorers")
	if s.Chest != 0 {
		b.WriteString(" · chest: " + relicNames[s.Chest])
	}
	b.WriteString("\n\n")

	if len(board) == 0 {
		b.WriteString(img)
		b.WriteString("No clears yet. [Be the first](" + playURL + ").\n\n")
	} else {
		top := board[0]
		b.WriteString(img)
		b.WriteString("*The best run, replayed by the chain: " + strconv.Itoa(int(top.Beats)) + " beats by " + playerLink(top.Owner.String()))
		if top.Relic != 0 {
			b.WriteString(" with " + relicNames[top.Relic])
		}
		b.WriteString(".*\n\n## Board\n\n| # | Player | Beats | Damage | Route |\n| ---: | --- | ---: | ---: | --- |\n")
		for i, e := range board {
			b.WriteString("| " + strconv.Itoa(i+1) + " | " + playerLink(e.Owner.String()) + " | " +
				strconv.Itoa(int(e.Beats)) + " | " + strconv.Itoa(int(e.Damage)) + " | `" + routeHex(e.Route) + "` |\n")
		}
		b.WriteString("\n")
	}
	b.WriteString("Room realm: [" + mdText(r.ID) + "](" + strings.TrimPrefix(r.ID, "gno.land") + ")\n")
	return b.String()
}

// ---- Player ----

func renderPlayer(a string) string {
	var p Player
	if v := playerOf(a, false); v != nil {
		p = *v
	}

	cleared := map[string]bool{}
	var rows strings.Builder
	if p.Cleared > 0 {
		rows.Grow(p.Cleared * 160)
		prefix := progressKey(a, "")
		// '}' is the byte after '|', so the range holds exactly this prefix.
		progress.Iterate(prefix, a+"}", func(k string, v any) bool {
			id := k[len(prefix):]
			cleared[id] = true
			pr := v.(*Progress)
			name := "*hidden room*"
			if rv := rooms.Get(id); rv != nil && !rv.(*Room).Hidden {
				name = roomLink(rv.(*Room))
			}
			rows.WriteString("| " + name + " | " + strconv.Itoa(int(pr.Best)) + " | " +
				strconv.Itoa(int(pr.Damage)) + " | " + starGlyphs(pr.Stars) + " |\n")
			return false
		})
	}
	img := image("World map with the rooms this explorer cleared in green", worldSVG(true, cleared))

	var b strings.Builder
	b.Grow(len(img) + rows.Len() + pageSlack)
	b.WriteString("# Explorer " + mdText(displayName(a)) + "\n\n")
	b.WriteString(playLine(" · [World map](" + hubPath + ")"))
	b.WriteString(mdText(a) + "\n\n")
	b.WriteString(bold(p.Renown) + " renown · " + bold(p.Cleared) + " rooms cleared · " + bold(p.Stars) + " stars · relics: ")
	held := ""
	for i := 1; i < len(relicNames); i++ {
		if p.Relics&(1<<uint(i)) != 0 {
			if held != "" {
				held += ", "
			}
			held += relicNames[i]
		}
	}
	if held == "" {
		held = "none"
	}
	b.WriteString(held + "\n\n")
	b.WriteString(img)
	b.WriteString("## Cleared rooms\n\n")
	if rows.Len() == 0 {
		b.WriteString("No clears yet. [Start in the hub](" + playURL + ").\n")
	} else {
		b.WriteString("| Room | Best beats | Damage | Stars |\n| --- | ---: | ---: | --- |\n")
		b.WriteString(rows.String())
	}
	return b.String()
}

// starGlyphs shows a room's star bits (clear, flawless, par) as three stars.
func starGlyphs(bits uint8) string {
	s := ""
	for _, bit := range []uint8{starCleared, starFlawless, starPar} {
		if bits&bit != 0 {
			s += "★"
		} else {
			s += "☆"
		}
	}
	return s
}

package torchbeat

import (
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/sim"
)

// The SVG here is written straight into a data URI (see dataURI), so svgW
// output is "URI-ready": every '#' is written pre-encoded as %23 and a '%'
// from text as %25. Gas shapes the rest: GnoVM charges per operation, so the
// writers append whole strings into a buffer sized up front (growing a slice
// recopies it), format small numbers by hand (strconv.Itoa costs ~25k gas),
// and precompute the strings a replay repeats.

const sharp = "%23" // '#'

// Palette: every color the pages draw with.
const (
	colBG        = sharp + "14110f"
	colFloor     = sharp + "2a2420"
	colWall      = sharp + "4a3f36"
	colWallFace  = sharp + "352d27" // the south face of a wall above a lower tile
	colPit       = sharp + "000000"
	colSpikes    = sharp + "8a8378"
	colCrumble   = sharp + "6b5a48"
	colPlate     = sharp + "3d6b5a"
	colGate      = sharp + "b08d57"
	colGateOpen  = sharp + "5a4a30"
	colChest     = sharp + "d9a441"
	colExit      = sharp + "5fbf77"
	colHub       = sharp + "e8b04a"
	colHero      = sharp + "f2e3c6"
	colSlime     = sharp + "7bc96f"
	colArcher    = sharp + "d07a6a"
	colBrute     = sharp + "9a7bd0"
	colGargoyle  = sharp + "6f93c9"
	colFireball  = sharp + "ff8a3d"
	colArrow     = sharp + "e0d4b0"
	colCleared   = colExit          // player map: a room the player cleared
	colUncharted = sharp + "2e2723" // player map: a room the player has not cleared
)

// shade is a world-map room color for clear-count step 0-3 (see shadeStep).
func shade(step int) string {
	switch step {
	case 0:
		return sharp + "3b322b"
	case 1:
		return sharp + "5e4b37"
	case 2:
		return sharp + "8c6a40"
	}
	return sharp + "bd8d47"
}

// shadeStep buckets a room's clears: 0, 1-9, 10-49, 50 and more.
func shadeStep(clears int) int {
	switch {
	case clears == 0:
		return 0
	case clears < 10:
		return 1
	case clears < 50:
		return 2
	}
	return 3
}

// svgW builds URI-ready SVG. raw writes trusted markup; text and attr escape
// & < > " ' as XML entities (and # % for the URI), so no value can end the
// attribute or element it sits in. Every room name and address goes through
// text or attr.
type svgW struct{ b []byte }

func newSVG(capacity int) *svgW { return &svgW{b: make([]byte, 0, capacity)} }

func (w *svgW) raw(s string) { w.b = append(w.b, s...) }

func (w *svgW) int(n int) { w.b = appendInt(w.b, n) }

func (w *svgW) text(s string) {
	start := 0
	for i := 0; i < len(s); i++ {
		var rep string
		switch s[i] {
		case '&':
			rep = "&amp;"
		case '<':
			rep = "&lt;"
		case '>':
			rep = "&gt;"
		case '"':
			rep = "&quot;"
		case '\'':
			rep = "&apos;"
		case '#':
			rep = sharp
		case '%':
			rep = "%25"
		default:
			continue
		}
		w.b = append(w.b, s[start:i]...)
		w.b = append(w.b, rep...)
		start = i + 1
	}
	w.b = append(w.b, s[start:]...)
}

// attr writes ` name="value"` with value escaped.
func (w *svgW) attr(name, value string) {
	w.raw(" " + name + `="`)
	w.text(value)
	w.b = append(w.b, '"')
}

// num writes ` name="n"`.
func (w *svgW) num(name string, n int) {
	w.raw(" " + name + `="`)
	w.b = append(appendInt(w.b, n), '"')
}

// rect writes a rect; fill is trusted (a palette color or url(...)).
func (w *svgW) rect(x, y, width, height int, fill string) {
	w.raw(`<rect x="`)
	w.int(x)
	w.raw(`" y="`)
	w.int(y)
	w.raw(`" width="`)
	w.int(width)
	w.raw(`" height="`)
	w.int(height)
	w.raw(`" fill="` + fill + `"/>`)
}

// path writes a path with a trusted fill, skipping an empty d.
func (w *svgW) path(d []byte, fill string) {
	if len(d) == 0 {
		return
	}
	w.raw(`<path fill="` + fill + `" d="`)
	w.b = append(w.b, d...)
	w.raw(`"/>`)
}

// open writes <svg ...> showing a vw x vh viewBox at width x height.
func (w *svgW) open(width, height, vw, vh int) {
	w.raw(`<svg xmlns="http://www.w3.org/2000/svg" width="`)
	w.int(width)
	w.raw(`" height="`)
	w.int(height)
	w.raw(`" viewBox="0 0 `)
	w.int(vw)
	w.raw(" ")
	w.int(vh)
	w.raw(`">`)
}

const svgURIPrefix = "data:image/svg+xml;charset=utf-8,"

// dataURI turns URI-ready SVG into an image destination through
// sanitize.ImageURL (native percent-encoding): gnoweb accepts any
// data:image/svg+xml destination (markdown/ext_imgvalidator.go, v1.8.0-rc.1)
// and goldmark needs the ';' after the media type. Spaces, quotes, < > and
// the like are encoded; '#' and '%' never reach it raw (svgW pre-encodes
// them), so the data cannot be cut at a fragment or decoded wrongly.
func dataURI(svg []byte) string {
	return sanitize.ImageURL(svgURIPrefix + string(svg))
}

// ---- World map ----

const (
	cellPx  = 20 // world-map cell
	mapSide = 2*maxCoord + 1
)

// worldSVG draws the world map: the hub, every room and corridors between
// orthogonal neighbours, over the bounding box of the used cells plus a 1-cell
// margin (at most 33x33 cells). On the home map (player false) rooms are
// shaded by clears and the newest visible room pulses; on a player's map the
// rooms in cleared are highlighted. Hidden rooms are hatched either way.
func worldSVG(player bool, cleared map[string]bool) []byte {
	newestID := ""
	if !player {
		if nr := newestRooms(1); len(nr) == 1 {
			newestID = nr[0].ID
		}
	}

	// One pass over the rooms: each used cell gets a look (0 empty, 1 the
	// hub, else an index into looks) and the bounding box grows to fit.
	var cell [mapSide * mapSide]uint8
	const hub, hatched, clearedLook, uncharted, shade0 = 1, 2, 3, 4, 5
	cell[maxCoord*mapSide+maxCoord] = hub
	pulse := -1
	minX, maxX, minY, maxY := 0, 0, 0, 0
	rooms.Iterate("", "", func(_ string, v any) bool {
		r := v.(*Room)
		x, y := int(r.X), int(r.Y)
		if x < minX {
			minX = x
		}
		if x > maxX {
			maxX = x
		}
		if y < minY {
			minY = y
		}
		if y > maxY {
			maxY = y
		}
		i := (y+maxCoord)*mapSide + x + maxCoord
		switch {
		case r.Hidden:
			cell[i] = hatched
		case !player:
			cell[i] = uint8(shade0 + shadeStep(r.Clears))
		case cleared[r.ID]:
			cell[i] = clearedLook
		default:
			cell[i] = uncharted
		}
		if r.ID == newestID {
			pulse = i
		}
		return false
	})
	looks := [shade0 + 4]string{"", colHub, "url(" + sharp + "hatch)", colCleared, colUncharted, shade(0), shade(1), shade(2), shade(3)}
	minX, minY = clampCoord(minX-1), clampCoord(minY-1)
	maxX, maxY = clampCoord(maxX+1), clampCoord(maxY+1)
	cols, rows := maxX-minX+1, maxY-minY+1
	vw, vh := cols*cellPx, rows*cellPx
	n := rooms.Size()

	w := newSVG(2048 + 96*n)
	scale := 1 // small maps show at 2x so a young world is not a speck
	if vw*2 <= 640 {
		scale = 2
	}
	w.open(vw*scale, vh*scale, vw, vh)
	w.raw(`<defs><pattern id="dots" width="20" height="20" patternUnits="userSpaceOnUse">`)
	w.rect(9, 9, 2, 2, colFloor)
	w.raw(`</pattern><pattern id="hatch" width="4" height="4" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">`)
	w.rect(0, 0, 4, 4, colBG)
	w.rect(0, 0, 2, 4, colWall)
	w.raw(`</pattern></defs>`)
	w.rect(0, 0, vw, vh, colBG)
	w.rect(0, 0, vw, vh, "url("+sharp+"dots)")

	// Corridors: a short link from each used cell to its east and south
	// neighbours.
	links := make([]byte, 0, 32*(n+1))
	for y := minY; y <= maxY; y++ {
		for x := minX; x <= maxX; x++ {
			i := (y+maxCoord)*mapSide + x + maxCoord
			if cell[i] == 0 {
				continue
			}
			px, py := (x-minX)*cellPx, (y-minY)*cellPx
			if x < maxX && cell[i+1] != 0 {
				links = appendBox(links, px+17, py+8, "h4v4h-4z")
			}
			if y < maxY && cell[i+mapSide] != 0 {
				links = appendBox(links, px+8, py+17, "h4v4h-4z")
			}
		}
	}
	w.path(links, colWall)

	// The hub: a gold cell with a flickering torch.
	hx, hy := -minX*cellPx, -minY*cellPx
	w.raw(`<g id="hub"><rect x="`)
	w.int(hx + 2)
	w.raw(`" y="`)
	w.int(hy + 2)
	w.raw(`" width="16" height="16" rx="2" fill="` + colHub + `"/>`)
	w.rect(hx+9, hy+10, 2, 6, colBG)
	w.raw(`<path fill="` + colBG + `" d="M`)
	w.int(hx + 10)
	w.raw(" ")
	w.int(hy + 4)
	w.raw(`q3 3 0 6q-3-3 0-6z"><animate attributeName="opacity" values="1;0.6;1" dur="0.9s" repeatCount="indefinite"/></path></g>`)

	// Rooms, one rect each, row by row.
	w.raw(`<g id="rooms">`)
	for y := minY; y <= maxY; y++ {
		for x := minX; x <= maxX; x++ {
			i := (y+maxCoord)*mapSide + x + maxCoord
			if cell[i] <= hub {
				continue
			}
			w.raw(`<rect x="`)
			w.int((x-minX)*cellPx + 2)
			w.raw(`" y="`)
			w.int((y-minY)*cellPx + 2)
			w.raw(`" width="16" height="16" rx="2" fill="` + looks[cell[i]])
			if i == pulse {
				w.raw(`"><animate attributeName="opacity" values="1;0.55;1" dur="1.6s" repeatCount="indefinite"/></rect>`)
			} else {
				w.raw(`"/>`)
			}
		}
	}
	w.raw("</g></svg>")
	return w.b
}

func clampCoord(v int) int {
	if v < -maxCoord {
		return -maxCoord
	}
	if v > maxCoord {
		return maxCoord
	}
	return v
}

// appendBox appends "M x y" and a relative shape.
func appendBox(d []byte, x, y int, shape string) []byte {
	d = appendInt(append(d, 'M'), x)
	d = appendInt(append(d, ' '), y)
	return append(d, shape...)
}

// ---- Room and ghost ----

const (
	tilePx    = 16
	holdBeats = 6 // the replay holds its last frame this many beats
)

// glyphDefs: monster glyphs drawn at the origin of a 16x16 tile and placed
// with <use>, the floor tiling, and the hero's torchlight.
const glyphDefs = `<g id="k1"><path fill="` + colSlime + `" d="M2 14c0-6 3-9 6-9s6 3 6 9z"/>` +
	`<rect x="5" y="9" width="2" height="2" fill="` + colBG + `"/><rect x="9" y="9" width="2" height="2" fill="` + colBG + `"/></g>` +
	`<g id="k2"><path fill="` + colArcher + `" d="M7 3l5 11H2z"/><path fill="none" stroke="` + colArrow + `" d="M11 3q4 5 0 10M11 3v10"/></g>` +
	`<g id="k3"><rect x="2" y="3" width="12" height="11" rx="2" fill="` + colBrute + `"/><rect x="4" y="6" width="8" height="2" fill="` + colBG + `"/></g>` +
	`<g id="k4"><path fill="` + colGargoyle + `" d="M8 4l3 3 4-4-1 11H2L1 3l4 4z"/>` +
	`<rect x="6" y="8" width="1" height="1" fill="` + colFireball + `"/><rect x="9" y="8" width="1" height="1" fill="` + colFireball + `"/></g>` +
	`<pattern id="fl" width="16" height="16" patternUnits="userSpaceOnUse"><rect width="16" height="16" fill="` + colBG + `"/>` +
	`<rect width="15" height="15" fill="` + colFloor + `"/></pattern>` +
	`<radialGradient id="glow"><stop offset="0" stop-color="` + colFireball + `" stop-opacity="0.35"/>` +
	`<stop offset="1" stop-color="` + colFireball + `" stop-opacity="0"/></radialGradient>`

// monKey is a monster keyframe: its tile at a beat.
type monKey struct {
	beat int
	x, y int8
}

// ghost is a replayed run, recorded beat by beat.
type ghost struct {
	beats      int                    // steps run
	hx, hy     [sim.MaxBeats + 1]int8 // hero tile after each beat
	keys       [sim.MaxMonsters][]monKey
	died       [sim.MaxMonsters]int // beat a monster died, 0 alive
	gates      [sim.MaxGates][]int  // beats a gate toggled
	gateOpen0  [sim.MaxGates]bool
	crumbles   []monKey // a crumble tile (x, y) fell at beat
	chestTaken int      // beat the chest was opened, 0 never
}

// replayRun runs log on m with relic, recording what the SVG animates:
// monsters only on beats where they move or die, gates when they toggle.
func replayRun(m *sim.Map, relic uint8, log string) *ghost {
	gh := &ghost{}
	g := sim.NewGame(m, relic)
	gh.hx[0], gh.hy[0] = g.HX, g.HY
	nm := int(g.NMons)
	var lx, ly [sim.MaxMonsters]int8
	for j := 0; j < nm; j++ {
		lx[j], ly[j] = g.Mons[j].X, g.Mons[j].Y
	}
	ng := int(g.NGates)
	var open [sim.MaxGates]bool
	for k := 0; k < ng; k++ {
		open[k] = g.Tile(int(g.Gates[k])) == sim.TGateOpen
		gh.gateOpen0[k] = open[k]
	}
	w := int(m.W)
	for i := 0; i < len(log) && !g.Won && !g.Dead; i++ {
		mark := int(g.Mark)
		g.Step(log[i] - '0')
		b := int(g.Beat)
		gh.beats = b
		gh.hx[b], gh.hy[b] = g.HX, g.HY
		for j := 0; j < nm; j++ {
			if gh.died[j] != 0 {
				continue
			}
			e := &g.Mons[j]
			if e.X != lx[j] || e.Y != ly[j] {
				gh.keys[j] = append(gh.keys[j], monKey{b, e.X, e.Y})
				lx[j], ly[j] = e.X, e.Y
			}
			if !e.Alive {
				gh.died[j] = b
			}
		}
		if g.Ev&sim.EvCrumble != 0 && mark >= 0 {
			gh.crumbles = append(gh.crumbles, monKey{b, int8(mark % w), int8(mark / w)})
		}
		if g.Ev&sim.EvChest != 0 {
			gh.chestTaken = b
		}
		for k := 0; k < ng; k++ {
			if o := g.Tile(int(g.Gates[k])) == sim.TGateOpen; o != open[k] {
				open[k] = o
				gh.gates[k] = append(gh.gates[k], b)
			}
		}
	}
	return gh
}

// keyTimes holds the keyTimes entry for every beat of a replay, each with a
// leading ';' (beat/total with 4 decimals; 0 and 1 exact).
func keyTimes(total int) []string {
	kt := make([]string, total+1)
	kt[0] = ";0"
	for b := 1; b < total; b++ {
		q := b * 10000 / total
		kt[b] = string([]byte{';', '0', '.', byte('0' + q/1000), byte('0' + q/100%10), byte('0' + q/10%10), byte('0' + q%10)})
	}
	kt[total] = ";1"
	return kt
}

// animHead opens an animation of attr with the keyTimes list kt (each entry
// with a leading ';') and starts its values.
func (w *svgW) animHead(attr, mode string, kt []byte) {
	w.raw(`<animate attributeName="` + attr + `" calcMode="` + mode + `" keyTimes="`)
	w.b = append(w.b, kt[1:]...)
	w.raw(`" values="`)
}

// animTail closes an animation's values and adds the shared timing.
func (w *svgW) animTail(dur string) {
	w.raw(`"` + dur + "/>")
}

// durAttr is the shared timing of a replay of total beats at 0.16 s each.
func durAttr(total int) string {
	cs := total * 16
	b := appendInt([]byte(` dur="`), cs/100)
	b = append(b, '.', byte('0'+cs%100/10), byte('0'+cs%10), 's', '"')
	return string(b) + ` repeatCount="indefinite"`
}

// roomSVG draws a room from its stored map at 16 px per tile and, when run is
// set, replays it: the hero is keyframed on every beat, monsters only when
// they move or die, gates when they toggle, a crumble when it falls and the
// chest when it is opened. Every animation shares one duration (the run plus a
// short hold) and loops.
func roomSVG(r *Room, run *Run) []byte {
	m := &r.Static.Map
	mw, mh := int(m.W), int(m.H)
	vw, vh := mw*tilePx, mh*tilePx

	var gh *ghost
	var kt []string
	dur := ""
	total := 0
	if run != nil {
		gh = replayRun(m, run.Relic, run.Log)
		total = gh.beats + holdBeats
		kt = keyTimes(total)
		dur = durAttr(total)
	}

	w := newSVG(160 << 10)
	w.open(vw*2, vh*2, vw, vh)
	w.raw("<title>")
	w.text(r.Name)
	w.raw("</title><defs>" + glyphDefs + "</defs>")
	w.rect(0, 0, vw, vh, "url("+sharp+"fl)")

	// Static tiles, one path per kind; walls, faces and pits merge runs.
	// Path buffers fit MaxTiles of their kind (appending past capacity
	// recopies the buffer, which costs gas, not correctness).
	const tiles = sim.MaxTiles
	walls, faces, pits := make([]byte, 0, 24*tiles), make([]byte, 0, 24*tiles), make([]byte, 0, 24*tiles)
	crumble, spikes, plates := make([]byte, 0, 20*tiles), make([]byte, 0, 48*tiles), make([]byte, 0, 20*sim.MaxPlates)
	exits, steps, bars := make([]byte, 0, 20*tiles), make([]byte, 0, 24*tiles), make([]byte, 0, 56*sim.MaxGates)
	var gates [sim.MaxGates]int
	ng := 0
	chest := -1
	for y := 0; y < mh; y++ {
		row := y * mw
		py := y * tilePx
		for x := 0; x < mw; x++ {
			px := x * tilePx
			switch m.Tiles[row+x] {
			case sim.TWall:
				if x == 0 || m.Tiles[row+x-1] != sim.TWall {
					n := 1
					for x+n < mw && m.Tiles[row+x+n] == sim.TWall {
						n++
					}
					walls = appendRun(walls, px, py, n, 16)
				}
				if y+1 < mh && m.Tiles[row+mw+x] != sim.TWall {
					faces = appendRun(faces, px, py+11, 1, 5)
				}
			case sim.TPit:
				if x == 0 || m.Tiles[row+x-1] != sim.TPit {
					n := 1
					for x+n < mw && m.Tiles[row+x+n] == sim.TPit {
						n++
					}
					pits = appendRun(pits, px, py, n, 16)
				}
			case sim.TCrumble:
				crumble = appendBox(crumble, px, py, "h15v15h-15z")
			case sim.TSpikes:
				spikes = appendBox(spikes, px+2, py+13, "l2-7 2 7zm4 0l2-7 2 7zm4 0l2-7 2 7z")
			case sim.TPlate:
				plates = appendBox(plates, px+3, py+3, "h9v9h-9z")
			case sim.TExit:
				exits = appendBox(exits, px, py, "h15v15h-15z")
				steps = appendBox(steps, px+3, py+12, "h9v-3h-6v-3h-3z")
			case sim.TGate:
				if ng < sim.MaxGates {
					gates[ng] = row + x
					ng++
				}
				bars = appendBox(bars, px+3, py, "h1v16h-1zm4 0h1v16h-1zm4 0h1v16h-1zm4 0h1v16h-1z")
			case sim.TChest:
				chest = row + x
			}
		}
	}
	w.raw(`<g shape-rendering="crispEdges">`)
	w.path(walls, colWall)
	w.path(faces, colWallFace)
	w.path(pits, colPit)
	w.path(crumble, colCrumble)
	w.path(spikes, colSpikes)
	w.path(plates, colPlate)
	w.path(exits, colExit)
	w.path(steps, colFloor)

	// Gates, each with its own fill so the replay can toggle it (NewGame
	// numbers gates in row-major order, as collected above).
	for k := 0; k < ng; k++ {
		fill := colGate
		if gh != nil && gh.gateOpen0[k] {
			fill = colGateOpen
		}
		w.raw(`<rect x="`)
		w.int(gates[k] % mw * tilePx)
		w.raw(`" y="`)
		w.int(gates[k] / mw * tilePx)
		w.raw(`" width="16" height="16" fill="` + fill)
		if gh == nil || len(gh.gates[k]) == 0 {
			w.raw(`"/>`)
			continue
		}
		w.raw(`"><animate attributeName="fill" calcMode="discrete" keyTimes="0`)
		for _, b := range gh.gates[k] {
			w.raw(kt[b])
		}
		w.raw(`" values="` + fill)
		for t := len(gh.gates[k]); t > 0; t-- {
			if fill == colGate {
				fill = colGateOpen
			} else {
				fill = colGate
			}
			w.raw(";" + fill)
		}
		w.raw(`"` + dur + "/></rect>")
	}
	w.path(bars, colBG)

	// A crumble that falls during the replay becomes a pit.
	if gh != nil {
		for _, c := range gh.crumbles {
			w.raw(`<rect x="`)
			w.int(int(c.x) * tilePx)
			w.raw(`" y="`)
			w.int(int(c.y) * tilePx)
			w.raw(`" width="16" height="16" fill="` + colPit + `" opacity="0"><animate attributeName="opacity" calcMode="discrete" keyTimes="0`)
			w.raw(kt[c.beat])
			w.raw(`" values="0;1"` + dur + "/></rect>")
		}
	}
	w.raw("</g>")

	if chest >= 0 {
		cx, cy := chest%mw*tilePx, chest/mw*tilePx
		w.raw(`<g id="chest">`)
		w.rect(cx+3, cy+5, 10, 8, colChest)
		w.rect(cx+3, cy+8, 10, 1, colBG)
		if gh != nil && gh.chestTaken != 0 {
			w.raw(`<animate attributeName="opacity" calcMode="discrete" keyTimes="0`)
			w.raw(kt[gh.chestTaken])
			w.raw(`" values="1;0"` + dur + "/>")
		}
		w.raw("</g>")
	}

	w.raw(`<g id="mons">`)
	for j := 0; j < int(m.NMons); j++ {
		s := m.Mons[j]
		w.raw(`<use href="` + sharp + `k`)
		w.int(int(s.Kind))
		w.raw(`" transform="translate(`)
		w.b = appendXY(w.b, s.X, s.Y)
		w.raw(`)"`)
		if gh == nil || (len(gh.keys[j]) == 0 && gh.died[j] == 0) {
			w.raw("/>")
			continue
		}
		w.raw(">")
		if len(gh.keys[j]) > 0 {
			w.monsterMoves(s, gh.keys[j], kt, dur)
		}
		if d := gh.died[j]; d != 0 {
			w.raw(`<animate attributeName="opacity" calcMode="linear" keyTimes="0`)
			w.raw(kt[d-1])
			w.raw(kt[d])
			w.raw(`;1" values="1;1;0;0"` + dur + "/>")
		}
		w.raw("</use>")
	}
	w.raw("</g>")

	w.raw(`<g id="hero">`)
	if gh == nil {
		sx, sy := int(m.StartX)*tilePx, int(m.StartY)*tilePx
		w.raw(`<circle r="28" fill="url(` + sharp + `glow)" cx="`)
		w.int(sx + 8)
		w.raw(`" cy="`)
		w.int(sy + 8)
		w.raw(`"/><rect x="`)
		w.int(sx + 3)
		w.raw(`" y="`)
		w.int(sy + 3)
		w.raw(`" width="10" height="10" rx="3" fill="` + colHero + `"/>`)
	} else {
		n := gh.beats
		hkt := make([]byte, 0, 8*(n+2))
		for b := 0; b <= n; b++ {
			hkt = append(hkt, kt[b]...)
		}
		hkt = append(hkt, kt[total]...)
		// Coordinates for tile t at offset off, each with a leading ';'.
		var c3, c8 [sim.MaxW]string
		for t := 0; t < sim.MaxW; t++ {
			c3[t] = string(appendInt([]byte{';'}, t*tilePx+3))
			c8[t] = string(appendInt([]byte{';'}, t*tilePx+8))
		}
		w.raw(`<circle r="28" fill="url(` + sharp + `glow)" cx="`)
		w.raw(c8[gh.hx[0]][1:])
		w.raw(`" cy="`)
		w.raw(c8[gh.hy[0]][1:])
		w.raw(`">`)
		w.heroAnim("cx", hkt, &c8, gh.hx[:n+1], dur)
		w.heroAnim("cy", hkt, &c8, gh.hy[:n+1], dur)
		w.raw(`</circle><rect x="`)
		w.raw(c3[gh.hx[0]][1:])
		w.raw(`" y="`)
		w.raw(c3[gh.hy[0]][1:])
		w.raw(`" width="10" height="10" rx="3" fill="` + colHero + `">`)
		w.heroAnim("x", hkt, &c3, gh.hx[:n+1], dur)
		w.heroAnim("y", hkt, &c3, gh.hy[:n+1], dur)
		w.raw("</rect>")
	}
	w.raw("</g></svg>")
	return w.b
}

// heroAnim writes a linear animation of attr over the hero's tiles, one value
// per beat plus the last one again for the hold.
func (w *svgW) heroAnim(attr string, kt []byte, coord *[sim.MaxW]string, tiles []int8, dur string) {
	w.animHead(attr, "linear", kt)
	w.raw(coord[tiles[0]][1:])
	for _, t := range tiles[1:] {
		w.raw(coord[t])
	}
	w.raw(coord[tiles[len(tiles)-1]])
	w.animTail(dur)
}

// monsterMoves writes a monster's translate keyframes: it holds each tile
// until the beat before a move, slides during the move's beat, and holds its
// last tile to the end.
func (w *svgW) monsterMoves(s sim.Mon, keys []monKey, kt []string, dur string) {
	total := len(kt) - 1
	ktb := make([]byte, 0, 16*len(keys)+8)
	vals := make([]byte, 0, 20*len(keys)+16)
	ktb = append(ktb, kt[0]...)
	vals = appendXY(vals, s.X, s.Y)
	last, lx, ly := 0, s.X, s.Y
	for _, k := range keys {
		if k.beat-1 > last {
			ktb = append(ktb, kt[k.beat-1]...)
			vals = appendXY(append(vals, ';'), lx, ly)
		}
		ktb = append(ktb, kt[k.beat]...)
		vals = appendXY(append(vals, ';'), k.x, k.y)
		last, lx, ly = k.beat, k.x, k.y
	}
	if last < total {
		ktb = append(ktb, kt[total]...)
		vals = appendXY(append(vals, ';'), lx, ly)
	}
	w.raw(`<animateTransform attributeName="transform" type="translate" calcMode="linear" keyTimes="`)
	w.b = append(w.b, ktb[1:]...)
	w.raw(`" values="`)
	w.b = append(w.b, vals...)
	w.animTail(dur)
}

func appendXY(b []byte, x, y int8) []byte {
	return appendInt(append(appendInt(b, int(x)*tilePx), ','), int(y)*tilePx)
}

// appendRun appends an n-tile-wide strip of height h at (x, y).
func appendRun(d []byte, x, y, n, h int) []byte {
	d = appendInt(append(d, 'M'), x)
	d = appendInt(append(d, ' '), y)
	d = appendInt(append(d, 'h'), n*tilePx)
	d = appendInt(append(d, 'v'), h)
	d = appendInt(append(d, 'h', '-'), n*tilePx)
	return append(d, 'z')
}

