package descent

import (
	"strconv"

	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/gen"
)

// The read API: JSON strings for vm/qeval, in the hub's style. Addresses are
// read as given; an invalid one reads as unknown.

// Today returns {"day":N,"floors":10}: today's UTC day number and the floors
// a descent has.
func Today() string {
	b := []byte{'{'}
	b = appendField(b, "day", true)
	b = appendUint(b, uint64(today()))
	b = appendField(b, "floors", false)
	b = appendInt(b, gen.Floors)
	return string(append(b, '}'))
}

// Board returns day's board, best first, one row per player (their best
// attempt): [{"owner":..,"floors":..,"beats":..,"damage":..,"height":..}],
// at most 50 rows, ranked by floors cleared (more first), then total beats,
// total damage and the commit height of the result (fewer, less, earlier
// first). A day more than 7 days old keeps only its winner. An unknown day
// is [].
func Board(day int) string {
	if day < 0 || day > int(^uint32(0)) {
		return "[]"
	}
	b := []byte{'['}
	if bd := boardOf(uint32(day), false); bd != nil {
		for i := 0; i < len(bd.Rows); {
			if i > 0 {
				b = append(b, ',')
			}
			var r Row
			r, i = unpackRow(bd.Rows, i)
			b = appendRow(b, &r)
		}
	}
	return string(append(b, ']'))
}

// Attempt returns the address's current (or last) attempt:
// {"day":..,"attempt":..,"floor":..,"floors":..,"hp":..,"relic":..,"beats":..,
// "damage":..,"ended":..,"pending":null|{"hash":..,"height":..}}. floor is the
// floor to play next, floors the floors cleared, hp the HP carried into floor,
// ended "" while live else "dead" or "cleared". With no attempt it is null.
func Attempt(addr string) string {
	a := attemptOf(addr)
	if a == nil {
		return "null"
	}
	b := []byte{'{'}
	b = appendField(b, "day", true)
	b = appendUint(b, uint64(a.Day))
	b = appendField(b, "attempt", false)
	b = appendUint(b, uint64(a.N))
	b = appendField(b, "floor", false)
	b = appendInt(b, int(a.Floor))
	b = appendField(b, "floors", false)
	b = appendInt(b, int(a.cleared()))
	b = appendField(b, "hp", false)
	b = appendInt(b, int(a.HP))
	b = appendField(b, "relic", false)
	b = appendInt(b, int(a.Relic))
	b = appendField(b, "beats", false)
	b = appendInt(b, int(a.Beats))
	b = appendField(b, "damage", false)
	b = appendInt(b, int(a.Damage))
	b = appendField(b, "ended", false)
	b = appendQuoted(b, a.Ended)
	b = appendField(b, "pending", false)
	if a.PendingHash == "" {
		b = append(b, "null"...)
	} else {
		b = append(b, '{')
		b = appendField(b, "hash", true)
		b = appendQuoted(b, a.PendingHash)
		b = appendField(b, "height", false)
		b = append(b, strconv.FormatInt(a.PendingHeight, 10)...)
		b = append(b, '}')
	}
	return string(append(b, '}'))
}

// Player returns the address's records: {"deepest":N,"streak":N,"longest":N,
// "total":N,"played":N,"days":[{"day":..,"floors":..,"beats":..,"damage":..,
// "height":..}]}. deepest is the most floors cleared in one attempt, ever;
// streak the run of consecutive UTC days (by attempt day) that reached floor
// 3, 0 once a whole day has passed without; longest the longest such run;
// total the floors of every day's best attempt added up; played the days with
// a floor cleared. days lists the best
// attempt of each day still kept (today and the 7 before), newest first.
func Player(addr string) string {
	var p Record
	if v := recordOf(addr, false); v != nil {
		p = *v
	}
	t := today()
	b := []byte{'{'}
	b = appendField(b, "deepest", true)
	b = appendInt(b, int(p.Deepest))
	b = appendField(b, "streak", false)
	b = appendInt(b, int(liveStreak(&p, t)))
	b = appendField(b, "longest", false)
	b = appendInt(b, int(p.Longest))
	b = appendField(b, "total", false)
	b = appendInt(b, int(p.Total))
	b = appendField(b, "played", false)
	b = appendInt(b, int(p.Played))
	b = appendField(b, "days", false)
	b = append(b, '[')
	first := true
	for d := t; ; d-- {
		if r, ok := ringGet(p.Days, d); ok {
			if !first {
				b = append(b, ',')
			}
			first = false
			b = append(b, '{')
			b = appendField(b, "day", true)
			b = appendUint(b, uint64(d))
			b = appendBestFields(b, &r)
			b = append(b, '}')
		}
		if d == cutoff(t) {
			break
		}
	}
	return string(append(b, ']', '}'))
}

// FloorBest returns the best clear of floor (1..10) on day: {"owner":..,
// "beats":..,"damage":..,"height":..,"log":..,"relic":..,"hp":..} with the
// relic and HP the run started the floor with, for ghosts and dares; ties go
// to less damage, then the earlier commit. null when there is none (or the
// day was pruned).
func FloorBest(day, floor int) string {
	if day < 0 || day > int(^uint32(0)) || floor < 1 || floor > gen.Floors {
		return "null"
	}
	bd := boardOf(uint32(day), false)
	if bd == nil {
		return "null"
	}
	r, ok := floorGet(bd.Floors, uint8(floor))
	if !ok {
		return "null"
	}
	b := []byte{'{'}
	b = appendField(b, "owner", true)
	b = appendQuoted(b, r.Owner.String())
	b = appendField(b, "beats", false)
	b = appendInt(b, int(r.Beats))
	b = appendField(b, "damage", false)
	b = appendInt(b, int(r.Damage))
	b = appendField(b, "height", false)
	b = append(b, strconv.FormatInt(r.Height, 10)...)
	b = appendField(b, "log", false)
	b = appendQuoted(b, r.Log)
	b = appendField(b, "relic", false)
	b = appendInt(b, int(r.Relic))
	b = appendField(b, "hp", false)
	b = appendInt(b, int(r.HP))
	return string(append(b, '}'))
}

func appendRow(b []byte, r *Row) []byte {
	b = append(b, '{')
	b = appendField(b, "owner", true)
	b = appendQuoted(b, r.Owner.String())
	b = appendBestFields(b, r)
	return append(b, '}')
}

func appendBestFields(b []byte, r *Row) []byte {
	b = appendField(b, "floors", false)
	b = appendInt(b, int(r.Floors))
	b = appendField(b, "beats", false)
	b = appendInt(b, int(r.Beats))
	b = appendField(b, "damage", false)
	b = appendInt(b, int(r.Damage))
	b = appendField(b, "height", false)
	return append(b, strconv.FormatInt(r.Height, 10)...)
}

// ---- JSON helpers (as in the hub's json.gno) ----

const hexDigits = "0123456789abcdef"

// appendQuoted appends s as a JSON string: quote and backslash are
// backslash-escaped, control characters become \u00XX.
func appendQuoted(b []byte, s string) []byte {
	b = append(b, '"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"' || c == '\\':
			b = append(b, '\\', c)
		case c < 0x20:
			b = append(b, '\\', 'u', '0', '0', hexDigits[c>>4], hexDigits[c&0xf])
		default:
			b = append(b, c)
		}
	}
	return append(b, '"')
}

// appendField appends `"key":`, preceded by a comma unless first.
func appendField(b []byte, key string, first bool) []byte {
	if !first {
		b = append(b, ',')
	}
	b = append(b, '"')
	b = append(b, key...)
	return append(b, '"', ':')
}

func appendInt(b []byte, n int) []byte { return append(b, strconv.Itoa(n)...) }

func appendUint(b []byte, n uint64) []byte { return append(b, strconv.FormatUint(n, 10)...) }

package descent

import (
	"gno.land/p/nt/avl/v0"
	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/gen"
)

// Storage grows with players only through their one record each; per day it
// is one object: a player's day bests live in a ring inside their record
// (updated in place), and each day keeps one DayBoard holding, packed, at most
// boardSize rows and gen.Floors floor bests. Gno stores every struct and tree
// node as an object of its own (about 1-3 KB of deposit each), so packing is
// what keeps a day's first full descent cheap. A day more than keepDays old is
// cut down to its winner.
const (
	boardSize = 50
	// streakFloor: a day counts toward a streak once an attempt of that day
	// reaches (stands on) this floor.
	streakFloor = 3
	// keepDays: a day more than keepDays before today keeps only its winner.
	keepDays = 7
	// ringDays is how many day bests a record holds: today and the keepDays
	// before it.
	ringDays = keepDays + 1
)

// Row is a player's best attempt of a day: a board row (packed by packRow),
// and (without the owner) a slot of their record's ring.
type Row struct {
	Owner  address
	Floors uint8  // floors cleared (0: no result)
	Beats  uint16 // total beats over them
	Damage uint8  // total damage over them
	Height int64  // commit height of the clear that set this result
}

// better ranks by floors (more first), then beats, damage and height (fewer,
// less, earlier first).
func (r *Row) better(o *Row) bool {
	if r.Floors != o.Floors {
		return r.Floors > o.Floors
	}
	if r.Beats != o.Beats {
		return r.Beats < o.Beats
	}
	if r.Damage != o.Damage {
		return r.Damage < o.Damage
	}
	return r.Height < o.Height
}

// DayBoard is one day's shared records, packed into strings so the day is a
// single object: Rows holds its top rows, best first, one per player (see
// packRow); Floors holds its floor bests (see floorGet).
type DayBoard struct {
	Day    uint32
	Rows   string
	Floors string
}

// FloorRun is the best clear of one floor of a day, with what a ghost or a
// dare needs to replay it: the log and the relic and HP it started from. It
// is stored packed in DayBoard.Floors.
type FloorRun struct {
	Owner  address
	Beats  uint16
	Damage uint8
	Height int64 // commit height
	Log    string
	Relic  uint8
	HP     int8
}

func (r *FloorRun) better(o *FloorRun) bool {
	if r.Beats != o.Beats {
		return r.Beats < o.Beats
	}
	if r.Damage != o.Damage {
		return r.Damage < o.Damage
	}
	return r.Height < o.Height
}

var (
	boards = avl.NewTree() // dayKey -> *DayBoard
	// pruneFrom: every day before it has been cut down to its winner.
	pruneFrom uint32
)

// noteResult records r as rec's result for bd's day if it beats their best
// of that day, adds its new floors to rec's totals, and enters it on the
// board.
func noteResult(rec *Record, bd *DayBoard, r Row) {
	old, ok := ringGet(rec.Days, bd.Day)
	if ok && !r.better(&old) {
		return
	}
	// The day's best only grows, so its new floors add to the all-time total.
	if !ok {
		rec.Played++
		old.Floors = 0
	}
	if r.Floors > old.Floors {
		rec.Total += uint32(r.Floors - old.Floors)
	}
	rec.Days = ringSet(rec.Days, bd.Day, &r)
	enterBoard(bd, r)
}

// enterBoard places r, its owner's improved best, on bd in one pass over the
// packed rows, keeping one row per player and at most boardSize rows. A
// player's best only improves (an old row of theirs is always worse than r,
// so r lands at or above it), and a player pushed off a full board belongs on
// it again only once they beat its last row: the board stays the exact top
// boardSize of every player's best.
func enterBoard(bd *DayBoard, r Row) {
	s := bd.Rows
	b := make([]byte, 0, len(s)+rowMax)
	placed := false
	n := 0
	for i := 0; i < len(s); {
		old, next := unpackRow(s, i)
		seg := s[i:next]
		i = next
		if old.Owner == r.Owner {
			continue
		}
		if !placed && r.better(&old) {
			b = packRow(b, &r)
			placed = true
			n++
		}
		if n == boardSize {
			break
		}
		b = append(b, seg...)
		n++
	}
	if !placed {
		if n >= boardSize {
			return // not better than a full board's last row
		}
		b = packRow(b, &r)
	}
	bd.Rows = string(b)
}

// noteFloor records run as floor n's best of bd's day if it beats the
// current one.
func noteFloor(bd *DayBoard, n uint8, run FloorRun) {
	if old, ok := floorGet(bd.Floors, n); ok && !run.better(&old) {
		return
	}
	bd.Floors = floorSet(bd.Floors, n, &run)
}

// noteStreak updates rec's deepest and streak after its attempt's latest
// clear.
func noteStreak(rec *Record) {
	if c := rec.cleared(); c > rec.Deepest {
		rec.Deepest = c
	}
	// Counted once per day, by the attempt's day: the clear that brings the
	// attempt onto streakFloor.
	if rec.cleared() != streakFloor-1 || rec.Streak > 0 && rec.Day <= rec.StreakDay {
		return
	}
	if rec.Streak > 0 && rec.StreakDay+1 == rec.Day {
		rec.Streak++
	} else {
		rec.Streak = 1
	}
	rec.StreakDay = rec.Day
	if rec.Streak > rec.Longest {
		rec.Longest = rec.Streak
	}
}

// liveStreak is rec's streak as of day: it lapses once a whole day passes
// without reaching streakFloor.
func liveStreak(rec *Record, day uint32) uint16 {
	if rec.Streak > 0 && rec.StreakDay+1 >= day {
		return rec.Streak
	}
	return 0
}

// prune cuts the oldest day before cutoff(today) not yet cut down to its
// winner: its board keeps one row and its floor bests go. It reports whether
// it cut a day. One day per call is bounded work (one object rewritten) and
// keeps up, since at most one day a day falls past the cutoff; days without a
// board are skipped in the same lookup.
func prune(today uint32) bool {
	c := cutoff(today)
	if pruneFrom >= c {
		return false
	}
	var bd *DayBoard
	boards.Iterate(dayKey(pruneFrom), dayKey(c), func(_ string, v any) bool {
		bd = v.(*DayBoard)
		return true
	})
	if bd == nil {
		pruneFrom = c
		return false
	}
	if bd.Rows != "" {
		_, next := unpackRow(bd.Rows, 0)
		bd.Rows = bd.Rows[:next]
	}
	bd.Floors = ""
	pruneFrom = bd.Day + 1
	return true
}

// cutoff is the oldest day that keeps its detail.
func cutoff(today uint32) uint32 {
	if today < keepDays {
		return 0
	}
	return today - keepDays
}

func boardOf(day uint32, create bool) *DayBoard {
	dk := dayKey(day)
	if v := boards.Get(dk); v != nil {
		return v.(*DayBoard)
	}
	if !create {
		return nil
	}
	bd := &DayBoard{Day: day}
	boards.Set(dk, bd)
	return bd
}

// The ring: Record.Days packs one slot per day of today and the keepDays
// before it, slot d % ringDays for day d, each slotLen bytes big-endian: day
// (4), floors (1), beats (2), damage (1), height (8). A slot whose day is not
// the one asked for is stale (or empty) and reads as no result.
const slotLen = 16

// ringGet returns the best of day packed in s, if s holds one.
func ringGet(s string, day uint32) (Row, bool) {
	i := int(day%ringDays) * slotLen
	if len(s) < i+slotLen || getUint(s, i, 4) != uint64(day) || s[i+4] == 0 {
		return Row{}, false
	}
	return Row{
		Floors: s[i+4],
		Beats:  uint16(getUint(s, i+5, 2)),
		Damage: s[i+7],
		Height: int64(getUint(s, i+8, 8)),
	}, true
}

// ringSet returns s with day's slot set to r (owner aside).
func ringSet(s string, day uint32, r *Row) string {
	if len(s) < ringDays*slotLen {
		s = string(make([]byte, ringDays*slotLen))
	}
	b := make([]byte, 0, slotLen)
	b = putUint(b, uint64(day), 4)
	b = append(b, r.Floors)
	b = putUint(b, uint64(r.Beats), 2)
	b = append(b, r.Damage)
	b = putUint(b, uint64(r.Height), 8)
	i := int(day%ringDays) * slotLen
	return s[:i] + string(b) + s[i+slotLen:]
}

// Packed rows: each is owner length (1), owner, floors (1), beats (2),
// damage (1), height (8), integers big-endian.
const rowMax = 1 + 255 + 12

func packRow(b []byte, r *Row) []byte {
	o := r.Owner.String()
	b = append(b, byte(len(o)))
	b = append(b, o...)
	b = append(b, r.Floors)
	b = putUint(b, uint64(r.Beats), 2)
	b = append(b, r.Damage)
	return putUint(b, uint64(r.Height), 8)
}

// unpackRow decodes the row at offset i of s and returns it with the offset
// of the next row.
func unpackRow(s string, i int) (Row, int) {
	j := i + 1 + int(s[i])
	return Row{
		Owner:  address(s[i+1 : j]),
		Floors: s[j],
		Beats:  uint16(getUint(s, j+1, 2)),
		Damage: s[j+3],
		Height: int64(getUint(s, j+4, 8)),
	}, j + 12
}

// Packed floor bests: gen.Floors slots in floor order, each either a single
// zero byte (no clear yet) or owner length (1, never 0), owner, beats (2),
// damage (1), height (8), relic (1), hp (1), log length (1), log. "" reads as
// every slot empty.

// floorSpan returns s (expanded to empty slots if "") and the bounds of
// floor n's slot in it.
func floorSpan(s string, n uint8) (string, int, int) {
	if s == "" {
		s = string(make([]byte, gen.Floors))
	}
	i := 0
	for k := uint8(1); ; k++ {
		end := i + 1
		if l := int(s[i]); l > 0 {
			end = i + 1 + l + 14 // through the log length byte
			end += int(s[end-1])
		}
		if k == n {
			return s, i, end
		}
		i = end
	}
}

// floorGet returns floor n's best packed in s, if there is one.
func floorGet(s string, n uint8) (FloorRun, bool) {
	s, i, end := floorSpan(s, n)
	if s[i] == 0 {
		return FloorRun{}, false
	}
	j := i + 1 + int(s[i])
	return FloorRun{
		Owner:  address(s[i+1 : j]),
		Beats:  uint16(getUint(s, j, 2)),
		Damage: s[j+2],
		Height: int64(getUint(s, j+3, 8)),
		Relic:  s[j+11],
		HP:     int8(s[j+12]),
		Log:    s[j+14 : end],
	}, true
}

// floorSet returns s with floor n's slot set to f. The owner and log must
// each fit 255 bytes (an address is 40; a log at most gen.DescentMaxBeats).
func floorSet(s string, n uint8, f *FloorRun) string {
	s, i, end := floorSpan(s, n)
	o := f.Owner.String()
	b := make([]byte, 0, 15+len(o)+len(f.Log))
	b = append(b, byte(len(o)))
	b = append(b, o...)
	b = putUint(b, uint64(f.Beats), 2)
	b = append(b, f.Damage)
	b = putUint(b, uint64(f.Height), 8)
	b = append(b, f.Relic, byte(f.HP), byte(len(f.Log)))
	b = append(b, f.Log...)
	return s[:i] + string(b) + s[end:]
}

func getUint(s string, i, n int) uint64 {
	var v uint64
	for k := 0; k < n; k++ {
		v = v<<8 | uint64(s[i+k])
	}
	return v
}

func putUint(b []byte, v uint64, n int) []byte {
	for k := n - 1; k >= 0; k-- {
		b = append(b, byte(v>>(8*uint(k))))
	}
	return b
}

// dayKey is day as 8 lowercase hex digits, so keys sort by day.
func dayKey(day uint32) string {
	return string(appendHex(make([]byte, 0, 8), uint64(day), 8))
}

func appendHex(b []byte, v uint64, digits int) []byte {
	for i := digits - 1; i >= 0; i-- {
		b = append(b, hexDigits[(v>>(4*uint(i)))&0xf])
	}
	return b
}

// Package descent is the Daily Descent: ten floors a UTC day, drawn on chain by
// gen from the day alone, played one floor per commit-reveal. Every counted
// floor is verified here by replaying the player's log on the regenerated
// floor from the HP and relic the attempt carries.
//
// An attempt starts at floor 1 with 3 HP and no relic. A clear advances it,
// carrying HP (healed by 1 on arriving at floors 4 and 8) and any relic taken
// from the day's chest; a death ends it. Attempts are unlimited; a player's
// best attempt of the day is what the board shows. There is no admin.
package descent

import (
	"chain"
	"chain/runtime"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/commit"
	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/gen"
	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/sim"
)

const (
	// revealWindow is how many blocks a commit stays revealable, as in the
	// hub (its play.gno).
	revealWindow = 600
	// roomPrefix names the descent in commit preimages:
	// gen.RoomID(roomPrefix, day, floor, attempt).
	roomPrefix = "descent"
	// Arriving at these floors heals 1 HP, up to the relic's max.
	healFloorA = 4
	healFloorB = 8
)

// Record is everything the realm keeps per player, in one flat object (Gno
// stores every nested struct as an object of its own, so nesting would cost
// deposit): the current (or last) attempt, the best of each recent day, and
// the all-time stats. It is updated in place, so playing more days does not
// grow it.
type Record struct {
	// The attempt.
	Day           uint32 // the UTC day it started; it plays that day's floors
	N             uint32 // attempt number within Day, from 1 (0: none yet)
	Floor         uint8  // the floor to play next (10 once the descent is cleared)
	HP            int8   // HP carried into Floor (0 once dead)
	Relic         uint8  // 0 none, 1 Featherboots, 2 Ironheart (from the chest)
	Beats         uint16 // total over cleared floors
	Damage        uint8  // total over cleared floors
	Ended         string // "" while live, else "dead" or "cleared"
	PendingHash   string // the pending commit, "" when none
	PendingHeight int64

	// Days holds the best of today and the keepDays before it, packed (see
	// ringGet).
	Days string

	// All-time.
	Deepest   uint8  // most floors cleared in one attempt
	Streak    uint16 // consecutive days reaching streakFloor, ending StreakDay
	Longest   uint16
	StreakDay uint32
	Total     uint32 // floors cleared: the sum of each day's best attempt
	Played    uint16 // days with at least one floor cleared
}

// cleared is the number of floors the attempt has cleared.
func (r *Record) cleared() uint8 {
	if r.Ended == "cleared" {
		return gen.Floors
	}
	return r.Floor - 1
}

var records = avl.NewTree() // addr -> *Record

// Start begins a new attempt on today's floors: floor 1, 3 HP, no relic. It
// replaces the caller's previous attempt and drops its pending commit; a live
// one that cleared a floor ends with DescentEnd reason "restart" (one that
// cleared nothing ends silently). User calls only.
func Start(cur realm) {
	who := userCaller(cur).String()
	day := today()
	prune(day)
	a := recordOf(who, true)
	if a.N > 0 && a.Ended == "" && a.cleared() > 0 {
		emitEnd(who, a, "restart")
	}
	if a.Day == day && a.N > 0 {
		a.N++
	} else {
		a.Day, a.N = day, 1
	}
	a.Floor, a.HP, a.Relic = 1, maxHP(0), 0
	a.Beats, a.Damage, a.Ended = 0, 0, ""
	a.PendingHash, a.PendingHeight = "", 0
}

// Commit records hash = commit.Hash(caller, gen.RoomID("descent", day, floor,
// attempt), relic, log, salt) for the attempt's current floor, with the
// attempt's day, floor, number and relic. User calls only. It panics with
// caller, hash, no attempt, done (the attempt ended), old day (it started
// before today: Start again) or pending (a commit is still revealable: reveal
// or Cancel it first).
func Commit(cur realm, hash string) {
	who := userCaller(cur).String()
	if !isLowerHex(hash, 64) {
		panic("hash")
	}
	a := attemptOf(who)
	if a == nil {
		panic("no attempt")
	}
	if a.Ended != "" {
		panic("done")
	}
	if a.Day != today() {
		panic("old day")
	}
	h := runtime.ChainHeight()
	if a.PendingHash != "" && h <= a.PendingHeight+revealWindow {
		panic("pending")
	}
	a.PendingHash, a.PendingHeight = hash, h
}

// Cancel drops the caller's pending commit, if any. User calls only.
func Cancel(cur realm) {
	if a := attemptOf(userCaller(cur).String()); a != nil {
		a.PendingHash, a.PendingHeight = "", 0
	}
}

// Reveal replays the committed log on the attempt's current floor, drawn again
// from the attempt's day and floor. A clear advances the attempt and emits
// DescentFloor (and DescentEnd "cleared" after floor 10); a death ends it with
// DescentEnd "dead". A commit made before midnight still reveals against its
// own day's floor. User calls only. It panics with caller, salt, log, too long
// (more than gen.DescentMaxBeats beats), no attempt, done, none, early,
// expired, mismatch, or "run:" + the sim reason for a run that neither clears
// nor dies (the commit is then kept).
func Reveal(cur realm, log, salt string) {
	who := userCaller(cur).String()
	if !isLowerHex(salt, 32) {
		panic("salt")
	}
	if why := checkLog(log); why != "" {
		panic(why)
	}
	a := attemptOf(who)
	if a == nil {
		panic("no attempt")
	}
	if a.Ended != "" {
		panic("done")
	}
	e := commit.Entry{Hash: a.PendingHash, Height: a.PendingHeight}
	got := commit.Hash(who, gen.RoomID(roomPrefix, a.Day, a.Floor, a.N), int(a.Relic), log, salt)
	if why := commit.CheckReveal(e, runtime.ChainHeight(), revealWindow, got); why != "" {
		panic(why)
	}
	f := gen.Layout(a.Day, a.Floor)
	m, why := sim.Parse(f.Grid, f.Props, f.Objective)
	if why != "" {
		panic("floor:" + why) // gen only draws floors Parse accepts
	}
	res := sim.RunFrom(&m, a.Relic, a.HP, log)
	switch {
	case res.Cleared:
		a.PendingHash, a.PendingHeight = "", 0
		cleared(who, a, f.HasChest, res, log, e.Height)
	case res.Reason == "dead":
		a.PendingHash, a.PendingHeight = "", 0
		a.Ended, a.HP = "dead", 0
		emitEnd(who, a, "dead")
	default:
		panic("run:" + res.Reason)
	}
}

// cleared applies a clear of a's current floor: totals, chest, floor best,
// the next floor (with its heal) or the end, then the player's records.
func cleared(who string, a *Record, hasChest bool, res sim.Result, log string, height int64) {
	n := a.Floor
	bd := boardOf(a.Day, true)
	noteFloor(bd, n, FloorRun{
		Owner: address(who), Beats: res.Beats, Damage: res.Damage, Height: height,
		Log: log, Relic: a.Relic, HP: a.HP,
	})
	a.Beats += res.Beats
	a.Damage += res.Damage
	a.HP -= int8(res.Damage)
	if hasChest && res.Chest {
		a.Relic = gen.ChestRelic(a.Day)
		if mx := maxHP(a.Relic); a.HP > mx {
			a.HP = mx
		}
	}
	chain.Emit("DescentFloor", "player", who, "day", u32(a.Day), "floor", strconv.Itoa(int(n)),
		"attempt", u32(a.N), "beats", strconv.Itoa(int(res.Beats)), "damage", strconv.Itoa(int(res.Damage)))
	if n == gen.Floors {
		a.Ended = "cleared"
	} else {
		a.Floor++
		if a.Floor == healFloorA || a.Floor == healFloorB {
			if a.HP < maxHP(a.Relic) {
				a.HP++
			}
		}
	}
	noteResult(a, bd, Row{Owner: address(who), Floors: a.cleared(), Beats: a.Beats, Damage: a.Damage, Height: height})
	noteStreak(a)
	if a.Ended != "" {
		emitEnd(who, a, a.Ended)
	}
}

func emitEnd(who string, a *Record, reason string) {
	chain.Emit("DescentEnd", "player", who, "day", u32(a.Day), "attempt", u32(a.N),
		"floors", strconv.Itoa(int(a.cleared())), "beats", strconv.Itoa(int(a.Beats)),
		"damage", strconv.Itoa(int(a.Damage)), "reason", reason)
}

// maxHP is the hero's max HP with relic, as sim.NewGameFrom sets it
// (TestMaxHPMatchesSim keeps the two in step).
func maxHP(relic uint8) int8 {
	switch relic {
	case 1:
		return 2
	case 2:
		return 4
	}
	return 3
}

// today is the UTC day of the block time.
func today() uint32 { return gen.DayOf(time.Now().Unix()) }

// attemptOf is who's record if they have started an attempt, else nil.
func attemptOf(who string) *Record {
	if r := recordOf(who, false); r != nil && r.N > 0 {
		return r
	}
	return nil
}

// recordOf returns who's record, creating it if create is set (else nil when
// absent).
func recordOf(who string, create bool) *Record {
	if v := records.Get(who); v != nil {
		return v.(*Record)
	}
	if !create {
		return nil
	}
	r := &Record{}
	records.Set(who, r)
	return r
}

func userCaller(cur realm) address {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("caller")
	}
	return prev.Address()
}

// checkLog accepts 1 to gen.DescentMaxBeats chars of '0'..'8': "" when it
// does, else "log" or "too long".
func checkLog(log string) string {
	if len(log) == 0 {
		return "log"
	}
	if len(log) > gen.DescentMaxBeats {
		return "too long"
	}
	for i := 0; i < len(log); i++ {
		if log[i] < '0' || log[i] > '8' {
			return "log"
		}
	}
	return ""
}

func isLowerHex(s string, n int) bool {
	if len(s) != n {
		return false
	}
	for i := 0; i < n; i++ {
		c := s[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

func u32(v uint32) string { return strconv.FormatUint(uint64(v), 10) }

package descent

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/gen"
	"gno.land/p/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/sim"
	"gno.land/r/sys/users"
)

const (
	selfPath = "/r/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/descent" // deploy rewrites the namespace
	hubPath  = "/r/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/v1"
	playURL  = "https://torchbeat.vercel.app"
)

// Render serves "" (today's board, yesterday's winner and a map of today's
// floor 10) and "player/<addr>". A query string is ignored. Every page is
// bounded: the board shows at most 50 rows, a player page at most 8 days,
// and the map draws one floor without replaying anything.
func Render(path string) string {
	if i := strings.IndexByte(path, '?'); i >= 0 {
		path = path[:i]
	}
	switch {
	case path == "":
		return renderHome()
	case strings.HasPrefix(path, "player/"):
		if a := strings.ToLower(path[len("player/"):]); address(a).IsValid() {
			return renderPlayer(a)
		}
	}
	return "# Not found\n\n" + playLine() + "Nothing lives at this path. [Back to the descent](" + selfPath + ").\n"
}

func renderHome() string {
	t := today()
	var b strings.Builder
	b.WriteString("# Torchbeat: Daily Descent\n\n")
	b.WriteString(playLine())
	b.WriteString("Ten floors a day, drawn from the date alone. Every floor counted below was replayed on chain. Today is **" + dateOf(t) + "** (day " + u32(t) + ").\n\n")

	b.WriteString("## Today's board\n\n")
	rows := ""
	if bd := boardOf(t, false); bd != nil {
		rows = bd.Rows
	}
	for i, k := 0, 1; i < len(rows); k++ {
		if i == 0 {
			b.WriteString("| # | Player | Floors | Beats | Damage |\n|---|---|---|---|---|\n")
		}
		var r Row
		r, i = unpackRow(rows, i)
		b.WriteString("| " + strconv.Itoa(k) + " | " + playerLink(r.Owner.String()) + " | " +
			strconv.Itoa(int(r.Floors)) + " | " + strconv.Itoa(int(r.Beats)) + " | " + strconv.Itoa(int(r.Damage)) + " |\n")
	}
	if len(rows) == 0 {
		b.WriteString("No one has cleared a floor today yet.\n")
	}
	b.WriteString("\n## Yesterday's winner\n\n")
	if bd := boardOf(t-1, false); bd != nil && bd.Rows != "" {
		w, _ := unpackRow(bd.Rows, 0)
		b.WriteString(playerLink(w.Owner.String()) + " cleared " + count(int(w.Floors), "floor") + " in " +
			count(int(w.Beats), "beat") + " on " + dateOf(t-1) + ".\n")
	} else {
		b.WriteString("No one cleared a floor on " + dateOf(t-1) + ".\n")
	}
	b.WriteString("\n## Today's floor 10\n\n")
	b.WriteString("![Floor 10 of " + dateOf(t) + "](" + dataURI(floorSVG(t, gen.Floors)) + ")\n")
	return b.String()
}

func renderPlayer(a string) string {
	var p Record
	if v := recordOf(a, false); v != nil {
		p = *v
	}
	t := today()
	var b strings.Builder
	b.WriteString("# " + mdText(displayName(a)) + "\n\n")
	b.WriteString(playLine())
	b.WriteString("Deepest: " + count(int(p.Deepest), "floor") + " in one attempt. Streak: " + count(int(liveStreak(&p, t)), "day") +
		" in a row reaching floor 3 (longest " + strconv.Itoa(int(p.Longest)) + "). All time: " +
		count(int(p.Total), "floor") + " over " + count(int(p.Played), "day") + ".\n\n")

	b.WriteString("## Current attempt\n\n")
	if at := attemptOf(a); at != nil {
		state := "on floor " + strconv.Itoa(int(at.Floor)) + " with " + strconv.Itoa(int(at.HP)) + " HP"
		switch at.Ended {
		case "dead":
			state = "fell on floor " + strconv.Itoa(int(at.Floor))
		case "cleared":
			state = "cleared all " + strconv.Itoa(gen.Floors) + " floors"
		}
		b.WriteString("Attempt " + u32(at.N) + " of " + dateOf(at.Day) + ": " + state + ", " + relicName(at.Relic) + ", " +
			count(int(at.Beats), "beat") + ", " + strconv.Itoa(int(at.Damage)) + " damage so far.\n\n")
	} else {
		b.WriteString("No attempt yet.\n\n")
	}

	b.WriteString("## Recent days\n\n")
	n := 0
	for d := t; ; d-- {
		if r, ok := ringGet(p.Days, d); ok {
			if n == 0 {
				b.WriteString("| Day | Floors | Beats | Damage |\n|---|---|---|---|\n")
			}
			n++
			b.WriteString("| " + dateOf(d) + " | " + strconv.Itoa(int(r.Floors)) + " | " + strconv.Itoa(int(r.Beats)) +
				" | " + strconv.Itoa(int(r.Damage)) + " |\n")
		}
		if d == cutoff(t) {
			break
		}
	}
	if n == 0 {
		b.WriteString("No floors cleared in the last " + strconv.Itoa(keepDays+1) + " days.\n")
	}
	return b.String()
}

// count is "**n** noun", with an s unless n is 1.
func count(n int, noun string) string {
	if n != 1 {
		noun += "s"
	}
	return "**" + strconv.Itoa(n) + "** " + noun
}

func relicName(r uint8) string {
	switch r {
	case 1:
		return "Featherboots"
	case 2:
		return "Ironheart"
	}
	return "no relic"
}

func dateOf(day uint32) string {
	return time.Unix(int64(day)*86400, 0).UTC().Format("2006-01-02")
}

func playLine() string {
	return "**[Play Torchbeat](" + playURL + ")** · [Torchbeat world](" + hubPath + ")\n\n"
}

func mdText(s string) string { return sanitize.InlineText(s) }

// displayName is a's r/sys/users name as "@name", else the shortened address.
func displayName(a string) string {
	if u := users.ResolveAddress(address(a)); u != nil {
		return "@" + u.Name()
	}
	if len(a) <= 10 {
		return a
	}
	return a[:6] + "…" + a[len(a)-4:]
}

func playerLink(a string) string {
	return "[" + mdText(displayName(a)) + "](" + selfPath + ":player/" + a + ")"
}

// ---- Floor map ----

// The SVG goes straight into a data URI, so every '#' is written as %23.
const (
	sharp    = "%23"
	tilePx   = 16
	colFloor = sharp + "2a2420"
	colWall  = sharp + "4a3f36"
	colPit   = sharp + "000000"
	colSpike = sharp + "8a8378"
	colCrumb = sharp + "6b5a48"
	colPlate = sharp + "3d6b5a"
	colGate  = sharp + "b08d57"
	colChest = sharp + "d9a441"
	colExit  = sharp + "5fbf77"
	colHero  = sharp + "f2e3c6"
)

var monCol = [5]string{"", sharp + "7bc96f", sharp + "d07a6a", sharp + "9a7bd0", sharp + "6f93c9"}

// floorSVG draws floor n of day as it starts: tiles, monsters and the hero.
func floorSVG(day uint32, n uint8) []byte {
	f := gen.Layout(day, n)
	m, why := sim.Parse(f.Grid, f.Props, f.Objective)
	if why != "" {
		return nil
	}
	w, h := int(m.W), int(m.H)
	b := make([]byte, 0, 24<<10)
	b = append(b, `<svg xmlns="http://www.w3.org/2000/svg" width="`...)
	b = appendInt(b, w*tilePx*2)
	b = append(b, `" height="`...)
	b = appendInt(b, h*tilePx*2)
	b = append(b, `" viewBox="0 0 `...)
	b = appendInt(b, w*tilePx)
	b = append(b, ' ')
	b = appendInt(b, h*tilePx)
	b = append(b, `" shape-rendering="crispEdges">`...)
	b = appendRect(b, 0, 0, w*tilePx, h*tilePx, colFloor)
	for y := 0; y < h; y++ {
		for x := 0; x < w; {
			c := m.Tiles[y*w+x]
			run := 1
			if c == sim.TWall || c == sim.TPit {
				for x+run < w && m.Tiles[y*w+x+run] == c {
					run++
				}
			}
			if col := tileCol(c); col != "" {
				b = appendRect(b, x*tilePx, y*tilePx, run*tilePx, tilePx, col)
			}
			x += run
		}
	}
	for i := 0; i < int(m.NMons); i++ {
		mon := m.Mons[i]
		if mon.Kind < 1 || mon.Kind > 4 {
			continue
		}
		b = append(b, `<circle cx="`...)
		b = appendInt(b, int(mon.X)*tilePx+tilePx/2)
		b = append(b, `" cy="`...)
		b = appendInt(b, int(mon.Y)*tilePx+tilePx/2)
		b = append(b, `" r="6" fill="`...)
		b = append(b, monCol[mon.Kind]...)
		b = append(b, `"/>`...)
	}
	b = appendRect(b, int(m.StartX)*tilePx+3, int(m.StartY)*tilePx+3, tilePx-6, tilePx-6, colHero)
	return append(b, "</svg>"...)
}

func tileCol(c uint8) string {
	switch c {
	case sim.TWall:
		return colWall
	case sim.TPit:
		return colPit
	case sim.TSpikes:
		return colSpike
	case sim.TCrumble:
		return colCrumb
	case sim.TPlate:
		return colPlate
	case sim.TGate:
		return colGate
	case sim.TChest:
		return colChest
	case sim.TExit:
		return colExit
	}
	return ""
}

func appendRect(b []byte, x, y, w, h int, fill string) []byte {
	b = append(b, `<rect x="`...)
	b = appendInt(b, x)
	b = append(b, `" y="`...)
	b = appendInt(b, y)
	b = append(b, `" width="`...)
	b = appendInt(b, w)
	b = append(b, `" height="`...)
	b = appendInt(b, h)
	b = append(b, `" fill="`...)
	b = append(b, fill...)
	return append(b, `"/>`...)
}

// dataURI turns URI-ready SVG into an image destination, as the hub does:
// sanitize.ImageURL percent-encodes the rest.
func dataURI(svg []byte) string {
	return sanitize.ImageURL("data:image/svg+xml;charset=utf-8," + string(svg))
}

// Package tavern is a short message board built on Torchbeat from another
// namespace: only players the hub records as having cleared at least one room
// may post, and every post is shown with its author's live stats read from
// the hub. An author may post once every 5 blocks, the board keeps the newest
// 50, and Since lets a polling client read what it has not seen yet.
package tavern

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/sys/users"
	torchbeat "gno.land/r/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/v1"
)

const (
	maxPosts = 50
	maxLen   = 140
	cooldown = 5 // blocks between two posts by one author
	hubPage  = "/r/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/v1"
)

type post struct {
	seq    int
	author address
	msg    string
	height int64
}

// ring holds the newest maxPosts posts in place: post number seq lives at
// ring[seq%maxPosts], so the backing storage stays one bounded object.
var ring [maxPosts]post

// newest is the seq of the latest post; the first post is 1. It only grows.
var newest int

// lastPost maps an author's address to the block height of their last post.
var lastPost avl.Tree

// Post puts msg on the board for the caller, at most once every 5 blocks
// ("slow down"): 1 to 140 characters of letters, digits, spaces and . , ! ? ' -
// ("message"), from a player who has cleared at least one Torchbeat room
// ("explore first").
func Post(cur realm, msg string) {
	if !validMessage(msg) {
		panic("message")
	}
	caller := cur.Previous().Address()
	if torchbeat.RoomsCleared(caller) < 1 {
		panic("explore first")
	}
	submit(caller, msg)
}

func validMessage(s string) bool {
	if len(s) < 1 || len(s) > maxLen {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' ||
			c == ' ' || c == '.' || c == ',' || c == '!' || c == '?' || c == '\'' || c == '-') {
			return false
		}
	}
	return true
}

// submit refuses a post made within cooldown blocks of the author's last one,
// else records it.
func submit(author address, msg string) {
	if v := lastPost.Get(string(author)); v != nil && runtime.ChainHeight() < v.(int64)+cooldown {
		panic("slow down")
	}
	record(author, msg)
}

// record stores a checked post as the newest, overwriting the oldest slot once
// the ring is full, and notes the author's post height for the cooldown.
func record(author address, msg string) {
	h := runtime.ChainHeight()
	newest++
	ring[newest%maxPosts] = post{seq: newest, author: author, msg: msg, height: h}
	lastPost.Set(string(author), h)
}

// retained is the seq of the oldest post still in the ring (newest+1 if none).
func retained() int {
	if newest > maxPosts {
		return newest - maxPosts + 1
	}
	return 1
}

// Since returns JSON {"seq":N,"posts":[...]}: N is the newest seq (0 when
// empty) and posts are the retained posts with seq greater than the argument,
// oldest first. A client resumes by passing back the N it last saw; a gap
// larger than the ring shows as a first seq above its argument plus one.
func Since(seq int) string {
	if seq < 0 {
		seq = 0
	}
	first := retained()
	if seq+1 > first {
		first = seq + 1
	}
	b := append([]byte(`{"seq":`), strconv.Itoa(newest)...)
	b = append(b, `,"posts":[`...)
	for s := first; s <= newest; s++ {
		p := ring[s%maxPosts]
		if s > first {
			b = append(b, ',')
		}
		b = append(b, `{"seq":`...)
		b = append(b, strconv.Itoa(p.seq)...)
		b = append(b, `,"author":`...)
		b = appendQuoted(b, p.author.String())
		b = append(b, `,"name":`...)
		b = appendQuoted(b, userName(p.author))
		b = append(b, `,"msg":`...)
		b = appendQuoted(b, p.msg)
		b = append(b, `,"height":`...)
		b = append(b, strconv.FormatInt(p.height, 10)...)
		b = append(b, '}')
	}
	return string(append(b, ']', '}'))
}

const hexDigits = "0123456789abcdef"

// appendQuoted appends s as a JSON string: quote and backslash are
// backslash-escaped, control characters become \u00XX.
func appendQuoted(b []byte, s string) []byte {
	b = append(b, '"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"' || c == '\\':
			b = append(b, '\\', c)
		case c < 0x20:
			b = append(b, '\\', 'u', '0', '0', hexDigits[c>>4], hexDigits[c&0xf])
		default:
			b = append(b, c)
		}
	}
	return append(b, '"')
}

// userName is a's r/sys/users name without "@", or "" if it has none.
func userName(a address) string {
	if u := users.ResolveAddress(a); u != nil {
		return u.Name()
	}
	return ""
}

// Render lists the posts newest first. Each poster's rooms cleared and renown
// are read from the hub at render time, so they stay current.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# The Tavern\n\n")
	b.WriteString("*Smoke, low beams and the smell of torch pitch. Only those who have cleared a room of the [Torchbeat](" +
		hubPage + ") dungeon may speak here. Call `Post` with up to 140 characters.*\n\n")
	if newest == 0 {
		b.WriteString("No one has spoken yet.\n")
		return b.String()
	}
	for s := newest; s >= retained(); s-- {
		p := ring[s%maxPosts]
		a := p.author.String()
		b.WriteString("**[" + sanitize.InlineText(displayName(p.author)) + "](" + hubPage + ":player/" + a + ")** · " +
			plural(torchbeat.RoomsCleared(p.author), "room") + " cleared · renown " +
			strconv.Itoa(torchbeat.Renown(p.author)) + " · block " + strconv.FormatInt(p.height, 10) + "\n\n" +
			sanitize.InlineText(p.msg) + "\n\n")
	}
	return b.String()
}

func plural(n int, noun string) string {
	if n != 1 {
		noun += "s"
	}
	return strconv.Itoa(n) + " " + noun
}

// displayName is a's r/sys/users name as "@name", or the shortened address.
func displayName(a address) string {
	if u := users.ResolveAddress(a); u != nil {
		return "@" + u.Name()
	}
	s := a.String()
	if len(s) <= 10 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

// Package treasury holds the funds and accounting for Shared Budget programs.
package treasury

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1aj9pzthj36aav0kff2zcmx9llapa7ng7xzcfct/shared_budget/budget/v1"
)

const (
	packagePath = "gno.land/r/g1aj9pzthj36aav0kff2zcmx9llapa7ng7xzcfct/shared_budget/treasury/v2"
	maxScheduleBlocks int64 = 2147483647

	Draft          = "draft"
	Active         = "active"
	IssuanceClosed = "issuance_closed"
	Closed         = "closed"

	Reserved = "reserved"
	Approved = "approved"
	Rejected = "rejected"
	Expired  = "expired"
)

type policy struct {
	path       string
	addr       address
	periodCap  int64
	itemCap    int64
	registered bool
	usage      map[int64]int64
	items      map[int64]*reservation
	itemIDs    []int64
}

type claim struct {
	recipient address
	amount    int64
	paid      bool
}

type reservation struct {
	payment  claim
	status   string
	period   int64
	deadline int64
}

type program struct {
	sponsor        address
	status         string
	periodBlocks   int64
	issueBlocks    int64
	maxHold        int64
	start          int64
	issueEnd       int64
	maintenance    policy
	reimbursements policy
	ledger         budget.Ledger
	activeCount    int64
	refund         claim
}

var (
	programs        = make(map[int64]*program)
	latestProgramID int64
	outstanding     int64
)

// CreateProgram pins both policy packages. The sponsor can fund the program
// after each policy has configured its roles and registered.
func CreateProgram(cur realm, maintenancePath, reimbursementsPath string, maintenancePeriodCap, maintenanceItemCap, reimbursementsPeriodCap, reimbursementsItemCap, periodBlocks, issueBlocks, maxHold int64) int64 {
	runtime.AssertOriginCall()
	sponsor := userCaller(cur, false)
	if maintenancePath == reimbursementsPath {
		panic("policies must use distinct realm paths")
	}
	if periodBlocks <= 0 || issueBlocks <= 0 || maxHold <= 0 {
		panic("program durations must be positive")
	}
	if periodBlocks > maxScheduleBlocks || issueBlocks > maxScheduleBlocks || maxHold > maxScheduleBlocks {
		panic("program durations cannot exceed 2147483647 blocks")
	}
	p := &program{
		sponsor:        sponsor,
		status:         Draft,
		periodBlocks:   periodBlocks,
		issueBlocks:    issueBlocks,
		maxHold:        maxHold,
		maintenance:    newPolicy(maintenancePath, maintenancePeriodCap, maintenanceItemCap),
		reimbursements: newPolicy(reimbursementsPath, reimbursementsPeriodCap, reimbursementsItemCap),
	}
	id := budget.Add(latestProgramID, 1)
	programs[id] = p
	latestProgramID = id
	chain.Emit("ProgramCreated", "program", number(id), "sponsor", string(sponsor))
	return id
}

func RegisterPolicy(cur realm, programID int64) {
	requireTreasury(cur)
	p := mustProgram(programID)
	lane, rule := p.policyCaller(cur)
	if p.status != Draft || rule.registered {
		panic("policy registration requires an unconfigured draft")
	}
	rule.registered = true
	chain.Emit("PolicyRegistered", "program", number(programID), "lane", lane, "path", rule.path)
}

func Open(cur realm, programID int64) {
	runtime.AssertOriginCall()
	sponsor := userCaller(cur, true)
	p := sponsorProgram(programID, sponsor)
	if p.status != Draft || !p.maintenance.registered || !p.reimbursements.registered {
		panic("opening requires a draft with both policies registered")
	}
	amount := fundingAmount()
	p.start = runtime.ChainHeight()
	p.issueEnd = budget.Add(p.start, p.issueBlocks)
	p.credit(amount)
	p.status = Active
	chain.Emit("ProgramOpened", "program", number(programID), "sponsor", string(sponsor), "amount", number(amount), "start", number(p.start), "issue_end", number(p.issueEnd))
}

func Fund(cur realm, programID int64) {
	runtime.AssertOriginCall()
	sponsor := userCaller(cur, true)
	p := sponsorProgram(programID, sponsor)
	if p.statusAt(runtime.ChainHeight()) != Active {
		panic("program is not accepting funds")
	}
	amount := fundingAmount()
	p.credit(amount)
	chain.Emit("ProgramFunded", "program", number(programID), "sponsor", string(sponsor), "amount", number(amount))
}

// Reserve is callable by the registered policy for its own spending lane.
func Reserve(cur realm, programID, itemID int64, recipient address, amount, deadline int64) int64 {
	requireTreasury(cur)
	p := mustProgram(programID)
	lane, rule := p.policyCaller(cur)
	height := runtime.ChainHeight()
	if !rule.registered || p.statusAt(height) != Active {
		panic("program is not accepting reservations")
	}
	if itemID <= 0 || rule.items[itemID] != nil {
		panic("item ID must be positive and unused in this lane")
	}
	budget.RequireAddress(recipient)
	if recipient == cur.Address() {
		panic("the treasury cannot be an item recipient")
	}
	budget.RequirePositive(amount)
	budget.CheckDeadline(height, deadline, p.maxHold)
	if amount > rule.itemCap {
		panic("item cap exceeded")
	}
	period := p.periodAt(height)
	if amount > rule.periodCap-rule.usage[period] {
		panic("period cap exceeded")
	}
	if amount > p.ledger.Available {
		panic("shared balance exceeded")
	}

	p.ledger = p.ledger.Reserve(amount)
	p.activeCount = budget.Add(p.activeCount, 1)
	rule.usage[period] = budget.Add(rule.usage[period], amount)
	item := &reservation{
		payment:  claim{recipient: recipient, amount: amount},
		status:   Reserved,
		period:   period,
		deadline: deadline,
	}
	rule.items[itemID] = item
	rule.itemIDs = append(rule.itemIDs, itemID)
	emitItem("Reserved", programID, lane, itemID, item)
	return p.ledger.Available
}

func Approve(cur realm, programID, itemID int64) {
	requireTreasury(cur)
	p := mustProgram(programID)
	lane, rule := p.policyCaller(cur)
	item := rule.pendingBeforeDeadline(itemID)
	p.ledger = p.ledger.Approve(item.payment.amount)
	p.activeCount = budget.Subtract(p.activeCount, 1)
	item.status = Approved
	emitItem("Approved", programID, lane, itemID, item)
}

func Reject(cur realm, programID, itemID int64) {
	requireTreasury(cur)
	p := mustProgram(programID)
	lane, rule := p.policyCaller(cur)
	item := rule.pendingBeforeDeadline(itemID)
	p.release(rule, item, Rejected)
	emitItem("Rejected", programID, lane, itemID, item)
}

func Expire(cur realm, programID int64, lane string, itemID int64) {
	runtime.AssertOriginCall()
	userCaller(cur, false)
	p := mustProgram(programID)
	rule := p.rule(lane)
	item := rule.pending(itemID)
	if runtime.ChainHeight() < item.deadline {
		panic("reservation has not reached its deadline")
	}
	p.release(rule, item, Expired)
	emitItem("Expired", programID, lane, itemID, item)
}

func CloseIssuance(cur realm, programID int64) {
	runtime.AssertOriginCall()
	sponsor := userCaller(cur, false)
	p := sponsorProgram(programID, sponsor)
	if p.statusAt(runtime.ChainHeight()) != Active {
		panic("issuance is not active")
	}
	p.status = IssuanceClosed
	chain.Emit("IssuanceClosed", "program", number(programID), "sponsor", string(sponsor))
}

// FinalizeClose turns the remainder into a sponsor claim. Recipient claims
// continue to be payable after the program closes.
func FinalizeClose(cur realm, programID int64) {
	runtime.AssertOriginCall()
	caller := userCaller(cur, false)
	p := mustProgram(programID)
	if p.statusAt(runtime.ChainHeight()) != IssuanceClosed {
		panic("close issuance before finalization")
	}
	if p.activeCount != 0 {
		panic("program still has active reservations")
	}
	amount := p.ledger.Available
	if amount > 0 {
		p.refund = claim{recipient: p.sponsor, amount: amount}
	}
	p.ledger = p.ledger.RefundAvailable()
	p.status = Closed
	chain.Emit("ProgramClosed", "program", number(programID), "actor", string(caller), "refund", number(amount))
}

// Withdraw pays an approved item. Use lane "refund" and item ID 0 for the
// sponsor claim created by FinalizeClose.
func Withdraw(cur realm, programID int64, lane string, itemID int64) {
	runtime.AssertOriginCall()
	caller := userCaller(cur, false)
	p := mustProgram(programID)
	payment := p.findClaim(lane, itemID)
	if payment == nil || payment.recipient != caller {
		panic("claim is payable only to its recipient")
	}
	if payment.paid {
		panic("claim already paid")
	}

	p.ledger = p.ledger.Pay(payment.amount)
	outstanding = budget.Subtract(outstanding, payment.amount)
	payment.paid = true
	coins := chain.Coins{chain.NewCoin(budget.Denom, payment.amount)}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(cur.Address(), payment.recipient, coins)
	chain.Emit("Withdrawn", "program", number(programID), "lane", lane, "item", number(itemID), "recipient", string(caller), "amount", number(payment.amount))
}

func newPolicy(path string, periodCap, itemCap int64) policy {
	const prefix = "gno.land/r/"
	if len(path) > 256 || !strings.HasPrefix(path, prefix) {
		panic("expected a versioned policy realm path")
	}
	parts := strings.Split(path[len(prefix):], "/")
	version := parts[len(parts)-1]
	if len(parts) < 3 || len(version) < 2 || version[0] != 'v' || path == packagePath {
		panic("expected a versioned policy realm path")
	}
	for _, part := range parts {
		if !validPathSegment(part) {
			panic("expected a versioned policy realm path")
		}
	}
	n, err := strconv.ParseInt(version[1:], 10, 64)
	if err != nil || n < 0 || version != "v"+number(n) {
		panic("expected a versioned policy realm path")
	}
	if itemCap <= 0 || itemCap > periodCap {
		panic("policy caps require 0 < item cap <= period cap")
	}
	return policy{
		path:      path,
		addr:      chain.PackageAddress(path),
		periodCap: periodCap,
		itemCap:   itemCap,
		usage:     make(map[int64]int64),
		items:     make(map[int64]*reservation),
	}
}

// Follow the Gno package path rules for each namespace and package segment.
func validPathSegment(part string) bool {
	if part == "" || part[0] < 'a' || part[0] > 'z' {
		return false
	}
	separator := false
	for i := 1; i < len(part); i++ {
		c := part[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
			separator = false
		case (c == '-' || c == '_') && !separator:
			separator = true
		default:
			return false
		}
	}
	return !separator
}

func (p *program) credit(amount int64) {
	p.ledger = p.ledger.Fund(amount)
	outstanding = budget.Add(outstanding, amount)
}

func (p *program) release(rule *policy, item *reservation, status string) {
	amount := item.payment.amount
	p.ledger = p.ledger.Release(amount)
	p.activeCount = budget.Subtract(p.activeCount, 1)
	rule.usage[item.period] = budget.Subtract(rule.usage[item.period], amount)
	item.status = status
}

func (p *program) statusAt(height int64) string {
	if p.status == Active && height >= p.issueEnd {
		return IssuanceClosed
	}
	return p.status
}

func (p *program) periodAt(height int64) int64 {
	return budget.PeriodAt(height, p.start, p.periodBlocks)
}

func (p *program) rule(lane string) *policy {
	switch lane {
	case budget.Maintenance:
		return &p.maintenance
	case budget.Reimbursements:
		return &p.reimbursements
	default:
		panic("unknown policy lane")
	}
}

func (p *program) policyCaller(cur realm) (string, *policy) {
	caller := cur.Previous()
	if caller.PkgPath() == p.maintenance.path && caller.Address() == p.maintenance.addr {
		return budget.Maintenance, &p.maintenance
	}
	if caller.PkgPath() == p.reimbursements.path && caller.Address() == p.reimbursements.addr {
		return budget.Reimbursements, &p.reimbursements
	}
	panic("caller is not a pinned policy realm")
}

func (p *program) findClaim(lane string, itemID int64) *claim {
	if lane == budget.Refund {
		if itemID == 0 && p.refund.amount > 0 {
			return &p.refund
		}
		return nil
	}
	item := p.rule(lane).items[itemID]
	if item == nil || item.status != Approved {
		return nil
	}
	return &item.payment
}

func (rule *policy) pending(itemID int64) *reservation {
	item := rule.items[itemID]
	if item == nil || item.status != Reserved {
		panic("reservation is not pending")
	}
	return item
}

func (rule *policy) pendingBeforeDeadline(itemID int64) *reservation {
	item := rule.pending(itemID)
	if runtime.ChainHeight() >= item.deadline {
		panic("reservation deadline reached")
	}
	return item
}

func mustProgram(id int64) *program {
	p := programs[id]
	if p == nil {
		panic("program not found")
	}
	return p
}

func sponsorProgram(id int64, caller address) *program {
	p := mustProgram(id)
	if p.sponsor != caller {
		panic("only the program sponsor can do that")
	}
	return p
}

func fundingAmount() int64 {
	coins := unsafe.OriginSend()
	if len(coins) != 1 || coins[0].Denom != budget.Denom || coins[0].Amount <= 0 {
		panic("attach a positive amount of ugnot")
	}
	return coins[0].Amount
}

func requireTreasury(cur realm) {
	if !cur.IsCurrent() || cur.PkgPath() != packagePath {
		panic("invalid treasury context")
	}
}

func userCaller(cur realm, payable bool) address {
	requireTreasury(cur)
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("direct treasury call required")
	}
	if !payable && len(unsafe.OriginSend()) != 0 {
		panic("unexpected attached coins")
	}
	return caller.Address()
}

func emitItem(event string, programID int64, lane string, id int64, item *reservation) {
	chain.Emit(event, "program", number(programID), "lane", lane, "item", number(id),
		"recipient", string(item.payment.recipient), "amount", number(item.payment.amount),
		"period", number(item.period), "deadline", number(item.deadline))
}

func number(n int64) string {
	return strconv.FormatInt(n, 10)
}

package treasury

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1aj9pzthj36aav0kff2zcmx9llapa7ng7xzcfct/shared_budget/budget/v1"
)

const MaxPageSize = 20

type PolicyView struct {
	Path       string
	Address    address
	PeriodCap  int64
	ItemCap    int64
	Registered bool
	Used       int64
}

type ProgramView struct {
	ID                 int64
	Sponsor            address
	Status             string
	StartHeight        int64
	IssueEndHeight     int64
	PeriodBlocks       int64
	MaxHoldBlocks      int64
	CurrentPeriod      int64
	ActiveReservations int64
	Balance            budget.Ledger
	Maintenance        PolicyView
	Reimbursements     PolicyView
}

type ReservationView struct {
	ID              int64
	Lane            string
	Recipient       address
	Amount          int64
	Status          string
	Period          int64
	Deadline        int64
	ExpiredAtHeight bool
	Paid            bool
}

type ClaimView struct {
	Exists    bool
	Recipient address
	Amount    int64
	Paid      bool
}

func LatestProgramID() int64 {
	return latestProgramID
}

func GetProgram(programID int64) ProgramView {
	p := mustProgram(programID)
	height := runtime.ChainHeight()
	period := int64(0)
	if p.status != Draft {
		period = p.periodAt(height)
	}
	return ProgramView{
		ID:                 programID,
		Sponsor:            p.sponsor,
		Status:             p.statusAt(height),
		StartHeight:        p.start,
		IssueEndHeight:     p.issueEnd,
		PeriodBlocks:       p.periodBlocks,
		MaxHoldBlocks:      p.maxHold,
		CurrentPeriod:      period,
		ActiveReservations: p.activeCount,
		Balance:            p.ledger,
		Maintenance:        p.maintenance.view(period),
		Reimbursements:     p.reimbursements.view(period),
	}
}

func GetPeriodUsage(programID, period int64) (int64, int64) {
	if period < 0 {
		panic("period must be non-negative")
	}
	p := mustProgram(programID)
	return p.maintenance.usage[period], p.reimbursements.usage[period]
}

func GetReservation(programID int64, lane string, itemID int64) ReservationView {
	item := mustProgram(programID).rule(lane).items[itemID]
	if item == nil {
		panic("reservation not found")
	}
	return item.view(lane, itemID, runtime.ChainHeight())
}

func ListReservations(programID int64, lane string, offset, limit int) []ReservationView {
	if offset < 0 || limit < 1 || limit > MaxPageSize {
		panic("offset must be non-negative and limit must be 1 to 20")
	}
	rule := mustProgram(programID).rule(lane)
	remaining := len(rule.itemIDs) - offset
	if remaining <= 0 {
		return []ReservationView{}
	}
	if remaining < limit {
		limit = remaining
	}
	height := runtime.ChainHeight()
	page := make([]ReservationView, limit)
	for i, id := range rule.itemIDs[offset : offset+limit] {
		page[i] = rule.items[id].view(lane, id, height)
	}
	return page
}

func GetClaim(programID int64, lane string, itemID int64) ClaimView {
	c := mustProgram(programID).findClaim(lane, itemID)
	if c == nil {
		return ClaimView{}
	}
	return ClaimView{Exists: true, Recipient: c.recipient, Amount: c.amount, Paid: c.paid}
}

// GetTreasuryBalance returns bank cash and the sum owed to all programs.
func GetTreasuryBalance() (int64, int64) {
	addr := chain.PackageAddress(packagePath)
	return banker.NewReadonlyBanker().GetCoin(addr, budget.Denom), outstanding
}

func (rule *policy) view(period int64) PolicyView {
	return PolicyView{
		Path: rule.path, Address: rule.addr, PeriodCap: rule.periodCap, ItemCap: rule.itemCap,
		Registered: rule.registered, Used: rule.usage[period],
	}
}

func (item *reservation) view(lane string, id, height int64) ReservationView {
	return ReservationView{
		ID: id, Lane: lane, Recipient: item.payment.recipient, Amount: item.payment.amount,
		Status: item.status, Period: item.period, Deadline: item.deadline,
		ExpiredAtHeight: item.status == Reserved && height >= item.deadline,
		Paid:            item.payment.paid,
	}
}

func Render(path string) string {
	if path == "" {
		return "# Shared Budget\n\nLatest program ID: " + number(latestProgramID) +
			"\n\nOpen a program with `:programID` or an item with `:programID/lane/itemID`."
	}
	parts := strings.SplitN(path, "/", 4)
	id, err := strconv.ParseInt(parts[0], 10, 64)
	if err != nil || programs[id] == nil {
		return "# Shared Budget\n\nProgram not found."
	}
	if len(parts) != 1 {
		if len(parts) == 3 {
			if parts[1] == "period" {
				return renderPeriod(id, parts[2])
			}
			if parts[1] == budget.Refund && parts[2] == "0" {
				return renderRefund(id)
			}
			return renderItem(id, parts[1], parts[2])
		}
		return "# Shared Budget\n\nUse a program, item, or period link."
	}

	p := GetProgram(id)
	b := p.Balance
	return "# Shared Budget · Program " + number(id) + "\n\n" +
		"- Status: " + p.Status + "\n" +
		"- Sponsor: " + string(p.Sponsor) + "\n" +
		"- Funded: " + number(b.Funded) + " ugnot\n" +
		"- Available: " + number(b.Available) + " ugnot\n" +
		"- Reserved: " + number(b.Reserved) + " ugnot\n" +
		"- Claimable: " + number(b.Claimable) + " ugnot\n" +
		"- Paid: " + number(b.Paid) + " ugnot\n" +
		"- Active reservations: " + number(p.ActiveReservations) + "\n" +
		"- Opening height: " + number(p.StartHeight) + "\n" +
		"- Issuance end: " + number(p.IssueEndHeight) + "\n" +
		"- Current period: [" + number(p.CurrentPeriod) + "](" + programURL(id) + "/period/" +
		number(p.CurrentPeriod) + ")\n" +
		renderPolicy(id, "Maintenance", budget.Maintenance, p.Maintenance) +
		renderPolicy(id, "Reimbursements", budget.Reimbursements, p.Reimbursements) +
		renderRefundLink(id)
}

func renderPolicy(id int64, name, lane string, p PolicyView) string {
	rule := programs[id].rule(lane)
	n := len(rule.itemIDs)
	start := 0
	if n > 4 {
		start = n - 4
	}
	recent := ""
	for _, itemID := range rule.itemIDs[start:] {
		item := rule.items[itemID]
		recent += "- [Item " + number(itemID) + "](" + programURL(id) + "/" + lane + "/" +
			number(itemID) + ") · " + item.status + " · " + number(item.payment.amount) + " ugnot\n"
	}
	link := strings.TrimPrefix(p.Path, "gno.land") + ":" + number(id)
	return "\n## " + name + "\n\n" +
		"- [Policy and roles](" + link + ")\n" +
		"- Period usage: " + number(p.Used) + " / " + number(p.PeriodCap) + " ugnot\n" +
		"- Item cap: " + number(p.ItemCap) + " ugnot\n" +
		recent
}

func programURL(id int64) string {
	return strings.TrimPrefix(packagePath, "gno.land") + ":" + number(id)
}

func renderRefundLink(id int64) string {
	if !GetClaim(id, budget.Refund, 0).Exists {
		return ""
	}
	return "\n[View sponsor refund](" + programURL(id) + "/refund/0)\n"
}

func renderRefund(id int64) string {
	c := GetClaim(id, budget.Refund, 0)
	if !c.Exists {
		return "# Sponsor refund\n\nNo refund claim."
	}
	return "# Sponsor refund\n\n" +
		"- Recipient: " + string(c.Recipient) + "\n" +
		"- Amount: " + number(c.Amount) + " ugnot\n" +
		"- Paid: " + strconv.FormatBool(c.Paid) + "\n"
}

func renderPeriod(id int64, text string) string {
	period, err := strconv.ParseInt(text, 10, 64)
	if err != nil || period < 0 || period > GetProgram(id).CurrentPeriod {
		return "# Shared Budget\n\nPeriod not found."
	}
	maintenance, reimbursements := GetPeriodUsage(id, period)
	return "# Shared Budget · Period " + number(period) + "\n\n" +
		"- Maintenance used: " + number(maintenance) + " ugnot\n" +
		"- Reimbursements used: " + number(reimbursements) + " ugnot\n"
}

func renderItem(programID int64, lane, itemText string) string {
	if lane != budget.Maintenance && lane != budget.Reimbursements {
		return "# Shared Budget\n\nPolicy lane not found."
	}
	id, err := strconv.ParseInt(itemText, 10, 64)
	if err != nil || programs[programID].rule(lane).items[id] == nil {
		return "# Shared Budget\n\nReservation not found."
	}
	item := GetReservation(programID, lane, id)
	return "# " + lane + " · Item " + number(id) + "\n\n" +
		"- Status: " + item.Status + "\n" +
		"- Recipient: " + string(item.Recipient) + "\n" +
		"- Amount: " + number(item.Amount) + " ugnot\n" +
		"- Period: " + number(item.Period) + "\n" +
		"- Deadline: " + number(item.Deadline) + "\n" +
		"- Eligible for expiry: " + strconv.FormatBool(item.ExpiredAtHeight) + "\n" +
		"- Paid: " + strconv.FormatBool(item.Paid) + "\n"
}

// Package maintenance requires two independent reviewers to settle a milestone.
package maintenance

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1aj9pzthj36aav0kff2zcmx9llapa7ng7xzcfct/shared_budget/budget/v1"
	"gno.land/r/g1aj9pzthj36aav0kff2zcmx9llapa7ng7xzcfct/shared_budget/treasury/v2"
)

const packagePath = "gno.land/r/g1aj9pzthj36aav0kff2zcmx9llapa7ng7xzcfct/shared_budget/maintenance/v2"

type Roles struct {
	Coordinator address
	Reviewers   [3]address
}

type milestone struct {
	digest string
	votes  [3]string
}

type program struct {
	roles      Roles
	milestones map[int64]*milestone
}

type MilestoneView struct {
	Evidence    string
	Votes       [3]string
	Reservation treasury.ReservationView
}

var programs = make(map[int64]*program)

func Configure(cur realm, programID int64, coordinator, reviewer1, reviewer2, reviewer3 address) {
	runtime.AssertOriginCall()
	caller := userCaller(cur)
	config := treasury.GetProgram(programID)
	if config.Sponsor != caller {
		panic("only the program sponsor can configure maintenance")
	}
	if config.Status != treasury.Draft || config.Maintenance.Path != packagePath || programs[programID] != nil {
		panic("maintenance configuration requires an unconfigured draft with this policy pinned")
	}
	budget.RequireAddress(coordinator)
	reviewers := [3]address{reviewer1, reviewer2, reviewer3}
	for _, reviewer := range reviewers {
		budget.RequireAddress(reviewer)
		if reviewer == coordinator {
			panic("coordinator cannot be a reviewer")
		}
	}
	if reviewer1 == reviewer2 || reviewer1 == reviewer3 || reviewer2 == reviewer3 {
		panic("reviewers must be distinct")
	}

	programs[programID] = &program{
		roles:      Roles{Coordinator: coordinator, Reviewers: reviewers},
		milestones: make(map[int64]*milestone),
	}
	treasury.RegisterPolicy(cross(cur), programID)
	chain.Emit("MaintenanceConfigured", "program", number(programID), "coordinator", string(coordinator))
}

// SubmitMilestone fixes the evidence and opens a reservation for holdBlocks.
func SubmitMilestone(cur realm, programID, itemID int64, recipient address, amount, holdBlocks int64, proofDigest string) int64 {
	runtime.AssertOriginCall()
	caller := userCaller(cur)
	p := mustProgram(programID)
	if caller != p.roles.Coordinator {
		panic("only the maintenance coordinator can submit")
	}
	evidence := budget.EvidenceCommitment(programID, budget.Maintenance, itemID, proofDigest)
	budget.RequirePositive(holdBlocks)
	deadline := budget.Add(runtime.ChainHeight(), holdBlocks)
	available := treasury.Reserve(cross(cur), programID, itemID, recipient, amount, deadline)
	p.milestones[itemID] = &milestone{digest: evidence}
	chain.Emit("MilestoneSubmitted", "program", number(programID), "item", number(itemID), "actor", string(caller), "evidence", evidence)
	return available
}

func Vote(cur realm, programID, itemID int64, evidence string, approve bool) string {
	runtime.AssertOriginCall()
	caller := userCaller(cur)
	p := mustProgram(programID)
	index := p.reviewerIndex(caller)
	item := p.mustMilestone(itemID)
	reservation := treasury.GetReservation(programID, budget.Maintenance, itemID)
	if caller == reservation.Recipient {
		panic("recipient cannot review their own milestone")
	}
	if reservation.Status != treasury.Reserved || reservation.ExpiredAtHeight {
		panic("milestone is no longer open for review")
	}
	if item.digest != evidence {
		panic("milestone evidence does not match")
	}
	if item.votes[index] != "" {
		panic("reviewer already voted")
	}

	vote := treasury.Rejected
	if approve {
		vote = treasury.Approved
	}
	item.votes[index] = vote
	chain.Emit("MilestoneVote", "program", number(programID), "item", number(itemID), "reviewer", string(caller), "decision", vote, "evidence", evidence)
	matching := 0
	for _, recorded := range item.votes {
		if recorded == vote {
			matching++
		}
	}
	if matching < 2 {
		return treasury.Reserved
	}
	if approve {
		treasury.Approve(cross(cur), programID, itemID)
	} else {
		treasury.Reject(cross(cur), programID, itemID)
	}
	return vote
}

func GetRoles(programID int64) Roles {
	return mustProgram(programID).roles
}

func GetMilestone(programID, itemID int64) MilestoneView {
	item := mustProgram(programID).mustMilestone(itemID)
	return MilestoneView{
		Evidence:    item.digest,
		Votes:       item.votes,
		Reservation: treasury.GetReservation(programID, budget.Maintenance, itemID),
	}
}

func Render(path string) string {
	id, itemID := budget.ParsePolicyViewPath(path)
	p := programs[id]
	if p == nil {
		return "# Shared Budget · Maintenance\n\nOpen a program with `:programID` or a milestone with `:programID/itemID`."
	}
	if itemID == 0 {
		r := p.roles
		return "# Maintenance · Program " + number(id) + "\n\n" +
			"- Coordinator: " + string(r.Coordinator) + "\n" +
			"- Quorum: two of three eligible reviewers\n" +
			"- Reviewers: " + string(r.Reviewers[0]) + ", " + string(r.Reviewers[1]) + ", " + string(r.Reviewers[2]) + "\n"
	}
	if p.milestones[itemID] == nil {
		return "# Maintenance\n\nMilestone not found."
	}
	m := GetMilestone(id, itemID)
	return "# Maintenance · Milestone " + number(itemID) + "\n\n" +
		"- Status: " + m.Reservation.Status + "\n" +
		"- Evidence: `" + m.Evidence + "`\n" +
		"- Votes in reviewer order: [" + m.Votes[0] + ", " + m.Votes[1] + ", " + m.Votes[2] + "]\n"
}

func mustProgram(id int64) *program {
	p := programs[id]
	if p == nil {
		panic("maintenance is not configured for this program")
	}
	return p
}

func (p *program) mustMilestone(itemID int64) *milestone {
	item := p.milestones[itemID]
	if item == nil {
		panic("milestone not found")
	}
	return item
}

func (p *program) reviewerIndex(caller address) int {
	for i, reviewer := range p.roles.Reviewers {
		if reviewer == caller {
			return i
		}
	}
	panic("only a registered maintenance reviewer can vote")
}

func userCaller(cur realm) address {
	if !cur.IsCurrent() || cur.PkgPath() != packagePath || !cur.Previous().IsUserCall() {
		panic("direct maintenance call required")
	}
	if len(unsafe.OriginSend()) != 0 {
		panic("unexpected attached coins")
	}
	return cur.Previous().Address()
}

func number(n int64) string {
	return strconv.FormatInt(n, 10)
}

// Package tavern is a short message board built on Torchbeat from another
// namespace: only players who have cleared at least one room of the hub or one
// floor of the Daily Descent may post, and every post is shown with its author's live stats read from
// the hub. An author may post once every 5 blocks, the board keeps the newest
// 50, and Since lets a polling client read what it has not seen yet.
package tavern

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/sys/users"
	"gno.land/r/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/descent"
	torchbeat "gno.land/r/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/v1"
)

const (
	maxPosts = 50
	maxLen   = 140
	cooldown = 5 // blocks between two posts by one author
	hubPage  = "/r/g1tesdl67tx9xv8856gmtsh8mrj26kfjky8jwgcl/torchbeat/v1"
)

type post struct {
	seq    int
	author address
	msg    string
	height int64
}

// ring holds the newest maxPosts posts in place: post number seq lives at
// ring[seq%maxPosts], so the backing storage stays one bounded object.
var ring [maxPosts]post

// newest is the seq of the latest post; the first post is 1. It only grows.
var newest int

// lastPost maps an author's address to the block height of their last post.
var lastPost avl.Tree

// Post puts msg on the board for the caller, at most once every 5 blocks
// ("slow down"): 1 to 140 characters of letters, digits, spaces and . , ! ? ' -
// ("message"), from a player who has cleared at least one Torchbeat room or
// one Daily Descent floor ("explore first").
func Post(cur realm, msg string) {
	if !validMessage(msg) {
		panic("message")
	}
	caller := cur.Previous().Address()
	if torchbeat.RoomsCleared(caller) < 1 && deepestOf(descent.Player(caller.String())) < 1 {
		panic("explore first")
	}
	submit(caller, msg)
}

// deepestOf reads "deepest" from the descent's Player JSON, which always opens
// with that field; anything else reads as 0.
func deepestOf(js string) int {
	const head = `{"deepest":`
	if !strings.HasPrefix(js, head) {
		return 0
	}
	n := 0
	for i := len(head); i < len(js) && js[i] >= '0' && js[i] <= '9'; i++ {
		n = n*10 + int(js[i]-'0')
	}
	return n
}

func validMessage(s string) bool {
	if len(s) < 1 || len(s) > maxLen {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' ||
			c == ' ' || c == '.' || c == ',' || c == '!' || c == '?' || c == '\'' || c == '-') {
			return false
		}
	}
	return true
}

// submit refuses a post made within cooldown blocks of the author's last one,
// else records it.
func submit(author address, msg string) {
	if v := lastPost.Get(string(author)); v != nil && runtime.ChainHeight() < v.(int64)+cooldown {
		panic("slow down")
	}
	record(author, msg)
}

// record stores a checked post as the newest, overwriting the oldest slot once
// the ring is full, and notes the author's post height for the cooldown.
func record(author address, msg string) {
	h := runtime.ChainHeight()
	newest++
	ring[newest%maxPosts] = post{seq: newest, author: author, msg: msg, height: h}
	lastPost.Set(string(author), h)
}

// retained is the seq of the oldest post still in the ring (newest+1 if none).
func retained() int {
	if newest > maxPosts {
		return newest - maxPosts + 1
	}
	return 1
}

// Since returns JSON {"seq":N,"posts":[...]}: N is the newest seq (0 when
// empty) and posts are the retained posts with seq greater than the argument,
// oldest first. A client resumes by passing back the N it last saw; a gap
// larger than the ring shows as a first seq above its argument plus one.
func Since(seq int) string {
	if seq < 0 {
		seq = 0
	}
	first := retained()
	if seq+1 > first {
		first = seq + 1
	}
	b := append([]byte(`{"seq":`), strconv.Itoa(newest)...)
	b = append(b, `,"posts":[`...)
	for s := first; s <= newest; s++ {
		p := ring[s%maxPosts]
		if s > first {
			b = append(b, ',')
		}
		b = append(b, `{"seq":`...)
		b = append(b, strconv.Itoa(p.seq)...)
		b = append(b, `,"author":`...)
		b = appendQuoted(b, p.author.String())
		b = append(b, `,"name":`...)
		b = appendQuoted(b, userName(p.author))
		b = append(b, `,"msg":`...)
		b = appendQuoted(b, p.msg)
		b = append(b, `,"height":`...)
		b = append(b, strconv.FormatInt(p.height, 10)...)
		b = append(b, '}')
	}
	return string(append(b, ']', '}'))
}

const hexDigits = "0123456789abcdef"

// appendQuoted appends s as a JSON string: quote and backslash are
// backslash-escaped, control characters become \u00XX.
func appendQuoted(b []byte, s string) []byte {
	b = append(b, '"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"' || c == '\\':
			b = append(b, '\\', c)
		case c < 0x20:
			b = append(b, '\\', 'u', '0', '0', hexDigits[c>>4], hexDigits[c&0xf])
		default:
			b = append(b, c)
		}
	}
	return append(b, '"')
}

// userName is a's r/sys/users name without "@", or "" if it has none.
func userName(a address) string {
	if u := users.ResolveAddress(a); u != nil {
		return u.Name()
	}
	return ""
}

// Render lists the posts newest first. Each poster's rooms cleared and renown
// are read from the hub at render time, so they stay current.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# The Tavern\n\n")
	b.WriteString("*Smoke, low beams and the smell of torch pitch. Only those who have cleared a room or a Daily Descent floor of the [Torchbeat](" +
		hubPage + ") dungeon may speak here. Call `Post` with up to 140 characters.*\n\n")
	if newest == 0 {
		b.WriteString("No one has spoken yet.\n")
		return b.String()
	}
	for s := newest; s >= retained(); s-- {
		p := ring[s%maxPosts]
		a := p.author.String()
		b.WriteString("**[" + sanitize.InlineText(displayName(p.author)) + "](" + hubPage + ":player/" + a + ")** · " +
			plural(torchbeat.RoomsCleared(p.author), "room") + " cleared · renown " +
			strconv.Itoa(torchbeat.Renown(p.author)) + " · block " + strconv.FormatInt(p.height, 10) + "\n\n" +
			sanitize.InlineText(p.msg) + "\n\n")
	}
	return b.String()
}

func plural(n int, noun string) string {
	if n != 1 {
		noun += "s"
	}
	return strconv.Itoa(n) + " " + noun
}

// displayName is a's r/sys/users name as "@name", or the shortened address.
func displayName(a address) string {
	if u := users.ResolveAddress(a); u != nil {
		return "@" + u.Name()
	}
	s := a.String()
	if len(s) <= 10 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

// Package reimbursements gives the finance officer control over expense approvals.
package reimbursements

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1aj9pzthj36aav0kff2zcmx9llapa7ng7xzcfct/shared_budget/budget/v1"
	"gno.land/r/g1aj9pzthj36aav0kff2zcmx9llapa7ng7xzcfct/shared_budget/treasury/v2"
)

const packagePath = "gno.land/r/g1aj9pzthj36aav0kff2zcmx9llapa7ng7xzcfct/shared_budget/reimbursements/v2"

type Roles struct {
	Clerk          address
	FinanceOfficer address
}

type expense struct {
	digest   string
	decision string
}

type program struct {
	roles    Roles
	expenses map[int64]*expense
}

type ExpenseView struct {
	Evidence    string
	Decision    string
	Reservation treasury.ReservationView
}

var programs = make(map[int64]*program)

func Configure(cur realm, programID int64, clerk, financeOfficer address) {
	runtime.AssertOriginCall()
	caller := userCaller(cur)
	config := treasury.GetProgram(programID)
	if config.Sponsor != caller {
		panic("only the program sponsor can configure reimbursements")
	}
	if config.Status != treasury.Draft || config.Reimbursements.Path != packagePath || programs[programID] != nil {
		panic("reimbursements configuration requires an unconfigured draft with this policy pinned")
	}
	budget.RequireAddress(clerk)
	budget.RequireAddress(financeOfficer)
	if clerk == financeOfficer {
		panic("expense clerk and finance officer must be distinct")
	}

	programs[programID] = &program{
		roles:    Roles{Clerk: clerk, FinanceOfficer: financeOfficer},
		expenses: make(map[int64]*expense),
	}
	treasury.RegisterPolicy(cross(cur), programID)
	chain.Emit("ReimbursementsConfigured", "program", number(programID), "clerk", string(clerk), "finance", string(financeOfficer))
}

// SubmitExpense fixes the evidence and opens a reservation for holdBlocks.
func SubmitExpense(cur realm, programID, itemID int64, recipient address, amount, holdBlocks int64, proofDigest string) int64 {
	runtime.AssertOriginCall()
	caller := userCaller(cur)
	p := mustProgram(programID)
	if caller != p.roles.Clerk {
		panic("only the expense clerk can submit")
	}
	if recipient == p.roles.FinanceOfficer {
		panic("finance officer cannot be the recipient")
	}
	evidence := budget.EvidenceCommitment(programID, budget.Reimbursements, itemID, proofDigest)
	budget.RequirePositive(holdBlocks)
	deadline := budget.Add(runtime.ChainHeight(), holdBlocks)
	available := treasury.Reserve(cross(cur), programID, itemID, recipient, amount, deadline)
	p.expenses[itemID] = &expense{digest: evidence}
	chain.Emit("ExpenseSubmitted", "program", number(programID), "item", number(itemID), "actor", string(caller), "evidence", evidence)
	return available
}

func Decide(cur realm, programID, itemID int64, evidence string, approve bool) string {
	runtime.AssertOriginCall()
	caller := userCaller(cur)
	p := mustProgram(programID)
	if caller != p.roles.FinanceOfficer {
		panic("only the finance officer can decide")
	}
	item := p.mustExpense(itemID)
	if item.digest != evidence {
		panic("expense evidence does not match")
	}
	if item.decision != "" {
		panic("expense already decided")
	}

	if approve {
		treasury.Approve(cross(cur), programID, itemID)
		item.decision = treasury.Approved
	} else {
		treasury.Reject(cross(cur), programID, itemID)
		item.decision = treasury.Rejected
	}
	chain.Emit("ExpenseDecided", "program", number(programID), "item", number(itemID), "officer", string(caller), "decision", item.decision, "evidence", evidence)
	return item.decision
}

func GetRoles(programID int64) Roles {
	return mustProgram(programID).roles
}

func GetExpense(programID, itemID int64) ExpenseView {
	item := mustProgram(programID).mustExpense(itemID)
	return ExpenseView{
		Evidence:    item.digest,
		Decision:    item.decision,
		Reservation: treasury.GetReservation(programID, budget.Reimbursements, itemID),
	}
}

func Render(path string) string {
	id, itemID := budget.ParsePolicyViewPath(path)
	p := programs[id]
	if p == nil {
		return "# Shared Budget · Reimbursements\n\nOpen a program with `:programID` or an expense with `:programID/itemID`."
	}
	if itemID == 0 {
		return "# Reimbursements · Program " + number(id) + "\n\n" +
			"- Expense clerk: " + string(p.roles.Clerk) + "\n" +
			"- Finance officer: " + string(p.roles.FinanceOfficer) + "\n"
	}
	if p.expenses[itemID] == nil {
		return "# Reimbursements\n\nExpense not found."
	}
	expense := GetExpense(id, itemID)
	return "# Reimbursements · Expense " + number(itemID) + "\n\n" +
		"- Status: " + expense.Reservation.Status + "\n" +
		"- Evidence: `" + expense.Evidence + "`\n"
}

func mustProgram(id int64) *program {
	p := programs[id]
	if p == nil {
		panic("reimbursements is not configured for this program")
	}
	return p
}

func (p *program) mustExpense(itemID int64) *expense {
	item := p.expenses[itemID]
	if item == nil {
		panic("expense not found")
	}
	return item
}

func userCaller(cur realm) address {
	if !cur.IsCurrent() || cur.PkgPath() != packagePath || !cur.Previous().IsUserCall() {
		panic("direct reimbursements call required")
	}
	if len(unsafe.OriginSend()) != 0 {
		panic("unexpected attached coins")
	}
	return cur.Previous().Address()
}

func number(n int64) string {
	return strconv.FormatInt(n, 10)
}

// Package check is a small test harness that runs inside a transaction.
//
// Go's testing package only runs under `gno test`. Assertpay needs the
// same idea on chain: a spec's tests run against a submitted implementation
// while a realm call is executing, and every result is kept. Each test runs
// under recover, so a panic in the implementation (declared in a /p/
// package) fails that one test instead of aborting the transaction.
package check

import "strconv"

// T is handed to each test.
type T struct {
	failed bool
	msg    string
}

// stop is the panic value of Fatal. It carries its T so that code under
// test cannot fake a clean stop with a throwaway T.
type stop struct{ t *T }

// Fatal fails the test with msg and stops it.
func (t *T) Fatal(msg string) {
	t.failed = true
	t.msg = msg
	panic(stop{t})
}

// Check fails the test with msg if ok is false.
func (t *T) Check(ok bool, msg string) {
	if !ok {
		t.Fatal(msg)
	}
}

// Test is one named check.
type Test struct {
	Name string
	Fn   func(t *T)
}

// Result is the outcome of one test.
type Result struct {
	Name string
	Pass bool
	Msg  string
}

// Spec describes a spec package to the Assertpay realm.
type Spec struct {
	Name string // short id, e.g. "intervals"
	Doc  string // one paragraph for humans
	// Tests builds the tests for an implementation and a seed. impl is
	// whatever the solver submitted; a spec must turn a wrong type into a
	// failing test, never a panic.
	Tests func(impl any, seed uint64) []Test
}

// Run runs every test and returns the results in order.
func Run(tests []Test) []Result {
	out := make([]Result, 0, len(tests))
	for _, tc := range tests {
		out = append(out, runOne(tc))
	}
	return out
}

// RunSpec builds and runs a spec's tests for impl and seed.
func RunSpec(s Spec, impl any, seed uint64) []Result {
	var tests []Test
	func() {
		defer func() {
			if recover() != nil {
				tests = []Test{{Name: "Build", Fn: func(t *T) { t.Fatal("the spec could not build tests for this implementation") }}}
			}
		}()
		tests = s.Tests(impl, seed)
	}()
	return Run(tests)
}

func runOne(tc Test) (r Result) {
	r.Name = tc.Name
	t := &T{}
	defer func() {
		if e := recover(); e != nil {
			s, ok := e.(stop)
			switch {
			case ok && s.t == t && t.failed:
				// a clean Fatal of this test
			case ok:
				t.failed = true
				t.msg = "implementation called check.T.Fatal itself"
			default:
				t.failed = true
				t.msg = "implementation panicked: " + panicText(e)
			}
		}
		r.Pass = !t.failed
		r.Msg = t.msg
	}()
	tc.Fn(t)
	return
}

func panicText(e any) string {
	switch v := e.(type) {
	case string:
		return v
	case error:
		return v.Error()
	}
	return "non-string panic"
}

// Passed counts passing results.
func Passed(rs []Result) int {
	n := 0
	for _, r := range rs {
		if r.Pass {
			n++
		}
	}
	return n
}

// FirstFailure returns the first failing result, if any.
func FirstFailure(rs []Result) (Result, bool) {
	for _, r := range rs {
		if !r.Pass {
			return r, true
		}
	}
	return Result{}, false
}

// Rand is a small deterministic generator (xorshift64*).
type Rand struct{ s uint64 }

// NewRand returns a generator for seed (0 is remapped).
func NewRand(seed uint64) *Rand {
	if seed == 0 {
		seed = 0x9e3779b97f4a7c15
	}
	return &Rand{s: seed}
}

// Next returns the next 64-bit value.
func (r *Rand) Next() uint64 {
	r.s ^= r.s >> 12
	r.s ^= r.s << 25
	r.s ^= r.s >> 27
	return r.s * 2685821657736338717
}

// Intn returns a value in [0, n).
func (r *Rand) Intn(n int) int {
	if n <= 0 {
		return 0
	}
	return int(r.Next() % uint64(n))
}

// Sub derives an independent seed for case i, so each generated case can be
// reproduced on its own.
func Sub(seed uint64, i int) uint64 {
	r := NewRand(seed ^ (uint64(i+1) * 0x9e3779b97f4a7c15))
	r.Next()
	return r.Next()
}

// Itoa is strconv.Itoa, re-exported for spec messages.
func Itoa(n int) string { return strconv.Itoa(n) }

// Package market is Assertpay's task state machine, kept pure: it takes
// heights, addresses and amounts as arguments and returns the payments to
// make. The realm owns the coins and decides who may call what and when.
//
// A task is funded on a spec. Solvers commit a hash with a bond, then
// reveal an implementation whose test results the realm passes in. Passing
// attempts are ordered by commit height; the earliest one not removed is
// the winner. During the window anyone may challenge the winner with a
// seed of their choice; a failure removes it and pays its bond to the
// challenger. After the window the winner can be paid.
package market

import "errors"

// Parameters, in blocks and ugnot.
const (
	Expiry      = 600 // a commit must be revealed within this many blocks
	MinWindow   = 100 // challenge window after a new winner, chosen per task
	MaxWindow   = 100_000
	MinGrace    = 1200      // an open challenge can be run for max(window, MinGrace) blocks
	FailFee     = 4         // a failed reveal forfeits bond/FailFee, so squatting costs money
	MinBond     = 1_000_000 // 1 GNOT
	BondDivisor = 10        // bond = max(MinBond, reward / BondDivisor)
	MinReward   = 1_000_000
	MinDeadline = 200
	MaxDeadline = 200_000
)

var (
	ErrClosed        = errors.New("task is closed")
	ErrDeadline      = errors.New("commits are closed: the deadline has passed")
	ErrLiveCommit    = errors.New("you already have a live commit on this task")
	ErrNoCommit      = errors.New("no live commit matches this reveal")
	ErrNoWinner      = errors.New("no winner to challenge")
	ErrWindowOver    = errors.New("the challenge window is over")
	ErrOpenChal      = errors.New("a challenge is already open")
	ErrNoOpenChal    = errors.New("no open challenge")
	ErrGraceRunning  = errors.New("the challenge can still be run: anyone may call RunChallenge")
	ErrNotClaimable  = errors.New("not claimable yet")
	ErrEarlierCommit = errors.New("not claimable yet: an earlier commit can still be revealed")
	ErrNotRefund     = errors.New("not refundable: deadline not passed, or a winner, live commit or challenge exists")
	ErrBadParams     = errors.New("bad parameters")
)

// State of a task.
const (
	Open     = "open"
	Paid     = "paid"
	Refunded = "refunded"
)

// Payment is a transfer the realm must make.
type Payment struct {
	To     address
	Amount int64
	Why    string
}

// Commit is a sealed promise to reveal.
type Commit struct {
	Hash      string
	Who       address
	Height    int64
	Revealed  bool
	Forfeited bool
}

// Attempt is one revealed implementation and its results.
type Attempt struct {
	ID       int
	Who      address
	Entry    string // realm that revealed it
	CommitH  int64
	Height   int64
	Seed     uint64
	Passed   int
	Total    int
	Fail     string // first failure, "Name: message"
	Bits     string // one char per test, 'p' or 'f'
	Removed  bool   // knocked out by a challenge
	BondHeld bool   // bond locked because it passed
	Impl     any    // what was submitted, kept for challenges
}

// Challenge is a recorded challenge of the winner.
type Challenge struct {
	Who     address
	Target  int // attempt id
	Seed    uint64
	Height  int64
	Bond    int64 // only for the open (two-phase) kind
	Open    bool
	Outcome string // "held", "broke", "timeout"
	Fail    string
	Bits    string
}

// Task is one funded spec.
type Task struct {
	ID         int
	Spec       string
	Sponsor    address
	Reward     int64
	Bond       int64
	Created    int64
	Deadline   int64
	State      string
	Commits    []*Commit
	Attempts   []*Attempt
	Challenges []*Challenge
	WinnerID   int   // -1 when none
	Window     int64 // challenge window length in blocks
	WindowEnd  int64
	Forfeit    int64 // expired bonds (kept out of the reward)
}

// NewTask validates and opens a task.
func NewTask(id int, spec string, sponsor address, reward int64, now, deadlineBlocks, window int64) *Task {
	if reward < MinReward || deadlineBlocks < MinDeadline || deadlineBlocks > MaxDeadline || window < MinWindow || window > MaxWindow || spec == "" {
		panic(ErrBadParams)
	}
	bond := reward / BondDivisor
	if bond < MinBond {
		bond = MinBond
	}
	return &Task{ID: id, Spec: spec, Sponsor: sponsor, Reward: reward, Bond: bond, Created: now, Deadline: now + deadlineBlocks, Window: window, State: Open, WinnerID: -1}
}

func (t *Task) mustOpen() {
	if t.State != Open {
		panic(ErrClosed)
	}
}

// Live reports whether a commit can still be revealed at now.
func (c *Commit) Live(now int64) bool {
	return !c.Revealed && !c.Forfeited && now-c.Height <= Expiry
}

// Sweep forfeits expired commits and returns how much bond moved to the
// forfeit pool. Every state change calls it first.
func (t *Task) Sweep(now int64) int64 {
	var moved int64
	for _, c := range t.Commits {
		if !c.Revealed && !c.Forfeited && now-c.Height > Expiry {
			c.Forfeited = true
			t.Forfeit += t.Bond
			moved += t.Bond
		}
	}
	return moved
}

// AddCommit records a commit; the caller has already received the bond.
func (t *Task) AddCommit(who address, hash string, now int64) {
	t.mustOpen()
	t.Sweep(now)
	if now > t.Deadline {
		panic(ErrDeadline)
	}
	for _, c := range t.Commits {
		if c.Who == who && c.Live(now) {
			panic(ErrLiveCommit)
		}
	}
	t.Commits = append(t.Commits, &Commit{Hash: hash, Who: who, Height: now})
}

// FindCommit returns the live commit with hash by who.
func (t *Task) FindCommit(who address, hash string, now int64) *Commit {
	t.mustOpen()
	t.Sweep(now)
	for _, c := range t.Commits {
		if c.Hash == hash && c.Who == who && c.Live(now) {
			return c
		}
	}
	panic(ErrNoCommit)
}

// Result summarises a test run for the market.
type Result struct {
	Seed   uint64
	Passed int
	Total  int
	Fail   string
	Bits   string
}

// Pass reports whether every test passed.
func (r Result) Pass() bool { return r.Total > 0 && r.Passed == r.Total }

// Reveal records an attempt for commit c. A failing attempt gets its bond
// back now; a passing one keeps it locked and may become the winner.
func (t *Task) Reveal(c *Commit, entry string, impl any, res Result, now int64) (*Attempt, []Payment) {
	c.Revealed = true
	a := &Attempt{ID: len(t.Attempts), Who: c.Who, Entry: entry, CommitH: c.Height, Height: now, Seed: res.Seed,
		Passed: res.Passed, Total: res.Total, Fail: res.Fail, Bits: res.Bits, Impl: impl}
	t.Attempts = append(t.Attempts, a)
	if !res.Pass() {
		fee := t.Bond / FailFee
		t.Forfeit += fee
		return a, []Payment{{To: c.Who, Amount: t.Bond - fee, Why: "bond back minus the failed-reveal fee"}}
	}
	a.BondHeld = true
	t.elect(now)
	return a, nil
}

// elect picks the earliest-committed passing attempt not removed and
// restarts the window if the winner changed.
func (t *Task) elect(now int64) {
	best := -1
	for _, a := range t.Attempts {
		if !a.BondHeld || a.Removed {
			continue
		}
		if best < 0 || a.CommitH < t.Attempts[best].CommitH || (a.CommitH == t.Attempts[best].CommitH && a.ID < best) {
			best = a.ID
		}
	}
	if best != t.WinnerID {
		t.WinnerID = best
		if best >= 0 {
			t.WindowEnd = now + t.Window
		}
	}
}

// Winner returns the current winner or nil.
func (t *Task) Winner() *Attempt {
	if t.WinnerID < 0 {
		return nil
	}
	return t.Attempts[t.WinnerID]
}

// OpenChallenge returns the open two-phase challenge, if any.
func (t *Task) OpenChallenge() *Challenge {
	for _, c := range t.Challenges {
		if c.Open {
			return c
		}
	}
	return nil
}

func (t *Task) mustChallengeable(now int64) *Attempt {
	t.mustOpen()
	w := t.Winner()
	if w == nil {
		panic(ErrNoWinner)
	}
	if now > t.WindowEnd {
		panic(ErrWindowOver)
	}
	if t.OpenChallenge() != nil {
		panic(ErrOpenChal)
	}
	return w
}

// CheckChallenge validates a one-shot challenge before the realm runs it.
func (t *Task) CheckChallenge(now int64) *Attempt { return t.mustChallengeable(now) }

// Challenged records a one-shot challenge result. A failure removes the
// winner and pays its bond to the challenger.
func (t *Task) Challenged(who address, res Result, now int64) []Payment {
	w := t.mustChallengeable(now)
	ch := &Challenge{Who: who, Target: w.ID, Seed: res.Seed, Height: now, Fail: res.Fail, Bits: res.Bits}
	t.Challenges = append(t.Challenges, ch)
	if res.Pass() {
		ch.Outcome = "held"
		return nil
	}
	ch.Outcome = "broke"
	return t.knockOut(w, who, 0, now)
}

func (t *Task) knockOut(w *Attempt, challenger address, extra int64, now int64) []Payment {
	w.Removed = true
	w.BondHeld = false
	t.elect(now)
	return []Payment{{To: challenger, Amount: t.Bond + extra, Why: "challenge broke the winner"}}
}

// Open starts a two-phase challenge (for winners whose code aborts the
// transaction). The caller has received bond from the challenger.
func (t *Task) Open(who address, seed uint64, bond int64, now int64) *Challenge {
	w := t.mustChallengeable(now)
	if bond < t.Bond {
		panic(ErrBadParams)
	}
	ch := &Challenge{Who: who, Target: w.ID, Seed: seed, Height: now, Bond: bond, Open: true}
	t.Challenges = append(t.Challenges, ch)
	return ch
}

// RanOpen records the run of the open challenge.
//
// If the winner holds, the challenger's bond is split: half to whoever ran
// it (so third parties are paid to keep honest winners from being timed
// out while offline) and the rest to the winner.
func (t *Task) RanOpen(runner address, res Result, now int64) []Payment {
	ch := t.OpenChallenge()
	if ch == nil {
		panic(ErrNoOpenChal)
	}
	ch.Open = false
	ch.Fail, ch.Bits = res.Fail, res.Bits
	w := t.Attempts[ch.Target]
	if res.Pass() {
		ch.Outcome = "held"
		fee := ch.Bond / 2
		return []Payment{{To: runner, Amount: fee, Why: "ran a challenge the winner held"}, {To: w.Who, Amount: ch.Bond - fee, Why: "challenger bond: winner held"}}
	}
	ch.Outcome = "broke"
	return t.knockOut(w, ch.Who, ch.Bond, now)
}

// TimeoutOpen resolves an open challenge that nobody could run within the
// task's window length: the winner is removed. Running a challenge is
// permissionless and pays the runner when the winner holds, so an honest
// winner does not depend on being online.
func (t *Task) TimeoutOpen(now int64) []Payment {
	ch := t.OpenChallenge()
	if ch == nil {
		panic(ErrNoOpenChal)
	}
	grace := t.Window
	if grace < MinGrace {
		grace = MinGrace
	}
	if now-ch.Height <= grace {
		panic(ErrGraceRunning)
	}
	ch.Open = false
	ch.Outcome = "timeout"
	return t.knockOut(t.Attempts[ch.Target], ch.Who, ch.Bond, now)
}

// Claim pays the winner after the window.
func (t *Task) Claim(now int64) []Payment {
	t.mustOpen()
	t.Sweep(now)
	w := t.Winner()
	if w == nil || now <= t.WindowEnd || t.OpenChallenge() != nil {
		panic(ErrNotClaimable)
	}
	for _, c := range t.Commits {
		if c.Live(now) && c.Height < w.CommitH {
			panic(ErrEarlierCommit)
		}
	}
	t.State = Paid
	w.BondHeld = false
	pays := []Payment{{To: w.Who, Amount: t.Reward + t.Bond, Why: "reward and bond"}}
	// later commits that were never revealed get their bonds back
	for _, c := range t.Commits {
		if c.Live(now) {
			c.Revealed = true
			pays = append(pays, Payment{To: c.Who, Amount: t.Bond, Why: "bond back: task closed before your reveal"})
		}
	}
	// other passing attempts get their bonds back
	for _, a := range t.Attempts {
		if a.BondHeld {
			a.BondHeld = false
			pays = append(pays, Payment{To: a.Who, Amount: t.Bond, Why: "bond back: task closed"})
		}
	}
	return pays
}

// Refund returns the reward after the deadline when nothing is pending.
func (t *Task) Refund(now int64) []Payment {
	t.mustOpen()
	t.Sweep(now)
	if now <= t.Deadline || t.Winner() != nil || t.OpenChallenge() != nil {
		panic(ErrNotRefund)
	}
	for _, c := range t.Commits {
		if c.Live(now) {
			panic(ErrNotRefund)
		}
	}
	t.State = Refunded
	return []Payment{{To: t.Sponsor, Amount: t.Reward, Why: "refund: no passing implementation"}}
}

// Package intervals is an Assertpay spec: a set of integers stored as
// half-open intervals.
//
// An implementation provides a Factory. Every test builds a fresh Set,
// applies a sequence of operations and compares the result with a simple
// bitmap model. Fixed examples come first; then Cases generated cases from
// the seed, each reproducible on its own with check.Sub(seed, i).
package intervals

import (
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/check/v1"
)

// Set is the interface a solver implements.
type Set interface {
	// Add inserts every x with lo <= x < hi. lo >= hi is a no-op.
	Add(lo, hi int)
	// Remove deletes every x with lo <= x < hi. lo >= hi is a no-op.
	Remove(lo, hi int)
	// Contains reports whether x is in the set.
	Contains(x int) bool
	// Spans returns the set as sorted, disjoint, non-touching half-open
	// intervals: [lo, hi) pairs where each hi < the next lo.
	Spans() [][2]int
}

// Factory builds an empty Set.
type Factory func() Set

const (
	// Cases is the number of generated cases per seed.
	Cases = 16
	// Universe bounds generated values to [0, Universe).
	Universe = 48
	// Ops is the number of operations per generated case.
	Ops = 12
)

// Spec describes this spec to Assertpay.
func Spec() check.Spec {
	return check.Spec{
		Name:  "intervals",
		Doc:   "An integer set stored as half-open intervals: Add, Remove, Contains and Spans (sorted, disjoint, merged). Checked against a bitmap model.",
		Tests: Tests,
	}
}

type op struct {
	add    bool
	lo, hi int
}

// Tests builds the tests for impl (a Factory or a func() Set).
func Tests(impl any, seed uint64) []check.Test {
	f, ok := asFactory(impl)
	if !ok {
		return []check.Test{{Name: "Type", Fn: func(t *check.T) { t.Fatal("implementation is not an intervals.Factory") }}}
	}
	tests := []check.Test{
		{"AddOne", run(f, []op{{true, 2, 5}})},
		{"MergeOverlap", run(f, []op{{true, 1, 4}, {true, 3, 8}})},
		{"RemoveMiddle", run(f, []op{{true, 0, 10}, {false, 4, 6}})},
		{"EmptyRange", run(f, []op{{true, 5, 5}, {true, 7, 3}})},
	}
	for i := 0; i < Cases; i++ {
		tests = append(tests, check.Test{Name: "Case" + check.Itoa(i), Fn: run(f, gen(check.Sub(seed, i)))})
	}
	return tests
}

func asFactory(impl any) (Factory, bool) {
	switch v := impl.(type) {
	case Factory:
		return v, v != nil
	case func() Set:
		return Factory(v), v != nil
	}
	return nil, false
}

func gen(seed uint64) []op {
	r := check.NewRand(seed)
	ops := make([]op, Ops)
	for i := range ops {
		lo := r.Intn(Universe)
		ops[i] = op{add: r.Intn(3) != 0, lo: lo, hi: lo + 1 + r.Intn(8)}
	}
	return ops
}

// run applies ops to a fresh Set and to the model, then compares.
func run(f Factory, ops []op) func(t *check.T) {
	return func(t *check.T) {
		s := f()
		var model [Universe + 16]bool
		for _, o := range ops {
			if o.add {
				s.Add(o.lo, o.hi)
			} else {
				s.Remove(o.lo, o.hi)
			}
			for x := o.lo; x < o.hi && x < len(model); x++ {
				model[x] = o.add
			}
		}
		for x := 0; x < len(model); x++ {
			if s.Contains(x) != model[x] {
				t.Fatal("after " + describe(ops) + ": Contains(" + check.Itoa(x) + ") = " + boolText(!model[x]))
			}
		}
		want := spansOf(model[:])
		got := s.Spans()
		if !equal(got, want) {
			t.Fatal("after " + describe(ops) + ": Spans() = " + spansText(got) + ", want " + spansText(want))
		}
	}
}

func spansOf(m []bool) [][2]int {
	var out [][2]int
	for x := 0; x < len(m); x++ {
		if m[x] && (x == 0 || !m[x-1]) {
			out = append(out, [2]int{x, x})
		}
		if m[x] && (x == len(m)-1 || !m[x+1]) {
			out[len(out)-1][1] = x + 1
		}
	}
	return out
}

func equal(a, b [][2]int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func describe(ops []op) string {
	s := ""
	for i, o := range ops {
		if i > 0 {
			s += " "
		}
		if o.add {
			s += "+"
		} else {
			s += "-"
		}
		s += "[" + check.Itoa(o.lo) + "," + check.Itoa(o.hi) + ")"
	}
	return s
}

func spansText(sp [][2]int) string {
	s := "{"
	for i, p := range sp {
		if i > 0 {
			s += " "
		}
		s += "[" + check.Itoa(p[0]) + "," + check.Itoa(p[1]) + ")"
	}
	return s + "}"
}

func boolText(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

// Package bad is a plausible but wrong intervals implementation: Add does
// not merge intervals that only touch, so Spans can return [1,3) [3,5)
// instead of [1,5). The fixed examples miss it; generated cases catch it.
package bad

import "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/specs/intervals/v1"

type set struct{ sp [][2]int }

// New returns an empty set.
func New() intervals.Set { return &set{} }

func (s *set) Add(lo, hi int) {
	if lo >= hi {
		return
	}
	var out [][2]int
	placed := false
	for _, p := range s.sp {
		switch {
		case p[1] <= lo:
			out = append(out, p)
		case p[0] >= hi:
			if !placed {
				out = append(out, [2]int{lo, hi})
				placed = true
			}
			out = append(out, p)
		default:
			if p[0] < lo {
				lo = p[0]
			}
			if p[1] > hi {
				hi = p[1]
			}
		}
	}
	if !placed {
		out = append(out, [2]int{lo, hi})
	}
	s.sp = out
}

func (s *set) Remove(lo, hi int) {
	if lo >= hi {
		return
	}
	var out [][2]int
	for _, p := range s.sp {
		if p[1] <= lo || p[0] >= hi {
			out = append(out, p)
			continue
		}
		if p[0] < lo {
			out = append(out, [2]int{p[0], lo})
		}
		if p[1] > hi {
			out = append(out, [2]int{hi, p[1]})
		}
	}
	s.sp = out
}

func (s *set) Contains(x int) bool {
	for _, p := range s.sp {
		if x >= p[0] && x < p[1] {
			return true
		}
	}
	return false
}

func (s *set) Spans() [][2]int {
	out := make([][2]int, len(s.sp))
	copy(out, s.sp)
	return out
}

// Package lru is an Assertpay spec: a fixed-capacity least-recently-used
// cache from string keys to ints.
//
// Every test builds a fresh cache with a capacity, applies a sequence of
// Get and Put calls and compares each answer with a slice model ordered by
// recency. Fixed examples come first; then Cases generated cases from the
// seed, each reproducible with check.Sub(seed, i).
package lru

import "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/check/v1"

// Cache is the interface a solver implements.
type Cache interface {
	// Get returns the value for key and marks key as most recently used.
	Get(key string) (int, bool)
	// Put sets key to v and marks it most recently used. If the cache is
	// full and key is new, the least recently used key is evicted first.
	Put(key string, v int)
	// Len is the number of keys held.
	Len() int
}

// Factory builds an empty cache holding at most capacity keys (>= 1).
type Factory func(capacity int) Cache

const (
	Cases = 16
	Ops   = 14
)

var keys = []string{"a", "b", "c", "d", "e", "f"}

// Spec describes this spec to Assertpay.
func Spec() check.Spec {
	return check.Spec{
		Name:  "lru",
		Doc:   "A fixed-capacity least-recently-used cache: Get refreshes a key, Put inserts or updates and evicts the least recently used key when full. Checked against a slice model.",
		Tests: Tests,
	}
}

type op struct {
	put bool
	key string
	v   int
}

// Tests builds the tests for impl (a Factory or a func(int) Cache).
func Tests(impl any, seed uint64) []check.Test {
	f, ok := asFactory(impl)
	if !ok {
		return []check.Test{{Name: "Type", Fn: func(t *check.T) { t.Fatal("implementation is not an lru.Factory") }}}
	}
	tests := []check.Test{
		{"PutGet", run(f, 2, []op{{true, "a", 1}, {false, "a", 0}})},
		{"Evict", run(f, 2, []op{{true, "a", 1}, {true, "b", 2}, {true, "c", 3}, {false, "a", 0}, {false, "c", 0}})},
		{"Update", run(f, 2, []op{{true, "a", 1}, {true, "a", 5}, {false, "a", 0}})},
		{"Missing", run(f, 1, []op{{false, "z", 0}})},
	}
	for i := 0; i < Cases; i++ {
		r := check.NewRand(check.Sub(seed, i))
		capacity := 1 + r.Intn(4)
		tests = append(tests, check.Test{Name: "Case" + check.Itoa(i), Fn: run(f, capacity, gen(r))})
	}
	return tests
}

func asFactory(impl any) (Factory, bool) {
	switch v := impl.(type) {
	case Factory:
		return v, v != nil
	case func(int) Cache:
		return Factory(v), v != nil
	}
	return nil, false
}

func gen(r *check.Rand) []op {
	ops := make([]op, Ops)
	for i := range ops {
		ops[i] = op{put: r.Intn(2) == 0, key: keys[r.Intn(len(keys))], v: r.Intn(100)}
	}
	return ops
}

func run(f Factory, capacity int, ops []op) func(t *check.T) {
	return func(t *check.T) {
		c := f(capacity)
		var order []string // least recent first
		vals := map[string]int{}
		trace := "cap " + check.Itoa(capacity) + ":"
		for _, o := range ops {
			if o.put {
				trace += " put(" + o.key + "," + check.Itoa(o.v) + ")"
				c.Put(o.key, o.v)
				if _, ok := vals[o.key]; ok {
					order = touch(order, o.key)
				} else {
					if len(order) == capacity {
						delete(vals, order[0])
						order = order[1:]
					}
					order = append(order, o.key)
				}
				vals[o.key] = o.v
			} else {
				trace += " get(" + o.key + ")"
				got, gotOK := c.Get(o.key)
				want, wantOK := vals[o.key]
				if wantOK {
					order = touch(order, o.key)
				}
				if got != want || gotOK != wantOK {
					t.Fatal(trace + " = " + pair(got, gotOK) + ", want " + pair(want, wantOK))
				}
			}
			if c.Len() != len(order) {
				t.Fatal(trace + ": Len() = " + check.Itoa(c.Len()) + ", want " + check.Itoa(len(order)))
			}
		}
	}
}

func touch(order []string, k string) []string {
	out := make([]string, 0, len(order))
	for _, x := range order {
		if x != k {
			out = append(out, x)
		}
	}
	return append(out, k)
}

func pair(v int, ok bool) string {
	if !ok {
		return "(missing)"
	}
	return check.Itoa(v)
}

// Package bad is a plausible but wrong lru implementation: Get does not
// refresh a key, so it evicts by insertion order (FIFO) instead of by use.
// The fixed examples miss it; generated cases catch it.
package bad

import "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/specs/lru/v1"

type cache struct {
	cap   int
	order []string
	vals  map[string]int
}

// New returns an empty cache.
func New(capacity int) lru.Cache { return &cache{cap: capacity, vals: map[string]int{}} }

func (c *cache) touch(k string) {
	out := c.order[:0:0]
	for _, x := range c.order {
		if x != k {
			out = append(out, x)
		}
	}
	c.order = append(out, k)
}

func (c *cache) Get(k string) (int, bool) {
	v, ok := c.vals[k]
	return v, ok
}

func (c *cache) Put(k string, v int) {
	if _, ok := c.vals[k]; !ok && len(c.order) == c.cap {
		delete(c.vals, c.order[0])
		c.order = c.order[1:]
	}
	c.vals[k] = v
	c.touch(k)
}

func (c *cache) Len() int { return len(c.order) }

// Package assertpay pays for code that passes.
//
// A spec is Go code on chain: an interface and a test suite in a frozen /p/
// package. A sponsor funds a task on a spec. A solver commits a hash with a
// bond, deploys an implementation and reveals it from a small entry realm.
// This realm runs the spec's tests against it, in the reveal transaction.
// The earliest-committed passing implementation wins, unless someone
// breaks it during the challenge window with a seed of their choice, which
// pays them the winner's bond. After the window the winner is paid.
//
// The task logic lives in the pure market package; this realm only moves
// coins and decides who may call what. There is no admin key.
package assertpay

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/check/v1"
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/market/v1"
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/specs/intervals/bad/v1"
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/specs/intervals/v1"
	lrubad "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/specs/lru/bad/v1"
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/specs/lru/v1"
)

const denom = "ugnot"

type specEntry struct {
	Spec      check.Spec
	Path      string // package holding the interface and tests
	Reviewed  bool   // imported statically by this realm
	Registrar string // realm that registered it (unreviewed specs)
	bad       any    // a known-bad implementation for the walletless demo
}

var (
	specs     = map[string]*specEntry{}
	specOrder []string
	tasks     []*market.Task
	running   bool

	// counters for the home page
	statPaid      int64
	statPaidTasks int
	statAttempts  int
	statBroken    int
)

func init() {
	addSpec(&specEntry{Spec: intervals.Spec(), Path: "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/specs/intervals/v1", Reviewed: true, bad: intervals.Factory(bad.New)})
	addSpec(&specEntry{Spec: lru.Spec(), Path: "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/assertpay/specs/lru/v1", Reviewed: true, bad: lru.Factory(lrubad.New)})
}

func addSpec(e *specEntry) {
	if _, ok := specs[e.Spec.Name]; ok {
		panic("assertpay: spec name taken")
	}
	specs[e.Spec.Name] = e
	specOrder = append(specOrder, e.Spec.Name)
}

// RegisterSpec adds a spec from another realm (usually from its init). It
// is listed as unreviewed: its test function could be realm code.
func RegisterSpec(cur realm, s check.Spec, path string) {
	guard()
	reg := cur.Previous().PkgPath()
	if reg == "" {
		panic("assertpay: RegisterSpec must be called from a realm")
	}
	if !validName(s.Name) || s.Tests == nil || len(s.Doc) > 600 || !validPkgPath(path) {
		panic("assertpay: bad spec")
	}
	addSpec(&specEntry{Spec: s, Path: path, Registrar: reg})
	chain.Emit("SpecRegistered", "name", s.Name, "registrar", reg)
}

func guard() {
	if running {
		panic("assertpay: re-entrant call")
	}
}

func mustUser(cur realm) address {
	guard()
	if cur.Previous().PkgPath() != "" {
		panic("assertpay: call this directly from your wallet")
	}
	return cur.Previous().Address()
}

func sent() int64 { return unsafe.OriginSend().AmountOf(denom) }

func mustTask(id int) *market.Task {
	if id < 0 || id >= len(tasks) {
		panic("assertpay: unknown task")
	}
	return tasks[id]
}

// Fund opens a task on spec with the ugnot sent as the reward. Commits are
// accepted for deadlineBlocks blocks; each new winner can be challenged for
// windowBlocks blocks before it can be paid (longer gives humans time to
// audit, shorter pays sooner).
func Fund(cur realm, spec string, deadlineBlocks, windowBlocks int64) int {
	who := mustUser(cur)
	if _, ok := specs[spec]; !ok {
		panic("assertpay: unknown spec")
	}
	t := market.NewTask(len(tasks), spec, who, sent(), runtime.ChainHeight(), deadlineBlocks, windowBlocks)
	tasks = append(tasks, t)
	chain.Emit("TaskFunded", "task", strconv.Itoa(t.ID), "spec", spec, "reward", strconv.FormatInt(t.Reward, 10))
	return t.ID
}

// HashFor is the commitment a solver must Commit before revealing from
// entry with salt. Compute it off chain or with a query.
func HashFor(task int, who address, entry, salt string) string {
	h := sha256.Sum256([]byte(strconv.Itoa(task) + "|" + who.String() + "|" + entry + "|" + salt))
	return hex.EncodeToString(h[:])
}

// Commit seals a future reveal. Send exactly the task's bond.
func Commit(cur realm, task int, hash string) {
	who := mustUser(cur)
	t := mustTask(task)
	if sent() != t.Bond {
		panic("assertpay: send exactly the bond (" + strconv.FormatInt(t.Bond, 10) + denom + ")")
	}
	if len(hash) != 64 {
		panic("assertpay: hash must be 64 hex chars")
	}
	t.AddCommit(who, hash, runtime.ChainHeight())
	chain.Emit("Committed", "task", strconv.Itoa(task), "who", who.String())
}

// SeedFor is the seed a reveal runs with: public and deterministic. A
// reveal passing one seed proves little; challenges decide.
func SeedFor(hash string, height int64) uint64 {
	d := sha256.Sum256([]byte(hash + "|" + strconv.FormatInt(height, 10)))
	var x uint64
	for i := 0; i < 8; i++ {
		x = x<<8 | uint64(d[i])
	}
	return x
}

// Reveal is called by the solver's entry realm with the implementation.
// It returns "passed/total".
func Reveal(cur realm, task int, salt string, impl any) string {
	guard()
	entry := cur.Previous().PkgPath()
	if entry == "" {
		panic("assertpay: Reveal must be called from your entry realm")
	}
	who := unsafe.OriginCaller()
	t := mustTask(task)
	now := runtime.ChainHeight()
	hash := HashFor(task, who, entry, salt)
	c := t.FindCommit(who, hash, now)
	res := runTests(t.Spec, impl, SeedFor(hash, now))
	a, pays := t.Reveal(c, entry, impl, res, now)
	statAttempts++
	pay(cur, pays)
	chain.Emit("Revealed", "task", strconv.Itoa(task), "attempt", strconv.Itoa(a.ID), "passed", strconv.Itoa(a.Passed), "total", strconv.Itoa(a.Total))
	return strconv.Itoa(a.Passed) + "/" + strconv.Itoa(a.Total)
}

// Challenge runs the current winner with your seed. If it fails, the
// winner is removed and its bond is paid to you.
func Challenge(cur realm, task int, seed uint64) string {
	who := mustUser(cur)
	t := mustTask(task)
	now := runtime.ChainHeight()
	w := t.CheckChallenge(now)
	res := runTests(t.Spec, w.Impl, seed)
	pays := t.Challenged(who, res, now)
	pay(cur, pays)
	out := "held"
	if !res.Pass() {
		out = "broke: " + res.Fail
		statBroken++
	}
	chain.Emit("Challenged", "task", strconv.Itoa(task), "seed", strconv.FormatUint(seed, 10), "outcome", out)
	return out
}

// OpenChallenge is the two-step challenge for a winner whose code aborts
// the transaction. Send the task's bond; then anyone calls RunChallenge,
// or after the task's window length TimeoutChallenge removes the winner.
func OpenChallenge(cur realm, task int, seed uint64) {
	who := mustUser(cur)
	t := mustTask(task)
	t.Open(who, seed, sent(), runtime.ChainHeight())
	chain.Emit("ChallengeOpened", "task", strconv.Itoa(task), "seed", strconv.FormatUint(seed, 10))
}

// RunChallenge runs the open challenge. Anyone may call it; if the winner
// holds, the caller gets half of the challenger's bond.
func RunChallenge(cur realm, task int) string {
	runner := mustUser(cur)
	t := mustTask(task)
	ch := t.OpenChallenge()
	if ch == nil {
		panic("assertpay: no open challenge")
	}
	res := runTests(t.Spec, t.Attempts[ch.Target].Impl, ch.Seed)
	pay(cur, t.RanOpen(runner, res, runtime.ChainHeight()))
	if ch.Outcome == "broke" {
		statBroken++
	}
	chain.Emit("ChallengeRun", "task", strconv.Itoa(task), "outcome", ch.Outcome)
	return ch.Outcome
}

// TimeoutChallenge removes a winner whose open challenge nobody could run.
func TimeoutChallenge(cur realm, task int) {
	mustUser(cur)
	t := mustTask(task)
	pay(cur, t.TimeoutOpen(runtime.ChainHeight()))
	statBroken++
	chain.Emit("ChallengeTimeout", "task", strconv.Itoa(task))
}

// Claim pays the winner after the window. Anyone may call it.
func Claim(cur realm, task int) string {
	mustUser(cur)
	t := mustTask(task)
	pays := t.Claim(runtime.ChainHeight())
	pay(cur, pays)
	statPaid += t.Reward
	statPaidTasks++
	chain.Emit("Paid", "task", strconv.Itoa(task), "to", pays[0].To.String(), "amount", strconv.FormatInt(pays[0].Amount, 10))
	return "paid " + pays[0].To.String()
}

// Refund returns the reward to the sponsor after the deadline when no
// implementation passed and nothing is pending. Anyone may call it.
func Refund(cur realm, task int) {
	mustUser(cur)
	t := mustTask(task)
	pay(cur, t.Refund(runtime.ChainHeight()))
	chain.Emit("Refunded", "task", strconv.Itoa(task))
}

func runTests(spec string, impl any, seed uint64) market.Result {
	e := specs[spec]
	running = true
	rs := check.RunSpec(e.Spec, impl, seed)
	running = false
	return summarize(rs, seed)
}

func summarize(rs []check.Result, seed uint64) market.Result {
	bits := make([]byte, len(rs))
	r := market.Result{Seed: seed, Total: len(rs)}
	for i, x := range rs {
		if x.Pass {
			bits[i] = 'p'
			r.Passed++
		} else {
			bits[i] = 'f'
			if r.Fail == "" {
				msg := x.Msg
				if len(msg) > 300 {
					msg = msg[:300] + "..."
				}
				r.Fail = x.Name + ": " + msg
			}
		}
	}
	r.Bits = string(bits)
	return r
}

func pay(cur realm, pays []market.Payment) {
	if len(pays) == 0 {
		return
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	for _, p := range pays {
		if p.Amount > 0 {
			b.SendCoins(cur.Address(), p.To, chain.NewCoins(chain.NewCoin(denom, p.Amount)))
		}
	}
}

func validName(s string) bool {
	if len(s) < 2 || len(s) > 24 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-') {
			return false
		}
	}
	return true
}

// validPkgPath accepts gno.land/p/... or gno.land/r/... with a plain charset,
// so a registered path cannot inject Markdown.
func validPkgPath(p string) bool {
	if len(p) > 120 || !(strings.HasPrefix(p, "gno.land/p/") || strings.HasPrefix(p, "gno.land/r/")) {
		return false
	}
	for i := 0; i < len(p); i++ {
		c := p[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '_' || c == '/' || c == '.' || c == '-') {
			return false
		}
	}
	return true
}

