// Package fundmath holds Charterbook's fund arithmetic as pure functions:
// exact integer money (6 decimals), share issue and cancellation at an
// approved NAV, the management fee, and the redemption-gate allocation.
//
// Rounding always favours the fund's remaining investors:
//   - shares issued for a subscription: rounded down;
//   - shares cancelled for a lot redemption: rounded up (the lot is paid exactly);
//   - value paid on a full exit: rounded down;
//   - management fee: rounded down.
//
// The worked example approved on 27 Nov 2026 (three periods, two investors)
// is reproduced to the micro-unit in fundmath_test.gno.
package fundmath

import "math/bits"

const (
	// Unit is one whole tUSD or one whole share in micro-units.
	Unit int64 = 1_000_000
	// BpsDenominator: 10,000 basis points = 100%.
	BpsDenominator int64 = 10_000
	// SecondsPerYear for fee accrual (365 days).
	SecondsPerYear int64 = 365 * 24 * 60 * 60
)

// MulDivDown returns floor(a*b/c) for non-negative a, b and positive c,
// using a 128-bit intermediate. It panics if the result does not fit int64.
func MulDivDown(a, b, c int64) int64 {
	q, _ := mulDiv(a, b, c)
	return q
}

// MulDivUp returns ceil(a*b/c) for non-negative a, b and positive c.
func MulDivUp(a, b, c int64) int64 {
	q, rem := mulDiv(a, b, c)
	if rem != 0 {
		if q == maxInt64 {
			panic("fundmath: overflow")
		}
		q++
	}
	return q
}

const maxInt64 int64 = 1<<63 - 1

func mulDiv(a, b, c int64) (int64, uint64) {
	if a < 0 || b < 0 {
		panic("fundmath: negative operand")
	}
	if c <= 0 {
		panic("fundmath: non-positive divisor")
	}
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	if hi >= uint64(c) {
		panic("fundmath: overflow")
	}
	q, rem := bits.Div64(hi, lo, uint64(c))
	if q > uint64(maxInt64) {
		panic("fundmath: overflow")
	}
	return int64(q), rem
}

// ManagementFee returns the fee accrued on gross assets over elapsed seconds
// at an annual rate in basis points, rounded down. The same rule serves every
// charge expressed as a percentage a year.
func ManagementFee(gross, rateBps, elapsedSeconds int64) int64 {
	return AnnualCharge(gross, rateBps, elapsedSeconds)
}

// AnnualCharge returns base x rateBps/10,000 x elapsed/365 days, rounded down.
func AnnualCharge(gross, rateBps, elapsedSeconds int64) int64 {
	if rateBps < 0 || rateBps > BpsDenominator || elapsedSeconds < 0 || elapsedSeconds > 10*SecondsPerYear {
		panic("fundmath: fee rate or period out of range")
	}
	if gross <= 0 || rateBps == 0 || elapsedSeconds == 0 {
		return 0
	}
	return MulDivDown(gross, rateBps*elapsedSeconds, BpsDenominator*SecondsPerYear)
}

// SharesForSubscription returns the shares issued for amount at the period's
// NAV over the opening shares in issue (rounded down). With no shares in
// issue, shares are issued at the par price (tUSD micro-units per share).
func SharesForSubscription(amount, sharesInIssue, nav, par int64) int64 {
	if amount <= 0 {
		panic("fundmath: amount must be positive")
	}
	if par <= 0 || sharesInIssue < 0 {
		panic("fundmath: invalid par or shares")
	}
	if sharesInIssue == 0 {
		return MulDivDown(amount, Unit, par)
	}
	if nav <= 0 {
		panic("fundmath: dealing suspended, NAV not positive")
	}
	return MulDivDown(amount, sharesInIssue, nav)
}

// SharesToCancel returns the shares cancelled to pay exactly amount at the
// period's NAV (rounded up).
func SharesToCancel(amount, sharesInIssue, nav int64) int64 {
	if amount <= 0 || sharesInIssue <= 0 || nav <= 0 {
		panic("fundmath: invalid redemption")
	}
	return MulDivUp(amount, sharesInIssue, nav)
}

// ValueOf returns the value of shares at the period's NAV (rounded down).
func ValueOf(shares, sharesInIssue, nav int64) int64 {
	if shares == 0 {
		return 0
	}
	if sharesInIssue <= 0 || nav <= 0 {
		panic("fundmath: invalid valuation")
	}
	return MulDivDown(shares, nav, sharesInIssue)
}

// Request is one redemption request for gate allocation.
//   - Full: a full exit of the wallet, worth Value;
//   - otherwise: Lots whole lots; Value is the wallet's value (for the
//     minimum-holding check).
type Request struct {
	Full     bool
	Lots     int64
	Value    int64
	Deferred bool // carried from an earlier period: served before new requests
}

// Fill is the result for one request.
type Fill struct {
	Lots int64 // whole lots paid (partial requests, and full exits paid in lots)
	Paid int64 // amount paid
	Done bool  // request completely filled
}

// Classify turns a request for `lots` lots from a wallet worth `value` into a
// Request: a full exit if lots is 0 (meaning "all"), if the lots exceed the
// value, or if paying them would leave less than minHolding. It never
// multiplies before comparing, so no lot count can overflow.
func Classify(lots, value, lot, minHolding int64) Request {
	checkLot(lot, minHolding)
	if lots < 0 {
		panic("fundmath: negative lots")
	}
	if value < 0 {
		panic("fundmath: negative value")
	}
	if lots == 0 || lots > value/lot || value-lots*lot < minHolding {
		return Request{Full: true, Value: value}
	}
	return Request{Lots: lots, Value: value}
}

func checkLot(lot, minHolding int64) {
	if lot <= 0 || minHolding < 0 {
		panic("fundmath: invalid lot or minimum holding")
	}
}

// maxLots is how many whole lots a full exit may be paid in this period
// while at least minHolding stays invested.
func maxLots(r Request, lot, minHolding int64) int64 {
	if r.Value < minHolding {
		return 0
	}
	return (r.Value - minHolding) / lot
}

func asked(r Request, lot int64) int64 {
	if r.Full {
		return r.Value
	}
	return r.Lots * lot
}

// AllocateGate shares capacity among redemption requests. Deferred requests
// (carried from earlier periods) are served first; only what is left goes to
// new requests. Within each tier, in request order:
//  1. if the whole tier fits what is left, it is filled;
//  2. round 1: each request gets its pro-rata share in whole lots; a full
//     exit is paid in whole lots while at least minHolding stays invested;
//  3. round 2: what is left goes first to requests that received nothing in
//     round 1; then one more lot at a time, in request order, until nothing
//     more fits. Whenever the rest of a full exit fits, it is paid in full.
//
// Last exit: if, after both tiers, exactly one request is unfilled, it is a
// full exit, and its rest is below one lot plus minHolding, the rest is paid
// from cash even above the gate (at most one such payment per period).
//
// cash is the cash available (cash >= capacity). Work is linear in the
// number of requests. AllocateGate panics on inputs Classify would not
// produce.
func AllocateGate(reqs []Request, capacity, cash, lot, minHolding int64) []Fill {
	checkLot(lot, minHolding)
	if capacity < 0 || cash < capacity {
		panic("fundmath: invalid capacity or cash")
	}
	fills := make([]Fill, len(reqs))
	var deferred, fresh []int
	for i, r := range reqs {
		if r.Value < 0 {
			panic("fundmath: negative value")
		}
		if !r.Full && (r.Lots <= 0 || r.Lots > maxLots(r, lot, minHolding)) {
			panic("fundmath: invalid partial request, use Classify")
		}
		if r.Deferred {
			deferred = append(deferred, i)
		} else {
			fresh = append(fresh, i)
		}
	}
	var used int64
	allocateTier(reqs, fills, deferred, capacity, lot, minHolding, &used)
	allocateTier(reqs, fills, fresh, capacity, lot, minHolding, &used)
	// Last exit.
	open := -1
	for i := range fills {
		if !fills[i].Done {
			if open >= 0 {
				return fills
			}
			open = i
		}
	}
	if open >= 0 && reqs[open].Full {
		rest := reqs[open].Value - fills[open].Paid
		if rest < lot+minHolding && rest <= cash-used {
			fills[open].Paid += rest
			fills[open].Done = true
		}
	}
	return fills
}

func allocateTier(reqs []Request, fills []Fill, idx []int, capacity, lot, minHolding int64, used *int64) {
	if len(idx) == 0 {
		return
	}
	var total int64
	for _, i := range idx {
		total = addChecked(total, asked(reqs[i], lot))
	}
	room := capacity - *used
	if total <= room {
		for _, i := range idx {
			r := reqs[i]
			fills[i] = Fill{Paid: asked(r, lot), Done: true}
			if !r.Full {
				fills[i].Lots = r.Lots
			}
			*used += fills[i].Paid
		}
		return
	}
	if room <= 0 {
		return
	}
	// Round 1. alloc < asked, because room < total.
	for _, i := range idx {
		r := reqs[i]
		alloc := MulDivDown(asked(r, lot), room, total)
		limit := r.Lots
		if r.Full {
			limit = maxLots(r, lot, minHolding)
		}
		k := alloc / lot
		if k > limit {
			k = limit
		}
		fills[i] = Fill{Lots: k, Paid: k * lot, Done: !r.Full && k == r.Lots}
		*used += fills[i].Paid
	}
	// Round 2, first pass: only requests that got nothing in round 1. An
	// entry that cannot move now never can, since what is left only shrinks;
	// it leaves the rotation.
	active := make([]int, 0, len(idx))
	for _, i := range idx {
		if fills[i].Done {
			continue
		}
		if fills[i].Paid > 0 {
			active = append(active, i)
			continue
		}
		if step(reqs[i], &fills[i], capacity-*used, lot, minHolding, used) && !fills[i].Done {
			active = append(active, i)
		}
	}
	// Then one payment per request per sweep, in request order.
	for len(active) > 0 {
		next := active[:0]
		for _, i := range active {
			if step(reqs[i], &fills[i], capacity-*used, lot, minHolding, used) && !fills[i].Done {
				next = append(next, i)
			}
		}
		active = next
	}
}

// step gives request r one more payment if it fits: the whole rest of a full
// exit, else one lot. It reports whether anything was paid.
func step(r Request, f *Fill, left, lot, minHolding int64, used *int64) bool {
	if r.Full {
		rest := r.Value - f.Paid
		if rest <= left {
			f.Paid += rest
			f.Done = true
			*used += rest
			return true
		}
		if f.Lots < maxLots(r, lot, minHolding) && lot <= left {
			f.Lots++
			f.Paid += lot
			*used += lot
			return true
		}
		return false
	}
	if f.Lots < r.Lots && lot <= left {
		f.Lots++
		f.Paid += lot
		f.Done = f.Lots == r.Lots
		*used += lot
		return true
	}
	return false
}

func addChecked(a, b int64) int64 {
	c := a + b
	if (b > 0 && c < a) || (b < 0 && c > a) {
		panic("fundmath: overflow")
	}
	return c
}

// PerformanceFeePerShare is rateBps of the rise of navps above hwm, per share
// (micro-units), rounded down; zero at or below the mark.
func PerformanceFeePerShare(navps, hwm, rateBps int64) int64 {
	if rateBps < 0 || rateBps > BpsDenominator || navps < 0 || hwm < 0 {
		panic("fundmath: invalid performance fee input")
	}
	if navps <= hwm {
		return 0
	}
	return MulDivDown(navps-hwm, rateBps, BpsDenominator)
}

// BlendHWM is the high-water mark after a holder of oldShares at mark oldHWM
// receives newShares at price: the share-weighted average, rounded up (in the
// investor's favour). A holder with no shares takes the price.
func BlendHWM(oldShares, oldHWM, newShares, price int64) int64 {
	if oldShares < 0 || newShares <= 0 || oldHWM < 0 || price <= 0 {
		panic("fundmath: invalid high-water mark input")
	}
	if oldShares == 0 {
		return price
	}
	total := addChecked(oldShares, newShares)
	if price >= oldHWM {
		return oldHWM + MulDivUp(price-oldHWM, newShares, total)
	}
	return oldHWM - MulDivDown(oldHWM-price, newShares, total)
}

// Package tusd is "Test Dollar" (tUSD), the dealing currency of the
// Charterbook demonstration fund on the Onyx testnet. It is a GRC20 token
// with 6 decimals. TEST TOKEN: it has no value and is not a stablecoin.
//
// Two ways to get tUSD:
//   - Faucet: anyone can claim 100,000 tUSD, once per 1,200 blocks per address;
//   - issuer desk: the test issuer mints against simulated dollar deposits and
//     holders redeem (burn) against simulated withdrawals. Both carry a
//     reference so the flow can be followed on-chain.
//
// A real stablecoin arriving over IBC can replace tUSD later; the fund only
// knows tUSD by its registry key.
package tusd

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const (
	// FaucetAmount is 100,000 tUSD (ten fund lots).
	FaucetAmount int64 = 100_000 * 1_000_000
	// FaucetCooldown in blocks between claims by the same address.
	FaucetCooldown int64 = 1_200
	maxRefLen            = 64
)

var (
	token     *grc20.Token
	ledger    *grc20.PrivateLedger
	user      grc20.Teller
	tokenKey  string
	owner     address
	issuer    address
	lastClaim = avl.NewTree() // address -> int64 height
	selfPath  string
)

func init(cur realm) {
	token, ledger = grc20.NewToken("Test Dollar", "tUSD", 6, 0, cur)
	user = ledger.CallerTeller()
	tokenKey = grc20reg.Register(cross(cur), token, "")
	owner = cur.Previous().Address()
	issuer = owner
	selfPath = cur.PkgPath()
}

// Path is this realm's package path, so other realms can link to it.
func Path() string { return selfPath }

// TokenKey is this token's key in the grc20reg registry.
func TokenKey() string { return tokenKey }

// Issuer is the address of the test issuer desk.
func Issuer() address { return issuer }

func BalanceOf(a address) int64          { return user.BalanceOf(a) }
func Allowance(o, spender address) int64 { return user.Allowance(o, spender) }
func TotalSupply() int64                 { return user.TotalSupply() }

// Faucet mints FaucetAmount to the caller, at most once per FaucetCooldown
// blocks per address.
func Faucet(cur realm) {
	caller := cur.Previous().Address()
	h := runtime.ChainHeight()
	if v := lastClaim.Get(caller.String()); v != nil {
		if next := v.(int64) + FaucetCooldown; h < next {
			panic(ufmt.Sprintf("faucet: next claim at block %d", next))
		}
	}
	lastClaim.Set(caller.String(), h)
	checkErr(ledger.Mint(caller, FaucetAmount))
	chain.Emit("Faucet", "to", caller.String(), "amount", ufmt.Sprintf("%d", FaucetAmount))
}

func Approve(cur realm, spender address, amount int64) {
	checkErr(user.Approve(0, cur, spender, amount))
}

func Transfer(cur realm, to address, amount int64) {
	checkErr(user.Transfer(0, cur, to, amount))
}

// IssuerMint mints amount to `to` against a simulated deposit. Issuer only.
func IssuerMint(cur realm, to address, amount int64, ref string) {
	if cur.Previous().Address() != issuer {
		panic("issuer only")
	}
	checkRef(ref)
	if amount <= 0 {
		panic("amount must be positive")
	}
	checkErr(ledger.Mint(to, amount))
	chain.Emit("IssuerMint", "to", to.String(), "amount", ufmt.Sprintf("%d", amount), "ref", ref)
}

// Redeem burns amount of the caller's tUSD against a simulated withdrawal.
func Redeem(cur realm, amount int64, ref string) {
	checkRef(ref)
	if amount <= 0 {
		panic("amount must be positive")
	}
	caller := cur.Previous().Address()
	checkErr(ledger.Burn(caller, amount))
	chain.Emit("Redeem", "from", caller.String(), "amount", ufmt.Sprintf("%d", amount), "ref", ref)
}

// SetIssuer hands the issuer desk to another address. Owner only.
func SetIssuer(cur realm, a address) {
	if cur.Previous().Address() != owner {
		panic("owner only")
	}
	if !a.IsValid() {
		panic("invalid address")
	}
	issuer = a
	chain.Emit("SetIssuer", "issuer", a.String())
}

func Render(path string) string {
	if path == "" {
		var b strings.Builder
		b.WriteString("# Test Dollar (tUSD)\n\n")
		b.WriteString("> **Test token on the Onyx testnet. No value. Not a stablecoin.** Not issued or operated by any regulated firm. Unaudited code. Not an offer.\n\n")
		b.WriteString("Dealing currency of the Charterbook demonstration fund.\n\n")
		b.WriteString(ufmt.Sprintf("- Total supply: %s tUSD\n- Issuer desk: %s\n- Registry key: %s\n- Faucet: %s tUSD per claim, once per %d blocks per address\n\n",
			fmtAmount(TotalSupply()), issuer.String(), sanitize.InlineText(tokenKey), fmtAmount(FaucetAmount), FaucetCooldown))
		b.WriteString("[Claim from the faucet](" + strings.TrimPrefix(selfPath, "gno.land") + "$help&func=Faucet)\n")
		return b.String()
	}
	parts := strings.Split(path, "/")
	if len(parts) == 2 && parts[0] == "balance" {
		a := address(parts[1])
		if !a.IsValid() {
			return "invalid address"
		}
		return fmtAmount(user.BalanceOf(a)) + " tUSD"
	}
	return "404"
}

func fmtAmount(v int64) string {
	f := ufmt.Sprintf("%d", v%1_000_000)
	for len(f) < 6 {
		f = "0" + f
	}
	return ufmt.Sprintf("%d", v/1_000_000) + "." + f
}

func checkRef(ref string) {
	if len(ref) == 0 || len(ref) > maxRefLen {
		panic("ref must be 1 to 64 characters")
	}
}

func checkErr(err error) {
	if err != nil {
		panic(err.Error())
	}
}

package fund

import "chain/runtime"

// Read-only views for the nominee realm and other readers. They return
// values only, never pointers to the fund's state.

// Address is the fund's own address (the spender to Approve on tUSD).
func Address() address { return fundAddr() }

// Path is the fund's package path.
func Path() string { return selfPath }

// CurrentPeriod returns the dealing period number and whether it is open
// for orders.
func CurrentPeriod() (n int64, open bool) { return cur0.n, cur0.state == stateOpen }

// Roles returns the fund's role holders (fixed at Launch).
func Roles() (mgr, admin, rev, off address) { return manager, administrator, reviewer, officer }

// NomineeTotals returns how many nominee sub-accounts hold shares, and how
// many shares they hold together.
func NomineeTotals() (accounts, shares int64) { return nomineeAccounts, nomineeShares }

// CheckAgent panics unless the current transaction is signed by the fund's
// registered screening-agent session, belonging to master, limited to this
// fund's realms, expiring no later than the registered expiry. The nominee calls it with its
// own cur.Previous().Address(). It reveals nothing and changes nothing.
func CheckAgent(master address) {
	addr, expiresAt, allow, isSession := runtime.GetSessionInfo()
	if !isSession {
		panic("screening agent: session key required")
	}
	if !launched || addr != agentSession {
		panic("screening agent: unregistered session key")
	}
	requireNotClosed() // review 3, m5
	if master != officer {
		panic("screening agent: session must belong to the compliance officer")
	}
	if len(allow) == 0 {
		panic("screening agent: session must be limited to this realm")
	}
	for _, p := range allow {
		if p != "vm/exec:"+selfPath {
			panic("screening agent: session must be limited to this realm")
		}
	}
	if expiresAt <= 0 || expiresAt > agentExpiry {
		panic("screening agent: session must expire no later than the registered expiry")
	}
}

// Auditor returns the auditor's address.
func Auditor() address { return auditor }

// Launched reports whether the fund has launched (its roles are fixed).
func Launched() bool { return launched }

// IsRoleOrFundAccount reports whether a holds a fund role, is the deployer,
// or is one of the fund's own accounts (the nominee checks its operator).
func IsRoleOrFundAccount(a address) bool { return isRole(a) || isFundAccount(a) }

// Status returns the board-level state: dealing suspended until (unix
// seconds, 0 if not), closed to subscriptions, winding down, closed.
func Status() (suspendedUntilUnix int64, subscriptionsClosedNow, windingDownNow, closed bool) {
	// A wind-down counts from its approval (review 3, m4).
	return suspendedUntil, subscriptionsClosed, windingDown || windDownApproved, cur0.state == stateClosed
}

// HighWaterMark returns a holder's performance-fee mark (per share).
func HighWaterMark(holderAddr address) int64 {
	if h := getHolder(holderAddr); h != nil {
		return h.hwm
	}
	return 0
}

package fund

import (
	"time"

	"gno.land/p/nt/ufmt/v0"
)

// AttestAnnualReport records the SHA-256 of the audited annual report for a
// fiscal year (calendar year, by block time) that has ended. Auditor only,
// master key, once per year. The report stays off-chain.
func AttestAnnualReport(cur realm, year int64, sha string) {
	onlyRole(cur, auditor, "auditor")
	checkCommitment(sha)
	cy := int64(time.Unix(now(), 0).Year())
	ly := int64(time.Unix(launchTime, 0).Year())
	if year < ly || year >= cy || year > lastFundYear() {
		panic("the year must have ended, and the fund must have existed in it")
	}
	if audits.Has(pad(year)) {
		panic("already recorded for this year")
	}
	audits.Set(pad(year), &auditRecord{year: year, sha: sha, height: heightNow()})
	addTrail("auditor", ufmt.Sprintf("Audited annual report for %d recorded: %s.", year, sha))
}

// auditStatus lists each ended fiscal year: recorded, due, or overdue (no
// report within 6 months of the year end).
func auditStatus() []string {
	var out []string
	if launchTime == 0 {
		return out
	}
	t := now()
	cy := int64(time.Unix(t, 0).Year())
	for y := int64(time.Unix(launchTime, 0).Year()); y < cy && y <= lastFundYear(); y++ {
		if v := audits.Get(pad(y)); v != nil {
			a := v.(*auditRecord)
			out = append(out, ufmt.Sprintf("| %d | recorded at height %d | `%s` |", y, a.height, a.sha))
			continue
		}
		yearEnd := time.Date(int(y)+1, time.January, 1, 0, 0, 0, 0, time.UTC).Unix()
		state := "due"
		if t > yearEnd+AuditDueDays*86400 {
			state = "**overdue**"
		}
		out = append(out, ufmt.Sprintf("| %d | %s | |", y, state))
	}
	return out
}

// lastFundYear is the last fiscal year the fund lived in: the closure year
// once closed (review 2, m12).
func lastFundYear() int64 {
	if closedAt > 0 {
		return int64(time.Unix(closedAt, 0).Year())
	}
	return 1 << 40
}

func launchYear() int64 { return int64(time.Unix(launchTime, 0).Year()) }

package fund

import "gno.land/p/nt/ufmt/v0"

// Board powers (design note v3.3, B). In the fund documents these belong to
// the directors. Here the manager proposes and the independent valuation
// reviewer countersigns anything that can move money: the manager never
// moves money or assets on his signature alone (the owner's rule).
//
// A proposal is valid only in the period it is made: the two keys agree at
// the same time, and a key spent once cannot be used alone later (review 2,
// I1 and I2).

var suspensionReasons = []string{"market-closed", "valuation-unavailable", "assets-illiquid", "investor-interest"}

func checkReason(code string, allowed []string) {
	for _, a := range allowed {
		if a == code {
			return
		}
	}
	panic("reason code not allowed here")
}

// ---- suspension of dealing ----

// ProposeSuspension proposes to suspend dealing for `days` days (1 to 30)
// with one of the reason codes, or to renew a suspension. Manager only.
func ProposeSuspension(cur realm, reasonCode string, days int64) {
	onlyRole(cur, manager, "manager")
	requireNotClosed()
	checkReason(reasonCode, suspensionReasons)
	if days < 1 || days > MaxSuspensionDays {
		panic("days must be 1 to 30")
	}
	pendingSusp = &suspension{period: cur0.n, days: days, reason: reasonCode}
	addTrail("manager", ufmt.Sprintf("Suspension of dealing proposed for %d days: %s.", days, reasonCode))
}

// ProposeLiftSuspension proposes to end a suspension early. Manager only.
func ProposeLiftSuspension(cur realm) {
	onlyRole(cur, manager, "manager")
	if !isSuspended() {
		panic("dealing is not suspended")
	}
	pendingSusp = &suspension{period: cur0.n, lift: true}
	addTrail("manager", "End of the suspension proposed.")
}

// ApproveSuspension countersigns the pending suspension, renewal or lift.
// Reviewer only. A suspension runs from now and ends by itself.
func ApproveSuspension(cur realm) {
	onlyRole(cur, reviewer, "valuation reviewer")
	if pendingSusp == nil {
		panic("nothing to approve")
	}
	if pendingSusp.period != cur0.n {
		panic("the proposal was made in an earlier period; propose again")
	}
	p := pendingSusp
	pendingSusp = nil
	if p.lift {
		suspendedUntil = 0
		addTrail("reviewer", "Suspension of dealing lifted.")
		return
	}
	suspendedUntil = now() + p.days*86400
	addTrail("reviewer", ufmt.Sprintf("Dealing suspended for %d days: %s. Orders wait for the first NAV after the suspension.", p.days, p.reason))
}

// DeclineSuspension drops a pending proposal. Reviewer or manager.
func DeclineSuspension(cur realm) {
	assertMasterKey()
	requireLaunched()
	c := cur.Previous().Address()
	if c != manager && c != reviewer {
		panic("manager or valuation reviewer only")
	}
	if pendingSusp == nil {
		panic("nothing pending")
	}
	pendingSusp = nil
	addTrail(roleName(c), "Suspension proposal dropped.")
}

// ---- closing to new subscriptions (no money moves: manager alone) ----

func CloseSubscriptions(cur realm) {
	onlyRole(cur, manager, "manager")
	requireLaunched()
	if subscriptionsClosed {
		panic("already closed to new subscriptions")
	}
	subscriptionsClosed = true
	addTrail("manager", "The fund is closed to new subscriptions. Redemptions continue.")
}

func ReopenSubscriptions(cur realm) {
	onlyRole(cur, manager, "manager")
	requireLaunched()
	requireNotWindingDown()
	if !subscriptionsClosed {
		panic("the fund is open to subscriptions")
	}
	subscriptionsClosed = false
	addTrail("manager", "The fund is open to new subscriptions again.")
}

// ---- compulsory redemption ----

// CompelRedemption orders the full redemption of a direct holder at the
// next NAV, ahead of the gate, for a compliance reason (not eligible, breach
// of law, information not provided). The reason stays off-chain: only a
// salted commitment to the officer's record is kept (review 2, I4). An open
// request of the holder becomes compulsory. Compliance officer only.
// Nominee sub-accounts are handled by the nominee, off-chain.
func CompelRedemption(cur realm, holderAddr address, reasonCommitment string) int64 {
	onlyRole(cur, officer, "compliance officer")
	requireState(stateOpen)
	requireNotWindingDown()
	checkCommitment(reasonCommitment)
	if isSubAccount(holderAddr) {
		panic("nominee sub-accounts are handled by the nominee, off-chain")
	}
	return compel(cur, holderAddr, reasonCommitment)
}

func compulsoryKind(reason string) (kind, ref string) {
	if reason == "below-minimum" {
		return "below-minimum", ""
	}
	return "compliance", reason
}

// NoticeBelowMinimum records notice to a holder worth less than the minimum
// holding at the last NAV: after 30 days without a top-up, the manager may
// propose a compulsory redemption. Manager only (no money moves).
func NoticeBelowMinimum(cur realm, holderAddr address) {
	onlyRole(cur, manager, "manager")
	requireLaunched()
	h := getHolder(holderAddr)
	if h == nil || h.shares == 0 {
		panic("not a holder")
	}
	if valueOfShares(h.shares) >= MinHolding {
		panic("the holding is not below the minimum")
	}
	notices.Set(holderAddr.String(), now())
	addTrail("manager", "Notice given to a holding below the minimum: 30 days to top up.")
}

// ProposeMinimumRedemption proposes the compulsory redemption of a holding
// still below the minimum 30 days after notice. Manager only; the reviewer
// must countersign with ApproveMinimumRedemption.
func ProposeMinimumRedemption(cur realm, holderAddr address) {
	onlyRole(cur, manager, "manager")
	requireState(stateOpen)
	v := notices.Get(holderAddr.String())
	if v == nil {
		panic("no notice given")
	}
	if now() < v.(int64)+MinHoldingNoticeDays*86400 {
		panic("the 30-day notice has not run out")
	}
	h := getHolder(holderAddr)
	if h == nil || h.shares == 0 || valueOfShares(h.shares) >= MinHolding {
		panic("the holding is not below the minimum")
	}
	pendingMin.Set(holderAddr.String(), cur0.n)
	addTrail("manager", "Compulsory redemption of a holding below the minimum proposed.")
}

// WithdrawMinimumRedemption drops the manager's proposal. Manager only.
func WithdrawMinimumRedemption(cur realm, holderAddr address) {
	onlyRole(cur, manager, "manager")
	if !pendingMin.Has(holderAddr.String()) {
		panic("nothing proposed for this holder")
	}
	pendingMin.Remove(holderAddr.String())
	addTrail("manager", "Proposal of a compulsory redemption below the minimum withdrawn.")
}

// ApproveMinimumRedemption countersigns it, in the period it was proposed,
// if the holding is still below the minimum. Reviewer only.
func ApproveMinimumRedemption(cur realm, holderAddr address) int64 {
	onlyRole(cur, reviewer, "valuation reviewer")
	requireState(stateOpen)
	v := pendingMin.Get(holderAddr.String())
	if v == nil {
		panic("nothing proposed for this holder")
	}
	if v.(int64) != cur0.n {
		panic("the proposal was made in an earlier period; propose again")
	}
	h := getHolder(holderAddr)
	if h == nil || h.shares == 0 || valueOfShares(h.shares) >= MinHolding {
		panic("the holding is not below the minimum")
	}
	pendingMin.Remove(holderAddr.String())
	notices.Remove(holderAddr.String())
	return compel(cur, holderAddr, "below-minimum")
}

func compel(cur realm, holderAddr address, reason string) int64 {
	h := getHolder(holderAddr)
	if h == nil || h.shares == 0 {
		panic("not a holder")
	}
	if h.openRed != 0 {
		r := getRed(h.openRed)
		r.compulsory, r.full, r.lots = true, true, 0
		r.kind, r.reasonRef = compulsoryKind(reason)
		addTrail("compulsory", ufmt.Sprintf("Redemption request #%d made compulsory.", r.id))
		return r.id
	}
	if h.activeSub != 0 {
		// A top-up the fund can no longer deal (the wallet is not eligible)
		// is refunded first (review 2, m4).
		s := getSub(h.activeSub)
		if held(s.wallet, s.payee) || isEligible(s.wallet) {
			panic("the holder has a subscription in escrow; decide it first")
		}
		closeSub(cur, s, true)
	}
	return placeRed(holderAddr, h.payee, h.viaNominee, 0, true, reason)
}

// ---- wind-down (design note v3.1): two keys ----

var windDownReasons = []string{"last-investor", "manager-decision", "too-small", "investor-interest"}

// ProposeWindDown proposes to close the fund. Manager only.
func ProposeWindDown(cur realm, reasonCode string) {
	onlyRole(cur, manager, "manager")
	requireState(stateOpen)
	requireNotWindingDown()
	checkReason(reasonCode, windDownReasons)
	windDownProposed, windDownReason, windDownPeriod = true, reasonCode, cur0.n
	addTrail("manager", "Wind-down of the fund proposed: "+reasonCode+".")
}

// WithdrawWindDown (manager) or DeclineWindDown (reviewer) drops the proposal.
func WithdrawWindDown(cur realm) {
	onlyRole(cur, manager, "manager")
	dropWindDown("manager", "withdrawn")
}

func DeclineWindDown(cur realm) {
	onlyRole(cur, reviewer, "valuation reviewer")
	dropWindDown("reviewer", "declined")
}

func dropWindDown(role, verb string) {
	if !windDownProposed || windDownApproved {
		panic("no wind-down proposal pending")
	}
	windDownProposed, windDownReason = false, ""
	addTrail(role, "Wind-down proposal "+verb+".")
}

// ApproveWindDown countersigns it, in the period it was proposed; the
// wind-down starts at this period's cut-off. Reviewer only. It cannot be
// reversed in this version.
func ApproveWindDown(cur realm) {
	onlyRole(cur, reviewer, "valuation reviewer")
	requireState(stateOpen)
	if !windDownProposed {
		panic("no wind-down proposed")
	}
	if windDownPeriod != cur0.n {
		panic("the proposal was made in an earlier period; propose again")
	}
	windDownApproved = true
	addTrail("reviewer", "Wind-down approved. It starts at this period's cut-off: no new subscriptions or investments; each period all available cash is paid out pro rata until the fund closes.")
}

// ---- closure (review 4, I2): two keys, after the wind-down ----

// ProposeClosure proposes to close the wound-down fund once nothing is left
// (no shares, no escrow, nothing set aside, no instrument on the books, no
// money to pay out). Until then late recoveries keep reaching the former
// holders. Manager only.
func ProposeClosure(cur realm) {
	onlyRole(cur, manager, "manager")
	requireState(stateOpen)
	if !windingDown {
		panic("the fund is not being wound down")
	}
	closureProposed = cur0.n
	addTrail("manager", "Closure of the fund proposed.")
}

// ApproveClosure countersigns it, in the same period. Reviewer only. The fund
// closes now if nothing is left, otherwise at the first settlement after.
func ApproveClosure(cur realm) {
	onlyRole(cur, reviewer, "valuation reviewer")
	requireState(stateOpen)
	if closureProposed == 0 || closureProposed != cur0.n {
		panic("no closure proposed in this period")
	}
	closureApproved = true
	addTrail("reviewer", "Closure approved: the fund closes once nothing is left to pay out.")
	closeIfDone(cur)
}

package fund

import "gno.land/p/nt/ufmt/v0"

// ---- screening agent (session key, recommend only) ----

// RecommendWallet posts the agent's screening of a wallet as a salted
// commitment. Nothing about the result is published.
func RecommendWallet(cur realm, wallet address, commitment string) {
	assertAgent(cur)
	checkCommitment(commitment)
	refuseSubAccount(wallet) // review 4, m2
	s := getStatus(wallet)
	if s == nil {
		s = &status{}
		eligibility.Set(wallet.String(), s)
	}
	s.screened = true
}

// RecommendSubscription records that the agent screened a pending direct
// subscription (source of funds). The commitment covers its result.
func RecommendSubscription(cur realm, id int64, commitment string) {
	assertAgent(cur)
	checkCommitment(commitment)
	s := getSub(id)
	if s.status != subPending {
		panic("subscription is not pending")
	}
	s.screened = true
}

// ---- compliance officer (master key, decides) ----

// DecideWallet records a wallet as eligible or not eligible for validDays
// (1 to 365), with a salted commitment to the off-chain file.
func DecideWallet(cur realm, wallet address, eligible bool, validDays int64, commitment string) {
	onlyRole(cur, officer, "compliance officer")
	if !wallet.IsValid() {
		panic("invalid address")
	}
	if isRole(wallet) {
		panic("role holders cannot invest")
	}
	refuseSubAccount(wallet)
	if wallet == fundAddr() || wallet == cashAddr() || wallet == escrowAddr() {
		panic("not an investor address")
	}
	if validDays < 1 || validDays > EligibilityMaxDays {
		panic("validDays must be 1 to 365")
	}
	checkCommitment(commitment)
	s := getStatus(wallet)
	if s == nil {
		s = &status{}
		eligibility.Set(wallet.String(), s)
	}
	countScreening(s.screened)
	s.eligible = eligible
	s.expiresAt = now() + validDays*86400
	s.commitment = commitment
	s.decidedAt = heightNow()
	s.screened = false
	word := "eligible"
	if !eligible {
		word = "not eligible"
	}
	// The trail names no wallet (design review 1, B5).
	addTrail("compliance", ufmt.Sprintf("A wallet was found %s, for %d days.", word, validDays))
}

// DecideSubscription approves or rejects a pending direct subscription while
// the period is open. A rejection refunds in the same transaction, except
// for a restricted wallet, whose subscription is held instead.
func DecideSubscription(cur realm, id int64, approve bool, commitment string) {
	onlyRole(cur, officer, "compliance officer")
	requireState(stateOpen)
	checkCommitment(commitment)
	s := getSub(id)
	if s.status != subPending {
		panic("subscription is not pending")
	}
	if approve {
		if !isEligible(s.wallet) {
			panic("wallet is not eligible, or its eligibility has expired")
		}
		countScreening(s.screened)
		s.status = subApproved
		s.screened = false
		approvedEscrow += s.amount
		addTrail("compliance", ufmt.Sprintf("Subscription #%d approved.", id))
		return
	}
	if held(s.wallet, s.payee) {
		panic("wallet is restricted; the subscription is held")
	}
	countScreening(s.screened)
	closeSub(cur, s, true)
}

// Restrict blocks a wallet: its pending orders are held, not dealt or
// refunded, until the restriction is lifted. Shown only as "restricted".
func Restrict(cur realm, wallet address, commitment string) {
	onlyRole(cur, officer, "compliance officer")
	checkCommitment(commitment)
	refuseSubAccount(wallet)
	s := getStatus(wallet)
	if s == nil {
		s = &status{}
		eligibility.Set(wallet.String(), s)
	}
	if s.restricted {
		panic("already restricted")
	}
	s.restricted = true
	s.commitment = commitment
	s.decidedAt = heightNow()
	addTrail("compliance", "A wallet was restricted.")
}

// Lift removes a restriction.
func Lift(cur realm, wallet address, commitment string) {
	onlyRole(cur, officer, "compliance officer")
	checkCommitment(commitment)
	s := getStatus(wallet)
	if s == nil || !s.restricted {
		panic("not restricted")
	}
	s.restricted = false
	s.commitment = commitment
	s.decidedAt = heightNow()
	addTrail("compliance", "A restriction was lifted.")
}

// refuseSubAccount keeps compliance outcomes about nominee sub-accounts off
// the chain: the nominee handles them (review 2, I4).
func refuseSubAccount(a address) {
	if isSubAccount(a) {
		panic("nominee sub-accounts are handled by the nominee, off-chain")
	}
}

func countScreening(screened bool) {
	if screened {
		decisionsScreened++
	} else {
		decisionsUnscreened++
	}
}

// WalletStatus tells a wallet where it stands: eligible or not, until when
// (unix seconds), and whether it is restricted. Nothing else is kept on-chain.
func WalletStatus(wallet address) (eligible bool, expiresAt int64, restricted bool) {
	s := getStatus(wallet)
	if s == nil {
		return false, 0, false
	}
	return s.eligible && now() < s.expiresAt, s.expiresAt, s.restricted
}

// Holding returns a wallet's shares and their value at the last approved
// NAV per share.
func Holding(wallet address) (shares, value int64) {
	h := getHolder(wallet)
	if h == nil || h.shares == 0 {
		return 0, 0
	}
	return h.shares, valueOfShares(h.shares)
}

package fund

import "gno.land/p/nt/ufmt/v0"

// MaxLotsPerRequest bounds a redemption request (1,000,000,000 tUSD);
// fundmath is overflow-safe anyway (review B1).
const MaxLotsPerRequest int64 = 100_000

// ---- direct registration: the investor's own wallet ----

// Subscribe places a subscription of amount tUSD (a multiple of one lot).
// First Approve this realm's address on tUSD for at least amount. The money
// goes to the escrow account until the compliance officer decides. Once
// accepted, a subscription is irrevocable.
func Subscribe(cur realm, amount int64) int64 {
	requireLaunched()
	requireState(stateOpen)
	requireTakingSubscriptions()
	w := cur.Previous().Address()
	if isFundAccount(w) {
		panic("not an investor address")
	}
	if isRole(w) {
		panic("role holders cannot invest")
	}
	if !isEligible(w) {
		panic("wallet is not eligible, or its eligibility has expired")
	}
	return placeSub(cur, w, w, false, amount, false)
}

// CancelSubscription withdraws a subscription the compliance officer has
// not yet accepted, and refunds it. Accepted subscriptions are irrevocable,
// except when the wallet is no longer eligible (the fund cannot deal it), or
// in a period stalled for 7 days in Cut-off or NAV proposed.
func CancelSubscription(cur realm, id int64) {
	requireLaunched()
	requireOpenOrStalled()
	s := getSub(id)
	if s.viaNominee || s.wallet != cur.Previous().Address() {
		panic("not your subscription")
	}
	// An accepted subscription binds the investor while the fund can deal
	// it; if the wallet is no longer eligible, the fund cannot, so the money
	// may come back.
	if s.status != subPending && !stalled() && isEligible(s.wallet) {
		panic("an accepted subscription is irrevocable")
	}
	if held(s.wallet, s.payee) {
		panic("wallet is restricted; the subscription is held")
	}
	closeSub(cur, s, true)
}

// RefundExpired refunds a direct subscription that the compliance officer
// has not decided within the timeout. Anyone may call it; the money goes
// back to the subscriber's wallet. A restricted wallet's subscription is
// held.
func RefundExpired(cur realm, id int64) {
	requireLaunched()
	requireOpenOrStalled()
	s := getSub(id)
	if s.viaNominee || s.status != subPending {
		panic("subscription is not pending")
	}
	if cur0.n-s.placedPeriod < ComplianceTimeoutPeriods {
		panic(ufmt.Sprintf("refundable from period %d", s.placedPeriod+ComplianceTimeoutPeriods))
	}
	if held(s.wallet, s.payee) {
		panic("wallet is restricted; the subscription is held")
	}
	closeSub(cur, s, true)
}

// RequestRedemption asks to redeem `lots` lots (0 = the whole holding) at
// this period's NAV. A request is irrevocable once placed. Shares stay
// invested until it is filled.
func RequestRedemption(cur realm, lots int64) int64 {
	requireLaunched()
	requireState(stateOpen)
	requireNotWindingDown()
	w := cur.Previous().Address()
	return placeRed(w, w, false, lots, false, "")
}

// ---- withdrawal at the investor's request ("save as determined by the fund") ----
//
// Orders are irrevocable: the investor cannot cancel one, but may ask the
// fund to withdraw it. The request is on-chain, so the administrator can
// withdraw only an order whose holder asked in this period (review 2, I6):
// one key cannot cancel orders nobody asked to cancel.

// AskToWithdraw asks the fund to withdraw the caller's open order (its
// subscription in escrow, or its redemption request). Investor only.
func AskToWithdraw(cur realm) {
	requireLaunched()
	requireState(stateOpen)
	assertMasterKey()
	askToWithdraw(cur.Previous().Address(), "investor")
}

// AskToWithdrawFor does the same for nominee sub-account `sub`. The nominee
// realm only.
func AskToWithdrawFor(cur realm, sub string) {
	requireNominee(cur)
	requireState(stateOpen)
	checkCommitment(sub)
	askToWithdraw(subAccountAddr(sub), "nominee")
}

func askToWithdraw(w address, role string) {
	h := getHolder(w)
	switch {
	case h != nil && h.activeSub != 0:
		s := getSub(h.activeSub)
		s.askedPeriod = cur0.n
		addTrail(role, ufmt.Sprintf("Withdrawal of subscription #%d requested.", s.id))
	case h != nil && h.openRed != 0:
		r := getRed(h.openRed)
		if r.compulsory {
			panic("a compulsory redemption cannot be withdrawn")
		}
		r.askedPeriod = cur0.n
		addTrail(role, ufmt.Sprintf("Withdrawal of redemption request #%d requested.", r.id))
	default:
		panic("no open order")
	}
}

// WithdrawSubscription withdraws and refunds a subscription whose investor
// asked for it in this period, with a reason code on the trail.
// Administrator only, while the period is open.
func WithdrawSubscription(cur realm, id int64, reasonCode string) {
	onlyRole(cur, administrator, "administrator")
	requireState(stateOpen)
	checkCode(reasonCode)
	s := getSub(id)
	if s.askedPeriod != cur0.n {
		panic("the investor has not asked to withdraw it in this period")
	}
	if held(s.wallet, s.payee) {
		panic("wallet is restricted; the subscription is held")
	}
	addTrail("administrator", ufmt.Sprintf("Subscription #%d withdrawn at the investor's request: %s.", id, reasonCode))
	closeSub(cur, s, true)
}

// WithdrawRedemption withdraws a redemption request whose investor asked for
// it in this period, with a reason code. Administrator only, while the
// period is open.
// A compulsory redemption cannot be withdrawn this way.
func WithdrawRedemption(cur realm, id int64, reasonCode string) {
	onlyRole(cur, administrator, "administrator")
	requireState(stateOpen)
	checkCode(reasonCode)
	r := getRed(id)
	if r.compulsory {
		panic("a compulsory redemption cannot be withdrawn")
	}
	if r.askedPeriod != cur0.n {
		panic("the investor has not asked to withdraw it in this period")
	}
	closeRed(r)
	addTrail("administrator", ufmt.Sprintf("Redemption request #%d withdrawn at the investor's request: %s.", id, reasonCode))
}

// ---- nominee route: orders for pseudonymous sub-accounts ----

func requireNominee(cur realm) {
	assertMasterKey()
	requireLaunched()
	if nomineePath == "" || cur.Previous().PkgPath() != nomineePath {
		panic("nominee realm only")
	}
}

// SubscribeFor places a subscription for nominee sub-account `sub` (a
// 64-hex identifier). The nominee realm only, after its batch attestation;
// the money comes from the nominee, which must Approve this realm first.
func SubscribeFor(cur realm, sub string, amount int64) int64 {
	requireNominee(cur)
	requireState(stateOpen)
	requireTakingSubscriptions()
	checkCommitment(sub)
	if !isEligible(nomineeAddr) {
		panic("the nominee is not eligible, or is restricted")
	}
	a := subAccountAddr(sub)
	if !isSubAccount(a) && getStatus(a) != nil {
		panic("this address already has a compliance status") // review 4, m2
	}
	subAccounts.Set(a.String(), true)
	return placeSub(cur, a, nomineeAddr, true, amount, true)
}

// RegisterSubAccountFor records nominee sub-account `sub` in the fund before
// its identifier is handed to the investor, so that no compliance decision
// can ever name it (review 3, m3). The nominee realm only.
func RegisterSubAccountFor(cur realm, sub string) {
	requireNominee(cur)
	checkCommitment(sub)
	a := subAccountAddr(sub)
	if getStatus(a) != nil {
		panic("this address already has a compliance status")
	}
	subAccounts.Set(a.String(), true)
}

// RequestRedemptionFor asks to redeem `lots` lots (0 = all) for nominee
// sub-account `sub`. Proceeds are paid to the nominee. Irrevocable.
func RequestRedemptionFor(cur realm, sub string, lots int64) int64 {
	requireNominee(cur)
	requireState(stateOpen)
	requireNotWindingDown()
	checkCommitment(sub)
	return placeRed(subAccountAddr(sub), nomineeAddr, true, lots, false, "")
}

// CancelFor takes a nominee sub-account's subscription back out of escrow
// in a period stalled for 7 days (orders are otherwise irrevocable).
func CancelFor(cur realm, sub string) {
	requireNominee(cur)
	checkCommitment(sub)
	if !stalled() {
		panic("orders are irrevocable; only a stalled period allows this")
	}
	h := getHolder(subAccountAddr(sub))
	if h == nil || h.activeSub == 0 {
		panic("no subscription in escrow")
	}
	s := getSub(h.activeSub)
	if held(s.wallet, s.payee) {
		panic("the nominee is restricted; the subscription is held")
	}
	closeSub(cur, s, true)
}

// HoldingOf returns a nominee sub-account's shares and their value at the
// last approved NAV per share.
func HoldingOf(sub string) (shares, value int64) {
	checkCommitment(sub)
	return Holding(subAccountAddr(sub))
}

// ---- shared ----

func requireTakingSubscriptions() {
	if subscriptionsClosed {
		panic("the fund is closed to new subscriptions")
	}
	requireNotWindingDown()
}

func requireNotWindingDown() {
	if windingDown || windDownApproved {
		panic("the fund is being wound down")
	}
}

func placeSub(cur realm, w, payee address, via bool, amount int64, approved bool) int64 {
	if amount < Lot || amount%Lot != 0 {
		panic("amount must be a multiple of one lot (10,000 tUSD)")
	}
	if activeSubs.Size() >= MaxOpenSubscriptions {
		panic("too many open subscriptions; try next period")
	}
	h := getHolder(w)
	if h == nil {
		h = &holder{addr: w, payee: payee, viaNominee: via}
		holders.Set(w.String(), h)
	}
	if h.activeSub != 0 {
		panic("this holder already has a subscription in escrow")
	}
	if h.openRed != 0 {
		panic("this holder has an open redemption request")
	}
	nextSub++
	id := nextSub
	s := &subscription{id: id, amount: amount, placedPeriod: cur0.n, wallet: w, payee: payee, viaNominee: via, status: subPending}
	if approved {
		s.status = subApproved
		approvedEscrow += amount
	}
	subs.Set(pad(id), s)
	activeSubs.Set(pad(id), true)
	h.activeSub = id
	escrowBook += amount
	checkErr(token.RealmTeller(0, cur).TransferFrom(0, cur, payee, escrowAddr(), amount))
	role := "investor"
	if via {
		role = "nominee"
	}
	addTrail(role, ufmt.Sprintf("Subscription #%d placed: %s tUSD in escrow.", id, fmtAmt(amount)))
	return id
}

// closeSub refunds a subscription still in escrow and deletes its record,
// so no closed order stays stored against a wallet (review I6). Rejection,
// cancellation and timeout share one trail wording.
func closeSub(cur realm, s *subscription, refund bool) {
	activeSubs.Remove(pad(s.id))
	subs.Remove(pad(s.id))
	escrowBook -= s.amount
	if s.status == subApproved {
		approvedEscrow -= s.amount
	}
	h := getHolder(s.wallet)
	if h != nil && h.activeSub == s.id {
		h.activeSub = 0
	}
	if refund {
		esc := cur.Sub(escrowSub)
		checkErr(token.RealmTeller(0, esc).Transfer(0, esc, s.payee, s.amount))
	}
	addTrail("settlement", ufmt.Sprintf("Subscription #%d closed; refunded.", s.id))
	prune(h)
}

func placeRed(w, payee address, via bool, lots int64, compulsory bool, reason string) int64 {
	if lots < 0 || lots > MaxLotsPerRequest {
		panic("lots must be 0 (whole holding) to 100,000")
	}
	h := getHolder(w)
	if h == nil || h.shares == 0 {
		panic("no shares to redeem")
	}
	if h.openRed != 0 {
		panic("this holder already has an open redemption request")
	}
	if h.activeSub != 0 {
		panic("this holder has a subscription in escrow")
	}
	if openReds.Size() >= MaxOpenRequests {
		panic("too many open redemption requests; try next period")
	}
	nextRed++
	id := nextRed
	r := &redemption{id: id, wallet: w, payee: payee, viaNominee: via, full: lots == 0, lots: lots, placedPeriod: cur0.n, dealPeriod: cur0.n + NoticePeriods, compulsory: compulsory}
	if compulsory {
		r.kind, r.reasonRef = compulsoryKind(reason)
	}
	reds.Set(pad(id), r)
	openReds.Set(pad(id), true)
	h.openRed = id
	what := "the whole holding"
	if lots > 0 {
		what = ufmt.Sprintf("%d lot(s)", lots)
	}
	role := "investor"
	if via {
		role = "nominee"
	}
	if compulsory {
		role = "compulsory"
	}
	addTrail(role, ufmt.Sprintf("Redemption request #%d: %s, dealt from period %d.", id, what, r.dealPeriod))
	return id
}

func closeRed(r *redemption) {
	openReds.Remove(pad(r.id))
	reds.Remove(pad(r.id))
	if h := getHolder(r.wallet); h != nil && h.openRed == r.id {
		h.openRed = 0
	}
}

package fund

import "gno.land/p/nt/ufmt/v0"

// listCodes are the public sanctions lists the screening agent uses.
var listCodes = []struct{ Code, Name string }{
	{"UN", "UN Security Council Consolidated List"},
	{"AE-LTL", "UAE Local Terrorist List"},
	{"US-SDN", "OFAC Specially Designated Nationals List"},
	{"US-CONS", "OFAC Consolidated (non-SDN) List"},
	{"EU-FSF", "EU Financial Sanctions Files (consolidated list)"},
	{"UK-SL", "UK Sanctions List"},
}

func listName(code string) string {
	for _, l := range listCodes {
		if l.Code == code {
			return l.Name
		}
	}
	return ""
}

// PostListSnapshot records a sanctions-list file the agent screens against:
// its list code, the publication date (YYYY-MM-DD) and the SHA-256 of the
// official file. Agent session only. It carries no investor data.
func PostListSnapshot(cur realm, list, published, sha string) {
	assertAgent(cur)
	if listName(list) == "" {
		panic("unknown list code")
	}
	checkDate(published)
	checkCommitment(sha)
	if v := lists.Get(list); v != nil && v.(*listSnapshot).sha == sha {
		panic("snapshot already recorded")
	}
	s := &listSnapshot{list: list, published: published, sha: sha, height: heightNow()}
	lists.Set(list, s)
	listSeq++
	listLog.Set(pad(listSeq), s)
	addTrail("screening agent", ufmt.Sprintf("List snapshot %s of %s: %s.", list, published, sha))
}

func checkDate(d string) {
	if len(d) != 10 || d[4] != '-' || d[7] != '-' {
		panic("date must be YYYY-MM-DD")
	}
	for i, r := range d {
		if i == 4 || i == 7 {
			continue
		}
		if r < '0' || r > '9' {
			panic("date must be YYYY-MM-DD")
		}
	}
	if d[5:7] < "01" || d[5:7] > "12" || d[8:10] < "01" || d[8:10] > "31" {
		panic("date must be YYYY-MM-DD")
	}
}

package fund

import (
	"strconv"
	"strings"

	"gno.land/p/g1thug63es793ckaw63l2704qzp3a92y58kekda0/cbtrial1/fundmath"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// MaxMark bounds one instrument's mark (1,000,000,000,000 tUSD).
const MaxMark int64 = 1_000_000_000_000 * u

// MinNAVps: below 1 tUSD per share dealing is suspended (review I1).
const MinNAVps int64 = 1 * u

// CutOff closes the period to new orders and compliance decisions. The
// administrator, or anyone once the period has been open for a full
// dealing period (so one silent key cannot stop dealing).
func CutOff(cur realm) {
	assertMasterKey()
	requireLaunched()
	requireState(stateOpen)
	c := cur.Previous().Address()
	who := "administrator"
	if c != administrator {
		if now() < cur0.openedAt+PeriodSeconds {
			panic("administrator only until the period has run its full length")
		}
		who = "anyone (period ran its full length)"
	}
	cur0.state = stateCutOff
	cur0.cutAt = now()
	cur0.cutBy = who
	addTrail(who, ufmt.Sprintf("Period %d cut-off.", cur0.n))
	if windDownApproved && !windingDown {
		windingDown = true
		addTrail("settlement", "Wind-down in force from this cut-off.")
	}
}

// ProposeNAV submits the period's valuation. marks lists every listed
// instrument once, as NAME=value in tUSD micro-units, separated by ";"
// (e.g. "NOTE-X=61800000000;BILL-Y=0"). sourceRef is the SHA-256 of the
// price sources, kept off-chain. A new proposal replaces an unapproved one.
//
// The fees and expenses (management, administration, deposit bank, set-up
// costs) accrue on the real time since the last approved valuation, capped
// at one dealing period (review I5).
func ProposeNAV(cur realm, marks string, sourceRef string) int64 {
	onlyRole(cur, administrator, "administrator")
	if cur0.state != stateCutOff && cur0.state != stateProposed {
		panic("not allowed in state " + stateNames[cur0.state])
	}
	checkCommitment(sourceRef)
	parsed := parseMarks(marks)
	gross := bookCash
	for _, m := range parsed {
		gross = addChecked(gross, m.value)
	}
	S := sharesInIssue
	t := now()
	var mgmt, admin, bank, org int64
	if S > 0 && lastStrikeTime > 0 {
		elapsed := t - lastStrikeTime
		if elapsed > PeriodSeconds {
			elapsed = PeriodSeconds
		}
		if elapsed > 0 {
			mgmt = fundmath.AnnualCharge(gross, FeeBps, elapsed)
			admin = fundmath.AnnualCharge(gross, AdminFeeBps, elapsed)
			bank = fundmath.AnnualCharge(gross, BankFeeBps, elapsed)
			org = fundmath.MulDivDown(OrgCostTotal, elapsed, OrgCostPeriods*PeriodSeconds)
			if org > orgLeft {
				org = orgLeft
			}
		}
	}
	fee := mgmt + admin + bank + org
	nav := gross - totalOwed - fee
	navps := Par
	lowNAV := false
	if S > 0 {
		// A NAV of zero or less, or below 1 tUSD per share, is accepted: the
		// period deals nothing (outside a wind-down) but completes, so the
		// board can still act (review 3, I3).
		if nav <= 0 {
			navps, lowNAV = 0, true
		} else {
			navps = fundmath.MulDivDown(nav, u, S)
			lowNAV = navps < MinNAVps
		}
	}
	needsAck := false
	if S > 0 && lastNAVps > 0 {
		diff := navps - lastNAVps
		if diff < 0 {
			diff = -diff
		}
		needsAck = fundmath.MulDivDown(diff, fundmath.BpsDenominator, lastNAVps) > NAVToleranceBps
	} else if S > 0 && lastStrikeTime > 0 {
		needsAck = true // from a NAV per share of 0, any NAV needs acknowledgement (review 4, m1)
	}
	cur0.proposalNo++
	cur0.valuedAt = t
	cur0.marks, cur0.sourceRef = parsed, sourceRef
	cur0.gross, cur0.fee, cur0.nav, cur0.navps, cur0.needsAck = gross, fee, nav, navps, needsAck
	cur0.mgmtFee, cur0.adminFee, cur0.bankFee, cur0.orgFee = mgmt, admin, bank, org
	cur0.lowNAV = lowNAV
	cur0.state = stateProposed
	addTrail("administrator", ufmt.Sprintf("Period %d NAV proposal %d: gross %s, fees and expenses %s, NAV %s, NAV per share %s%s.",
		cur0.n, cur0.proposalNo, fmtAmt(gross), fmtAmt(fee), fmtAmt(nav), fmtAmt(navps), ackNote(needsAck)+lowNote(lowNAV)))
	return cur0.proposalNo
}

func lowNote(b bool) string {
	if b && !windingDown {
		return "; below 1 tUSD per share or not positive: no order is dealt this period"
	}
	return ""
}

func ackNote(b bool) string {
	if b {
		return " (move beyond tolerance: needs the reviewer's acknowledgement)"
	}
	return ""
}

// ApproveNAV countersigns proposal number `proposal`. A move beyond the
// tolerance needs acknowledgeMove = true. Settlement can then start.
func ApproveNAV(cur realm, proposal int64, acknowledgeMove bool) {
	onlyRole(cur, reviewer, "valuation reviewer")
	requireState(stateProposed)
	if proposal != cur0.proposalNo {
		panic("proposal number does not match the current proposal")
	}
	if cur0.needsAck && !acknowledgeMove {
		panic("NAV move beyond tolerance: acknowledgeMove must be true")
	}
	for _, m := range cur0.marks {
		getInstrument(m.name).book = m.value
	}
	cur0.sharesOpen = sharesInIssue
	cur0.state = stateSettling
	cur0.phase = 0
	cur0.fills = avl.NewTree()
	lastNAVps = cur0.navps
	lastStrikeTime = cur0.valuedAt
	addTrail("reviewer", ufmt.Sprintf("Period %d NAV proposal %d approved. NAV per share %s.", cur0.n, proposal, fmtAmt(cur0.navps)))
}

// RejectNAV sends the proposal back to the administrator with a reason code.
func RejectNAV(cur realm, proposal int64, reasonCode string) {
	onlyRole(cur, reviewer, "valuation reviewer")
	requireState(stateProposed)
	if proposal != cur0.proposalNo {
		panic("proposal number does not match the current proposal")
	}
	checkCode(reasonCode)
	cur0.state = stateCutOff
	addTrail("reviewer", ufmt.Sprintf("Period %d NAV proposal %d rejected: %s.", cur0.n, proposal, reasonCode))
}

func parseMarks(s string) []mark {
	if len(s) > 1024 {
		panic("marks too long")
	}
	seen := map[string]bool{}
	var out []mark
	for _, part := range strings.Split(s, ";") {
		kv := strings.Split(part, "=")
		if len(kv) != 2 {
			panic("marks: expected NAME=value")
		}
		name := kv[0]
		if !instruments.Has(name) {
			panic("marks: unknown instrument " + name)
		}
		if seen[name] {
			panic("marks: instrument listed twice: " + name)
		}
		v, err := strconv.ParseInt(kv[1], 10, 64)
		if err != nil || v < 0 || v > MaxMark {
			panic("marks: value must be an integer from 0 to 10^18 micro-units")
		}
		seen[name] = true
		out = append(out, mark{name, v})
	}
	if len(out) != len(instrOrder) {
		panic("marks: every listed instrument must be marked")
	}
	return out
}

package fund

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1thug63es793ckaw63l2704qzp3a92y58kekda0/cbtrial1/fundmath"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Contract notes and annual statements (design note v6): written by the
// settlement code for every issue and cancellation of shares, so an investor
// can show the date, price, amounts, fees and the realised gain or loss at
// average cost. They contain nothing the chain does not already show to
// someone who knows the wallet or the sub-account.

const (
	noteSubscription = iota
	noteRedemption
	noteCompulsory
	noteDistribution
	noteRecovery
	noteInsolvency
	noteCrystallisation
)

var noteKinds = []string{"Subscription", "Redemption", "Compulsory redemption", "Wind-down distribution", "Recovery after the final distribution", "Cancellation without payment (insolvency)", "Performance fee crystallised"}

const noteCaveat = "> For information. Tax treatment depends on your country; confirm with your tax adviser. Test deployment: fictional fund, test tokens without value.\n\n"

var (
	notes      = avl.NewTree() // padded number -> *note
	notesByKey = avl.NewTree() // holder address + "/" + padded number -> true
	noteSeq    int64
)

type note struct {
	n, period, valuedAt, height int64
	kind                        int
	holder                      address
	navps                       int64
	shares                      int64 // issued (subscription) or cancelled
	holdingAfter                int64
	gross                       int64 // value of the shares at the NAV (before the performance fee)
	perfFee                     int64
	net                         int64 // paid (or set aside), or subscribed
	held                        bool  // set aside for a restricted holder
	cost                        int64 // cost added (subscription) or taken off (cancellation)
	avgCostAfter                int64 // per share
	gain                        int64 // net - cost taken off
}

// takeCost removes the average cost of q shares from h (all of it for the
// whole holding) and returns it. Call before the shares are removed.
func takeCost(h *holder, q int64) int64 {
	if q <= 0 || h.shares <= 0 {
		return 0
	}
	c := h.cost
	if q < h.shares {
		c = fundmath.MulDivDown(h.cost, q, h.shares)
	}
	h.cost -= c
	return c
}

func avgCost(h *holder) int64 {
	if h.shares <= 0 {
		return 0
	}
	return fundmath.MulDivDown(h.cost, u, h.shares)
}

func addNote(h *holder, kind int, shares, perf, net, cost int64, held bool) {
	noteSeq++
	nt := &note{n: noteSeq, period: cur0.n, valuedAt: cur0.valuedAt, height: heightNow(), kind: kind, holder: h.addr,
		navps: cur0.navps, shares: shares, holdingAfter: h.shares, perfFee: perf, net: net, held: held, cost: cost, avgCostAfter: avgCost(h)}
	switch kind {
	case noteSubscription:
		nt.gross = net
	case noteCrystallisation:
		nt.gross = perf
	default:
		nt.gross = net + perf
		nt.gain = net - cost
	}
	notes.Set(pad(noteSeq), nt)
	notesByKey.Set(h.addr.String()+"/"+pad(noteSeq), true)
}

// NoteCount returns the number of contract notes issued.
func NoteCount() int64 { return noteSeq }

// ---- pages ----

func renderNotePage(parts []string) string {
	if len(parts) == 2 && parts[0] == "note" {
		n, err := strconv.Atoi(parts[1])
		if err != nil || n < 1 || int64(n) > noteSeq {
			return "unknown note"
		}
		return renderNote(notes.Get(pad(int64(n))).(*note))
	}
	if parts[0] == "notes" && len(parts) >= 2 {
		a, rest := holderFromPath(parts[1:])
		if a == "" {
			return "invalid holder"
		}
		page := 1
		if len(rest) == 1 {
			p, err := strconv.Atoi(rest[0])
			if err != nil || p < 1 {
				return "invalid page"
			}
			page = p
		} else if len(rest) > 1 {
			return "404"
		}
		return renderNotesOf(a, page)
	}
	if parts[0] == "statement" && len(parts) >= 3 {
		a, rest := holderFromPath(parts[1:])
		if a == "" || len(rest) != 1 {
			return "invalid holder or year"
		}
		y, err := strconv.Atoi(rest[0])
		if err != nil || y < 2000 || y > 3000 {
			return "invalid year"
		}
		return renderStatement(a, int64(y))
	}
	return "404"
}

// holderFromPath reads "g1..." or "sub/<64 hex>" (a nominee sub-account).
func holderFromPath(p []string) (address, []string) {
	if len(p) >= 2 && p[0] == "sub" {
		if len(p[1]) != 64 {
			return "", nil
		}
		for _, r := range p[1] {
			if !(r >= '0' && r <= '9' || r >= 'a' && r <= 'f') {
				return "", nil
			}
		}
		if nomineePath == "" {
			return "", nil
		}
		return subAccountAddr(p[1]), p[2:]
	}
	a := address(p[0])
	if !a.IsValid() {
		return "", nil
	}
	return a, p[1:]
}

func dateOf(t int64) string { return time.Unix(t, 0).UTC().Format("2006-01-02") }

func renderNote(nt *note) string {
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# Contract note %d\n\n", nt.n) + banner + nav() + noteCaveat)
	rows := [][2]string{
		{"Fund", FundName},
		{"Kind", noteKinds[nt.kind]},
		{"Holder", "`" + nt.holder.String() + "`"},
		{"Dealing period", ufmt.Sprintf("%d (valued %s UTC)", nt.period, dateOf(nt.valuedAt))},
		{"NAV per share", fmtAmt(nt.navps) + " tUSD"},
	}
	switch nt.kind {
	case noteSubscription:
		rows = append(rows, [2]string{"Amount subscribed", fmtAmt(nt.net) + " tUSD"}, [2]string{"Shares issued", fmtAmt(nt.shares)})
	case noteCrystallisation:
		rows = append(rows, [2]string{"Performance fee", fmtAmt(nt.perfFee) + " tUSD"}, [2]string{"Shares cancelled for the fee", fmtAmt(nt.shares)})
	default:
		paid := "Net amount paid"
		if nt.held {
			paid = "Net amount set aside (restricted holder)"
		}
		rows = append(rows,
			[2]string{"Shares cancelled", fmtAmt(nt.shares)},
			[2]string{"Gross value", fmtAmt(nt.gross) + " tUSD"},
			[2]string{"Performance fee", fmtAmt(nt.perfFee) + " tUSD"},
			[2]string{paid, fmtAmt(nt.net) + " tUSD"},
			[2]string{"Cost of the shares (average cost)", fmtAmt(nt.cost) + " tUSD"},
			[2]string{"Realised gain or loss", fmtAmt(nt.gain) + " tUSD"})
	}
	rows = append(rows, [2]string{"Holding after", fmtAmt(nt.holdingAfter) + " shares"}, [2]string{"Average cost per share after", fmtAmt(nt.avgCostAfter) + " tUSD"},
		[2]string{"Issued", ufmt.Sprintf("by the fund's code at block height %d", nt.height)})
	b.WriteString("| | |\n|---|---|\n")
	for _, r := range rows {
		b.WriteString("| " + r[0] + " | " + r[1] + " |\n")
	}
	return b.String()
}

func renderNotesOf(a address, page int) string {
	var b strings.Builder
	b.WriteString("# Contract notes\n\n" + banner + nav() + noteCaveat)
	b.WriteString("Holder `" + a.String() + "`. Newest first. Annual statement: `" + home() + ":statement/" + a.String() + "/<year>`.\n\n| Note | Period | Date | Kind | Shares | Net tUSD | Gain or loss |\n|---:|---:|---|---|---:|---:|---:|\n")
	prefix := a.String() + "/"
	var keys []string
	notesByKey.Iterate(prefix, prefix+"~", func(k string, _ any) bool {
		keys = append(keys, k)
		return false
	})
	pages := pageCount(len(keys), trailPageSize)
	if page > pages {
		return "invalid page"
	}
	for i := len(keys) - 1 - (page-1)*trailPageSize; i >= 0 && i > len(keys)-1-page*trailPageSize; i-- {
		nt := notes.Get(keys[i][len(prefix):]).(*note)
		b.WriteString(ufmt.Sprintf("| [%d](%s:note/%d) | %d | %s | %s | %s | %s | %s |\n", nt.n, home(), nt.n, nt.period, dateOf(nt.valuedAt), noteKinds[nt.kind], fmtAmt(nt.shares), fmtAmt(nt.net), fmtAmt(nt.gain)))
	}
	if page < pages {
		b.WriteString(ufmt.Sprintf("\n[Older](%s:notes/%s/%d)", home(), a.String(), page+1))
	}
	return b.String()
}

func renderStatement(a address, year int64) string {
	from := time.Date(int(year), time.January, 1, 0, 0, 0, 0, time.UTC).Unix()
	to := time.Date(int(year)+1, time.January, 1, 0, 0, 0, 0, time.UTC).Unix()
	var b strings.Builder
	b.WriteString(ufmt.Sprintf("# Annual statement %d\n\n", year) + banner + nav() + noteCaveat)
	b.WriteString("Fund: " + FundName + ". Holder `" + a.String() + "`. Average cost method.\n\n| Note | Date | Kind | Shares | Net tUSD | Performance fee | Gain or loss |\n|---:|---|---|---:|---:|---:|---:|\n")
	prefix := a.String() + "/"
	var subscribed, received, perf, gain, holding, avg int64
	found := false
	notesByKey.Iterate(prefix, prefix+"~", func(k string, _ any) bool {
		nt := notes.Get(k[len(prefix):]).(*note)
		if nt.valuedAt >= to {
			return true
		}
		holding, avg, found = nt.holdingAfter, nt.avgCostAfter, true
		if nt.valuedAt < from {
			return false
		}
		b.WriteString(ufmt.Sprintf("| %d | %s | %s | %s | %s | %s | %s |\n", nt.n, dateOf(nt.valuedAt), noteKinds[nt.kind], fmtAmt(nt.shares), fmtAmt(nt.net), fmtAmt(nt.perfFee), fmtAmt(nt.gain)))
		switch nt.kind {
		case noteSubscription:
			subscribed += nt.net
		case noteCrystallisation:
			perf += nt.perfFee
		default:
			received += nt.net
			perf += nt.perfFee
			gain += nt.gain
		}
		return false
	})
	if !found {
		return "no contract notes for this holder up to that year"
	}
	navps := yearEndNAVps(to)
	b.WriteString(ufmt.Sprintf("\n- Subscribed in the year: %s tUSD\n- Received in the year (paid or set aside): %s tUSD\n- Performance fees charged in the year: %s tUSD\n- Realised gain or loss in the year: %s tUSD\n", fmtAmt(subscribed), fmtAmt(received), fmtAmt(perf), fmtAmt(gain)))
	b.WriteString(ufmt.Sprintf("- Holding at the year end: %s shares, average cost %s tUSD per share\n", fmtAmt(holding), fmtAmt(avg)))
	if navps > 0 && holding > 0 {
		b.WriteString(ufmt.Sprintf("- Value at the last NAV of the year (%s tUSD per share): %s tUSD\n", fmtAmt(navps), fmtAmt(fundmath.MulDivDown(holding, navps, u))))
	}
	return b.String()
}

// yearEndNAVps is the NAV per share of the last period valued before t.
func yearEndNAVps(t int64) int64 {
	var v int64
	history.ReverseIterate("", "", func(_ string, x any) bool {
		r := x.(*record)
		if r.valuedAt < t {
			v = r.navps
			return true
		}
		return false
	})
	return v
}

package fund

import (
	"gno.land/p/g1thug63es793ckaw63l2704qzp3a92y58kekda0/cbtrial1/fundmath"
	"gno.land/p/nt/ufmt/v0"
)

// ---- investment payments out ----

// ProposeOutflow proposes an investment payment to a listed instrument.
// Manager only, while the period is open.
func ProposeOutflow(cur realm, instrumentName string, amount int64) int64 {
	onlyRole(cur, manager, "manager")
	requireState(stateOpen)
	requireNotWindingDown()
	countProposal()
	getInstrument(instrumentName)
	if amount <= 0 || amount > MaxMark {
		panic("amount out of range")
	}
	nextOut++
	o := &outflow{id: nextOut, instrument: instrumentName, amount: amount, period: cur0.n}
	outflows.Set(pad(o.id), o)
	addTrail("manager", ufmt.Sprintf("Outflow #%d proposed: %s tUSD to %s.", o.id, fmtAmt(amount), instrumentName))
	return o.id
}

// ApproveOutflow countersigns and pays an outflow. Reviewer only. The limits
// are checked before payment, against the NAV after the last settlement
// (design review 1, B4): the total for the period, and the concentration
// in one instrument. Payment goes only to the instrument's listed address.
func ApproveOutflow(cur realm, id int64) {
	onlyRole(cur, reviewer, "valuation reviewer")
	requireState(stateOpen)
	o := getOutflow(id)
	if o.paid || o.cancelled {
		panic("outflow is closed")
	}
	if o.period != cur0.n {
		panic("outflow was proposed in an earlier period; propose it again")
	}
	requireNotWindingDown()
	if lastNAV <= 0 {
		panic("no settled NAV yet")
	}
	if o.amount > bookCash-totalOwed {
		panic("not enough cash")
	}
	capPeriod := fundmath.MulDivDown(lastNAV, OutflowCapBps, fundmath.BpsDenominator)
	if addChecked(cur0.outflowUsed, o.amount) > capPeriod {
		panic(ufmt.Sprintf("outflow cap: %s tUSD left this period", fmtAmt(capPeriod-cur0.outflowUsed)))
	}
	in := getInstrument(o.instrument)
	capInstr := fundmath.MulDivDown(lastNAV, ConcentrationBps, fundmath.BpsDenominator)
	if addChecked(in.book, o.amount) > capInstr {
		panic("concentration limit: " + o.instrument + " would exceed " + pct(ConcentrationBps) + " of NAV")
	}
	o.paid = true
	cur0.outflowUsed += o.amount
	bookCash -= o.amount
	in.book += o.amount
	c := cur.Sub(cashSub)
	checkErr(token.RealmTeller(0, c).Transfer(0, c, in.payTo, o.amount))
	addTrail("reviewer", ufmt.Sprintf("Outflow #%d countersigned and paid: %s tUSD to %s.", id, fmtAmt(o.amount), o.instrument))
}

// CancelOutflow withdraws (manager) or declines (reviewer) an outflow.
func CancelOutflow(cur realm, id int64) {
	assertMasterKey()
	requireLaunched()
	c := cur.Previous().Address()
	if c != manager && c != reviewer {
		panic("manager or valuation reviewer only")
	}
	o := getOutflow(id)
	if o.paid || o.cancelled {
		panic("outflow is closed")
	}
	o.cancelled = true
	addTrail(roleName(c), ufmt.Sprintf("Outflow #%d cancelled.", id))
}

func getOutflow(id int64) *outflow {
	v := outflows.Get(pad(id))
	if v == nil {
		panic("unknown outflow")
	}
	return v.(*outflow)
}

// ---- money coming back (review I4) ----

// ProposeReceipt proposes to record tUSD that has arrived in the fund's cash
// account: from an instrument (a maturity, coupon or sale), or OTHER for
// anything unexplained, such as a donation. Manager only, while open.
func ProposeReceipt(cur realm, source string, amount int64) int64 {
	onlyRole(cur, manager, "manager")
	requireState(stateOpen)
	countProposal()
	if source != "OTHER" {
		getInstrument(source)
	}
	if amount <= 0 || amount > MaxMark {
		panic("amount out of range")
	}
	nextRcpt++
	r := &receipt{id: nextRcpt, source: source, amount: amount, period: cur0.n}
	receipts.Set(pad(r.id), r)
	addTrail("manager", ufmt.Sprintf("Receipt #%d proposed: %s tUSD from %s.", r.id, fmtAmt(amount), source))
	return r.id
}

// ApproveReceipt countersigns a receipt. Reviewer only. The cash account must
// already hold the recorded cash plus the amount, so nothing is counted
// twice. A receipt from an instrument lowers its book value (never below 0).
func ApproveReceipt(cur realm, id int64) {
	onlyRole(cur, reviewer, "valuation reviewer")
	requireState(stateOpen)
	r := getReceipt(id)
	if r.recorded || r.cancelled {
		panic("receipt is closed")
	}
	if r.period != cur0.n {
		panic("receipt was proposed in an earlier period; propose it again")
	}
	// The cash account holds the recorded cash and the payments set aside for
	// restricted holders; a receipt must come on top of both (review 3, I1).
	if token.BalanceOf(cashAddr()) < addChecked(addChecked(bookCash, totalHeld), r.amount) {
		panic("the cash account does not hold this amount beyond the recorded cash")
	}
	r.recorded = true
	bookCash += r.amount
	if r.source != "OTHER" {
		in := getInstrument(r.source)
		if r.amount >= in.book {
			in.book = 0
		} else {
			in.book -= r.amount
		}
	}
	addTrail("reviewer", ufmt.Sprintf("Receipt #%d countersigned: %s tUSD from %s added to cash.", id, fmtAmt(r.amount), r.source))
}

// CancelReceipt withdraws (manager) or declines (reviewer) a receipt.
func CancelReceipt(cur realm, id int64) {
	assertMasterKey()
	requireLaunched()
	c := cur.Previous().Address()
	if c != manager && c != reviewer {
		panic("manager or valuation reviewer only")
	}
	r := getReceipt(id)
	if r.recorded || r.cancelled {
		panic("receipt is closed")
	}
	r.cancelled = true
	addTrail(roleName(c), ufmt.Sprintf("Receipt #%d cancelled.", id))
}

func getReceipt(id int64) *receipt {
	v := receipts.Get(pad(id))
	if v == nil {
		panic("unknown receipt")
	}
	return v.(*receipt)
}

// ---- expenses (administrator proposes, reviewer approves) ----

// ProposeExpense proposes to pay a listed service provider (audit, legal,
// ...) from the fund's cash. Administrator only, while open.
func ProposeExpense(cur realm, provider string, amount int64, reasonCode string) int64 {
	onlyRole(cur, administrator, "administrator")
	requireState(stateOpen)
	countProposal()
	getProvider(provider)
	checkCode(reasonCode)
	if amount <= 0 || amount > MaxMark {
		panic("amount out of range")
	}
	nextExp++
	e := &expense{id: nextExp, provider: provider, amount: amount, reason: reasonCode, period: cur0.n}
	expenses.Set(pad(e.id), e)
	addTrail("administrator", ufmt.Sprintf("Expense #%d proposed: %s tUSD to %s (%s).", e.id, fmtAmt(amount), provider, reasonCode))
	return e.id
}

// ApproveExpense countersigns and pays an expense. Reviewer only.
func ApproveExpense(cur realm, id int64) {
	onlyRole(cur, reviewer, "valuation reviewer")
	requireState(stateOpen)
	e := getExpense(id)
	if e.paid || e.cancelled {
		panic("expense is closed")
	}
	if e.period != cur0.n {
		panic("expense was proposed in an earlier period; propose it again")
	}
	if e.amount > bookCash-totalOwed {
		panic("not enough cash")
	}
	e.paid = true
	bookCash -= e.amount
	c := cur.Sub(cashSub)
	checkErr(token.RealmTeller(0, c).Transfer(0, c, getProvider(e.provider), e.amount))
	addTrail("reviewer", ufmt.Sprintf("Expense #%d countersigned and paid: %s tUSD to %s.", id, fmtAmt(e.amount), e.provider))
}

// CancelExpense withdraws (administrator) or declines (reviewer) an expense.
func CancelExpense(cur realm, id int64) {
	assertMasterKey()
	requireLaunched()
	c := cur.Previous().Address()
	if c != administrator && c != reviewer {
		panic("administrator or valuation reviewer only")
	}
	e := getExpense(id)
	if e.paid || e.cancelled {
		panic("expense is closed")
	}
	e.cancelled = true
	addTrail(roleName(c), ufmt.Sprintf("Expense #%d cancelled.", id))
}

func getExpense(id int64) *expense {
	v := expenses.Get(pad(id))
	if v == nil {
		panic("unknown expense")
	}
	return v.(*expense)
}

func roleName(a address) string {
	switch a {
	case manager:
		return "manager"
	case administrator:
		return "administrator"
	case reviewer:
		return "reviewer"
	case officer:
		return "compliance"
	case auditor:
		return "auditor"
	}
	return "investor"
}

// MaxProposalsPerPeriod bounds the payments, receipts and expenses proposed
// in one period, so the desk page stays readable (review 2, m9).
const MaxProposalsPerPeriod int64 = 30

func countProposal() {
	if cur0.proposals >= MaxProposalsPerPeriod {
		panic("too many proposals in this period")
	}
	cur0.proposals++
}

