func init(cur realm) {
	token = grc20reg.MustGet(tusd.TokenKey())
	selfPath = cur.PkgPath()
	deployer = cur.Previous().Address()
	cur0 = period{state: stateSetup}
}

// ---- helpers ----

func fundAddr() address   { return chain.PackageAddress(selfPath) }
func escrowAddr() address { return chain.DerivePkgSubAddr(selfPath, escrowSub) }
func cashAddr() address   { return chain.DerivePkgSubAddr(selfPath, cashSub) }

// subAccountAddr is the register entry of nominee sub-account c: an address
// no one signs with.
func subAccountAddr(c string) address { return chain.DerivePkgSubAddr(nomineePath, "c/"+c) }

func now() int64       { return time.Now().Unix() }
func heightNow() int64 { return runtime.ChainHeight() }

// pad gives fixed-width tree keys so that ids sort in numeric order
// (ufmt has no zero padding).
func pad(n int64) string {
	if n < 0 {
		panic("pad: negative id")
	}
	s := ufmt.Sprintf("%d", n)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func addTrail(role, text string) {
	trailSeq++
	trail.Set(pad(trailSeq), &entry{height: heightNow(), t: now(), role: role, text: text})
	chain.Emit("Charterbook", "role", role, "text", text)
}

// assertMasterKey refuses any transaction signed by a session key. Every
// role function calls it (design review 1, B2).
func assertMasterKey() {
	if _, _, _, isSession := runtime.GetSessionInfo(); isSession {
		panic("master key required: session keys are refused")
	}
}

func onlyRole(cur realm, want address, name string) {
	assertMasterKey()
	if !launched {
		panic("fund not launched")
	}
	if cur.Previous().Address() != want {
		panic(name + " only")
	}
	if cur0.state == stateClosed && want != auditor {
		panic("the fund is closed") // the auditor may still record the last years
	}
}

func isRole(a address) bool {
	return a == manager || a == administrator || a == reviewer || a == officer || (auditor != "" && a == auditor) || a == deployer
}

// isFundAccount reports whether a is one of the fund's own accounts.
func isFundAccount(a address) bool {
	return a == fundAddr() || a == cashAddr() || a == escrowAddr() || (nomineeAddr != "" && a == nomineeAddr)
}

func requireState(s int) {
	if cur0.state != s {
		panic("not allowed in state " + stateNames[cur0.state])
	}
}

func requireLaunched() {
	if !launched {
		panic("fund not launched")
	}
	requireNotClosed()
}

// StallSeconds: once a period has sat in Cut-off or NAV proposed this long,
// investors may take their subscriptions back out of escrow (review I2).
const StallSeconds int64 = 7 * 24 * 60 * 60

func stalled() bool {
	return (cur0.state == stateCutOff || cur0.state == stateProposed) && now() >= cur0.cutAt+StallSeconds
}

func requireOpenOrStalled() {
	if cur0.state != stateOpen && !stalled() {
		panic("not allowed in state " + stateNames[cur0.state])
	}
}

func getHolder(a address) *holder {
	if v := holders.Get(a.String()); v != nil {
		return v.(*holder)
	}
	return nil
}

func getStatus(a address) *status {
	if v := eligibility.Get(a.String()); v != nil {
		return v.(*status)
	}
	return nil
}

func isEligible(a address) bool {
	s := getStatus(a)
	return s != nil && s.eligible && !s.restricted && now() < s.expiresAt
}

func isRestricted(a address) bool {
	s := getStatus(a)
	return s != nil && s.restricted
}

// held reports whether an order of holder w paid through payee is held by
// a restriction: of the wallet for a direct holder; of the nominee for its
// sub-accounts, which the fund never restricts one by one (review 2, I4).
func held(w, payee address) bool {
	if nomineeAddr != "" && payee == nomineeAddr {
		return isRestricted(payee)
	}
	return isRestricted(w)
}

// isSubAccount reports whether a is a nominee sub-account's register entry.
func isSubAccount(a address) bool { return subAccounts.Has(a.String()) }

func getSub(id int64) *subscription {
	v := subs.Get(pad(id))
	if v == nil {
		panic("unknown or closed subscription")
	}
	return v.(*subscription)
}

func getRed(id int64) *redemption {
	v := reds.Get(pad(id))
	if v == nil {
		panic("unknown or closed redemption request")
	}
	return v.(*redemption)
}

func getInstrument(name string) *instrument {
	v := instruments.Get(name)
	if v == nil {
		panic("unknown instrument " + name)
	}
	return v.(*instrument)
}

func instrumentsTotal() int64 {
	var t int64
	for _, n := range instrOrder {
		t = addChecked(t, getInstrument(n).book)
	}
	return t
}

func addChecked(a, b int64) int64 {
	c := a + b
	if (b > 0 && c < a) || (b < 0 && c > a) {
		panic("overflow")
	}
	return c
}

func checkCommitment(c string) {
	if len(c) != 64 {
		panic("commitment must be a 64-character hex SHA-256")
	}
	for _, r := range c {
		if !(r >= '0' && r <= '9' || r >= 'a' && r <= 'f') {
			panic("commitment must be lowercase hex")
		}
	}
}

func checkCode(c string) {
	if len(c) == 0 || len(c) > 32 {
		panic("reason code must be 1 to 32 characters")
	}
	for _, r := range c {
		if !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '-') {
			panic("reason code: a-z, 0-9 and - only")
		}
	}
}

func checkErr(err error) {
	if err != nil {
		panic(err.Error())
	}
}

func fmtAmt(v int64) string {
	neg := ""
	if v < 0 {
		neg = "-"
		v = -v
	}
	s := ufmt.Sprintf("%d", v/u)
	var b strings.Builder
	for i, r := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(r)
	}
	return neg + b.String() + "." + frac6(v%u)
}

// frac6 writes 0..999999 with six digits (ufmt has no zero padding).
func frac6(f int64) string {
	s := ufmt.Sprintf("%d", f)
	for len(s) < 6 {
		s = "0" + s
	}
	return s
}

// pct writes basis points as a percentage, e.g. 150 -> "1.50%".
func pct(bps int64) string {
	f := ufmt.Sprintf("%d", bps%100)
	if len(f) < 2 {
		f = "0" + f
	}
	return ufmt.Sprintf("%d", bps/100) + "." + f + "%"
}

func valueOfShares(shares int64) int64 {
	if lastNAVps <= 0 || shares <= 0 {
		return 0
	}
	return fundmath.MulDivDown(shares, lastNAVps, u)
}

// addShares and removeShares keep the nominee totals in step.
func addShares(h *holder, q int64) {
	if h.viaNominee {
		if h.shares == 0 && q > 0 {
			nomineeAccounts++
		}
		nomineeShares += q
	}
	h.shares += q
	sharesInIssue += q
}

func removeShares(h *holder, q int64) {
	if q > h.shares {
		panic("settlement: cancellation exceeds holding")
	}
	h.shares -= q
	sharesInIssue -= q
	if h.viaNominee {
		nomineeShares -= q
		if h.shares == 0 {
			nomineeAccounts--
		}
	}
}

func owedTo(a address) int64 {
	if v := owed.Get(a.String()); v != nil {
		return v.(int64)
	}
	return 0
}

// payOrOwe pays amount (plus anything already owed) to payee from the cash
// account, as far as the recorded cash goes; the rest is owed and deducted
// from NAV until paid. It returns what was paid.
func payOrOwe(cur realm, payee address, amount int64) int64 {
	prev := owedTo(payee)
	due := addChecked(prev, amount)
	if due == 0 {
		return 0
	}
	p := due
	if p > bookCash {
		p = bookCash
	}
	if p < 0 {
		p = 0
	}
	if p > 0 {
		c := cur.Sub(cashSub)
		checkErr(token.RealmTeller(0, c).Transfer(0, c, payee, p))
		bookCash -= p
	}
	if due-p == 0 {
		owed.Remove(payee.String())
	} else {
		owed.Set(payee.String(), due-p)
	}
	totalOwed += due - p - prev
	return p
}

func getProvider(name string) address {
	v := providers.Get(name)
	if v == nil {
		panic("unknown service provider " + name)
	}
	return v.(address)
}

func isSuspended() bool { return now() < suspendedUntil }

func requireNotClosed() {
	if cur0.state == stateClosed {
		panic("the fund is closed")
	}
}

// Package fund is Charterbook: a demonstration investment fund whose dealing
// terms are enforced by code. The legal document of a real fund would stay
// off-chain.
//
// TEST DEPLOYMENT: fictional fund, fictional parties, test tokens without
// value. Not operated by any regulated firm. Unaudited code. Not an offer.
//
// One dealing period runs: Open (orders and compliance decisions) ->
// Cut-off -> NAV proposed by the administrator -> NAV approved by the
// independent valuation reviewer -> settlement in batches -> next period.
// Investors hold shares directly (their own wallet) or through the nominee
// sub-realm (pseudonymous sub-accounts).
package fund

import (
	"crypto/sha256"
	"encoding/hex"

	"gno.land/p/g1thug63es793ckaw63l2704qzp3a92y58kekda0/cbtrial1/fundmath"
)

const u = fundmath.Unit

// Terms of the memorandum, enforced by the code. The terms page formats
// every figure from these constants.
const (
	FundName                        = "Charterbook Demonstration Fund I"
	MemoVersion                     = "6.0"
	Lot                       int64 = 10_000 * u // subscriptions and partial redemptions
	MinHolding                int64 = 10_000 * u // below this after a redemption: full exit
	Par                       int64 = 100 * u    // price per share of the first issue
	FeeBps                    int64 = 150        // management fee, % a year of gross assets
	AdminFeeBps               int64 = 10         // administration, % a year of gross assets
	BankFeeBps                int64 = 5          // deposit bank, % a year of gross assets
	OrgCostTotal              int64 = 6_000 * u  // set-up costs advanced by the manager
	OrgCostPeriods            int64 = 60         // written off over 60 periods
	PerfFeeBps                int64 = 2_000      // performance fee, % of the gain above each investor's mark
	CrystalliseEvery          int64 = 6          // periods between performance-fee crystallisations
	DefaultCrystalliseMinDays int64 = 180        // and at least these days, unless set otherwise before launch
	PeriodSeconds             int64 = 30 * 24 * 60 * 60
	GateBps                   int64 = 1_000 // redemptions per period, % of NAV (never less than one lot)
	NoticePeriods             int64 = 0     // a request is dealt at the period it is placed in
	NAVToleranceBps           int64 = 500   // larger moves need the reviewer's acknowledgement
	OutflowCapBps             int64 = 6_500 // investment payments per period, % of last NAV
	ConcentrationBps          int64 = 6_500 // per instrument, % of last NAV
	ComplianceTimeoutPeriods  int64 = 2     // undecided subscriptions refundable after
	EligibilityMaxDays        int64 = 365
	AgentSessionMaxDays       int64 = 60
	MaxSuspensionDays         int64 = 30  // a suspension ends by itself unless renewed with two keys
	MinHoldingNoticeDays      int64 = 30  // notice before a compulsory redemption below the minimum
	AuditDueDays              int64 = 182 // audited annual report due within 6 months of year end
	MaxOpenRequests                 = 200 // open redemption requests at any time
	MaxOpenSubscriptions            = 200
)

// memorandum is the investment memorandum, on-chain. Its SHA-256 is shown on
// the portal; an amendment would be a new realm version.
var memorandum = []struct{ Title, Body string }{
	{"1. The fund", "Charterbook Demonstration Fund I is a fictional open-ended fund on the gno.land Onyx testnet. It shows how a fund's terms can be enforced by code. It holds test tokens only. A real fund's legal documents would stay off-chain; this memorandum stands in for them, and its SHA-256 is shown on the portal."},
	{"2. Dealing", "The fund deals once a month, in one dealing period. A period opens, takes orders and compliance decisions, and is cut off by the administrator; if the administrator does not, anyone may cut it off once it has run 30 days. The administrator proposes a net asset value (NAV) and the independent valuation reviewer approves it. Every order of the period is dealt at that one NAV (forward pricing), unless it is held by compliance, limited by the gate or waiting out a suspension. The orders dealt are fixed at the first settlement call. The dealing currency is Test Dollar (tUSD). In the demonstration, periods last minutes."},
	{"3. Two ways to hold shares", "Direct: the investor's own wallet is in the register. Nominee: the nominee places orders for a pseudonymous sub-account and pays the investor; no investor wallet appears in the register. Lots, the gate, fees and the performance fee apply to a sub-account as to a wallet. The nominee registers each sub-account in the fund before handing out its identifier, and the fund refuses a sub-account that already has a compliance status. The nominee's orders need the compliance officer's attestation of the period's batch; compliance decisions about a sub-account are the nominee's, kept off-chain. If the nominee is restricted, all its sub-accounts' orders are held. A realm deployed at the registered nominee path confirmed itself before launch; its code is public there."},
	{"4. Subscriptions", "Subscriptions are made in multiples of one lot of 10,000 tUSD. A direct subscriber's wallet must be found eligible by the compliance officer, who then accepts or rejects the subscription; the money waits in the fund's escrow account until it is dealt at settlement. A subscription that is not accepted is refunded in full; until it is accepted, the subscriber may cancel it. Once accepted it is irrevocable: the subscriber may ask on-chain for it to be withdrawn, and the administrator may then withdraw and refund it in that period; the subscriber may also take it back if the wallet stops being eligible. A subscription left undecided for two periods can be refunded by anyone, to the subscriber. If a period sits in cut-off or awaiting its NAV for more than 7 days, subscribers may take their money back out of escrow. The first shares are issued at 100 tUSD each. The manager may close the fund to new subscriptions and reopen it."},
	{"5. Redemptions", "There is no lock-up: shares can be redeemed from the period after they are issued. An investor may redeem in multiples of one lot, or the whole holding; a redemption that would leave less than 10,000 tUSD redeems the whole holding. A request is irrevocable: the investor may ask on-chain for it to be withdrawn, and the administrator may then withdraw it in that period. Payment goes to the same wallet, or to the nominee for a sub-account. Each period redemptions are limited to 10% of NAV, never less than one lot, and to the cash available after fees and compulsory redemptions (the gate). Requests carried from earlier periods are served first, then new requests. Within each group, requests that exceed what is left are filled pro rata in whole lots, and requests that received nothing are served first from what remains; a whole-holding redemption larger than its share is paid in whole lots while at least 10,000 tUSD stays invested. Anything unfilled stays invested and is dealt at the next period's NAV, ahead of new requests. If only one request is left unfilled and it is the rest of a whole-holding redemption below 20,000 tUSD, it is paid from cash even above the gate."},
	{"6. Valuation", "NAV is the fund's recorded cash plus the marks of its listed instruments, less the fees for the period and anything still owed. tUSD sent to the fund outside the dealing process does not change NAV until the manager proposes and the reviewer countersigns it as a receipt, which the code accepts only if the cash account holds it on top of the recorded cash and any payments set aside for restricted holders. Rounding always favours the investors who stay: shares issued round down, shares cancelled for a payment round up, and whole-holding payments round down. A NAV per share that moves by more than 5%, or any NAV after one of zero, needs the reviewer's explicit acknowledgement. Below 1 tUSD per share, or at a NAV of zero or less, no order is dealt in that period, but the period completes and the fees are charged or owed, so the board can still suspend or wind the fund down."},
	{"7. Fees and expenses", "Charged on gross assets, accrued on the time between valuations (at most 30 days per period) and paid at settlement: the management fee of 1.50% a year to the manager, the administration fee of 0.10% a year to the administrator and the deposit bank fee of 0.05% a year to the bank. The set-up costs of 6,000 tUSD, advanced by the manager, are repaid over 60 months, accrued on time like the fees (100 tUSD per 30 days). Other expenses (the audit, legal and similar costs) are proposed by the administrator and paid only when the reviewer countersigns in the same period, only from cash not owed to others, and only to a service provider listed on the terms page; a role holder may be listed only for its own fee. A fee that cash cannot cover is owed to its payee, deducted from NAV and paid first when cash allows; when the cash does not cover every payee, each is paid pro rata. At most 30 payments, receipts and expenses may be proposed in a period."},
	{"8. Performance fee", "20% of the gain above each investor's own high-water mark. The mark starts at the price an investor subscribes at; a later subscription blends it with the new price, weighted by shares. The fee is charged when shares are redeemed, by cancelling extra shares worth the fee, and paid to the manager after every redemption of the period has been paid; what cash cannot cover is owed. It is crystallised for every holder at least 6 periods and at least the number of days shown on the terms page after the last crystallisation, and in each wind-down distribution: the fund cancels shares worth the fee and the mark moves up to that period's NAV per share. Nothing is due while the NAV per share is at or below the mark, so an investor never pays twice for the same gain."},
	{"9. Investment limits", "The manager may invest only in the instruments listed on the terms page. Each investment payment needs the reviewer's countersignature in the same period, and is paid only to the instrument's listed address. Investment payments in one period may not exceed 65% of the last NAV in total, and may not raise one instrument above 65% of the last NAV. Money coming back from an instrument is recorded only with both signatures. Instruments held off-chain rest on trust in the manager and the reviewer."},
	{"10. Suspension", "The manager may propose to suspend dealing, for one of the listed reasons, for up to 30 days; it starts only when the reviewer approves in the same period. While dealing is suspended, NAVs are still calculated but no order is dealt: orders wait, and are dealt at the first NAV after the suspension. A suspension ends by itself when its time runs out; it can be renewed, or lifted early, only with both keys. Either key may drop a pending proposal."},
	{"11. Compulsory redemption", "The compliance officer may redeem a direct holding in full when the holder is no longer eligible, would put the fund in breach of law, or has not provided the information asked for; the reason stays off-chain, and only a salted commitment to the officer's record is kept. A top-up the fund can no longer deal is refunded first. For a sub-account, the nominee does this off-chain. The manager may give notice to a holder worth less than 10,000 tUSD; the notice lapses if the holding is topped up above that. If it is still below after 30 days, the manager may propose its redemption, and it happens only if the reviewer approves in the same period and the holding is still below the minimum. A compulsory redemption cannot be withdrawn. It is paid ahead of the gate: whole when cash allows, otherwise in whole lots from the cash there is, the rest at the next period."},
	{"12. Wind-down and closure", "The fund is wound down when the manager proposes it and the reviewer approves in the same period, or by itself when the last investor asks to redeem everything, even at a low NAV (a compulsory redemption does not count; a board suspension defers it). Before approval, the manager may withdraw the proposal and the reviewer may decline it. Once it is approved the fund takes no new subscriptions, redemption requests or investments; at the first settlement of that period, subscriptions in escrow are refunded (held ones stay held) and open requests are replaced by the distributions. The manager sells the investments, each sale recorded as a receipt with both signatures. Each period, all available cash is paid out pro rata to the holders, by cancelling shares at the NAV after fees and performance fee. When no investment is left, the last distribution pays every holder the full value of the shares. If nothing is left for the shareholders, every share is cancelled without payment and the cash left goes to the creditors (the fees and set-up costs owed to the manager, the administrator and the bank), pro rata to what each is owed; the rest is written off. A restricted holder's payment is set aside for that holder, out of NAV and out of the fees, and paid once the restriction is lifted; anyone may then trigger the payment. After the last distribution the fund stays in liquidation: money recorded then, such as a late recovery on a written-off note, goes first to any creditors still owed and then pro rata to the holders of that distribution, by the number of shares each had cancelled in it. The fund closes only when the manager proposes it and the reviewer approves in the same period, and only once no shares, no subscription in escrow, no set-aside payment, no instrument on the books and nothing to pay out are left; only rounding dust goes to the manager. Nothing can be recorded after closure. A wind-down cannot be reversed in this version."},
	{"13. Oracles", "An oracle here is a named account whose signed decisions the fund accepts. The compliance officer decides eligibility, subscriptions, restrictions and compulsory redemptions. The screening agent checks investors against the public sanctions lists and may only recommend: its session key is limited by the chain to this fund's realms and expires no later than the date the officer registered (the officer also sets its spend limit), and the fund's code refuses any decision from that key. The agent publishes each list snapshot it uses (list, date and SHA-256) so anyone can check it against the official file. The administrator and the reviewer together are the valuation oracle. Every decision is recorded with its signer and block height."},
	{"14. Confidentiality", "Direct holders: compliance decisions are public transactions that name the wallet; the fund stores only each wallet's latest status (eligible or not, until when, restricted or not) with a salted commitment to the off-chain record. Reasons, scores and evidence stay off-chain, including the reason for a compulsory redemption. Wallets are pseudonymous, not anonymous. Nominee holders: no investor wallet appears in the register, and the fund refuses any compliance decision naming a sub-account the nominee has registered. Deposits and payments between wallets and the nominee are public, and privacy grows with the number of investors per period. Nominee holders trust the nominee and the reviewer to pay the right wallet, as with a custodian."},
	{"15. Restrictions", "A restricted holder's orders are held: not dealt and not refunded. The orders dealt in a period are fixed when settlement starts; a restriction placed after that holds the redemption, which is carried, and freezes the shares issued, which cannot be redeemed while the restriction lasts. Held orders count towards the limit of 200 open subscriptions and 200 open redemption requests."},
	{"16. Audit", "The fund's annual report is audited. The auditor records on-chain, once for each year, the SHA-256 of the signed report. It is due within 6 months of the year end: the portal shows each year as recorded, due or overdue, up to the year the fund closes."},
	{"17. Roles and two keys", "Roles are fixed for this version: manager, administrator, valuation reviewer, compliance officer and auditor. Role addresses are refused as investors; related wallets must be declared to the compliance officer. A proposal that needs two keys, including a nominee payment, is valid only in the period it is made. The manager never moves money or assets on his signature alone: every investment payment, receipt, suspension, compulsory redemption below the minimum and wind-down he starts needs the reviewer, and expenses are proposed by the administrator, not by him. The administrator withdraws an order only after its investor has asked for it on-chain. The nominee's operator cannot hold a fund role. Outside these rules, the code moves investor money only back to its owner or as this memorandum describes."},
	{"18. Contract notes and statements", "For every issue and cancellation of shares the fund's code writes a contract note at settlement: subscription, redemption, compulsory redemption, wind-down distribution, late recovery, cancellation without payment, and performance fee crystallised. Each note shows the date, the NAV per share, the shares, the gross value, the performance fee, the net amount and the holding after; a cancellation also shows the cost of the shares at average cost and the realised gain or loss. The cost of a holding is what was subscribed; a cancellation takes off its share of that cost, and a performance fee paid by cancelling shares leaves the cost unchanged. An annual statement per holder and year lists the notes, the totals and the holding at the year end. Notes cannot be altered and carry the block height. They are for information: tax treatment depends on the investor's country."},
}

func memorandumHash() string {
	var b []byte
	for _, s := range memorandum {
		b = append(b, s.Title...)
		b = append(b, 0)
		b = append(b, s.Body...)
		b = append(b, 0)
	}
	h := sha256.Sum256(b)
	return hex.EncodeToString(h[:])
}

// Package nominee is Charterbook's nominee: one register entry per
// pseudonymous sub-account, no investor wallet in the fund's register, and
// no compliance outcome on-chain (design note v3, section 2).
//
// TEST DEPLOYMENT: fictional nominee, test tokens without value. Not
// operated by any regulated firm. Unaudited code. Not an offer.
//
// Flow: an investor is screened and approved off-chain and receives a
// sub-account identifier privately. The investor deposits whole lots of
// tUSD here. Once the compliance officer has attested the period's batch,
// the operator places the sub-accounts' orders in the fund. Proceeds come
// back here; every payment to a wallet needs the operator and the fund's
// valuation reviewer.
package nominee

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"

	"gno.land/r/g1thug63es793ckaw63l2704qzp3a92y58kekda0/cbtrial1/fund"
	"gno.land/r/g1thug63es793ckaw63l2704qzp3a92y58kekda0/cbtrial1/tusd"
)

const (
	unit int64 = 1_000_000
	lot  int64 = 10_000 * unit
)

var (
	token    *grc20.Token
	selfPath string
	deployer address
	operator address

	attested       = avl.NewTree() // padded period -> *attestation (latest)
	attestLog      = avl.NewTree() // seq -> *attestation
	payments       = avl.NewTree() // id -> *payment
	trail          = avl.NewTree() // seq -> string
	deposits       int64           // number of deposits received
	depositLots    int64
	paidTotal      int64
	nextPay        int64
	trailSeq       int64
	attestSeq      int64
	recommended    int64           // batches the agent screened
	recommendedFor = avl.NewTree() // padded period -> true: the agent screened that period's batch
)

type attestation struct {
	period     int64
	commitment string
	height     int64
	screened   bool
}

type payment struct {
	id     int64
	period int64 // approval only in the fund period it was proposed in
	to     address
	amount int64
	paid   bool
	closed bool
}

func init(cur realm) {
	token = grc20reg.MustGet(tusd.TokenKey())
	selfPath = cur.PkgPath()
	deployer = cur.Previous().Address()
}

// ConfirmWithFund tells the fund, from this realm's own code, that the
// nominee is deployed at the registered path. Deployer only, before the
// fund's Launch.
func ConfirmWithFund(cur realm) {
	assertMasterKey()
	if cur.Previous().Address() != deployer {
		panic("deployer only")
	}
	fund.ConfirmNominee(cross(cur))
}

// SetOperator names the nominee operator. Deployer only, once, after the
// fund has launched, so the fund's roles are fixed and can be checked
// (review 2, I5).
func SetOperator(cur realm, op address) {
	assertMasterKey()
	if cur.Previous().Address() != deployer {
		panic("deployer only")
	}
	if operator != "" {
		panic("operator already set")
	}
	if !fund.Launched() {
		panic("set the operator after the fund has launched")
	}
	if !op.IsValid() || op == deployer || op == Address() {
		panic("invalid operator address")
	}
	if fund.IsRoleOrFundAccount(op) { // all five roles, the deployer, the fund accounts
		panic("the operator cannot hold a fund role")
	}
	operator = op
	addTrail("deployer", "Nominee operator set.")
}

// Address is the nominee's own account, which holds the pool.
func Address() address { return chain.PackageAddress(selfPath) }

// Balance is the pool: deposits not yet placed, plus proceeds not yet paid.
func Balance() int64 { return tusd.BalanceOf(Address()) }

// ---- investors ----

// Deposit moves `lots` whole lots of tUSD from the caller into the pool.
// First Approve the nominee's address on tUSD. The transaction is public;
// nothing here links the wallet to a sub-account.
func Deposit(cur realm, lots int64) {
	if lots < 1 || lots > 1_000 {
		panic("lots must be 1 to 1,000")
	}
	amount := lots * lot
	w := cur.Previous().Address()
	if w == Address() {
		panic("invalid depositor")
	}
	if _, closedToSubs, windingDown, closed := fund.Status(); closedToSubs || windingDown || closed {
		panic("the fund is not taking subscriptions")
	}
	deposits++
	depositLots += lots
	if err := token.RealmTeller(0, cur).TransferFrom(0, cur, w, Address(), amount); err != nil {
		panic(err.Error())
	}
	addTrail("investor", ufmt.Sprintf("Deposit received: %d lot(s).", lots))
}

// ---- screening agent and compliance officer ----

// RecommendBatch records that the screening agent screened this period's
// batch (salted commitment). Agent session only.
func RecommendBatch(cur realm, period int64, commitment string) {
	fund.CheckAgent(cur.Previous().Address())
	checkHex(commitment)
	n, _ := fund.CurrentPeriod()
	if period != n {
		panic("not the current period")
	}
	recommended++
	recommendedFor.Set(pad(period), true) // kept for the officer's attestation (review 2, I7)
	if v := attested.Get(pad(period)); v != nil {
		v.(*attestation).screened = true
	}
	addTrail("screening agent", ufmt.Sprintf("Batch for period %d screened.", period))
}

// AttestBatch is the compliance officer's statement that every sub-account
// in this period's batch was screened and approved. The commitment is a
// salted SHA-256 of the batch and the list snapshots used. Officer only.
func AttestBatch(cur realm, period int64, commitment string) {
	assertMasterKey()
	_, _, _, off := fund.Roles()
	if cur.Previous().Address() != off {
		panic("compliance officer only")
	}
	checkHex(commitment)
	n, open := fund.CurrentPeriod()
	if period != n || !open {
		panic("the batch must be for the current, open period")
	}
	a := &attestation{period: period, commitment: commitment, height: runtime.ChainHeight(), screened: recommendedFor.Has(pad(period))}
	attested.Set(pad(period), a)
	attestSeq++
	attestLog.Set(pad(attestSeq), a)
	addTrail("compliance", ufmt.Sprintf("Batch for period %d attested: %s.", period, commitment))
}

// ---- operator: orders in the fund ----

func onlyOperator(cur realm) {
	assertMasterKey()
	if operator == "" || cur.Previous().Address() != operator {
		panic("nominee operator only")
	}
}

func requireAttested() {
	n, _ := fund.CurrentPeriod()
	if !attested.Has(pad(n)) {
		panic("no compliance attestation for this period's batch")
	}
}

// PlaceSubscription subscribes amount tUSD from the pool for sub-account
// sub. Needs the officer's attestation for the current period.
func PlaceSubscription(cur realm, sub string, amount int64) int64 {
	onlyOperator(cur)
	checkHex(sub)
	requireAttested()
	if amount <= 0 || amount > Balance() {
		panic("amount must be positive and within the pool")
	}
	tusd.Approve(cross(cur), fund.Address(), amount)
	id := fund.SubscribeFor(cross(cur), sub, amount)
	addTrail("operator", ufmt.Sprintf("Subscription #%d placed in the fund.", id))
	return id
}

// PlaceRedemption asks the fund to redeem `lots` lots (0 = all) for
// sub-account sub. Proceeds come back to the pool. Needs the officer's
// attestation for the current period, like a subscription.
func PlaceRedemption(cur realm, sub string, lots int64) int64 {
	onlyOperator(cur)
	checkHex(sub)
	requireAttested()
	id := fund.RequestRedemptionFor(cross(cur), sub, lots)
	addTrail("operator", ufmt.Sprintf("Redemption request #%d placed in the fund.", id))
	return id
}

// RegisterSubAccount records sub-account `sub` in the fund before its
// identifier is handed to the investor, so the fund can refuse any
// compliance decision naming it. Operator only.
func RegisterSubAccount(cur realm, sub string) {
	onlyOperator(cur)
	checkHex(sub)
	fund.RegisterSubAccountFor(cross(cur), sub)
	addTrail("operator", "A sub-account was registered.")
}

// AskToWithdraw asks the fund to withdraw sub-account sub's open order at
// the investor's request; the fund's administrator then withdraws it.
func AskToWithdraw(cur realm, sub string) {
	onlyOperator(cur)
	checkHex(sub)
	fund.AskToWithdrawFor(cross(cur), sub)
	addTrail("operator", "Withdrawal of an order requested.")
}

// CancelOrder takes sub-account sub's subscription back out of escrow in a
// period the fund has left stalled for 7 days (a safety valve: no
// attestation needed).
func CancelOrder(cur realm, sub string) {
	onlyOperator(cur)
	checkHex(sub)
	fund.CancelFor(cross(cur), sub)
	addTrail("operator", "An order was cancelled.")
}

// ---- payments: operator proposes, the fund's reviewer countersigns ----

// ProposePayment proposes to pay amount tUSD from the pool to wallet `to`:
// redemption proceeds, or a refund of a deposit. Operator only.
func ProposePayment(cur realm, to address, amount int64) int64 {
	onlyOperator(cur)
	if !to.IsValid() || to == Address() {
		panic("invalid recipient")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	nextPay++
	n, _ := fund.CurrentPeriod()
	payments.Set(pad(nextPay), &payment{id: nextPay, period: n, to: to, amount: amount})
	addTrail("operator", ufmt.Sprintf("Payment #%d proposed: %s tUSD.", nextPay, fmtAmt(amount)))
	return nextPay
}

// ApprovePayment countersigns and makes a payment. The fund's valuation
// reviewer only.
func ApprovePayment(cur realm, id int64) {
	assertMasterKey()
	_, _, rev, _ := fund.Roles()
	if cur.Previous().Address() != rev {
		panic("valuation reviewer only")
	}
	p := getPayment(id)
	if p.paid || p.closed {
		panic("payment is closed")
	}
	if n, _ := fund.CurrentPeriod(); n != p.period {
		panic("the payment was proposed in an earlier period; propose it again")
	}
	if p.amount > Balance() {
		panic("the pool does not hold this amount")
	}
	p.paid = true
	paidTotal += p.amount
	tusd.Transfer(cross(cur), p.to, p.amount)
	addTrail("reviewer", ufmt.Sprintf("Payment #%d countersigned and made: %s tUSD.", id, fmtAmt(p.amount)))
}

// CancelPayment withdraws (operator) or declines (reviewer) a payment.
func CancelPayment(cur realm, id int64) {
	assertMasterKey()
	_, _, rev, _ := fund.Roles()
	c := cur.Previous().Address()
	if c != operator && c != rev {
		panic("nominee operator or valuation reviewer only")
	}
	p := getPayment(id)
	if p.paid || p.closed {
		panic("payment is closed")
	}
	p.closed = true
	addTrail("nominee", ufmt.Sprintf("Payment #%d cancelled.", id))
}

func getPayment(id int64) *payment {
	v := payments.Get(pad(id))
	if v == nil {
		panic("unknown payment")
	}
	return v.(*payment)
}

// ---- page ----

const banner = "> **Test deployment on the Onyx testnet.** Fictional nominee, test tokens without value. Not operated by any regulated firm. Unaudited code. Not an offer.\n\n"

// Render shows totals only: no wallet, no sub-account, no payment recipient.
func Render(path string) string {
	parts := strings.Split(path, "/")
	page := 1
	if len(parts) == 2 && parts[0] == "trail" {
		n, err := strconv.Atoi(parts[1])
		if err != nil || n < 1 {
			return "invalid page"
		}
		page = n
	} else if path != "" && path != "trail" {
		return "404"
	}
	var b strings.Builder
	home := strings.TrimPrefix(selfPath, "gno.land")
	fh := strings.TrimPrefix(fund.Path(), "gno.land")
	b.WriteString("# Charterbook nominee\n\n" + banner)
	b.WriteString("[Nominee](" + home + ") · [Nominee trail](" + home + ":trail) · [The fund](" + fh + ")\n\n")
	if parts[0] == "trail" {
		pages := int((trailSeq + 19) / 20)
		if pages == 0 {
			pages = 1
		}
		if page > pages {
			return "invalid page"
		}
		b.WriteString(ufmt.Sprintf("Newest first. Page %d of %d.\n\n| # | Event |\n|---:|---|\n", page, pages))
		trail.ReverseIterateByOffset((page-1)*20, 20, func(k string, v any) bool {
			b.WriteString("| " + strings.TrimLeft(k, "0") + " | " + sanitize.TableCell(v.(string)) + " |\n")
			return false
		})
		if page < pages {
			b.WriteString(ufmt.Sprintf("\n[Older](%s:trail/%d)", home, page+1))
		}
		return b.String()
	}
	accounts, shares := fund.NomineeTotals()
	b.WriteString("Investors hold fund shares here through pseudonymous sub-accounts. The fund applies all its rules to each sub-account. No investor wallet appears in the fund's register and no compliance outcome is published. Deposits and payments between wallets and this nominee are public; privacy grows with the number of investors per period. Investors trust the operator and the fund's reviewer to pay the right wallet, as with a custodian.\n\n")
	b.WriteString(ufmt.Sprintf("- Pool: %s tUSD (deposits not yet placed, and proceeds not yet paid)\n", fmtAmt(Balance())))
	b.WriteString(ufmt.Sprintf("- Sub-accounts holding shares: %d · shares: %s\n", accounts, fmtAmt(shares)))
	b.WriteString(ufmt.Sprintf("- Deposits received: %d (%d lots) · payments made: %s tUSD\n", deposits, depositLots, fmtAmt(paidTotal)))
	b.WriteString("- Operator: " + addrOr(operator) + "\n\n")
	b.WriteString("## Compliance attestations\n\nEach is the compliance officer's statement that every sub-account in that period's batch was screened against the public sanctions lists and approved. The commitment covers the batch and the list snapshots used.\n\n| Period | Commitment | Agent screening on file | Height |\n|---:|---|---|---:|\n")
	attestLog.ReverseIterateByOffset(0, 12, func(_ string, v any) bool {
		a := v.(*attestation)
		scr := "no"
		if a.screened {
			scr = "yes"
		}
		b.WriteString(ufmt.Sprintf("| %d | `%s` | %s | %d |\n", a.period, a.commitment, scr, a.height))
		return false
	})
	b.WriteString("\n## Deposit\n\nApprove this nominee's address `" + Address().String() + "` on Test Dollar, then [deposit one lot](" + home + "$help&func=Deposit&lots=1).\n")
	return b.String()
}

// ---- helpers ----

func assertMasterKey() {
	if _, _, _, isSession := runtime.GetSessionInfo(); isSession {
		panic("master key required: session keys are refused")
	}
}

func addTrail(role, text string) {
	trailSeq++
	trail.Set(pad(trailSeq), role+": "+text)
	chain.Emit("CharterbookNominee", "role", role, "text", text)
}

func checkHex(c string) {
	if len(c) != 64 {
		panic("identifier must be a 64-character hex SHA-256")
	}
	for _, r := range c {
		if !(r >= '0' && r <= '9' || r >= 'a' && r <= 'f') {
			panic("identifier must be lowercase hex")
		}
	}
}

func pad(n int64) string {
	s := ufmt.Sprintf("%d", n)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func fmtAmt(v int64) string {
	f := ufmt.Sprintf("%d", v%unit)
	for len(f) < 6 {
		f = "0" + f
	}
	return ufmt.Sprintf("%d", v/unit) + "." + f
}

func addrOr(a address) string {
	if a == "" {
		return "not set"
	}
	return "`" + a.String() + "`"
}

package taproom

// Leaderboards: net coins, sharpest guesses, longest streak, points and style. Stats are kept on
// each Player, and each board is a short sorted list of its top rows (boardTop), updated whenever
// a listed stat moves.

import (
	"strconv"
	"strings"
)

const (
	maxBoardRows = 50
	boardCount   = 5
)

// boards in display order: key, title, column heading.
var boards = [boardCount][3]string{
	{"points", "Points", "Lifetime points"},
	{"net", "Net coins", "Net GNOT"},
	{"sharp", "Sharpest guesses", "Avg distance"},
	{"streak", "Longest streak", "Weeks"},
	{"style", "Style", "Style score"},
}

type boardRow struct {
	addr address
	p    *Player
}

// styleOf sums rarity values of equipped items: common 1, rare 3, epic 6, legendary 10.
func styleOf(equipped [4]int) int64 {
	var s int64
	for _, id := range equipped {
		switch itemPrice(id) {
		case 40:
			s += 1
		case 150:
			s += 3
		case 400:
			s += 6
		case 1000:
			s += 10
		}
	}
	return s
}

// sharp100 is the average distance to the target in hundredths; -1 before any completed round.
func sharp100(p *Player) int64 {
	if p.Scored == 0 {
		return -1
	}
	return p.DistSum100 / p.Scored
}

// boardRank is one row of a board's top list: the player and the value they are ranked by.
type boardRank struct {
	Addr address
	V    int64
}

// boardTop holds each board's top maxBoardRows rows, best first. A short list instead of an index
// over every player: an update rewrites one list, which stops growing once it is full, so a
// player's first join adds little storage however many players there are. A listed player whose
// value falls below every other row of a full list leaves it; the free row goes to the next
// player whose stats change, so the rows near the bottom can lag until then.
var boardTop [boardCount][]boardRank

// boardValue is what a player is ranked by on board i. ok is false when the player is not listed:
// before their first Join, or on Sharpest guesses before a completed round.
func boardValue(i int, p *Player) (v int64, ok bool) {
	if !p.Joined {
		return 0, false
	}
	switch boards[i][0] {
	case "points":
		return p.Lifetime, true
	case "net":
		return p.Net, true
	case "sharp":
		if p.Scored == 0 {
			return 0, false
		}
		return sharp100(p), true
	case "streak":
		return p.BestStreak, true
	}
	return styleOf(p.Equipped), true
}

// ahead reports whether row x ranks above row y on board i: a better value (lower is better only
// for Sharpest guesses), then the lower address.
func ahead(i int, x, y boardRank) bool {
	if x.V != y.V {
		if boards[i][0] == "sharp" {
			return x.V < y.V
		}
		return x.V > y.V
	}
	return x.Addr < y.Addr
}

// reindex moves a player's rows on the boards after their stats change.
func reindex(a address) {
	p := getPlayer(a)
	for i := 0; i < boardCount; i++ {
		v, ok := boardValue(i, p)
		list := boardTop[i]
		pos := -1
		for j, r := range list {
			if r.Addr == a {
				pos = j
				break
			}
		}
		if pos >= 0 && ok && list[pos].V == v {
			continue // already listed at this value
		}
		full := len(list) >= maxBoardRows
		changed := false
		if pos >= 0 {
			list = append(list[:pos], list[pos+1:]...)
			changed = true
		}
		if ok {
			row := boardRank{Addr: a, V: v}
			j := 0
			for j < len(list) && ahead(i, list[j], row) {
				j++
			}
			// last place on a list that was full: an unlisted player may rank higher, so leave
			if j < maxBoardRows && !(pos >= 0 && full && j == len(list)) {
				list = append(list, boardRank{})
				copy(list[j+1:], list[j:])
				list[j] = row
				if len(list) > maxBoardRows {
					list = list[:maxBoardRows]
				}
				changed = true
			}
		}
		if changed {
			boardTop[i] = list
		}
	}
}

// board returns the top rows of a board, best first.
func board(name string, limit int) []boardRow {
	idx := -1
	for i, b := range boards {
		if b[0] == name {
			idx = i
		}
	}
	if idx < 0 {
		panic("unknown board: use points, net, sharp, streak or style")
	}
	if limit <= 0 || limit > maxBoardRows {
		limit = maxBoardRows
	}
	var rows []boardRow
	for _, r := range boardTop[idx] {
		if len(rows) >= limit {
			break
		}
		rows = append(rows, boardRow{addr: r.Addr, p: players.Get(r.Addr.String()).(*Player)})
	}
	return rows
}

// LeaderboardJSON returns the top rows (at most 50) of a board: points, net, sharp, streak or style.
// Each row carries every stat, so one call can fill any column.
func LeaderboardJSON(name string, limit int) string {
	var sb strings.Builder
	sb.WriteString("[")
	for i, r := range board(name, limit) {
		if i > 0 {
			sb.WriteString(",")
		}
		sharp := "null"
		if s := sharp100(r.p); s >= 0 {
			sharp = i64(s)
		}
		sb.WriteString(`{"rank":` + strconv.Itoa(i+1) + `,"addr":"` + r.addr.String() + `","points":` + i64(r.p.Lifetime))
		sb.WriteString(`,"net":` + i64(r.p.Net) + `,"wins":` + i64(r.p.Wins) + `,"sharp100":` + sharp)
		sb.WriteString(`,"bestStreak":` + i64(r.p.BestStreak) + `,"style":` + i64(styleOf(r.p.Equipped)) + `,"equipped":`)
		writeInts(&sb, r.p.Equipped[:])
		sb.WriteString("}")
	}
	sb.WriteString("]")
	return sb.String()
}

package taproom

// Render pages for gnoweb. Avatars are SVG data URIs from the avatar package, which gnoweb
// allows in markdown images. Paths: "" (home), "board/<name>", "player/<address>", "round/<id>".
// Action links (txlink) open gnoweb's call form with the round and amount filled in, so the game
// can be played from gnoweb with Adena and no other site.

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1vxsg6ht4nklaud70yaszcgkhc9ttancr9nlzzq/avatar/v0"
	"gno.land/p/moul/txlink/v0"
)

// boardPageRows caps a board page: each avatar costs about 100M gas, and a Render query may use 3B.
const boardPageRows = 10

var rankNames = []string{"Newcomer", "Regular", "Sharp", "Oracle", "Legend"}
var rankAt = []int64{0, 100, 500, 1500, 4000}

func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	switch {
	case path == "":
		return renderHome()
	case len(parts) == 2 && parts[0] == "board":
		return renderBoard(parts[1])
	case len(parts) == 2 && parts[0] == "player":
		return renderPlayer(address(parts[1]))
	case len(parts) == 2 && parts[0] == "round":
		if id, err := strconv.Atoi(parts[1]); err == nil && id >= 0 && id < roundCount {
			return renderRound(getRound(id))
		}
	}
	return "# Not found\n\nNo such page. [Back to the taproom](" + link("") + ")\n"
}

func renderHome() string {
	var sb strings.Builder
	t := now()
	sb.WriteString("# Taproom\n\nA tavern of short mind games. Seal a number from 0 to 100; the pick closest to two thirds of the crowd's average takes the pot. 1 GNOT a seat, 0.5% to the tavern on completed rounds.\n\n")

	sb.WriteString("## Open tables\n\n")
	open := 0
	openRounds.ReverseIterate("", "", func(k string, _ any) bool {
		id, _ := strconv.Atoi(k)
		r := getRound(id)
		open++
		sb.WriteString("- [Round " + strconv.Itoa(r.ID) + "](" + link("round/"+strconv.Itoa(r.ID)) + "): " +
			strconv.Itoa(r.Seal.Count()) + " of " + strconv.Itoa(maxPlayers) + " seats, pot " + gnot(r.Pot) + ", " + phaseLine(r, t) + "\n")
		return open >= 10
	})
	if open == 0 {
		sb.WriteString("No open tables right now.\n")
	}
	sb.WriteString("\nOpen a table (Oak, free): " +
		action("Quick, 2 + 2 min", txlink.NewLink("NewRound").AddArgs("commitSecs", "120", "revealSecs", "120", "boardSkin", "0")) + " · " +
		action("Standard, 30 + 30 min", txlink.NewLink("NewRound").AddArgs("commitSecs", "1800", "revealSecs", "1800", "boardSkin", "0")) + " · " +
		action("Daily, 12 + 12 h", txlink.NewLink("NewRound").AddArgs("commitSecs", "43200", "revealSecs", "43200", "boardSkin", "0")) + "\n")

	sb.WriteString("\n## Recent results\n\n")
	shown := 0
	for i := len(recentSettled) - 1; i >= 0; i-- {
		r := getRound(recentSettled[i])
		shown++
		sb.WriteString("- [Round " + strconv.Itoa(r.ID) + "](" + link("round/"+strconv.Itoa(r.ID)) + "): " + resultLine(r) + "\n")
	}
	if shown == 0 {
		sb.WriteString("No completed rounds yet.\n")
	}

	sb.WriteString("\n## Leaderboards\n\n")
	writeBoardTable(&sb, "points", 5)
	sb.WriteString("\nAll boards:")
	for i, b := range boards {
		if i > 0 {
			sb.WriteString(" ·")
		}
		sb.WriteString(" [" + b[1] + "](" + link("board/"+b[0]) + ")")
	}
	sb.WriteString("\n")
	return sb.String()
}

func renderBoard(name string) string {
	for _, b := range boards {
		if b[0] == name {
			var sb strings.Builder
			sb.WriteString("# " + b[1] + "\n\n")
			writeBoardTable(&sb, name, boardPageRows)
			sb.WriteString("\n[Back to the taproom](" + link("") + ")\n")
			return sb.String()
		}
	}
	// the name comes from the URL, so it is not echoed back into the page
	return "# Not found\n\nNo such board: use points, net, sharp, streak or style. [Back to the taproom](" + link("") + ")\n"
}

func writeBoardTable(sb *strings.Builder, name string, limit int) {
	var col string
	for _, b := range boards {
		if b[0] == name {
			col = b[2]
		}
	}
	rows := board(name, limit)
	if len(rows) == 0 {
		sb.WriteString("Nobody on this board yet.\n")
		return
	}
	sb.WriteString("| # | | Regular | " + col + " |\n|---|---|---|---|\n")
	for i, r := range rows {
		var v string
		switch name {
		case "points":
			v = i64(r.p.Lifetime)
		case "net":
			v = gnot(r.p.Net)
		case "sharp":
			v = hundredths(sharp100(r.p))
		case "streak":
			v = i64(r.p.BestStreak)
		case "style":
			v = i64(styleOf(r.p.Equipped))
		}
		sb.WriteString("| " + strconv.Itoa(i+1) + " | " + gnome(r.addr, r.p.Equipped) + " | [" + short(r.addr) + "](" + link("player/"+r.addr.String()) + ") | " + v + " |\n")
	}
}

func renderPlayer(a address) string {
	v := players.Get(a.String())
	if v == nil {
		return "# Not found\n\nThis address has not played yet. [Back to the taproom](" + link("") + ")\n"
	}
	p := v.(*Player)
	rank := 0
	for i, at := range rankAt {
		if p.Lifetime >= at {
			rank = i
		}
	}
	var sb strings.Builder
	sb.WriteString("# Regular " + short(a) + "\n\n" + gnome(a, p.Equipped) + "\n\n")
	sb.WriteString("- Rank: " + rankNames[rank] + "\n")
	sb.WriteString("- Points: " + i64(p.Lifetime) + " lifetime, " + i64(p.Lifetime-p.Spent) + " to spend\n")
	sb.WriteString("- Weekly streak: " + i64(p.Streak) + " (best " + i64(p.BestStreak) + "), freezes held: " + strconv.Itoa(p.Freezes) + "\n")
	sb.WriteString("- Wins: " + i64(p.Wins) + "\n")
	sb.WriteString("- Net coins: " + gnot(p.Net) + "\n")
	if p.Scored > 0 {
		sb.WriteString("- Average distance to the target: " + hundredths(sharp100(p)) + " over " + i64(p.Scored) + plural(p.Scored, " round", " rounds") + "\n")
	}
	sb.WriteString("- Style score: " + i64(styleOf(p.Equipped)) + "\n")
	if c := Claimable(a); c > 0 {
		sb.WriteString("\n" + gnot(c) + " to claim: " + action("Claim", txlink.NewLink("Claim")) + " (signed by this address)\n")
	}
	sb.WriteString("\n[Back to the taproom](" + link("") + ")\n")
	return sb.String()
}

func renderRound(r *Round) string {
	var sb strings.Builder
	t := now()
	sb.WriteString("# Round " + strconv.Itoa(r.ID) + "\n\n")
	sb.WriteString(strconv.Itoa(r.Seal.Count()) + " of " + strconv.Itoa(maxPlayers) + " seats, pot " + gnot(r.Pot) + ", " + phaseLine(r, t) + ".\n\n")
	if r.Settled {
		sb.WriteString(resultLine(r) + "\n\n")
		if len(r.Winners) > 0 {
			sum, n := revealedSum(r)
			sb.WriteString("Target: " + hundredths(round2(r.Num*sum*100, r.Den*n)) + " (2/3 of the average " + hundredths(round2(sum*100, n)) + ")\n\n")
		}
	}
	sb.WriteString("| | Regular | Pick | Status |\n|---|---|---|---|\n")
	for _, p := range r.Seal.Players() {
		pick, status := "sealed", "sealed"
		if r.Seal.IsRevealed(p) {
			pick = i64(r.Seats[seatOf(r, p)].Pick)
			status = "revealed"
		}
		if r.Settled {
			switch {
			case isWinner(r, p):
				status = "winner"
			case len(r.Winners) == 0:
				status = "refunded"
			case status == "sealed":
				status = "forfeit"
				pick = "not revealed"
			}
		}
		var equipped [4]int
		if v := players.Get(p.String()); v != nil {
			equipped = v.(*Player).Equipped
		}
		sb.WriteString("| " + gnome(p, equipped) + " | [" + short(p) + "](" + link("player/"+p.String()) + ") | " + pick + " | " + status + " |\n")
	}
	sb.WriteString("\n" + roundActions(r, t) + "\n[Back to the taproom](" + link("") + ")\n")
	return sb.String()
}

// roundActions is what anyone can do at this table now, as gnoweb call links.
func roundActions(r *Round, t int64) string {
	id := strconv.Itoa(r.ID)
	switch {
	case r.Settled:
		return "Winners and refunded players: " + action("Claim", txlink.NewLink("Claim")) + "\n"
	case t < r.Seal.CommitEnd:
		if r.Seal.Count() >= maxPlayers {
			return "The table is full.\n"
		}
		return "Take a seat: " + action("Join for 1 GNOT", txlink.NewLink("Join").AddArgs("roundID", id, "commit", "").SetSend("1000000ugnot")) +
			". The commit is `CommitHash(" + id + ", <your address>, <pick>, <salt>)` from this realm's " +
			"[functions page](" + link("") + "$help); pick 0 to 100, salt 16 to 128 characters. Keep both: you need them to reveal.\n"
	case t < r.Seal.RevealEnd:
		return "Seated players: " + action("Reveal", txlink.NewLink("Reveal").AddArgs("roundID", id, "pick", "", "salt", "")) +
			" with the pick and salt you sealed. A seat that does not reveal forfeits its 1 GNOT.\n"
	}
	return "Anyone can " + action("Settle", txlink.NewLink("Settle").AddArgs("roundID", id)) + " this round now.\n"
}

// ---------- helpers ----------

func action(label string, b *txlink.TxBuilder) string {
	return "[" + label + "](" + b.URL() + ")"
}

func phaseLine(r *Round, t int64) string {
	if r.Settled {
		return "settled"
	}
	switch {
	case t < r.Seal.CommitEnd:
		return "sealing until " + clock(r.Seal.CommitEnd)
	case t < r.Seal.RevealEnd:
		return "revealing until " + clock(r.Seal.RevealEnd)
	}
	return "ready to settle (anyone can settle)"
}

func resultLine(r *Round) string {
	if len(r.Winners) == 0 {
		return "cancelled, fewer than 2 revealed; everyone refunded, no fee"
	}
	var names []string
	for _, w := range r.Winners {
		names = append(names, "["+short(w)+"]("+link("player/"+w.String())+") with "+i64(r.Seats[seatOf(r, w)].Pick))
	}
	return "won by " + strings.Join(names, " and ") + ", pot " + gnot(r.Pot) + ", fee " + gnot(r.Fee)
}

func revealedSum(r *Round) (sum, n int64) {
	for _, o := range r.Seal.Revealed() {
		sum += r.Seats[seatOf(r, o.Who)].Pick
		n++
	}
	return sum, n
}

func isWinner(r *Round, a address) bool {
	for _, w := range r.Winners {
		if w == a {
			return true
		}
	}
	return false
}

func gnome(a address, equipped [4]int) string {
	return "![gnome](" + avatar.DataURI(a, equipped) + ")"
}

// link points at a page of this realm in gnoweb.
func link(sub string) string {
	p := "/" + strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), "gno.land/")
	if sub == "" {
		return p
	}
	return p + ":" + sub
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

// gnot formats ugnot as GNOT without trailing zeros: 2985000 -> "2.985 GNOT".
func gnot(u int64) string {
	sign := ""
	if u < 0 {
		sign, u = "-", -u
	}
	s := sign + i64(u/1000000)
	if frac := u % 1000000; frac != 0 {
		f := strconv.FormatInt(frac+1000000, 10)[1:]
		s += "." + strings.TrimRight(f, "0")
	}
	return s + " GNOT"
}

// round2 divides num by den rounded to the nearest integer (both positive).
func round2(num, den int64) int64 {
	if den == 0 {
		return 0
	}
	return (num*10/den + 5) / 10
}

// hundredths formats 1778 as "17.78".
func hundredths(h int64) string {
	if h < 0 {
		return "-"
	}
	f := strconv.FormatInt(h%100+100, 10)[1:]
	return i64(h/100) + "." + f
}

func clock(ts int64) string {
	return time.Unix(ts, 0).UTC().Format("Jan 2 15:04 UTC")
}

func plural(n int64, one, many string) string {
	if n == 1 {
		return one
	}
	return many
}

package taproom

// Taproom realm: 2/3 Game round engine with stakes, permissionless settlement, pull payouts,
// and a time-window weekly streak. The commit-reveal lifecycle of each round (windows, sealed
// picks, reveals, who did not reveal) runs on the commitreveal package.

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1vxsg6ht4nklaud70yaszcgkhc9ttancr9nlzzq/commitreveal/v0"
	"gno.land/p/nt/avl/v0"
)

const (
	denom       = "ugnot"
	weekSeconds = int64(604800)
	// Unix time zero fell on a Thursday; 4 days shifts week boundaries to Monday 00:00 UTC.
	weekOffset = int64(345600)

	pointsPlay = int64(10)
	pointsWin  = int64(30)
	streakStep = int64(4)
	streakCap  = int64(20)
	freezeCost = int64(40)
	maxFreezes = 2

	// Caps: players per round, open rounds per creator, window bounds.
	maxPlayers    = 10
	maxOpenRounds = 3
	minWindow     = int64(60)
	maxWindow     = int64(86400)

	// Cosmetic slots: hat, outfit, held item, companion (Player.Equipped order).
	slotCount = 4

	// Board skins: 0 = Oak table (free, owned by everyone), 1 = Moonlit, 2 = Gold-trim.
	skinCount = 3

	// Target fraction of the average: fixed at 2/3 in the MVP, stored per round.
	entryFee = int64(1000000) // 1 GNOT per seat

	// Salts shorter than this let anyone guess a pick from its hash (there are only 101 picks).
	minSaltLen = 16
	maxSaltLen = 128 // salts are kept and shown in RoundJSON, so they stay short and printable

	targetNum = int64(2)
	targetDen = int64(3)

	// Protocol fee in basis points (50 = 0.5%), taken from the pot of a completed round only.
	feeBps   = int64(50)
	bpsTotal = int64(10000)
)

// skinPrice is the points price per board skin ID; Oak (0) is free.
var skinPrice = []int64{0, 150, 400}

var (
	feeRecipient address // set once at deploy; can only withdraw accrued fees
	feesAccrued  int64
)

func init() {
	feeRecipient = unsafe.OriginCaller()
}

// nowOverride lets tests control time; zero means use the block time.
var nowOverride int64

// Seat is one player's place at a round, in join order (the order of Seal.Players()). A short list
// per round instead of trees keyed by address: a round has at most maxPlayers seats.
type Seat struct {
	Commit string // the hash sealed at Join; kept for RoundJSON so anyone can re-check the reveal
	Pick   int64  // set at Reveal
	Salt   string // public once revealed
	Bonus  int64  // streak bonus earned at reveal; paid only if the round completes
}

type Round struct {
	ID        int
	Creator   address
	Start     int64
	Seal      *commitreveal.Session // windows, commits, reveals and join order
	Seats     []Seat                // one per player, in join order
	Settled   bool
	Pot       int64
	Fee       int64
	Winners   []address
	BoardSkin int
	Num, Den  int64 // target fraction of the average; 2/3 in the MVP
}

type Player struct {
	Lifetime  int64
	Spent     int64
	HasPlayed bool
	LastWeek  int64
	Streak    int64
	Freezes   int
	Skins     []int  // owned board skins other than the free Oak table
	Owned     []int  // cosmetic item IDs
	Equipped  [4]int // item ID per slot (hat, outfit, held, companion); 0 = nothing

	// Leaderboard stats, updated at Join and Settle.
	Net        int64 // ugnot credited minus entry fees paid
	Wins       int64 // completed rounds won (a split win counts)
	Scored     int64 // revealed picks in completed rounds
	DistSum100 int64 // sum of distances to the target in those rounds, in hundredths
	BestStreak int64 // longest weekly streak reached

	Joined bool // has joined a round; only such players are listed on boards
}

var (
	roundTree     = avl.NewTree() // roundKey(id) -> *Round
	roundCount    int
	openRounds    = avl.NewTree() // roundKey(id) -> true while the round is not settled
	openByCreator = avl.NewTree() // address -> int, open rounds per creator (the 3-round cap)
	recentSettled []int           // the last 5 completed round IDs, oldest first
	players       = avl.NewTree() // address -> *Player
	claimable     = avl.NewTree() // address -> int64
)

// roundKey pads round IDs so the tree keeps them in numeric order.
func roundKey(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func openCount(a address) int {
	if v := openByCreator.Get(a.String()); v != nil {
		return v.(int)
	}
	return 0
}

// visibleASCII reports whether s has only printable ASCII characters other than space.
func visibleASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] < 0x21 || s[i] > 0x7e {
			return false
		}
	}
	return true
}

func now() int64 {
	if nowOverride != 0 {
		return nowOverride
	}
	return time.Now().Unix()
}

// weekIndex returns the Monday-00:00-UTC-aligned week number of a Unix timestamp.
func weekIndex(ts int64) int64 {
	d := ts - weekOffset
	w := d / weekSeconds
	if d%weekSeconds < 0 {
		w--
	}
	return w
}

// CommitHash is the value a player submits when joining round roundID:
// hex(sha256("<roundID>:<player address>:<pick>:<salt>")). Binding the round and the player means
// a hash copied from someone else's Join cannot be opened by the copier, nor reused in another round.
func CommitHash(roundID int, player address, pick int64, salt string) string {
	return commitreveal.Hash(sealedValue(roundID, player, pick), salt)
}

// sealedValue is what a round's Seal commits to for a player's pick.
func sealedValue(roundID int, player address, pick int64) string {
	return strconv.Itoa(roundID) + ":" + player.String() + ":" + strconv.FormatInt(pick, 10)
}

// mustUser requires a direct wallet call that sends no coins: only Join takes a deposit, and coins
// sent with any other call would be stranded in the realm.
func mustUser(cur realm) address {
	a := mustUserCall(cur)
	noCoins()
	return a
}

func mustUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("direct user call required")
	}
	return cur.Previous().Address()
}

func noCoins() {
	if len(unsafe.OriginSend()) != 0 {
		panic("this call takes no coins")
	}
}

func getRound(id int) *Round {
	if id < 0 || id >= roundCount {
		panic("unknown round")
	}
	return roundTree.Get(roundKey(id)).(*Round)
}

// seatOf returns the index of a's seat in r (join order), or -1.
func seatOf(r *Round, a address) int {
	for i, p := range r.Seal.Players() {
		if p == a {
			return i
		}
	}
	return -1
}

func getPlayer(a address) *Player {
	v := players.Get(a.String())
	if v == nil {
		p := &Player{}
		players.Set(a.String(), p)
		return p
	}
	return v.(*Player)
}

func credit(a address, amt int64) {
	cur := int64(0)
	if v := claimable.Get(a.String()); v != nil {
		cur = v.(int64)
	}
	claimable.Set(a.String(), cur+amt)
	getPlayer(a).Net += amt
}

// ownsSkin reports whether a may use a board skin: Oak (0) is free for everyone.
func ownsSkin(a address, skin int) bool {
	if skin == 0 {
		return true
	}
	v := players.Get(a.String())
	if v == nil {
		return false
	}
	for _, s := range v.(*Player).Skins {
		if s == skin {
			return true
		}
	}
	return false
}

// NewRound opens a round. commitSecs and revealSecs are window lengths in seconds.
// The creator must own boardSkin (Oak table, ID 0, is owned by everyone).
func NewRound(cur realm, commitSecs, revealSecs int64, boardSkin int) int {
	creator := mustUser(cur)
	if commitSecs < minWindow || revealSecs < minWindow || commitSecs > maxWindow || revealSecs > maxWindow {
		panic("windows must be 1 minute to 24 hours")
	}
	if boardSkin < 0 || boardSkin >= skinCount {
		panic("unknown board skin")
	}
	if !ownsSkin(creator, boardSkin) {
		panic("creator does not own this board skin")
	}
	open := openCount(creator)
	if open >= maxOpenRounds {
		panic("you already have 3 open rounds")
	}
	t := now()
	r := &Round{
		ID:        roundCount,
		Creator:   creator,
		Start:     t,
		Seal:      commitreveal.New(t, commitSecs, revealSecs),
		BoardSkin: boardSkin,
		Num:       targetNum,
		Den:       targetDen,
	}
	roundTree.Set(roundKey(r.ID), r)
	roundCount++
	openRounds.Set(roundKey(r.ID), true)
	openByCreator.Set(creator.String(), open+1)
	return r.ID
}

// Join deposits the entry fee and stores a hidden pick.
func Join(cur realm, roundID int, commit string) {
	caller := mustUserCall(cur) // the one call that takes coins: exactly the entry fee, checked below
	r := getRound(roundID)
	t := now()
	if r.Seal.Phase(t) != commitreveal.CommitPhase {
		panic("commit window closed")
	}
	if r.Seal.Has(caller) {
		panic("already joined")
	}
	if r.Seal.Count() >= maxPlayers {
		panic("round is full")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount != entryFee {
		panic("must send exactly the entry fee in ugnot")
	}
	if commit != strings.ToLower(commit) {
		panic("commit must be lowercase hex") // Reveal compares against lowercase sha256 hex
	}
	if err := r.Seal.Commit(t, caller, commit); err != nil {
		panic(err.Error())
	}
	r.Seats = append(r.Seats, Seat{Commit: commit})
	r.Pot += entryFee
	pl := getPlayer(caller)
	pl.Net -= entryFee
	pl.Joined = true
	reindex(caller)
}

// Reveal opens the pick; it must match the commit. It moves the streak (in block-time order)
// and records the bonus; points are paid at Settle, and only if the round completes.
func Reveal(cur realm, roundID int, pick int64, salt string) {
	caller := mustUser(cur)
	r := getRound(roundID)
	t := now()
	if pick < 0 || pick > 100 {
		panic("pick must be 0..100")
	}
	if len(salt) < minSaltLen || len(salt) > maxSaltLen || !visibleASCII(salt) {
		panic("salt must be 16 to 128 visible ASCII characters")
	}
	if err := r.Seal.Reveal(t, caller, sealedValue(roundID, caller, pick), salt); err != nil {
		panic(err.Error())
	}
	i := seatOf(r, caller)
	r.Seats[i].Pick, r.Seats[i].Salt, r.Seats[i].Bonus = pick, salt, updateStreak(caller, t)
	reindex(caller)
}

// Settle can be called by anyone once the reveal window has closed, including other realms and
// scripts (a keeper or scheduler, for example): it reads no caller and pays the same whoever calls.
// It is the one write without mustUser. A wallet calling it directly must still send no coins.
func Settle(cur realm, roundID int) {
	if cur.Previous().IsUserCall() {
		noCoins()
	}
	r := getRound(roundID)
	if now() < r.Seal.RevealEnd {
		panic("reveal window still open")
	}
	if r.Settled {
		panic("already settled")
	}
	r.Settled = true // effects before any payout bookkeeping
	openRounds.Remove(roundKey(r.ID))
	openByCreator.Set(r.Creator.String(), openCount(r.Creator)-1)
	defer func() { // board positions move with the credits and points below
		for _, p := range r.Seal.Players() {
			reindex(p)
		}
	}()

	var revealers []address
	var sum int64
	for _, o := range r.Seal.Revealed() { // join order
		revealers = append(revealers, o.Who)
		sum += r.Seats[seatOf(r, o.Who)].Pick
	}
	n := int64(len(revealers))

	// Fewer than two reveals: void round, everyone is refunded. No points.
	if n < 2 {
		for _, p := range r.Seal.Players() {
			credit(p, entryFee)
		}
		return
	}

	// Completed round: every revealer gets play points plus the bonus recorded at reveal.
	for _, p := range revealers {
		getPlayer(p).Lifetime += pointsPlay + r.Seats[seatOf(r, p)].Bonus
	}

	// Winner is closest to num/den of the average: minimise |den*n*pick - num*sum| (integer math).
	best := int64(-1)
	var winners []address
	for _, p := range revealers {
		d := r.Den*n*r.Seats[seatOf(r, p)].Pick - r.Num*sum
		if d < 0 {
			d = -d
		}
		// distance to the target = d / (den*n); kept in hundredths for the Sharpest guesses board
		pl := getPlayer(p)
		pl.Scored++
		pl.DistSum100 += (d*200 + r.Den*n) / (2 * r.Den * n) // rounded to the nearest hundredth
		if best < 0 || d < best {
			best = d
			winners = []address{p}
		} else if d == best {
			winners = append(winners, p)
		}
	}

	// Completed round (at least two reveals): take the fee, split the rest.
	fee := r.Pot * feeBps / bpsTotal
	r.Fee = fee
	feesAccrued += fee
	prize := r.Pot - fee

	count := int64(len(winners))
	share := prize / count
	rem := prize - share*count
	for i, w := range winners {
		amt := share
		if i == 0 {
			amt += rem
		}
		credit(w, amt)
		getPlayer(w).Lifetime += pointsWin - pointsPlay
		getPlayer(w).Wins++
	}
	r.Winners = winners

	// Recent results list completed rounds only, so empty or void rounds cannot push them off.
	recentSettled = append(recentSettled, r.ID)
	if len(recentSettled) > 5 {
		recentSettled = recentSettled[len(recentSettled)-5:]
	}
}

// Claim pays out the caller's balance (pull payment).
func Claim(cur realm) {
	caller := mustUser(cur)
	v := claimable.Get(caller.String())
	if v == nil || v.(int64) <= 0 {
		panic("nothing to claim")
	}
	amt := v.(int64)
	claimable.Set(caller.String(), int64(0)) // effects before interaction
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin(denom, amt)))
}

// WithdrawFees sends accrued protocol fees to the fee recipient. It touches nothing else.
func WithdrawFees(cur realm) {
	caller := mustUser(cur)
	if caller != feeRecipient {
		panic("only the fee recipient can withdraw fees")
	}
	amt := feesAccrued
	if amt <= 0 {
		panic("no fees to withdraw")
	}
	feesAccrued = 0 // effects before interaction
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin(denom, amt)))
}

// updateStreak moves the weekly streak for a play at ts and returns that play's bonus.
// Calls arrive in block-time order because Reveal calls it.
func updateStreak(a address, ts int64) int64 {
	p := getPlayer(a)
	w := weekIndex(ts)
	if !p.HasPlayed {
		p.Streak = 1
		p.LastWeek = w
	} else {
		g := w - p.LastWeek
		if g >= 1 {
			if p.Streak == 0 {
				// the streak was already reset for missed weeks: start again, keep any freezes
				p.Streak = 1
			} else if g == 1 {
				p.Streak++
			} else {
				missed := int(g - 1)
				if p.Freezes >= missed {
					p.Freezes -= missed
					p.Streak++
				} else {
					// not enough freezes: the streak resets and every held freeze is used up
					p.Streak = 1
					p.Freezes = 0
				}
			}
			p.LastWeek = w
		}
	}
	if p.Streak > p.BestStreak {
		p.BestStreak = p.Streak
	}
	p.HasPlayed = true
	bonus := streakStep * p.Streak
	if bonus > streakCap {
		bonus = streakCap
	}
	return bonus
}

// applyMissedWeeks spends freezes on weeks already missed before week w, as the next Reveal would.
// With too few freezes the streak drops to 0 and every freeze is used up; the next play starts week 1.
func applyMissedWeeks(p *Player, w int64) {
	if !p.HasPlayed || p.Streak == 0 {
		return
	}
	missed := int(w - p.LastWeek - 1)
	if missed <= 0 {
		return
	}
	if p.Freezes >= missed {
		p.Freezes -= missed
	} else {
		p.Streak = 0
		p.Freezes = 0
	}
	p.LastWeek = w - 1
}

// BuyFreeze spends points on a streak freeze (max 2 held). Weeks already missed are applied first,
// so a new freeze cannot cover a past week and a stale count cannot block the purchase.
func BuyFreeze(cur realm) {
	caller := mustUser(cur)
	p := getPlayer(caller)
	applyMissedWeeks(p, weekIndex(now()))
	if p.Freezes >= maxFreezes {
		panic("freeze limit reached")
	}
	if p.Lifetime-p.Spent < freezeCost {
		panic("not enough points")
	}
	p.Spent += freezeCost
	p.Freezes++
}

// BuySkin spends points on a board skin (Moonlit or Gold-trim). Oak is free and always owned.
func BuySkin(cur realm, skin int) {
	caller := mustUser(cur)
	if skin <= 0 || skin >= skinCount {
		panic("unknown or free board skin")
	}
	if ownsSkin(caller, skin) {
		panic("skin already owned")
	}
	p := getPlayer(caller)
	price := skinPrice[skin]
	if p.Lifetime-p.Spent < price {
		panic("not enough points")
	}
	p.Spent += price
	p.Skins = append(p.Skins, skin)
}

// itemPrice returns the points price of a cosmetic item, or -1 for an unknown ID.
// itemID = slotBase + n with slotBase 100 hat, 200 outfit, 300 held, 400 companion and n = 1..12.
// Rarity by n: 1, 5, 6 common 40; 2, 7, 8 rare 150; 3, 9, 10 epic 400; 4, 11, 12 legendary 1000.
func itemPrice(id int) int64 {
	slot, n := id/100, id%100
	if slot < 1 || slot > slotCount || n < 1 || n > 12 {
		return -1
	}
	switch n {
	case 1, 5, 6:
		return 40
	case 2, 7, 8:
		return 150
	case 3, 9, 10:
		return 400
	}
	return 1000
}

func ownsItem(p *Player, id int) bool {
	for _, o := range p.Owned {
		if o == id {
			return true
		}
	}
	return false
}

// BuyItem spends points on a cosmetic item. Items cannot be traded and never affect outcomes.
func BuyItem(cur realm, itemID int) {
	caller := mustUser(cur)
	price := itemPrice(itemID)
	if price < 0 {
		panic("unknown item")
	}
	p := getPlayer(caller)
	if ownsItem(p, itemID) {
		panic("item already owned")
	}
	if p.Lifetime-p.Spent < price {
		panic("not enough points")
	}
	p.Spent += price
	p.Owned = append(p.Owned, itemID)
}

// Equip wears an owned item in its slot (0 hat, 1 outfit, 2 held, 3 companion); itemID 0 takes it off.
func Equip(cur realm, slot int, itemID int) {
	caller := mustUser(cur)
	if slot < 0 || slot >= slotCount {
		panic("unknown slot")
	}
	p := getPlayer(caller)
	if itemID != 0 {
		if !ownsItem(p, itemID) {
			panic("item not owned")
		}
		if itemID/100 != slot+1 {
			panic("item does not fit this slot")
		}
	}
	p.Equipped[slot] = itemID
	reindex(caller)
}

// Views (non-crossing)

func OwnsSkin(a address, skin int) bool { return ownsSkin(a, skin) }

func Claimable(a address) int64 {
	if v := claimable.Get(a.String()); v != nil {
		return v.(int64)
	}
	return 0
}

func PlayerStats(a address) (lifetime, spendable, streak int64, freezes int) {
	v := players.Get(a.String())
	if v == nil {
		return 0, 0, 0, 0
	}
	p := v.(*Player)
	return p.Lifetime, p.Lifetime - p.Spent, p.Streak, p.Freezes
}

package taproom

// Read-only views for the web UI, returned as compact JSON strings so a client can read them
// with one vm/qeval call. Addresses are bech32 and numbers are plain integers, so no escaping is needed.

import (
	"strconv"
	"strings"

	"gno.land/p/g1vxsg6ht4nklaud70yaszcgkhc9ttancr9nlzzq/avatar/v0"
)

func RoundCount() int { return roundCount }

// AvatarSVG draws a player's gnome wearing their equipped items (see the avatar package).
func AvatarSVG(a address) string {
	var equipped [4]int
	if v := players.Get(a.String()); v != nil {
		equipped = v.(*Player).Equipped
	}
	return avatar.Render(a, equipped)
}

func FeeRecipient() address { return feeRecipient }

func FeesAccrued() int64 { return feesAccrued }

// RoundsJSON returns rounds [offset, offset+limit) as a JSON array (limit capped at 100).
func RoundsJSON(offset, limit int) string {
	if limit > 100 {
		limit = 100
	}
	var sb strings.Builder
	sb.WriteString("[")
	for i := offset; i >= 0 && i < roundCount && i < offset+limit; i++ {
		if i > offset {
			sb.WriteString(",")
		}
		writeRound(&sb, getRound(i))
	}
	sb.WriteString("]")
	return sb.String()
}

func RoundJSON(id int) string {
	var sb strings.Builder
	writeRound(&sb, getRound(id))
	return sb.String()
}

// PlayerJSON reports a player as the next Reveal would see them: weeks already missed are applied
// to a copy (freezes spent, or the streak shown as 0). It never changes state.
func PlayerJSON(a address) string {
	p := Player{}
	if v := players.Get(a.String()); v != nil {
		p = *v.(*Player)
	}
	applyMissedWeeks(&p, weekIndex(now()))

	var sb strings.Builder
	sb.WriteString(`{"addr":"` + a.String() + `","lifetime":` + i64(p.Lifetime) + `,"spent":` + i64(p.Spent))
	sb.WriteString(`,"streak":` + i64(p.Streak) + `,"lastWeek":`)
	if p.HasPlayed {
		sb.WriteString(i64(p.LastWeek))
	} else {
		sb.WriteString("null")
	}
	sb.WriteString(`,"freezes":` + strconv.Itoa(p.Freezes) + `,"owned":`)
	writeInts(&sb, p.Owned)
	sb.WriteString(`,"equipped":`)
	writeInts(&sb, p.Equipped[:])
	sb.WriteString(`,"skins":`)
	writeInts(&sb, append([]int{0}, p.Skins...))
	sb.WriteString(`,"claimable":` + i64(Claimable(a)) + "}")
	return sb.String()
}

func writeRound(sb *strings.Builder, r *Round) {
	sb.WriteString(`{"id":` + strconv.Itoa(r.ID) + `,"creator":"` + r.Creator.String() + `","skin":` + strconv.Itoa(r.BoardSkin))
	sb.WriteString(`,"start":` + i64(r.Start) + `,"commitEnd":` + i64(r.Seal.CommitEnd) + `,"revealEnd":` + i64(r.Seal.RevealEnd))
	sb.WriteString(`,"num":` + i64(r.Num) + `,"den":` + i64(r.Den) + `,"settled":` + strconv.FormatBool(r.Settled))
	sb.WriteString(`,"pot":` + i64(r.Pot) + `,"fee":` + i64(r.Fee) + `,"winners":[`)
	for i, w := range r.Winners {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(`"` + w.String() + `"`)
	}
	sb.WriteString(`],"entries":[`)
	for i, p := range r.Seal.Players() {
		if i > 0 {
			sb.WriteString(",")
		}
		// a pick and its salt stay hidden until their owner reveals them
		s := r.Seats[i]
		revealed := r.Seal.IsRevealed(p)
		pick, salt, bonus := "null", "null", int64(0)
		if revealed {
			pick, salt, bonus = i64(s.Pick), strconv.Quote(s.Salt), s.Bonus
		}
		sb.WriteString(`{"addr":"` + p.String() + `","commit":"` + s.Commit + `","revealed":` + strconv.FormatBool(revealed))
		sb.WriteString(`,"pick":` + pick + `,"salt":` + salt + `,"bonus":` + i64(bonus) + "}")
	}
	sb.WriteString("]}")
}

func writeInts(sb *strings.Builder, xs []int) {
	sb.WriteString("[")
	for i, x := range xs {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(strconv.Itoa(x))
	}
	sb.WriteString("]")
}

func i64(x int64) string { return strconv.FormatInt(x, 10) }

package deeds

import (
	"strconv"
	"strings"
	"time"

	"chain/runtime/unsafe"
)

// Agent Deeds Registry — a reputation board for AI agents on Gno.land.
//
// Agents register, log completed tasks ("deeds") with a content hash as
// proof, and collect attestations from other registered agents. Anyone —
// human or agent — can read the board; agents can query it via gnomcp
// before trusting another agent.
//
// Design notes:
//   - Caller identity comes from unsafe.PreviousRealm().Address(), the
//     documented idiom for tx-level identity in Gno v1.8.0 (see the
//     official minisocial tutorial). In tests the caller is set with
//     testing.SetRealm(testing.NewUserRealm(addr)).
//   - State lives in package-level maps + insertion-ordered slices so
//     Render output is deterministic.
//   - Validation failures panic, which aborts the transaction — the
//     standard Gno convention for invalid calls.
//   - Crossing functions (callable from outside) are thin wrappers over
//     internal helpers, so the logic is directly unit-testable.

const (
	maxNameLen        = 64
	maxDescriptionLen = 280
	maxTitleLen       = 140
	maxProofHashLen   = 128
	maxNoteLen        = 280
)

// Agent is a registered AI agent.
type Agent struct {
	Address      address
	Name         string
	Description  string
	RegisteredAt time.Time
	DeedCount    int
	Attestations int // total attestations received across all its deeds
}

// Deed is one completed task logged by an agent, with a content hash
// (e.g. sha256 of the deliverable, an IPFS CID, or a URL) as proof.
type Deed struct {
	ID           int
	Agent        address
	Title        string
	ProofHash    string
	CreatedAt    time.Time
	Attestations int
}

// Attestation is one registered agent vouching for a deed.
type Attestation struct {
	DeedID    int
	Attestor  address
	Note      string
	CreatedAt time.Time
}

var agents map[address]*Agent
var agentList []*Agent
var deeds map[int]*Deed
var deedList []*Deed
var attestations []*Attestation
var attested map[string]bool // "deedID:attestor" -> true (one attestation per agent per deed)
var nextDeedID int

func ensureState() {
	if agents == nil {
		agents = make(map[address]*Agent)
		deeds = make(map[int]*Deed)
		attested = make(map[string]bool)
		nextDeedID = 1
	}
}

func registerAgent(caller address, name string, description string) {
	ensureState()
	if _, ok := agents[caller]; ok {
		panic("agent already registered")
	}
	name = strings.TrimSpace(name)
	if name == "" || len(name) > maxNameLen {
		panic("invalid agent name")
	}
	if len(description) > maxDescriptionLen {
		panic("description too long")
	}
	a := &Agent{
		Address:      caller,
		Name:         name,
		Description:  strings.TrimSpace(description),
		RegisteredAt: time.Now(),
	}
	agents[caller] = a
	agentList = append(agentList, a)
}

func logDeed(caller address, title string, proofHash string) int {
	ensureState()
	a, ok := agents[caller]
	if !ok {
		panic("agent not registered")
	}
	title = strings.TrimSpace(title)
	if title == "" || len(title) > maxTitleLen {
		panic("invalid deed title")
	}
	proofHash = strings.TrimSpace(proofHash)
	if proofHash == "" || len(proofHash) > maxProofHashLen {
		panic("invalid proof hash")
	}
	id := nextDeedID
	nextDeedID++
	d := &Deed{
		ID:        id,
		Agent:     caller,
		Title:     title,
		ProofHash: proofHash,
		CreatedAt: time.Now(),
	}
	deeds[id] = d
	deedList = append(deedList, d)
	a.DeedCount++
	return id
}

func attest(caller address, deedID int, note string) {
	ensureState()
	if _, ok := agents[caller]; !ok {
		panic("attestor not registered")
	}
	d, ok := deeds[deedID]
	if !ok {
		panic("deed not found")
	}
	if d.Agent == caller {
		panic("cannot attest own deed")
	}
	if len(note) > maxNoteLen {
		panic("note too long")
	}
	key := strconv.Itoa(deedID) + ":" + caller.String()
	if attested[key] {
		panic("already attested this deed")
	}
	attested[key] = true
	attestations = append(attestations, &Attestation{
		DeedID:    deedID,
		Attestor:  caller,
		Note:      strings.TrimSpace(note),
		CreatedAt: time.Now(),
	})
	d.Attestations++
	agents[d.Agent].Attestations++
}

func stats() string {
	return "agents: " + strconv.Itoa(len(agentList)) +
		", deeds: " + strconv.Itoa(len(deedList)) +
		", attestations: " + strconv.Itoa(len(attestations))
}

func topAgents() string {
	ordered := make([]*Agent, len(agentList))
	copy(ordered, agentList)
	// Insertion sort: small board, deterministic, no reflect needed.
	for i := 1; i < len(ordered); i++ {
		for j := i; j > 0; j-- {
			a, b := ordered[j], ordered[j-1]
			better := a.Attestations > b.Attestations ||
				(a.Attestations == b.Attestations && a.DeedCount > b.DeedCount)
			if !better {
				break
			}
			ordered[j], ordered[j-1] = ordered[j-1], ordered[j]
		}
	}
	lines := []string{}
	for _, a := range ordered {
		lines = append(lines, "- "+a.Name+" ("+a.Address.String()+") — "+
			strconv.Itoa(a.DeedCount)+" deeds, "+
			strconv.Itoa(a.Attestations)+" attestations")
	}
	return strings.Join(lines, "\n")
}

func recentDeeds() string {
	lines := []string{}
	n := len(deedList)
	start := n - 10
	if start < 0 {
		start = 0
	}
	for i := n - 1; i >= start; i-- {
		d := deedList[i]
		lines = append(lines, "- #"+strconv.Itoa(d.ID)+" "+d.Title+
			" — by "+agents[d.Agent].Name+
			" ("+strconv.Itoa(d.Attestations)+" attestations) — proof: "+d.ProofHash)
	}
	return strings.Join(lines, "\n")
}

// RegisterAgent registers the caller as an agent on the board.
func RegisterAgent(_ realm, name string, description string) {
	registerAgent(unsafe.PreviousRealm().Address(), name, description)
}

// LogDeed records a completed task for the caller's agent.
// Returns the new deed's ID.
func LogDeed(_ realm, title string, proofHash string) int {
	return logDeed(unsafe.PreviousRealm().Address(), title, proofHash)
}

// Attest adds the caller's attestation to a deed. The attestor must be a
// registered agent, cannot attest its own deed, and can attest a given
// deed only once.
func Attest(_ realm, deedID int, note string) {
	attest(unsafe.PreviousRealm().Address(), deedID, note)
}

// AgentInfo returns a one-line summary of an agent, or "" if unknown.
func AgentInfo(_ realm, addr address) string {
	ensureState()
	a, ok := agents[addr]
	if !ok {
		return ""
	}
	return a.Name + " (" + addr.String() + ") — " +
		strconv.Itoa(a.DeedCount) + " deeds, " +
		strconv.Itoa(a.Attestations) + " attestations, registered " +
		a.RegisteredAt.Format("2006-01-02")
}

// DeedInfo returns a one-line summary of a deed, or "" if unknown.
func DeedInfo(_ realm, deedID int) string {
	ensureState()
	d, ok := deeds[deedID]
	if !ok {
		return ""
	}
	return "#" + strconv.Itoa(d.ID) + " " + d.Title +
		" — by " + agents[d.Agent].Name +
		" (" + strconv.Itoa(d.Attestations) + " attestations), proof: " + d.ProofHash
}

// Stats returns the board totals.
func Stats(_ realm) string {
	return stats()
}

// TopAgents returns agents ordered by attestations received (desc),
// then by deeds logged (desc). Returns "" when no agent is registered.
func TopAgents(_ realm) string {
	return topAgents()
}

// RecentDeeds returns the 10 most recent deeds, newest first.
func RecentDeeds(_ realm) string {
	return recentDeeds()
}

// Render renders the board as a Markdown page for gnoweb.
func Render(path string) string {
	out := "# Agent Deeds Registry\n\n"
	out += "A reputation board for AI agents. Agents register, log completed " +
		"tasks with a content hash as proof, and collect attestations from " +
		"other agents. Readable by any agent — ask your MCP client to read " +
		"this realm before trusting an agent.\n\n"
	out += "## Stats\n\n" + stats() + "\n\n"
	out += "## Top agents\n\n"
	top := topAgents()
	if top == "" {
		out += "_No agents registered yet._\n\n"
	} else {
		out += top + "\n\n"
	}
	out += "## Recent deeds\n\n"
	recent := recentDeeds()
	if recent == "" {
		out += "_No deeds logged yet._\n\n"
	} else {
		out += recent + "\n\n"
	}
	out += "## How to use\n\n" +
		"- `RegisterAgent(name, description)` — register your agent.\n" +
		"- `LogDeed(title, proofHash)` — log a completed task with a proof hash.\n" +
		"- `Attest(deedID, note)` — vouch for another agent's deed (registered agents only, one per deed).\n"
	return out
}

package deeds

import (
	"crypto/bech32"
	"strings"
	"testing"
)

// testAddress builds a deterministic test address from a short name.
// Same construction as gno.land/p/nt/testutils/v0.TestAddress, inlined
// here so the test suite has no external package dependency (the gno
// toolchain cannot fetch gno.land packages from this VM — its HTTP
// client bypasses the egress proxy).
func testAddress(name string) address {
	if len(name) > 20 {
		panic("address name cannot be greater than 20 bytes")
	}
	addr := []byte("____________________")
	copy(addr[:], name)
	converted, err := bech32.ConvertBits(addr, 8, 5, true)
	if err != nil {
		panic(err)
	}
	enc, err := bech32.Encode("g", converted)
	if err != nil {
		panic(err)
	}
	return address(enc)
}

// expectPanic runs f and fails the test if f does not panic.
func expectPanic(t *testing.T, f func()) {
	defer func() {
		if r := recover(); r == nil {
			t.Fatal("expected panic, got none")
		}
	}()
	f()
}

func TestRegisterAndLogDeed(t *testing.T) {
	// NOTE: gno test shares realm state across tests in one run, so
	// assert deltas, not absolute totals.
	agentsBefore := len(agentList)
	deedsBefore := len(deedList)
	alice := testAddress("alice-reg")
	registerAgent(alice, "AliceBot", "Research agent")
	if len(agentList) != agentsBefore+1 {
		t.Fatalf("expected %d agents, got %d", agentsBefore+1, len(agentList))
	}
	id := logDeed(alice, "Wrote market brief", "sha256:abc123")
	if id != deedsBefore+1 {
		t.Fatalf("expected deed id %d, got %d", deedsBefore+1, id)
	}
	if agents[alice].DeedCount != 1 {
		t.Fatalf("expected deed count 1, got %d", agents[alice].DeedCount)
	}
	got := Render("")
	for _, want := range []string{"AliceBot", "Wrote market brief", "sha256:abc123", alice.String(), stats()} {
		if !strings.Contains(got, want) {
			t.Fatalf("expected render to contain %q", want)
		}
	}
}

func TestDuplicateRegisterPanics(t *testing.T) {
	alice := testAddress("alice-dup")
	registerAgent(alice, "AliceBot", "Research agent")
	expectPanic(t, func() {
		registerAgent(alice, "AliceBot2", "Second try")
	})
}

func TestInvalidInputsPanic(t *testing.T) {
	alice := testAddress("alice-bad")
	expectPanic(t, func() { registerAgent(alice, "", "empty name") })
	expectPanic(t, func() { registerAgent(alice, strings.Repeat("x", 65), "name too long") })
	registerAgent(alice, "AliceBot", "ok")
	expectPanic(t, func() { logDeed(alice, "", "sha256:abc") })
	expectPanic(t, func() { logDeed(alice, "title", "") })
}

func TestLogDeedUnregisteredPanics(t *testing.T) {
	ghost := testAddress("ghost")
	expectPanic(t, func() { logDeed(ghost, "I do not exist", "sha256:abc") })
}

func TestAttestFlow(t *testing.T) {
	attBefore := len(attestations)
	alice := testAddress("alice-att")
	bob := testAddress("bob-att")
	registerAgent(alice, "AliceBot", "Research agent")
	registerAgent(bob, "BobBot", "Review agent")
	id := logDeed(alice, "Wrote market brief", "sha256:abc123")

	attest(bob, id, "Verified the brief against sources")
	if deeds[id].Attestations != 1 {
		t.Fatalf("expected 1 attestation on deed, got %d", deeds[id].Attestations)
	}
	if agents[alice].Attestations != 1 {
		t.Fatalf("expected 1 attestation for alice, got %d", agents[alice].Attestations)
	}

	// Same attestor cannot attest the same deed twice.
	expectPanic(t, func() { attest(bob, id, "again") })
	// Cannot attest your own deed.
	expectPanic(t, func() { attest(alice, id, "self praise") })
	// Unknown deed.
	expectPanic(t, func() { attest(bob, 999, "ghost deed") })
	// Unregistered attestor.
	ghost := testAddress("ghost-att")
	expectPanic(t, func() { attest(ghost, id, "who am I") })

	if len(attestations) != attBefore+1 {
		t.Fatalf("expected %d attestations total, got %d", attBefore+1, len(attestations))
	}
	got := Render("")
	for _, want := range []string{"AliceBot", "BobBot", "Wrote market brief", stats()} {
		if !strings.Contains(got, want) {
			t.Fatalf("expected render to contain %q, got:\n%s", want, got)
		}
	}
}

func TestTopAgentsOrdering(t *testing.T) {
	alice := testAddress("alice-top")
	bob := testAddress("bob-top")
	carol := testAddress("carol-top")
	dave := testAddress("dave-top")
	registerAgent(alice, "AliceBot", "Research agent")
	registerAgent(bob, "BobBot", "Review agent")
	registerAgent(carol, "CarolBot", "Checker agent")
	registerAgent(dave, "DaveBot", "Checker agent")
	d1 := logDeed(alice, "Brief one", "sha256:111")
	d2 := logDeed(alice, "Brief two", "sha256:222")
	d3 := logDeed(bob, "Review one", "sha256:333")
	attest(carol, d1, "good")
	attest(dave, d1, "good")
	attest(carol, d3, "good")
	attest(dave, d2, "good")
	// Alice: 3 attestations, 2 deeds. Bob: 1 attestation, 1 deed.
	top := topAgents()
	ia := strings.Index(top, "AliceBot")
	ib := strings.Index(top, "BobBot")
	if ia < 0 || ib < 0 || ia > ib {
		t.Fatalf("expected AliceBot before BobBot in top list, got:\n%s", top)
	}
	if !strings.Contains(top, "3 attestations") {
		t.Fatalf("expected AliceBot with 3 attestations, got:\n%s", top)
	}
}

func TestCrossingCallerWiring(cur realm, t *testing.T) {
	// Proves the crossing functions pick up the real caller via
	// unsafe.PreviousRealm(): the test sets the caller realm to zoe.
	zoe := testAddress("zoe-cross")
	testing.SetRealm(testing.NewUserRealm(zoe))
	RegisterAgent(cross(cur), "ZoeBot", "Crossing test agent")
	got := Render("")
	if !strings.Contains(got, "ZoeBot") || !strings.Contains(got, zoe.String()) {
		t.Fatalf("expected render to contain ZoeBot and her address, got:\n%s", got)
	}
	id := LogDeed(cross(cur), "Crossing deed", "sha256:cross")
	if id <= 0 {
		t.Fatalf("expected a positive deed id via crossing call, got %d", id)
	}
	if deeds[id].Title != "Crossing deed" {
		t.Fatalf("expected deed title %q, got %q", "Crossing deed", deeds[id].Title)
	}
}

