func findVault(projectID uint64) *ProjectVault {
	raw := vaults.Get(seqid.ID(projectID).String())
	if raw == nil {
		return nil
	}
	return raw.(*ProjectVault)
}

func countApprovedMilestones(v *ProjectVault) int {
	n := 0
	for _, m := range v.Milestones {
		if m.Status == StatusApproved {
			n++
		}
	}
	return n
}

func contractorHasBadge(contractor address, badgeID string) bool {
	if badgeID == "" {
		return true
	}
	raw := profiles.Get(contractor.String())
	if raw == nil {
		return false
	}
	return raw.(*BuilderProfile).Badges.Get(badgeID) != nil
}

func contractorLink(addr address) string {
	label := shortAddr(addr)
	if raw := profiles.Get(addr.String()); raw != nil {
		p := raw.(*BuilderProfile)
		if p.Handle != "" {
			label = p.Handle
		}
	}
	return ufmt.Sprintf("[%s](%s:builder/%s)", label, realmBase, addr.String())
}

func badgeSummary(p *BuilderProfile) string {
	if p.Badges.Size() == 0 {
		return "None"
	}
	var ids []string
	p.Badges.Iterate("", "", func(key string, value any) bool {
		b := value.(*Badge)
		ids = append(ids, "`"+b.ID+"`")
		return false
	})
	return strings.Join(ids, ", ")
}

func circuitStatusLabel() string {
	if policy.Paused {
		return "🔴 **PAUSED**"
	}
	return "🟢 **ACTIVE**"
}

func statusLabel(s MilestoneStatus) string {
	switch s {
	case StatusPending:
		return "⏳ PENDING"
	case StatusSubmitted:
		return "📤 SUBMITTED"
	case StatusApproved:
		return "✅ APPROVED"
	case StatusRejected:
		return "❌ REJECTED"
	default:
		return "UNKNOWN"
	}
}

func formatGNOT(ugnot int64) string {
	neg := ""
	if ugnot < 0 {
		neg = "-"
		ugnot = -ugnot
	}
	whole := ugnot / 1_000_000
	frac := (ugnot % 1_000_000) / 10_000
	fracStr := strconv.FormatInt(frac, 10)
	if frac < 10 {
		fracStr = "0" + fracStr
	}
	return neg + strconv.FormatInt(whole, 10) + "." + fracStr + " GNOT"
}

func progressBar(current, total int64, width int) string {
	if total <= 0 || width <= 0 {
		return "`[" + strings.Repeat("░", width) + "] 0%`"
	}
	pct := (current * 100) / total
	if pct < 0 {
		pct = 0
	}
	if pct > 100 {
		pct = 100
	}
	filled := int((current * int64(width)) / total)
	if filled < 0 {
		filled = 0
	}
	if filled > width {
		filled = width
	}
	return "`[" + strings.Repeat("█", filled) + strings.Repeat("░", width-filled) + "] " + strconv.FormatInt(pct, 10) + "%`"
}

func formatProof(proof string) string {
	if proof == "" {
		return "—"
	}
	if strings.HasPrefix(proof, "ipfs://") {
		cid := strings.TrimPrefix(proof, "ipfs://")
		shortCID := cid
		if len(shortCID) > 14 {
			shortCID = shortCID[:8] + "..." + shortCID[len(shortCID)-4:]
		}
		return ufmt.Sprintf("[ipfs://%s](https://ipfs.io/ipfs/%s)", shortCID, cid)
	}
	return "`" + proof + "`"
}

func helpLink(fn string, kv ...string) string {
	var sb strings.Builder
	sb.WriteString(realmBase)
	sb.WriteString("$help&func=")
	sb.WriteString(fn)
	for i := 0; i+1 < len(kv); i += 2 {
		sb.WriteString("&")
		sb.WriteString(kv[i])
		sb.WriteString("=")
		sb.WriteString(kv[i+1])
	}
	return sb.String()
}

func pauseToggleLink() string {
	nextPaused := "true"
	if policy.Paused {
		nextPaused = "false"
	}
	reqBadge := "false"
	if policy.RequireBadgeMatch {
		reqBadge = "true"
	}
	return helpLink(
		"SetGuardrailPolicy",
		"agent", policy.AgentAddr.String(),
		"maxSingle", strconv.FormatInt(policy.MaxSinglePayout, 10),
		"dailyLimit", strconv.FormatInt(policy.DailySpendLimit, 10),
		"cooldown", strconv.FormatInt(policy.CooldownBlocks, 10),
		"requireBadge", reqBadge,
		"paused", nextPaused,
	)
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "..." + s[len(s)-4:]
}

package idox

import (
	"strings"
	"testing"
)

func TestRenderHelpersAndRoutes(t *testing.T) {
	if got := formatGNOT(30_000_000); got != "30.00 GNOT" {
		t.Fatalf("expected 30.00 GNOT, got %s", got)
	}
	if got := formatGNOT(1_050_000); got != "1.05 GNOT" {
		t.Fatalf("expected 1.05 GNOT, got %s", got)
	}
	if got := progressBar(30_000_000, 70_000_000, 10); !strings.Contains(got, "42%") {
		t.Fatalf("expected 42%% progress bar, got %s", got)
	}
	if got := formatProof("ipfs://QmFramingInspectionPassedHash123"); !strings.Contains(got, "https://ipfs.io/ipfs/QmFramingInspectionPassedHash123") {
		t.Fatalf("expected clickable IPFS gateway URL, got %s", got)
	}
	if got := Render("vault/9999"); !strings.Contains(got, "Vault #9999 Not Found") {
		t.Fatalf("expected clean not-found page for missing vault, got %s", got)
	}
	if got := Render("audits"); !strings.Contains(got, "Idox AI Audit & Guardrail Log") {
		t.Fatalf("expected audit log heading, got %s", got)
	}
}

package idox

import (
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

var (
	adminAddr     address
	policy        GuardrailPolicy
	vaultSeq      seqid.ID
	vaults        *avl.Tree // seqid string -> *ProjectVault
	profiles      *avl.Tree // address string -> *BuilderProfile
	auditLogs     []*AuditLog
	dailySpent    int64
	windowStartBk int64
)

func init(cur realm) {
	adminAddr = cur.Previous().Address()
	if adminAddr == "" {
		adminAddr = cur.Address()
	}
	windowStartBk = runtime.ChainHeight()

	vaults = avl.NewTree()
	profiles = avl.NewTree()

	policy = GuardrailPolicy{
		AgentAddr:         adminAddr,
		MaxSinglePayout:   50_000_000,  // 50 GNOT cap per milestone (in ugnot)
		DailySpendLimit:   150_000_000, // 150 GNOT rolling 24h cap
		CooldownBlocks:    10,          // Minimum blocks between AI approvals
		RequireBadgeMatch: true,
		Paused:            false,
	}
}

func SetGuardrailPolicy(cur realm, agent address, maxSingle int64, dailyLimit int64, cooldown int64, requireBadge bool, paused bool) {
	if cur.Previous().Address() != adminAddr {
		panic("unauthorized: admin only")
	}
	policy = GuardrailPolicy{
		AgentAddr:         agent,
		MaxSinglePayout:   maxSingle,
		DailySpendLimit:   dailyLimit,
		CooldownBlocks:    cooldown,
		RequireBadgeMatch: requireBadge,
		Paused:            paused,
	}
}

func Admin() address {
	return adminAddr
}

func GetVaultReleased(projectID uint64) int64 {
	return getVault(projectID).ReleasedAmount
}

func getOrCreateProfile(addr address, handle string) *BuilderProfile {
	key := addr.String()
	if raw := profiles.Get(key); raw != nil {
		return raw.(*BuilderProfile)
	}
	p := &BuilderProfile{
		Addr:   addr,
		Handle: handle,
		Badges: avl.NewTree(),
	}
	profiles.Set(key, p)
	return p
}

func getVault(projectID uint64) *ProjectVault {
	key := seqid.ID(projectID).String()
	raw := vaults.Get(key)
	if raw == nil {
		panic("project vault not found")
	}
	return raw.(*ProjectVault)
}

package idox

import (
	"chain"
	"chain/banker"
	"chain/runtime"
)

const blocksPerDay int64 = 43200

func IssueBadge(cur realm, builder address, handle string, badgeID string, badgeName string) {
	caller := cur.Previous().Address()
	if caller != adminAddr {
		panic("unauthorized: only admin can issue credentials")
	}

	profile := getOrCreateProfile(builder, handle)
	profile.Badges.Set(badgeID, &Badge{
		ID:          badgeID,
		Name:        badgeName,
		Issuer:      caller,
		IssuedBlock: runtime.ChainHeight(),
	})
}

func CreateVault(cur realm, title string, contractor address, milestoneTitles []string, requiredBadges []string, allocations []int64) uint64 {
	if len(milestoneTitles) == 0 || len(milestoneTitles) != len(requiredBadges) || len(milestoneTitles) != len(allocations) {
		panic("invalid milestone configuration")
	}

	var totalNeeded int64
	milestones := make([]*Milestone, len(milestoneTitles))
	for i := range milestoneTitles {
		if allocations[i] <= 0 {
			panic("milestone allocation must be positive")
		}
		totalNeeded += allocations[i]
		milestones[i] = &Milestone{
			ID:            i,
			Title:         milestoneTitles[i],
			RequiredBadge: requiredBadges[i],
			Allocation:    allocations[i],
			Status:        StatusPending,
		}
	}

	caller := cur.Previous().Address()
	originBanker := banker.NewBanker(banker.BankerTypeOriginSend, cur)
	originBanker.SendCoins(cur.Address(), cur.Address(), chain.Coins{chain.NewCoin("ugnot", totalNeeded)})

	id := vaultSeq.Next()
	v := &ProjectVault{
		ID:            uint64(id),
		Title:         title,
		Sponsor:       caller,
		Contractor:    contractor,
		TotalEscrowed: chain.NewCoin("ugnot", totalNeeded),
		Milestones:    milestones,
		CreatedBlock:  runtime.ChainHeight(),
	}

	vaults.Set(id.String(), v)
	return uint64(id)
}

func SubmitProof(cur realm, projectID uint64, milestoneID int, proofHash string) {
	v := getVault(projectID)
	if cur.Previous().Address() != v.Contractor {
		panic("unauthorized: only assigned contractor can submit proof")
	}
	if milestoneID < 0 || milestoneID >= len(v.Milestones) {
		panic("invalid milestone ID")
	}
	if proofHash == "" {
		panic("proof hash cannot be empty")
	}

	m := v.Milestones[milestoneID]
	if m.Status == StatusApproved {
		panic("milestone already approved")
	}

	m.ProofHash = proofHash
	m.Status = StatusSubmitted
}

func AIAuditAndRelease(cur realm, projectID uint64, milestoneID int, auditNote string) {
	caller := cur.Previous().Address()
	if caller != policy.AgentAddr {
		panic("unauthorized: caller is not registered AI agent")
	}
	if policy.Paused {
		panic("guardrail blocked: AI execution is paused")
	}

	v := getVault(projectID)
	if milestoneID < 0 || milestoneID >= len(v.Milestones) {
		panic("invalid milestone ID")
	}
	m := v.Milestones[milestoneID]
	if m.Status != StatusSubmitted {
		panic("milestone is not awaiting audit")
	}

	now := runtime.ChainHeight()

	if len(auditLogs) > 0 {
		lastLog := auditLogs[len(auditLogs)-1]
		if lastLog.Action == "APPROVED" && (now-lastLog.BlockHeight) < policy.CooldownBlocks {
			recordViolation(now, projectID, milestoneID, "CooldownBlocks violation")
			panic("guardrail blocked: cooldown period active")
		}
	}

	if m.Allocation > policy.MaxSinglePayout {
		recordViolation(now, projectID, milestoneID, "Exceeds MaxSinglePayout")
		panic("guardrail blocked: payout exceeds MaxSinglePayout")
	}

	if now-windowStartBk >= blocksPerDay {
		windowStartBk = now
		dailySpent = 0
	}
	if dailySpent+m.Allocation > policy.DailySpendLimit {
		recordViolation(now, projectID, milestoneID, "Exceeds DailySpendLimit")
		panic("guardrail blocked: payout exceeds DailySpendLimit")
	}

	rawProf := profiles.Get(v.Contractor.String())
	if rawProf == nil {
		recordViolation(now, projectID, milestoneID, "Contractor has no profile")
		panic("guardrail blocked: contractor has no verified profile")
	}
	profile := rawProf.(*BuilderProfile)
	if policy.RequireBadgeMatch && m.RequiredBadge != "" {
		if !profile.Badges.Has(m.RequiredBadge) {
			recordViolation(now, projectID, milestoneID, "Missing required badge: "+m.RequiredBadge)
			panic("guardrail blocked: contractor lacks required credential badge")
		}
	}

	m.Status = StatusApproved
	m.AuditNote = auditNote
	v.ReleasedAmount += m.Allocation
	dailySpent += m.Allocation

	profile.CompletedTasks++
	profile.TotalEarned += m.Allocation
	profile.ReputationScore += 10

	realmBanker := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmBanker.SendCoins(cur.Address(), v.Contractor, chain.Coins{chain.NewCoin("ugnot", m.Allocation)})

	auditLogs = append(auditLogs, &AuditLog{
		BlockHeight: now,
		ProjectID:   projectID,
		MilestoneID: milestoneID,
		Action:      "APPROVED",
		Reason:      auditNote,
	})
}

func recordViolation(height int64, projectID uint64, milestoneID int, reason string) {
	auditLogs = append(auditLogs, &AuditLog{
		BlockHeight: height,
		ProjectID:   projectID,
		MilestoneID: milestoneID,
		Action:      "BLOCKED_GUARDRAIL",
		Reason:      reason,
	})
}

package idox

import (
	"strconv"
	"strings"
)

// CreateVaultCSV is a CLI and gnoweb $help wrapper around CreateVault.
// Pass pipe-delimited ("|") strings for milestone titles, required badges, and ugnot amounts.
// Example:
//   titlesCSV:      "Tranche 1: Framing & Dry-In|Tranche 2: Rough Electrical"
//   badgesCSV:      "gc_license|electrical_master"
//   allocationsCSV: "30000000|40000000"
func CreateVaultCSV(
	cur realm,
	title string,
	contractor address,
	titlesCSV string,
	badgesCSV string,
	allocationsCSV string,
) uint64 {
	if strings.TrimSpace(titlesCSV) == "" {
		panic("at least one milestone title is required")
	}

	rawTitles := strings.Split(titlesCSV, "|")
	rawBadges := strings.Split(badgesCSV, "|")
	rawAllocs := strings.Split(allocationsCSV, "|")

	n := len(rawTitles)
	if len(rawBadges) != n || len(rawAllocs) != n {
		panic("mismatched pipe-delimited counts across titles, badges, and allocations")
	}

	titles := make([]string, n)
	badges := make([]string, n)
	allocations := make([]int64, n)

	for i := 0; i < n; i++ {
		t := strings.TrimSpace(rawTitles[i])
		if t == "" {
			panic("milestone title cannot be empty")
		}
		titles[i] = t
		badges[i] = strings.TrimSpace(rawBadges[i])

		amtStr := strings.TrimSpace(rawAllocs[i])
		amt, err := strconv.ParseInt(amtStr, 10, 64)
		if err != nil || amt <= 0 {
			panic("invalid milestone allocation: " + amtStr)
		}
		allocations[i] = amt
	}

	// Forward cur directly (no cross) so cur.Previous().IsUserCall() stays true
	// for CreateVault's BankerTypeOriginSend guard.
	return CreateVault(cur, title, contractor, titles, badges, allocations)
}

package idox

import (
	"chain"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
)

func TestCreateVaultCSV(cur realm, t *testing.T) {
	sponsor := testutils.TestAddress("csv_sponsor")
	contractor := testutils.TestAddress("csv_contractor")

	testing.IssueCoins(cur.Address(), chain.Coins{chain.NewCoin("ugnot", 70_000_000)})
	testing.SetOriginCaller(sponsor)
	testing.SetRealm(testing.NewUserRealm(sponsor))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", 70_000_000)})

	vaultID := CreateVaultCSV(
		cross(cur),
		"Alachua Rental Rehab (CSV)",
		contractor,
		"Tranche 1: Framing & Dry-In | Tranche 2: Rough Electrical",
		"gc_license | electrical_master",
		"30000000 | 40000000",
	)
	testing.SetOriginSend(nil)

	if vaultID == 0 {
		t.Fatalf("expected non-zero vaultID")
	}
	if got := GetVaultReleased(vaultID); got != 0 {
		t.Fatalf("expected 0 released initially, got %d", got)
	}
	if !strings.Contains(Render(""), "Alachua Rental Rehab (CSV)") {
		t.Fatalf("expected CSV-created vault in Render() output")
	}

	// Mismatched pipe counts should panic
	testing.SetOriginCaller(sponsor)
	testing.SetRealm(testing.NewUserRealm(sponsor))
	if rec := revive(func() {
		CreateVaultCSV(cross(cur), "Bad Vault", contractor, "Only One", "gc_license|extra", "1000000")
	}); rec == nil {
		t.Fatalf("expected panic on mismatched pipe-delimited counts")
	}
}

package idox

import (
	"chain"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
)

func TestFullWorkflowAndGuardrails(cur realm, t *testing.T) {
	vaultAddr := cur.Address()
	admin := adminAddr
	sponsor := testutils.TestAddress("sponsor")
	contractor := testutils.TestAddress("contractor")
	aiAgent := testutils.TestAddress("ai_agent")

	// 1. Admin configures the AI Agent address and strict guardrails
	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	SetGuardrailPolicy(cross(cur), aiAgent, 50_000_000, 150_000_000, 10, true, false)

	// 2. Admin issues the "gc_license" badge (withholding "electrical_master" for testing)
	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	IssueBadge(cross(cur), contractor, "EdwinBuilds", "gc_license", "Licensed General Contractor")

	// 3. Sponsor creates a 2-milestone RWA rehab vault with 70 GNOT total escrow
	testing.IssueCoins(vaultAddr, chain.Coins{chain.NewCoin("ugnot", 70_000_000)})
	testing.SetOriginCaller(sponsor)
	testing.SetRealm(testing.NewUserRealm(sponsor))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", 70_000_000)})

	vaultID := CreateVault(
		cross(cur),
		"Alachua Rental Rehab & Bath Addition",
		contractor,
		[]string{"Tranche 1: Framing & Dry-In", "Tranche 2: Rough Electrical"},
		[]string{"gc_license", "electrical_master"},
		[]int64{30_000_000, 40_000_000},
	)
	testing.SetOriginSend(nil)

	// 4. Contractor submits proof-of-work for both milestones
	testing.SetOriginCaller(contractor)
	testing.SetRealm(testing.NewUserRealm(contractor))
	SubmitProof(cross(cur), vaultID, 0, "ipfs://QmFramingInspectionPassedHash123")

	testing.SetOriginCaller(contractor)
	testing.SetRealm(testing.NewUserRealm(contractor))
	SubmitProof(cross(cur), vaultID, 1, "ipfs://QmElectricalPanelPhotoHash456")

	// 5. AI Agent audits and approves Tranche 1 -> Should SUCCEED
	testing.SetOriginCaller(aiAgent)
	testing.SetRealm(testing.NewUserRealm(aiAgent))
	AIAuditAndRelease(cross(cur), vaultID, 0, "Verified framing inspection hash & active gc_license")

	if got := GetVaultReleased(vaultID); got != 30_000_000 {
		t.Fatalf("expected 30_000_000 released, got %d", got)
	}

	// 6. Guardrail: AI attempts Tranche 2 immediately (violates CooldownBlocks)
	testing.SetOriginCaller(aiAgent)
	testing.SetRealm(testing.NewUserRealm(aiAgent))
	if rec := revive(func() {
		AIAuditAndRelease(cross(cur), vaultID, 1, "Attempting early payout")
	}); rec == nil {
		t.Fatalf("expected guardrail panic on cooldown violation")
	}

	// 7. Advance chain height past cooldown, then test Missing Badge Guardrail
	testing.SkipHeights(15)
	testing.SetOriginCaller(aiAgent)
	testing.SetRealm(testing.NewUserRealm(aiAgent))
	if rec := revive(func() {
		AIAuditAndRelease(cross(cur), vaultID, 1, "Attempting payout without electrical_master badge")
	}); rec == nil {
		t.Fatalf("expected guardrail panic on missing credential badge")
	}

	// 8. Verify Render() outputs clean Markdown
	rendered := Render("")
	if !strings.Contains(rendered, "Alachua Rental Rehab & Bath Addition") {
		t.Fatalf("expected project title in Render() output")
	}
	if !strings.Contains(rendered, "EdwinBuilds") {
		t.Fatalf("expected builder handle in Render() output")
	}
}

func TestGuardrailMaxSinglePayout(cur realm, t *testing.T) {
	vaultAddr := cur.Address()
	admin := adminAddr
	sponsor := testutils.TestAddress("cap_sponsor")
	contractor := testutils.TestAddress("cap_contractor")
	aiAgent := testutils.TestAddress("cap_agent")

	testing.SkipHeights(200_000)

	// Cap single payout at 25 GNOT while daily cap is 200 GNOT
	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	SetGuardrailPolicy(cross(cur), aiAgent, 25_000_000, 200_000_000, 5, true, false)

	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	IssueBadge(cross(cur), contractor, "CapBuilder", "gc_license", "Licensed General Contractor")

	testing.IssueCoins(vaultAddr, chain.Coins{chain.NewCoin("ugnot", 30_000_000)})
	testing.SetOriginCaller(sponsor)
	testing.SetRealm(testing.NewUserRealm(sponsor))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", 30_000_000)})

	vaultID := CreateVault(
		cross(cur),
		"Single Payout Cap Vault",
		contractor,
		[]string{"Oversized Tranche"},
		[]string{"gc_license"},
		[]int64{30_000_000},
	)
	testing.SetOriginSend(nil)

	testing.SetOriginCaller(contractor)
	testing.SetRealm(testing.NewUserRealm(contractor))
	SubmitProof(cross(cur), vaultID, 0, "ipfs://QmSingleCapProof1")

	// 30 GNOT > 25 GNOT MaxSinglePayout -> must panic
	testing.SetOriginCaller(aiAgent)
	testing.SetRealm(testing.NewUserRealm(aiAgent))
	if rec := revive(func() {
		AIAuditAndRelease(cross(cur), vaultID, 0, "Exceeds single payout cap")
	}); rec == nil {
		t.Fatalf("expected guardrail panic on MaxSinglePayout violation")
	}
	if got := GetVaultReleased(vaultID); got != 0 {
		t.Fatalf("expected 0 released after cap rejection, got %d", got)
	}

	// Raise single cap to 35 GNOT -> exact same release must now succeed
	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	SetGuardrailPolicy(cross(cur), aiAgent, 35_000_000, 200_000_000, 5, true, false)

	testing.SkipHeights(10)
	testing.SetOriginCaller(aiAgent)
	testing.SetRealm(testing.NewUserRealm(aiAgent))
	AIAuditAndRelease(cross(cur), vaultID, 0, "Approved after cap raised")

	if got := GetVaultReleased(vaultID); got != 30_000_000 {
		t.Fatalf("expected 30_000_000 released, got %d", got)
	}
}

func TestGuardrailDailySpendLimitAndRollingWindow(cur realm, t *testing.T) {
	vaultAddr := cur.Address()
	admin := adminAddr
	sponsor := testutils.TestAddress("daily_sponsor")
	contractor := testutils.TestAddress("daily_contractor")
	aiAgent := testutils.TestAddress("daily_agent")

	// Start in a fresh rolling 24h window
	testing.SkipHeights(400_000)

	// Single cap = 50 GNOT, rolling 24h daily cap = 60 GNOT, cooldown = 5 blocks
	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	SetGuardrailPolicy(cross(cur), aiAgent, 50_000_000, 60_000_000, 5, true, false)

	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	IssueBadge(cross(cur), contractor, "DailyBuilder", "gc_license", "Licensed General Contractor")

	testing.IssueCoins(vaultAddr, chain.Coins{chain.NewCoin("ugnot", 70_000_000)})
	testing.SetOriginCaller(sponsor)
	testing.SetRealm(testing.NewUserRealm(sponsor))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", 70_000_000)})

	vaultID := CreateVault(
		cross(cur),
		"Daily Spend Limit Vault",
		contractor,
		[]string{"Draw 1: Foundation", "Draw 2: Roof Dry-In"},
		[]string{"gc_license", "gc_license"},
		[]int64{40_000_000, 30_000_000},
	)
	testing.SetOriginSend(nil)

	testing.SetOriginCaller(contractor)
	testing.SetRealm(testing.NewUserRealm(contractor))
	SubmitProof(cross(cur), vaultID, 0, "ipfs://QmDailyProof0")

	testing.SetOriginCaller(contractor)
	testing.SetRealm(testing.NewUserRealm(contractor))
	SubmitProof(cross(cur), vaultID, 1, "ipfs://QmDailyProof1")

	// Draw 1 (40 GNOT <= 60 GNOT daily cap) -> succeeds
	testing.SetOriginCaller(aiAgent)
	testing.SetRealm(testing.NewUserRealm(aiAgent))
	AIAuditAndRelease(cross(cur), vaultID, 0, "Within daily spend cap")

	if got := GetVaultReleased(vaultID); got != 40_000_000 {
		t.Fatalf("expected 40_000_000 released, got %d", got)
	}

	// Clear cooldown (10 > 5), stay inside 24h window: 40 + 30 = 70 > 60 -> must panic
	testing.SkipHeights(10)
	testing.SetOriginCaller(aiAgent)
	testing.SetRealm(testing.NewUserRealm(aiAgent))
	if rec := revive(func() {
		AIAuditAndRelease(cross(cur), vaultID, 1, "Breaches rolling daily limit")
	}); rec == nil {
		t.Fatalf("expected guardrail panic on DailySpendLimit violation")
	}
	if got := GetVaultReleased(vaultID); got != 40_000_000 {
		t.Fatalf("expected released to remain 40_000_000, got %d", got)
	}

	// Advance past the 24h rolling window -> daily counter resets and Draw 2 succeeds
	testing.SkipHeights(200_000)
	testing.SetOriginCaller(aiAgent)
	testing.SetRealm(testing.NewUserRealm(aiAgent))
	AIAuditAndRelease(cross(cur), vaultID, 1, "Approved in new 24h rolling window")

	if got := GetVaultReleased(vaultID); got != 70_000_000 {
		t.Fatalf("expected 70_000_000 total released after window rollover, got %d", got)
	}
}

func TestGuardrailEmergencyPauseKillSwitch(cur realm, t *testing.T) {
	vaultAddr := cur.Address()
	admin := adminAddr
	sponsor := testutils.TestAddress("pause_sponsor")
	contractor := testutils.TestAddress("pause_contractor")
	aiAgent := testutils.TestAddress("pause_agent")

	testing.SkipHeights(800_000)

	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	SetGuardrailPolicy(cross(cur), aiAgent, 50_000_000, 150_000_000, 5, true, false)

	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	IssueBadge(cross(cur), contractor, "PauseBuilder", "gc_license", "Licensed General Contractor")

	testing.IssueCoins(vaultAddr, chain.Coins{chain.NewCoin("ugnot", 20_000_000)})
	testing.SetOriginCaller(sponsor)
	testing.SetRealm(testing.NewUserRealm(sponsor))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", 20_000_000)})

	vaultID := CreateVault(
		cross(cur),
		"Emergency Pause Test Vault",
		contractor,
		[]string{"Tranche 1: Site Prep"},
		[]string{"gc_license"},
		[]int64{20_000_000},
	)
	testing.SetOriginSend(nil)

	testing.SetOriginCaller(contractor)
	testing.SetRealm(testing.NewUserRealm(contractor))
	SubmitProof(cross(cur), vaultID, 0, "ipfs://QmPauseProof0")

	// Engage emergency kill-switch (paused = true)
	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	SetGuardrailPolicy(cross(cur), aiAgent, 50_000_000, 150_000_000, 5, true, true)

	testing.SkipHeights(10)
	testing.SetOriginCaller(aiAgent)
	testing.SetRealm(testing.NewUserRealm(aiAgent))
	if rec := revive(func() {
		AIAuditAndRelease(cross(cur), vaultID, 0, "Attempt payout while paused")
	}); rec == nil {
		t.Fatalf("expected guardrail panic while circuit breaker is paused")
	}
	if got := GetVaultReleased(vaultID); got != 0 {
		t.Fatalf("expected 0 released while paused, got %d", got)
	}

	// Disengage kill-switch (paused = false) -> payout succeeds
	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	SetGuardrailPolicy(cross(cur), aiAgent, 50_000_000, 150_000_000, 5, true, false)

	testing.SetOriginCaller(aiAgent)
	testing.SetRealm(testing.NewUserRealm(aiAgent))
	AIAuditAndRelease(cross(cur), vaultID, 0, "Approved after resume")

	if got := GetVaultReleased(vaultID); got != 20_000_000 {
		t.Fatalf("expected 20_000_000 released after unpause, got %d", got)
	}
}

func TestGuardrailUnauthorizedCallers(cur realm, t *testing.T) {
	vaultAddr := cur.Address()
	admin := adminAddr
	sponsor := testutils.TestAddress("auth_sponsor")
	contractor := testutils.TestAddress("auth_contractor")
	aiAgent := testutils.TestAddress("auth_agent")
	attacker := testutils.TestAddress("auth_attacker")

	testing.SkipHeights(1_000_000)

	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	SetGuardrailPolicy(cross(cur), aiAgent, 50_000_000, 150_000_000, 5, true, false)

	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	IssueBadge(cross(cur), contractor, "AuthBuilder", "gc_license", "Licensed General Contractor")

	testing.IssueCoins(vaultAddr, chain.Coins{chain.NewCoin("ugnot", 15_000_000)})
	testing.SetOriginCaller(sponsor)
	testing.SetRealm(testing.NewUserRealm(sponsor))
	testing.SetOriginSend(chain.Coins{chain.NewCoin("ugnot", 15_000_000)})

	vaultID := CreateVault(
		cross(cur),
		"Authorization Test Vault",
		contractor,
		[]string{"Tranche 1: Trim"},
		[]string{"gc_license"},
		[]int64{15_000_000},
	)
	testing.SetOriginSend(nil)

	// 1. Non-admin (attacker & AI agent) cannot modify guardrail policy
	testing.SetOriginCaller(attacker)
	testing.SetRealm(testing.NewUserRealm(attacker))
	if rec := revive(func() {
		SetGuardrailPolicy(cross(cur), attacker, 999_000_000, 999_000_000, 0, false, false)
	}); rec == nil {
		t.Fatalf("expected panic: attacker called SetGuardrailPolicy")
	}

	testing.SetOriginCaller(aiAgent)
	testing.SetRealm(testing.NewUserRealm(aiAgent))
	if rec := revive(func() {
		SetGuardrailPolicy(cross(cur), aiAgent, 999_000_000, 999_000_000, 0, false, false)
	}); rec == nil {
		t.Fatalf("expected panic: AI agent attempted to self-raise guardrails")
	}

	// 2. Non-admin cannot issue badges
	testing.SetOriginCaller(attacker)
	testing.SetRealm(testing.NewUserRealm(attacker))
	if rec := revive(func() {
		IssueBadge(cross(cur), attacker, "FakeGC", "gc_license", "Forged License")
	}); rec == nil {
		t.Fatalf("expected panic: attacker called IssueBadge")
	}

	// 3. Non-contractor (attacker & sponsor) cannot submit milestone proofs
	testing.SetOriginCaller(attacker)
	testing.SetRealm(testing.NewUserRealm(attacker))
	if rec := revive(func() {
		SubmitProof(cross(cur), vaultID, 0, "ipfs://QmSpoofedProof")
	}); rec == nil {
		t.Fatalf("expected panic: attacker called SubmitProof")
	}

	testing.SetOriginCaller(sponsor)
	testing.SetRealm(testing.NewUserRealm(sponsor))
	if rec := revive(func() {
		SubmitProof(cross(cur), vaultID, 0, "ipfs://QmSponsorProof")
	}); rec == nil {
		t.Fatalf("expected panic: sponsor called SubmitProof")
	}

	// Legitimate contractor submits proof so payout checks test caller auth only
	testing.SetOriginCaller(contractor)
	testing.SetRealm(testing.NewUserRealm(contractor))
	SubmitProof(cross(cur), vaultID, 0, "ipfs://QmValidContractorProof")

	// 4. Unauthorized callers (attacker, contractor, and admin when admin != aiAgent) cannot release payouts
	testing.SetOriginCaller(attacker)
	testing.SetRealm(testing.NewUserRealm(attacker))
	if rec := revive(func() {
		AIAuditAndRelease(cross(cur), vaultID, 0, "Attacker drain attempt")
	}); rec == nil {
		t.Fatalf("expected panic: attacker called AIAuditAndRelease")
	}

	testing.SetOriginCaller(contractor)
	testing.SetRealm(testing.NewUserRealm(contractor))
	if rec := revive(func() {
		AIAuditAndRelease(cross(cur), vaultID, 0, "Contractor self-approval attempt")
	}); rec == nil {
		t.Fatalf("expected panic: contractor called AIAuditAndRelease")
	}

	testing.SetOriginCaller(admin)
	testing.SetRealm(testing.NewUserRealm(admin))
	if rec := revive(func() {
		AIAuditAndRelease(cross(cur), vaultID, 0, "Admin bypass attempt")
	}); rec == nil {
		t.Fatalf("expected panic: admin bypassed AI agent role on AIAuditAndRelease")
	}

	if got := GetVaultReleased(vaultID); got != 0 {
		t.Fatalf("expected 0 released after all unauthorized attempts, got %d", got)
	}
}

// Package builders is a public directory of people with proven, paid work.
//
// Anyone can list themselves, but only after finishing at least one paid task
// on Gild. The proof is not copied or claimed: the directory asks the Gild
// realm directly, at the moment you join and every time the page renders.
// No oracle, no admin, no off-chain list. This is the point of the Gild
// record: any realm can trust it with a single function call.
package builders

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1jw2yrfqnd4fp90qadw88pnjgpden4vgagjvpe6/gild/v0"
)

const (
	// MinTasks is how many paid Gild tasks you need before you can join.
	MinTasks = 1
	MaxPitch = 160
	MaxLink  = 200
	MaxPage  = 50
)

const (
	ErrNoProof = "builders: finish a paid task on Gild first"
	ErrPitch   = "builders: pitch must be 1 to 160 characters"
	ErrLink    = "builders: link must start with https:// and have no spaces"
	ErrNotIn   = "builders: you are not in the directory"
)

// Entry is one person in the directory. Their work stats are not stored here:
// they are read from Gild so they are always current.
type Entry struct {
	Addr     address
	Pitch    string
	Link     string
	JoinedAt time.Time
}

var (
	entries avl.Tree // address string -> *Entry
	webPath string
)

func init(cur realm) {
	webPath = strings.TrimPrefix(cur.PkgPath(), "gno.land")
}

// Join adds the caller to the directory, or updates their pitch and link.
// It fails unless the caller has finished at least MinTasks paid Gild tasks.
func Join(cur realm, pitch, link string) {
	caller := cur.Previous().Address()
	if !gild.HasCompleted(caller, MinTasks) {
		panic(ErrNoProof)
	}
	pitch = strings.TrimSpace(pitch)
	link = strings.TrimSpace(link)
	if len(pitch) == 0 || len(pitch) > MaxPitch || hasControl(pitch) {
		panic(ErrPitch)
	}
	if link != "" && !isLink(link) {
		panic(ErrLink)
	}
	key := caller.String()
	if v := entries.Get(key); v != nil {
		e := v.(*Entry)
		e.Pitch, e.Link = pitch, link
		return
	}
	entries.Set(key, &Entry{Addr: caller, Pitch: pitch, Link: link, JoinedAt: time.Now()})
}

// Leave removes the caller from the directory.
func Leave(cur realm) {
	key := cur.Previous().Address().String()
	if _, removed := entries.Remove(key); !removed {
		panic(ErrNotIn)
	}
}

// IsListed reports whether addr is in the directory.
func IsListed(addr address) bool {
	return entries.Has(addr.String())
}

// Size returns how many people are listed.
func Size() int { return entries.Size() }

// BuildersJSON lists entries with their live Gild stats.
func BuildersJSON(offset, limit int) string {
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 || limit > MaxPage {
		limit = MaxPage
	}
	var b strings.Builder
	b.WriteString(`{"total":`)
	b.WriteString(strconv.Itoa(entries.Size()))
	b.WriteString(`,"items":[`)
	first := true
	entries.IterateByOffset(offset, limit, func(_ string, v any) bool {
		e := v.(*Entry)
		if !first {
			b.WriteByte(',')
		}
		first = false
		b.WriteString(`{"address":`)
		b.WriteString(jsonStr(e.Addr.String()))
		b.WriteString(`,"pitch":`)
		b.WriteString(jsonStr(e.Pitch))
		b.WriteString(`,"link":`)
		b.WriteString(jsonStr(e.Link))
		b.WriteString(`,"completed":`)
		b.WriteString(strconv.Itoa(gild.Completed(e.Addr)))
		b.WriteString(`,"earned":`)
		b.WriteString(strconv.FormatInt(gild.Earned(e.Addr), 10))
		b.WriteString(`,"joinedAt":`)
		b.WriteString(strconv.FormatInt(e.JoinedAt.Unix(), 10))
		b.WriteByte('}')
		return false
	})
	b.WriteString("]}")
	return b.String()
}

// Render shows the directory on gno.land.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Gild Builders\n\n")
	b.WriteString("People with proven, paid work on [Gild](/r/" + gildPath() + "). ")
	b.WriteString("To join, finish at least ")
	b.WriteString(strconv.Itoa(MinTasks))
	b.WriteString(" paid task, then call `Join`. Stats below are read live from Gild.\n\n")
	if entries.Size() == 0 {
		b.WriteString("_Nobody has joined yet._\n")
		return b.String()
	}
	b.WriteString("| Builder | Tasks done | Earned | Pitch |\n|---|---|---|---|\n")
	entries.Iterate("", "", func(_ string, v any) bool {
		e := v.(*Entry)
		addr := e.Addr.String()
		short := addr[:8] + "…" + addr[len(addr)-4:]
		b.WriteString("| [" + short + "](" + "/r/" + gildPath() + ":u/" + addr + ") | ")
		b.WriteString(strconv.Itoa(gild.Completed(e.Addr)))
		b.WriteString(" | ")
		b.WriteString(gnot(gild.Earned(e.Addr)))
		b.WriteString(" | ")
		b.WriteString(mdText(e.Pitch))
		if e.Link != "" {
			b.WriteString(" ([link](" + e.Link + "))")
		}
		b.WriteString(" |\n")
		return false
	})
	return b.String()
}

// gildPath is the Gild realm path without the gno.land/r/ prefix, derived from
// this realm's own namespace so it works wherever both are deployed.
func gildPath() string {
	p := strings.TrimPrefix(webPath, "/r/")
	if i := strings.Index(p, "/"); i >= 0 {
		return p[:i] + "/gild/v0"
	}
	return "gild/v0"
}

func hasControl(s string) bool {
	for _, r := range s {
		if r < 0x20 || r == 0x7f {
			return true
		}
	}
	return false
}

func isLink(s string) bool {
	if len(s) > MaxLink || !strings.HasPrefix(s, "https://") || len(s) <= len("https://") {
		return false
	}
	for _, r := range s {
		if r <= ' ' || r == 0x7f || strings.ContainsRune("\"<>`()[]|", r) {
			return false
		}
	}
	return true
}

func gnot(u int64) string {
	whole := u / 1_000_000
	frac := u % 1_000_000
	s := strconv.FormatInt(whole, 10)
	if frac != 0 {
		f := strconv.FormatInt(frac+1_000_000, 10)[1:]
		s += "." + strings.TrimRight(f, "0")
	}
	return s + " GNOT"
}

// mdText escapes characters that would change markdown or table layout.
func mdText(s string) string {
	var b strings.Builder
	for _, r := range s {
		if strings.ContainsRune("\\`*_[]()<>#|!~", r) {
			b.WriteByte('\\')
		}
		b.WriteRune(r)
	}
	return b.String()
}

func jsonStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			b.WriteString(`\"`)
		case r == '\\':
			b.WriteString(`\\`)
		case r < 0x20 || r == '<' || r == '>' || r == '&' || r == 0x2028 || r == 0x2029:
			h := strconv.FormatInt(int64(r), 16)
			b.WriteString(`\u` + strings.Repeat("0", 4-len(h)) + h)
		default:
			b.WriteRune(r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

package tavernodds

// LMSR pricing for Tavern Odds — binary prediction market (Gno.land).
//
// Port of the Prophet LMSR math (Solana, f64) to int64 fixed point.
// Gno has no floats, so every real number x is carried as a scaled
// integer: xScaled = round(x * scale).
//
// Formulas (qYes/qNo = outstanding YES/NO shares, b = liquidity):
//
//	C(qy, qn) = b * ln(exp(qy/b) + exp(qn/b))
//	price(YES) = exp(qy/b) / (exp(qy/b) + exp(qn/b)) = sigmoid((qy-qn)/b)
//
// Cost uses the numerically stable log-sum-exp form with
// m = max(qy, qn)/b:
//
//	C = b * (m + ln(exp(qy/b - m) + exp(qn/b - m)))
//
// so exp is only ever evaluated on (-inf, 0] and ln only on [1, 2].
//
// # Scales
//
// LMSRScale (1e6) is the fixed-point scale of this package's public
// interface: one LMSRScale unit = 1e-6 of a unit. Amounts themselves
// (q, b, costs) are plain ugnot integers (1 GNOT = 1e6 ugnot); the
// scale only quantises the fractional math inside.
//
// Internally exp/ln run at 1e9 (lmsrInternalScale), NOT 1e6. Reason:
// a 1e6-scale exp has rounding ~1e-6, which becomes a cost error of
// ~b*1e-6 ugnot (100 ugnot at b=1e8) — enough to swamp sub-100-ugnot
// trade deltas and even flip the sign of a 1-share buy. At 1e9 the
// measured cost error is ~b*1e-8 (see VERIFICATION below).
//
// # Primitives (all int64, deterministic, no floats)
//
//   - expNeg(x): exp(x) for x <= 0. Range reduction by ln(2):
//     x = -n*ln2 + r with r in (-ln2, 0], exp(x) = exp(r)/2^n.
//     exp(r) is a Taylor series (16 terms, |r| <= 0.694, truncation
//     < 1e-12); division by 2^n is exact repeated halving. No
//     error amplification: unlike exp(x/1024)^1024 squaring, which
//     multiplies the base rounding error by 1024, halving only ever
//     loses < 1 unit of absolute error per step.
//   - ln1to2(y): ln(y) for y in [1, 2] via the atanh series
//     ln(y) = 2*atanh(z), z = (y-1)/(y+1) in [0, 1/3],
//     9 odd terms through z^17 (truncation < 1e-10).
//   - mulDiv(a, b, d) = a*b/d computed limb-wise (a split into
//     1e6 high/low limbs) so no intermediate exceeds ~1e18.
//     Valid for 0 <= a <= 1e15, 0 <= b <= 1e10, 1 <= d <= 1e10,
//     b <= 1000*d, and (a/1e6)*d < 9e18. Every call site below
//     satisfies this (verified in lmsr_test.go's bound checks);
//     it truncates, underestimating the exact quotient by < 3 units.
//
// # Valid input ranges (correctness domain)
//
//   - b in [LMSRMinB, LMSRMaxB] = [1e6, 1e10] ugnot (1..10,000 GNOT),
//     same numerics as Prophet's MIN_B/MAX_B (0.001..10 SOL there).
//   - qYes, qNo in [0, LMSRMaxQ] = [0, 1e12] ugnot (1e6 GNOT of
//     outstanding shares — far above any realistic market).
//   - |dYes|, |dNo| <= LMSRMaxQ in lmsrCostDelta.
//   Outside this domain the public functions return 0 (invalid
//   input) instead of overflowing or panicking on division by zero.
//   lmsrCostDelta clamps a negative resulting q to 0 (selling more
//   than held is a caller bug; the realm must check balances first).
//
// # Rounding / solvency notes
//
//   - lmsrCost truncates (each mulDiv truncates); the error is
//     bounded by the tolerance below, not by a fixed direction.
//     Like the Rust code (buys ceil, sells floor), the realm should
//     charge cost+1 on buys and pay out cost on sells if it wants
//     the strict solvency direction; the raw delta here is the
//     unbiased fixed-point value.
//   - lmsrPriceBps returns YES and 10000-YES for NO, so the two
//     prices always sum to exactly 10000 bps.
//   - Seed/solvency: creator must seed at least b*ln(2); see
//     lmsrMinSeed. Since C(q) >= max(qYes, qNo) always, the vault
//     covers every outstanding winning share (1 share = 1 ugnot).
//
// # VERIFICATION (measured 2026-11-28, see lmsr_reference.py;
// sweep harness output compared by compare_sweep.py)
//
//   - Cost: max |C_gno - C_f64| = 49.3 ugnot over 716 cases (16-case
//     grid + 500-case random sweep + 200-case large-q sweep to
//     LMSRMaxQ), worst at b=1e10; tolerance max(10 ugnot, b*2e-8).
//   - Cost delta: max error 46.9 ugnot over 860 cases (incl. sells),
//     same tolerance. 1-share buy from zero: Gno 1 vs f64 0.5.
//   - Price: max |p_gno - p_f64| = 0 bps over 716 cases (tolerance
//     1 bp; differences would only be f64-vs-int rounding at .5 bp).
//   - Min seed: Gno exceeds the true ceil(b*ln2) by at most +5 ugnot
//     (b=1e10), within the documented +0..6.
//   - Primitives: exp(-ln2) exact 5e8; exp(-10 ln2) 976563 vs
//     976562.5; ln(2) 693147178 vs 693147180.6 (all at 1e9 scale).
//   - gno test: 8 tests PASS (cost, delta, price, monotone+solvent,
//     min seed, invalid inputs, exp/ln primitives, mulDiv sanity).

// LMSRScale is the fixed-point scale of this package: 1 unit = 1e-6.
const LMSRScale int64 = 1000000

// lmsrInternalScale is the scale used inside exp/ln (see header).
const lmsrInternalScale int64 = 1000000000

// LMSRMinB / LMSRMaxB bound the liquidity parameter b (ugnot).
// Same numerics as Prophet MIN_B/MAX_B; units here are ugnot
// (1e-6 GNOT) instead of lamports.
const LMSRMinB int64 = 1000000
const LMSRMaxB int64 = 10000000000

// LMSRMaxQ bounds outstanding shares per outcome (ugnot).
const LMSRMaxQ int64 = 1000000000000

// lmsrLn2Scaled is ln(2)*1e9 rounded UP (true value 693147180.56).
const lmsrLn2Scaled int64 = 693147181

// mulDiv returns a*b/d for non-negative a, b and d > 0, computed so no
// intermediate product overflows int64. See the header for the valid
// domain; all call sites in this file satisfy it. The result is the
// exact quotient truncated down, underestimating it by < 3 units.
func mulDiv(a, b, d int64) int64 {
	if a <= 0 || b <= 0 {
		return 0
	}
	ah := a / 1000000
	al := a % 1000000
	// b*1e6/d split into quotient + remainder so ah*(b*1e6)/d stays
	// exact: ah*q1 + (ah*r1)/d.
	q1 := (b * 1000000) / d
	r1 := (b * 1000000) % d
	return ah*q1 + (ah*r1)/d + (al*b)/d
}

// expNeg returns exp(x)*1e9 for x <= 0, where x is given scaled by 1e9
// (xK = x * 1e9). Returns 1e9 for x = 0 and 0 for x <= -50
// (exp(-50) ~= 1.9e-22, far below half a unit at 1e9 scale).
// Method: x = -n*ln2 + r, exp(x) = exp(r)/2^n; exp(r) by Taylor
// (|r| < ln2, 16 terms), /2^n by repeated halving.
func expNeg(xK int64) int64 {
	if xK >= 0 {
		return lmsrInternalScale
	}
	if xK <= -50*lmsrInternalScale {
		return 0
	}
	// n = floor(-x/ln2), r = x + n*ln2 in (-ln2, 0].
	n := (-xK) / lmsrLn2Scaled
	rK := xK + n*lmsrLn2Scaled
	// Taylor: exp(r) = sum r^k/k!, k = 0..15. |r| <= 0.694 (1.387 in
	// the measure-zero edge case where n is one short); term 15 is
	// < 1e-10, so the truncation error is < 1 unit at 1e9 scale.
	// |term*rK| <= 1.4e9*1.4e9 = 2e18 < 2^63, so no overflow.
	sum := lmsrInternalScale
	term := lmsrInternalScale
	for k := int64(1); k <= 15; k++ {
		num := term * rK
		if num >= 0 {
			num += lmsrInternalScale / 2
		} else {
			num -= lmsrInternalScale / 2
		}
		term = (num / lmsrInternalScale) / k
		sum += term
	}
	// Divide by 2^n by repeated halving (exact, < 1 unit lost total).
	v := sum
	for i := int64(0); i < n; i++ {
		v = (v + 1) / 2
	}
	return v
}

// ln1to2 returns ln(y)*1e9 for y in [1, 2], where y is given scaled by
// 1e9 (yK in [1e9, 2e9]). Method: z = (y-1)/(y+1) in [0, 1/3],
// ln(y) = 2*atanh(z) = 2*sum_{k>=0} z^(2k+1)/(2k+1), 9 terms through
// z^17 (series remainder < 1e-10).
func ln1to2(yK int64) int64 {
	num := yK - lmsrInternalScale
	den := yK + lmsrInternalScale
	// z = (y-1)/(y+1), scaled by 1e9, rounded to nearest.
	zK := (num*lmsrInternalScale + den/2) / den
	// z^2, scaled by 1e9.
	z2K := (zK*zK + lmsrInternalScale/2) / lmsrInternalScale
	sum := int64(0)
	pow := zK // z^(2k+1), scaled by 1e9
	for k := int64(0); k <= 8; k++ {
		div := 2*k + 1
		sum += (pow + div/2) / div
		pow = (pow*z2K + lmsrInternalScale/2) / lmsrInternalScale
	}
	return 2 * sum
}

// lmsrCost returns the LMSR cost C(qYes, qNo) = b*ln(exp(qy/b) +
// exp(qn/b)) in ugnot, via the stable log-sum-exp form. Returns 0 for
// out-of-domain inputs (see header).
func lmsrCost(qYes, qNo, b int64) int64 {
	if b < LMSRMinB || b > LMSRMaxB {
		return 0
	}
	if qYes < 0 || qNo < 0 || qYes > LMSRMaxQ || qNo > LMSRMaxQ {
		return 0
	}
	aK := mulDiv(qYes, lmsrInternalScale, b)
	cK := mulDiv(qNo, lmsrInternalScale, b)
	mK := aK
	if cK > mK {
		mK = cK
	}
	e1 := expNeg(aK - mK)
	e2 := expNeg(cK - mK)
	sumK := e1 + e2 // in [1e9, 2e9]
	lnK := ln1to2(sumK)
	return mulDiv(mK+lnK, b, lmsrInternalScale)
}

// lmsrCostDelta returns C(q+d) - C(q) in ugnot: the cost of buying
// dYes/dNo shares (positive), or the negative of the refund for
// selling (pass negative deltas). Returns 0 for out-of-domain inputs;
// a resulting negative q is clamped to 0. New q above LMSRMaxQ is
// rejected (returns 0).
func lmsrCostDelta(qYes, qNo, b, dYes, dNo int64) int64 {
	if b < LMSRMinB || b > LMSRMaxB {
		return 0
	}
	if qYes < 0 || qNo < 0 || qYes > LMSRMaxQ || qNo > LMSRMaxQ {
		return 0
	}
	if dYes < -LMSRMaxQ || dYes > LMSRMaxQ || dNo < -LMSRMaxQ || dNo > LMSRMaxQ {
		return 0
	}
	var nYes int64
	if dYes >= 0 {
		if dYes > LMSRMaxQ-qYes {
			return 0
		}
		nYes = qYes + dYes
	} else if -dYes > qYes {
		nYes = 0
	} else {
		nYes = qYes + dYes
	}
	var nNo int64
	if dNo >= 0 {
		if dNo > LMSRMaxQ-qNo {
			return 0
		}
		nNo = qNo + dNo
	} else if -dNo > qNo {
		nNo = 0
	} else {
		nNo = qNo + dNo
	}
	return lmsrCost(nYes, nNo, b) - lmsrCost(qYes, qNo, b)
}

// lmsrPriceBps returns the price of outcome `yes` in basis points
// (0..10000). price(YES) = sigmoid((qYes-qNo)/b); price(NO) is
// exactly 10000 - price(YES). Returns 0 for out-of-domain inputs.
func lmsrPriceBps(qYes, qNo, b int64, yes bool) int64 {
	if b < LMSRMinB || b > LMSRMaxB {
		return 0
	}
	if qYes < 0 || qNo < 0 || qYes > LMSRMaxQ || qNo > LMSRMaxQ {
		return 0
	}
	diff := qYes - qNo // in [-1e12, 1e12]
	var tK int64
	if diff >= 0 {
		tK = mulDiv(diff, lmsrInternalScale, b)
	} else {
		tK = -mulDiv(-diff, lmsrInternalScale, b)
	}
	var pYes int64
	switch {
	case tK >= 50*lmsrInternalScale:
		pYes = 10000
	case tK <= -50*lmsrInternalScale:
		pYes = 0
	case tK >= 0:
		// p = 1/(1+exp(-t)); exp(-t) in (0, 1].
		e := expNeg(-tK)
		den := lmsrInternalScale + e
		pYes = (10000*lmsrInternalScale + den/2) / den
	default:
		// p = exp(t)/(1+exp(t)); exp(t) in (0, 1).
		e := expNeg(tK)
		den := lmsrInternalScale + e
		pYes = (10000*e + den/2) / den
	}
	if yes {
		return pYes
	}
	return 10000 - pYes
}

// lmsrMinSeed returns the minimum creator seed for liquidity b:
// ceil(b*ln(2)) in ugnot. It overestimates the true ceiling by at
// most 6 ugnot (ln2 is rounded up at 1e9 scale, plus the +1 covers
// the floor truncation) — safe direction for a minimum-seed check.
// Returns 0 for out-of-domain b.
func lmsrMinSeed(b int64) int64 {
	if b < LMSRMinB || b > LMSRMaxB {
		return 0
	}
	return mulDiv(b, lmsrLn2Scaled, lmsrInternalScale) + 1
}

package tavernodds

// Tests for the fixed-point LMSR math in lmsr.gno.
//
// Expected values are taken from lmsr_reference.py (plain f64 port of
// the Rust Prophet math), rounded to the nearest integer. Gno results
// must agree within the stated tolerances — the Python is never
// adjusted to match the Gno code.
//
// Tolerances (measured maxima over a 716-cost / 860-delta / 716-price
// sweep, incl. q up to LMSRMaxQ, are ~4x inside these bounds):
//   - cost / cost-delta: max(10 ugnot, b*2e-8)  [worst observed 49 ugnot at b=1e10]
//   - price: 1 bp (worst observed 0 bps over 716 cases)
//   - exp/ln primitives: 10 units at 1e9 scale (worst observed ~3)
//   - min seed: true ceil <= got <= ceil+6 (worst observed +5)

import "testing"

// costTol is the allowed |gno - f64| for a cost/delta at liquidity b.
func costTol(b int64) int64 {
	tol := b / 50000000 // b*2e-8
	if tol < 10 {
		tol = 10
	}
	return tol
}

func abs64(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func TestLMSRCost(t *testing.T) {
	cases := []struct {
		qy, qn, b int64
		want      int64 // f64 reference, rounded
	}{
		{0, 0, 100000000, 69314718},              // b*ln2
		{0, 0, 1000000, 693147},                  // b*ln2, min b
		{0, 0, 10000000000, 6931471806},          // b*ln2, max b
		{1000000000, 1000000000, 100000000, 1069314718},
		{10000000, 10000000, 100000000, 79314718},
		{100000000, 0, 100000000, 131326169}, // one-sided YES
		{0, 100000000, 100000000, 131326169}, // one-sided NO (symmetric)
		{50000000, 30000000, 100000000, 109813887},
		{30000000, 50000000, 100000000, 109813887},
		{1000000000, 0, 100000000, 1000004540},
		{1000000000, 500000000, 100000000, 1000671535},
		{10000000, 0, 100000000, 74439666},
		{5000000, 2000000, 1000000, 5048587},
		{50000000000, 30000000000, 10000000000, 51269280110},
		{1000000000000, 1000000000, 100000000, 1000000000000}, // exp(-9990) -> 0
		{1000000000000, 1000000000000, 1000000, 1000000693147},
	}
	for _, c := range cases {
		got := lmsrCost(c.qy, c.qn, c.b)
		if d := abs64(got - c.want); d > costTol(c.b) {
			t.Errorf("lmsrCost(%d,%d,%d) = %d, want %d (err %d > tol %d)",
				c.qy, c.qn, c.b, got, c.want, d, costTol(c.b))
		}
	}
}

func TestLMSRCostDelta(t *testing.T) {
	cases := []struct {
		qy, qn, b, dy, dn int64
		want              int64 // f64 reference, rounded
	}{
		{0, 0, 100000000, 10000000, 0, 5124948},       // buy YES from zero
		{0, 0, 100000000, 0, 10000000, 5124948},      // buy NO from zero
		{100000000, 0, 100000000, 10000000, 0, 7407364}, // buy YES when dear
		{0, 0, 100000000, 1, 0, 1},                   // 1-share buy, true 0.5
		{0, 0, 100000000, 1000, 0, 500},              // true 500.001
		{10000000, 0, 100000000, -10000000, 0, -5124948}, // sell all YES
		{50000000, 30000000, 100000000, 0, -5000000, -2219945},
		{0, 0, 100000000, 10000000, 10000000, 10000000}, // buy both = shares
		{0, 0, 1000000, 100000, 0, 51249},            // small b
		{0, 0, 100000000, 500000000, 0, 431356817},    // large buy
	}
	for _, c := range cases {
		got := lmsrCostDelta(c.qy, c.qn, c.b, c.dy, c.dn)
		if d := abs64(got - c.want); d > costTol(c.b) {
			t.Errorf("lmsrCostDelta(%d,%d,%d,%d,%d) = %d, want %d (err %d > tol %d)",
				c.qy, c.qn, c.b, c.dy, c.dn, got, c.want, d, costTol(c.b))
		}
	}
	// Sell is the exact negative of the corresponding buy.
	buy := lmsrCostDelta(0, 0, 100000000, 10000000, 0)
	sell := lmsrCostDelta(10000000, 0, 100000000, -10000000, 0)
	if buy+sell != 0 {
		t.Errorf("buy+sell roundtrip = %d, want 0 (buy %d, sell %d)", buy+sell, buy, sell)
	}
	// Buying YES when YES is already expensive costs more per share.
	cheap := lmsrCostDelta(0, 0, 100000000, 10000000, 0)
	dear := lmsrCostDelta(100000000, 0, 100000000, 10000000, 0)
	if !(dear > cheap) {
		t.Errorf("dear buy %d should exceed cheap buy %d", dear, cheap)
	}
	// Selling more than held clamps to selling everything held.
	over := lmsrCostDelta(100, 0, 100000000, -200, 0)
	all := lmsrCostDelta(100, 0, 100000000, -100, 0)
	if over != all {
		t.Errorf("oversell %d should equal sell-all %d", over, all)
	}
}

func TestLMSRPriceBps(t *testing.T) {
	cases := []struct {
		qy, qn, b int64
		wantYes   int64
	}{
		{0, 0, 100000000, 5000},
		{10000000, 0, 100000000, 5250},
		{20000000, 0, 100000000, 5498},
		{50000000, 0, 100000000, 6225},
		{100000000, 0, 100000000, 7311},
		{500000000, 0, 100000000, 9933},
		{0, 100000000, 100000000, 2689},
		{50000000, 30000000, 100000000, 5498},
		{30000000, 50000000, 100000000, 4502},
		{1000000000, 0, 100000000, 10000}, // extreme YES
		{0, 1000000000, 100000000, 0},     // extreme NO
		{50000000, 0, 1000000, 10000},     // extreme at min b
		{0, 50000000, 1000000, 0},
		{1000001, 1000000, 100000000, 5000}, // 1-ugnot difference: still 50/50
		{1000000000, 1000000000, 100000000, 5000},
		{5000000000, 0, 10000000000, 6225},
	}
	for _, c := range cases {
		gotYes := lmsrPriceBps(c.qy, c.qn, c.b, true)
		gotNo := lmsrPriceBps(c.qy, c.qn, c.b, false)
		if d := abs64(gotYes - c.wantYes); d > 1 {
			t.Errorf("lmsrPriceBps(%d,%d,%d,YES) = %d, want %d",
				c.qy, c.qn, c.b, gotYes, c.wantYes)
		}
		if gotYes+gotNo != 10000 {
			t.Errorf("prices sum %d + %d != 10000 at (%d,%d,%d)",
				gotYes, gotNo, c.qy, c.qn, c.b)
		}
	}
	// Monotone in qYes: price never decreases as YES shares grow.
	prev := int64(-1)
	for _, q := range []int64{0, 10000000, 20000000, 50000000, 100000000, 500000000} {
		p := lmsrPriceBps(q, 0, 100000000, true)
		if p < prev {
			t.Errorf("price not monotone: %d after %d at q=%d", p, prev, q)
		}
		prev = p
	}
	if prev <= 9000 {
		t.Errorf("deep YES price %d should exceed 9000", prev)
	}
}

func TestLMSRMonotoneAndSolvent(t *testing.T) {
	b := int64(100000000)
	// Cost increases with either side's shares.
	states := [][2]int64{
		{0, 0}, {10000000, 0}, {0, 10000000}, {50000000, 30000000},
		{1000000000, 1000000000}, {1000000000, 0}, {1000000000000, 1000000000},
	}
	for _, s := range states {
		c := lmsrCost(s[0], s[1], b)
		// Solvency: C(q) >= max(qy, qn), up to the fixed-point tolerance.
		mx := s[0]
		if s[1] > mx {
			mx = s[1]
		}
		if c+costTol(b) < mx {
			t.Errorf("C(%d,%d) = %d < max q %d", s[0], s[1], c, mx)
		}
	}
	// Strictly increasing along the YES axis.
	prev := lmsrCost(0, 0, b)
	for _, q := range []int64{1, 1000, 10000000, 100000000, 1000000000} {
		c := lmsrCost(q, 0, b)
		if c <= prev {
			t.Errorf("cost not increasing: C(%d,0)=%d <= C(prev)=%d", q, c, prev)
		}
		prev = c
	}
}

func TestLMSRMinSeed(t *testing.T) {
	// want = ceil(b*ln2) from the f64 reference.
	cases := []struct {
		b    int64
		want int64
	}{
		{1000000, 693148},
		{100000000, 69314719},
		{10000000000, 6931471806},
	}
	for _, c := range cases {
		got := lmsrMinSeed(c.b)
		if got < c.want || got-c.want > 6 {
			t.Errorf("lmsrMinSeed(%d) = %d, want ceil %d (+0..6)", c.b, got, c.want)
		}
	}
	if got := lmsrMinSeed(0); got != 0 {
		t.Errorf("lmsrMinSeed(0) = %d, want 0", got)
	}
}

func TestLMSRInvalidInputs(t *testing.T) {
	// Out-of-domain inputs return 0 instead of overflowing/panicking.
	if got := lmsrCost(0, 0, 0); got != 0 {
		t.Errorf("lmsrCost b=0 = %d, want 0", got)
	}
	if got := lmsrCost(0, 0, 999999); got != 0 {
		t.Errorf("lmsrCost b<MIN = %d, want 0", got)
	}
	if got := lmsrCost(0, 0, 10000000001); got != 0 {
		t.Errorf("lmsrCost b>MAX = %d, want 0", got)
	}
	if got := lmsrCost(-1, 0, 100000000); got != 0 {
		t.Errorf("lmsrCost q<0 = %d, want 0", got)
	}
	if got := lmsrCost(1000000000001, 0, 100000000); got != 0 {
		t.Errorf("lmsrCost q>MAX = %d, want 0", got)
	}
	if got := lmsrPriceBps(0, 0, 0, true); got != 0 {
		t.Errorf("lmsrPriceBps b=0 = %d, want 0", got)
	}
	if got := lmsrCostDelta(0, 0, 100000000, 1000000000001, 0); got != 0 {
		t.Errorf("lmsrCostDelta d>MAX = %d, want 0", got)
	}
	if got := lmsrCostDelta(0, 0, 100000000, 0, 0); got != 0 {
		t.Errorf("lmsrCostDelta zero trade = %d, want 0", got)
	}
}

func TestLMSRExpLnPrimitives(t *testing.T) {
	// exp(0) = 1 and exp(-50) ~ 0 are exact by construction.
	if got := expNeg(0); got != 1000000000 {
		t.Errorf("expNeg(0) = %d, want 1000000000", got)
	}
	if got := expNeg(-50000000000); got != 0 {
		t.Errorf("expNeg(-50) = %d, want 0", got)
	}
	// exp(-ln2) = 0.5 exactly (up to primitive tolerance).
	if got := expNeg(-693147181); abs64(got-500000000) > 10 {
		t.Errorf("expNeg(-ln2) = %d, want 500000000", got)
	}
	// exp(-10 ln2) = 1/1024 = 976562.5 (scaled).
	if got := expNeg(-6931471810); abs64(got-976563) > 10 {
		t.Errorf("expNeg(-10 ln2) = %d, want 976563", got)
	}
	// ln(1) = 0 exactly; ln(2) and ln(1.5) from f64.
	if got := ln1to2(1000000000); got != 0 {
		t.Errorf("ln1to2(1) = %d, want 0", got)
	}
	if got := ln1to2(2000000000); abs64(got-693147181) > 10 {
		t.Errorf("ln1to2(2) = %d, want 693147181", got)
	}
	if got := ln1to2(1500000000); abs64(got-405465108) > 10 {
		t.Errorf("ln1to2(1.5) = %d, want 405465108", got)
	}
}

func TestMulDivSanity(t *testing.T) {
	if got := mulDiv(7, 3, 2); got != 10 {
		t.Errorf("mulDiv(7,3,2) = %d, want 10", got)
	}
	if got := mulDiv(1000000000000, 1000000000, 100000000); got != 10000000000000 {
		t.Errorf("mulDiv(1e12,1e9,1e8) = %d, want 1e13", got)
	}
	// (1e15 * 1e10) / 1e9 = 1e16 — the largest product this helper is used for.
	if got := mulDiv(1000000000000000, 10000000000, 1000000000); got != 10000000000000000 {
		t.Errorf("mulDiv(1e15,1e10,1e9) = %d, want 1e16", got)
	}
}

// Package tavernodds is a binary prediction-market realm on Gno.land.
//
// Anyone can create a YES/NO market (question + close time) by seeding
// it with enough ugnot to cover the market maker's worst-case loss.
// Traders buy/sell YES/NO shares priced by an LMSR (lmsr.gno,
// fixed-point port of the Prophet formulas). A designated resolver resolves the outcome after the
// close time; after a 24h dispute window, winning shares redeem 1:1
// for ugnot and losing shares are worth 0.
//
// Design notes (mirrors the Solana Prophet program this was ported from):
//   - Solvency: the creator must seed at least ceil(b*ln(2)) ugnot
//     (lmsrMinSeed). Since C(q) >= max(qYes,qNo) always, the vault
//     always covers every outstanding winning share. Buys are charged
//     the raw LMSR delta + 1 ugnot (the fixed-point delta truncates,
//     so +1 keeps the strict solvency direction, as lmsr.gno documents);
//     sells pay the raw delta. Quotes (QuoteBuy/QuoteSell) use the same
//     values Buy/Sell charge, so a quoted cost is always exact.
//   - Clock: Gno has no wall-clock syscall; time.Now() returns the
//     block time (the chain sets it from the block header), and
//     runtime.ChainHeight() is the block height. Close/dispute times
//     are unix seconds of block time, matching Prophet's expiry_ts.
//   - Payments are push-only: there is no transferFrom in Gno. Buyers
//     and creators attach ugnot with `-send`; the realm verifies the
//     envelope with unsafe.OriginSend() AND requires a direct EOA
//     caller (cur.Previous().IsUserCall()) — the pair is required, see
//     docs/resources/effective-gno.md "Verifying inbound Coin payments".
//     Without the EOA guard an intermediate `maketx run` realm could
//     consume the envelope and leave OriginSend() describing a phantom
//     payment. Payouts (sell refunds, redemptions) use a RealmSend
//     banker constructed fresh in each call.
//   - Shares are GRC20 tokens: two per market (YES/NO), minted/burned
//     by this realm's PrivateLedger. They are NOT registered in
//     grc20reg (per-market symbols like YES1/NO1 would collide in the
//     registry's symbol-keyed index); balances are readable via
//     BalanceOf / the token's own Render. This keeps the realm small:
//     storage deposit is 100 ugnot/byte, so no registry, no fees, no
//     sweep — leftover vault funds after all redemptions stay locked
//     (a creator sweep is future work).
//   - Double-redeem is prevented twice: a redeemed flag per
//     (market, user) AND burning the winning shares on redeem, so a
//     second redeem finds a zero balance.
package tavernodds

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/seqid/v0"
)

// Module path of this realm (used to derive its on-chain address).
const pkgPath = "gno.land/r/g1lm95v9pqlxtxwc9k8m0rw87agjx5nk3d7waz6l/tavernodds"

// Outcomes.
const (
	OutcomeUnresolved = 0
	OutcomeYes        = 1
	OutcomeNo         = 2
)

// Bounds and windows.
const (
	MinB             int64 = 1000000     // 1 GNOT of liquidity parameter b
	MaxB             int64 = 10000000000 // 10_000 GNOT
	MaxQuestionLen         = 128
	DisputeWindow    int64 = 86400 // 24h of block time between resolve and redeem
	ugnotDenom             = "ugnot"
)

// Market is one binary prediction market. Token/ledger pointers live in
// realm state (same pattern as the GRC20 factory, which stores token +
// ledger pointers in an AVL tree); they are never returned to callers —
// see GetMarket, which returns a plain-data MarketView instead.
type Market struct {
	ID               uint64
	Question         string
	Creator          address
	Resolver         address
	CloseTime        int64 // unix seconds (block time)
	LiquidityB       int64
	QYes             int64
	QNo              int64
	Resolved         bool
	Outcome          int
	ResolveTime      int64
	DisputeEndTime   int64
	SeededCollateral int64
	YesToken         *grc20.Token
	YesLedger        *grc20.PrivateLedger
	NoToken          *grc20.Token
	NoLedger         *grc20.PrivateLedger
	Redeemed         map[address]bool
}

// MarketView is the read-only, pointer-free view of a Market.
type MarketView struct {
	ID               uint64
	Question         string
	Creator          address
	Resolver         address
	CloseTime        int64
	LiquidityB       int64
	QYes             int64
	QNo              int64
	Resolved         bool
	Outcome          int
	ResolveTime      int64
	DisputeEndTime   int64
	SeededCollateral int64
	YesPriceBps      int64
	NoPriceBps       int64
	YesSupply        int64
	NoSupply         int64
}

var (
	markets      []*Market
	nextMarketID uint64
	nextTokenID  seqid.ID
)

// nowUnix returns the current block time as unix seconds.
func nowUnix() int64 {
	return time.Now().Unix()
}

// realmAddr returns this realm's on-chain address.
func realmAddr() address {
	return chain.PackageAddress(pkgPath)
}

func mustMarket(marketID uint64) *Market {
	if marketID == 0 || marketID > uint64(len(markets)) {
		panic("market not found")
	}
	return markets[marketID-1]
}

// requireEOA panics unless the caller is a direct EOA call
// (gnokey maketx call). Must be paired with an OriginSend() amount
// check whenever the function accepts payment — see package docs.
func requireEOA(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by a user (maketx call)")
	}
}

func callerOf(cur realm) address {
	return cur.Previous().Address()
}

// payOut sends amount ugnot from this realm to `to`. No-op for 0.
func payOut(cur realm, to address, amount int64) {
	if amount == 0 {
		return
	}
	if amount < 0 {
		panic("payout must be >= 0")
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.Coins{{Denom: ugnotDenom, Amount: amount}})
}

func checkErr(err error) {
	if err != nil {
		panic(err.Error())
	}
}

// CreateMarket opens a new market. The creator attaches the seed
// collateral with `-send` (at least lmsrMinSeed(b) = ceil(b*ln2) ugnot);
// any excess stays in the vault as extra coverage. The resolver is
// the only address that may later call Resolve. Returns the market ID.
func CreateMarket(cur realm, question string, closeTime int64, liquidityB int64, resolver address) uint64 {
	requireEOA(cur)
	if len(question) == 0 || len(question) > MaxQuestionLen {
		panic("question must be 1..128 bytes")
	}
	if closeTime <= nowUnix() {
		panic("close time must be in the future")
	}
	if liquidityB < MinB || liquidityB > MaxB {
		panic("liquidity b out of range")
	}
	if !resolver.IsValid() {
		panic("resolver address invalid")
	}
	minSeed := lmsrMinSeed(liquidityB)
	if minSeed <= 0 {
		panic("invalid liquidity b")
	}
	paid := unsafe.OriginSend().AmountOf(ugnotDenom)
	if paid < minSeed {
		panic("seed below b*ln(2): vault could not cover winners")
	}

	creator := callerOf(cur)
	nextMarketID++
	id := nextMarketID

	yesToken, yesLedger := grc20.NewToken(
		"Tavern Odds YES #"+strconv.FormatUint(id, 10),
		"YES"+strconv.FormatUint(id, 10),
		0, nextTokenID.Next(), cur)
	noToken, noLedger := grc20.NewToken(
		"Tavern Odds NO #"+strconv.FormatUint(id, 10),
		"NO"+strconv.FormatUint(id, 10),
		0, nextTokenID.Next(), cur)

	markets = append(markets, &Market{
		ID:               id,
		Question:         question,
		Creator:          creator,
		Resolver:         resolver,
		CloseTime:        closeTime,
		LiquidityB:       liquidityB,
		QYes:             0,
		QNo:              0,
		Resolved:         false,
		Outcome:          OutcomeUnresolved,
		ResolveTime:      0,
		DisputeEndTime:   0,
		SeededCollateral: paid,
		YesToken:         yesToken,
		YesLedger:        yesLedger,
		NoToken:          noToken,
		NoLedger:         noLedger,
		Redeemed:         make(map[address]bool),
	})
	return id
}

// Buy mints `shares` YES/NO shares to the caller. The exact LMSR cost
// in ugnot must be attached with `-send`; cost must not exceed maxCost.
// The cost is the raw LMSR delta + 1 ugnot (see package docs for why).
// Returns the cost paid.
func Buy(cur realm, marketID uint64, outcome int, shares int64, maxCost int64) int64 {
	requireEOA(cur)
	m := mustMarket(marketID)
	if m.Resolved {
		panic("market already resolved")
	}
	if nowUnix() >= m.CloseTime {
		panic("market closed")
	}
	if outcome != OutcomeYes && outcome != OutcomeNo {
		panic("outcome must be YES (1) or NO (2)")
	}
	if shares <= 0 {
		panic("shares must be > 0")
	}
	dYes, dNo := shares, int64(0)
	if outcome == OutcomeNo {
		dYes, dNo = int64(0), shares
	}
	// Reject quantities outside the LMSR domain before pricing: the
	// pricing returns 0 out of domain, which must never be mistaken
	// for a real (free) price.
	if outcome == OutcomeYes && shares > LMSRMaxQ-m.QYes {
		panic("shares exceed LMSR quantity domain")
	}
	if outcome == OutcomeNo && shares > LMSRMaxQ-m.QNo {
		panic("shares exceed LMSR quantity domain")
	}
	cost := lmsrCostDelta(m.QYes, m.QNo, m.LiquidityB, dYes, dNo) + 1
	if cost > maxCost {
		panic("cost exceeds maxCost")
	}
	paid := unsafe.OriginSend().AmountOf(ugnotDenom)
	if paid != cost {
		panic("must send exactly the cost in ugnot")
	}

	buyer := callerOf(cur)
	if outcome == OutcomeYes {
		checkErr(m.YesLedger.Mint(buyer, shares))
		m.QYes += shares
	} else {
		checkErr(m.NoLedger.Mint(buyer, shares))
		m.QNo += shares
	}
	return cost
}

// Sell burns `shares` YES/NO shares and refunds the LMSR value in
// ugnot; the refund must be at least minOut. Returns the refund.
func Sell(cur realm, marketID uint64, outcome int, shares int64, minOut int64) int64 {
	m := mustMarket(marketID)
	if m.Resolved {
		panic("market already resolved")
	}
	if nowUnix() >= m.CloseTime {
		panic("market closed")
	}
	if outcome != OutcomeYes && outcome != OutcomeNo {
		panic("outcome must be YES (1) or NO (2)")
	}
	if shares <= 0 {
		panic("shares must be > 0")
	}
	seller := callerOf(cur)
	dYes, dNo := shares, int64(0)
	if outcome == OutcomeNo {
		dYes, dNo = int64(0), shares
	}
	// Balances are read from the token (read API); mint/burn go
	// through the ledger (write API).
	var balance int64
	if outcome == OutcomeYes {
		balance = m.YesToken.BalanceOf(seller)
	} else {
		balance = m.NoToken.BalanceOf(seller)
	}
	if balance < shares {
		panic("not enough shares")
	}
	// Refund is C(old) - C(new): pass negative deltas.
	refund := -lmsrCostDelta(m.QYes, m.QNo, m.LiquidityB, -dYes, -dNo)
	if refund <= 0 {
		panic("refund must be > 0")
	}
	if refund < minOut {
		panic("refund below minOut")
	}

	if outcome == OutcomeYes {
		checkErr(m.YesLedger.Burn(seller, shares))
		m.QYes -= shares
	} else {
		checkErr(m.NoLedger.Burn(seller, shares))
		m.QNo -= shares
	}
	payOut(cur, seller, refund)
	return refund
}

// Resolve sets the outcome. Only the designated resolver may call it,
// only after the close time. Redemption unlocks after the dispute
// window (DisputeWindow seconds) so a wrong resolution can be
// challenged off-chain before funds move.
func Resolve(cur realm, marketID uint64, outcome int) {
	m := mustMarket(marketID)
	if m.Resolved {
		panic("market already resolved")
	}
	if callerOf(cur) != m.Resolver {
		panic("only the designated resolver can resolve")
	}
	if nowUnix() < m.CloseTime {
		panic("market not closed yet")
	}
	if outcome != OutcomeYes && outcome != OutcomeNo {
		panic("outcome must be YES (1) or NO (2)")
	}
	m.Resolved = true
	m.Outcome = outcome
	m.ResolveTime = nowUnix()
	m.DisputeEndTime = m.ResolveTime + DisputeWindow
}

// Redeem pays the caller 1 ugnot per winning share (losing shares pay
// 0) and burns the winning shares. Only after the dispute window ends,
// and only once per user per market. Returns the payout in ugnot.
func Redeem(cur realm, marketID uint64) int64 {
	m := mustMarket(marketID)
	if !m.Resolved {
		panic("market not resolved yet")
	}
	if nowUnix() < m.DisputeEndTime {
		panic("dispute window still open")
	}
	caller := callerOf(cur)
	if m.Redeemed[caller] {
		panic("already redeemed")
	}
	m.Redeemed[caller] = true

	var winToken *grc20.Token
	var winLedger *grc20.PrivateLedger
	if m.Outcome == OutcomeYes {
		winToken, winLedger = m.YesToken, m.YesLedger
	} else {
		winToken, winLedger = m.NoToken, m.NoLedger
	}
	win := winToken.BalanceOf(caller)
	if win > 0 {
		checkErr(winLedger.Burn(caller, win))
		payOut(cur, caller, win)
	}
	return win
}

// ---- read-only views (no realm handle needed) ----

// MarketCount returns the number of markets created.
func MarketCount() int {
	return len(markets)
}

// GetMarket returns a pointer-free snapshot of a market.
func GetMarket(marketID uint64) MarketView {
	m := mustMarket(marketID)
	return MarketView{
		ID:               m.ID,
		Question:         m.Question,
		Creator:          m.Creator,
		Resolver:         m.Resolver,
		CloseTime:        m.CloseTime,
		LiquidityB:       m.LiquidityB,
		QYes:             m.QYes,
		QNo:              m.QNo,
		Resolved:         m.Resolved,
		Outcome:          m.Outcome,
		ResolveTime:      m.ResolveTime,
		DisputeEndTime:   m.DisputeEndTime,
		SeededCollateral: m.SeededCollateral,
		YesPriceBps:      lmsrPriceBps(m.QYes, m.QNo, m.LiquidityB, true),
		NoPriceBps:       lmsrPriceBps(m.QYes, m.QNo, m.LiquidityB, false),
		YesSupply:        m.YesToken.TotalSupply(),
		NoSupply:         m.NoToken.TotalSupply(),
	}
}

// PriceBps returns the current price of one side in basis points.
func PriceBps(marketID uint64, yes bool) int64 {
	m := mustMarket(marketID)
	return lmsrPriceBps(m.QYes, m.QNo, m.LiquidityB, yes)
}

// BalanceOf returns a user's YES (yes=true) or NO share balance.
func BalanceOf(marketID uint64, owner address, yes bool) int64 {
	m := mustMarket(marketID)
	if yes {
		return m.YesToken.BalanceOf(owner)
	}
	return m.NoToken.BalanceOf(owner)
}

// QuoteBuy returns the ugnot cost of buying `shares` of one side —
// exactly what Buy would charge (raw LMSR delta + 1 ugnot).
func QuoteBuy(marketID uint64, outcome int, shares int64) int64 {
	m := mustMarket(marketID)
	if outcome != OutcomeYes && outcome != OutcomeNo {
		panic("outcome must be YES (1) or NO (2)")
	}
	if shares <= 0 {
		panic("shares must be > 0")
	}
	dYes, dNo := shares, int64(0)
	if outcome == OutcomeNo {
		dYes, dNo = int64(0), shares
	}
	if outcome == OutcomeYes && shares > LMSRMaxQ-m.QYes {
		panic("shares exceed LMSR quantity domain")
	}
	if outcome == OutcomeNo && shares > LMSRMaxQ-m.QNo {
		panic("shares exceed LMSR quantity domain")
	}
	return lmsrCostDelta(m.QYes, m.QNo, m.LiquidityB, dYes, dNo) + 1
}

// QuoteSell returns the ugnot refund of selling `shares` of one side.
func QuoteSell(marketID uint64, outcome int, shares int64) int64 {
	m := mustMarket(marketID)
	if outcome != OutcomeYes && outcome != OutcomeNo {
		panic("outcome must be YES (1) or NO (2)")
	}
	if shares <= 0 {
		panic("shares must be > 0")
	}
	dYes, dNo := shares, int64(0)
	if outcome == OutcomeNo {
		dYes, dNo = int64(0), shares
	}
	return -lmsrCostDelta(m.QYes, m.QNo, m.LiquidityB, -dYes, -dNo)
}

// VaultBalance returns the realm's ugnot balance (seed + buys -
// refunds - redemptions). Read-only banker; cheap single-denom read.
func VaultBalance() int64 {
	return banker.NewReadonlyBanker().GetCoin(realmAddr(), ugnotDenom)
}

// Tests for the Tavern Odds market lifecycle.
//
// These tests assert BEHAVIOUR, not exact LMSR values, so they must pass
// against the real fixed-point LMSR — no assertion depends on the
// pricing curve, except the 1:1 redemption (1 winning share = 1 ugnot),
// which is a property of the market, not of the pricing.
//
// Test clock: gno test runs with a fixed block time,
// 2009-02-13T23:31:30Z (unix 1234567890). Tests set it explicitly via
// setTime and advance it the same way. Coins sent with a call are only
// an envelope record in tests (testing.SetOriginSend); the realm's
// spendable balance is funded separately with testing.IssueCoins,
// mirroring what `-send` credits on-chain.
//
// IMPORTANT: testing.SetRealm must be called DIRECTLY from the test
// function, never via a helper. The realm override attaches to the
// frame SetRealm is called from and mutates that frame's `cur`; called
// from a helper it overrides the helper's frame and the test's `cur`
// keeps the tavernodds code realm, so every EOA-guarded call panics.
// Helpers below therefore never touch the realm — each test sets its
// caller inline before calling them.
package tavernodds

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"
	"time"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// testNow is the fixed gno-test block time (2009-02-13T23:31:30Z).
const testNow = 1234567890

const testB = 1000000 // liquidity b used by most tests

func resetState() {
	markets = nil
	nextMarketID = 0
	nextTokenID = 0
}

func setTime(unix int64) {
	ctx := testing.GetContext()
	ctx.Time = time.Unix(unix, 0)
	testing.SetContext(ctx)
}

func sendCoins(amount int64) {
	testing.SetOriginSend(chain.Coins{{Denom: ugnotDenom, Amount: amount}})
}

// fundRealm credits the realm's spendable ugnot balance, simulating
// what `-send` receipts do on-chain.
func fundRealm(amount int64) {
	testing.IssueCoins(realmAddr(), chain.Coins{{Denom: ugnotDenom, Amount: amount}})
}

func traderBalance(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, ugnotDenom)
}

func minSeed() int64 {
	return lmsrMinSeed(testB)
}

// createTestMarket creates a market closing 1h after testNow, funded
// with the given seed (must be >= minSeed), and funds the realm with
// the seed. Caller must have set the creator realm first (testing.SetRealm, inline).
// Returns the market ID.
func createTestMarket(cur realm, resolver address, seed int64) uint64 {
	sendCoins(seed)
	id := CreateMarket(cross(cur), "Will it rain tomorrow?", testNow+3600, testB, resolver)
	fundRealm(seed)
	return id
}

// buyTestShares quotes, sends, buys, and funds the realm with the cost.
// Caller must have set the buyer realm first (testing.SetRealm, inline).
func buyTestShares(cur realm, id uint64, outcome int, shares int64) int64 {
	cost := QuoteBuy(id, outcome, shares)
	sendCoins(cost)
	return Buy(cross(cur), id, outcome, shares, cost)
}

func TestCreateMarket(cur realm, t *testing.T) {
	defer resetState()
	setTime(testNow)
	creator := testutils.TestAddress("creator1")
	resolver := testutils.TestAddress("resolver1")

	// Happy path with the exact minimum seed.
	testing.SetRealm(testing.NewUserRealm(creator))
	testing.SetOriginSend(chain.Coins{})
	sendCoins(minSeed())
	id := CreateMarket(cross(cur), "Will it rain tomorrow?", testNow+3600, testB, resolver)
	uassert.Equal(t, uint64(1), id)
	v := GetMarket(id)
	uassert.Equal(t, "Will it rain tomorrow?", v.Question)
	uassert.Equal(t, creator, v.Creator)
	uassert.Equal(t, resolver, v.Resolver)
	uassert.Equal(t, int64(testNow+3600), v.CloseTime)
	uassert.Equal(t, int64(testB), v.LiquidityB)
	uassert.Equal(t, int64(0), v.QYes)
	uassert.Equal(t, int64(0), v.QNo)
	uassert.False(t, v.Resolved)
	uassert.Equal(t, OutcomeUnresolved, v.Outcome)
	uassert.Equal(t, minSeed(), v.SeededCollateral)
	uassert.Equal(t, int64(5000), v.YesPriceBps)
	uassert.Equal(t, int64(5000), v.NoPriceBps)
	uassert.Equal(t, 1, MarketCount())

	// Bad inputs, each must abort with the exact panic message.
	// (AbortsWithMessage matches exactly, not by substring.)
	testing.SetRealm(testing.NewUserRealm(creator))
	testing.SetOriginSend(chain.Coins{})
	sendCoins(minSeed())
	uassert.AbortsWithMessage(t, cur, "question must be 1..128 bytes", func() {
		CreateMarket(cross(cur), "", testNow+3600, testB, resolver)
	})
	uassert.AbortsWithMessage(t, cur, "question must be 1..128 bytes", func() {
		CreateMarket(cross(cur), strings.Repeat("x", 129), testNow+3600, testB, resolver)
	})
	uassert.AbortsWithMessage(t, cur, "close time must be in the future", func() {
		CreateMarket(cross(cur), "Q?", testNow, testB, resolver)
	})
	uassert.AbortsWithMessage(t, cur, "close time must be in the future", func() {
		CreateMarket(cross(cur), "Q?", testNow-1, testB, resolver)
	})
	uassert.AbortsWithMessage(t, cur, "liquidity b out of range", func() {
		CreateMarket(cross(cur), "Q?", testNow+3600, MinB-1, resolver)
	})
	uassert.AbortsWithMessage(t, cur, "liquidity b out of range", func() {
		CreateMarket(cross(cur), "Q?", testNow+3600, MaxB+1, resolver)
	})
	uassert.AbortsWithMessage(t, cur, "resolver address invalid", func() {
		CreateMarket(cross(cur), "Q?", testNow+3600, testB, address(""))
	})
	// Seed one ugnot short of the minimum.
	testing.SetRealm(testing.NewUserRealm(creator))
	testing.SetOriginSend(chain.Coins{})
	sendCoins(minSeed() - 1)
	uassert.AbortsWithMessage(t, cur, "seed below b*ln(2): vault could not cover winners", func() {
		CreateMarket(cross(cur), "Q?", testNow+3600, testB, resolver)
	})
	// Non-EOA caller (intermediate code realm) must be rejected even
	// with a big enough envelope.
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/g1lm95v9pqlxtxwc9k8m0rw87agjx5nk3d7waz6l/attacker"))
	testing.SetOriginSend(chain.Coins{{Denom: ugnotDenom, Amount: minSeed()}})
	uassert.AbortsWithMessage(t, cur, "must be called directly by a user (maketx call)", func() {
		CreateMarket(cross(cur), "Q?", testNow+3600, testB, resolver)
	})
}

func TestBuyYesAndNo(cur realm, t *testing.T) {
	defer resetState()
	setTime(testNow)
	creator := testutils.TestAddress("creator2")
	resolver := testutils.TestAddress("resolver2")
	alice := testutils.TestAddress("alice2")
	bob := testutils.TestAddress("bob2")
	testing.SetRealm(testing.NewUserRealm(creator))
	testing.SetOriginSend(chain.Coins{})
	id := createTestMarket(cur, resolver, minSeed()+100000)

	// Alice buys a large YES position: YES price must rise above 50%.
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	costYes := buyTestShares(cur, id, OutcomeYes, 100000)
	uassert.True(t, costYes > 0)
	uassert.Equal(t, int64(100000), BalanceOf(id, alice, true))
	uassert.Equal(t, int64(0), BalanceOf(id, alice, false))
	uassert.Equal(t, int64(100000), GetMarket(id).QYes)
	uassert.True(t, PriceBps(id, true) > 5000)
	uassert.True(t, PriceBps(id, false) < 5000)

	// Bob buys NO: the market balances again at 50/50.
	testing.SetRealm(testing.NewUserRealm(bob))
	testing.SetOriginSend(chain.Coins{})
	costNo := buyTestShares(cur, id, OutcomeNo, 100000)
	uassert.True(t, costNo > 0)
	uassert.Equal(t, int64(100000), BalanceOf(id, bob, false))
	uassert.Equal(t, int64(100000), GetMarket(id).QNo)
	uassert.Equal(t, int64(5000), PriceBps(id, true))
	uassert.Equal(t, int64(5000), PriceBps(id, false))

	// Wrong payment, slippage, and bad inputs must abort.
	cost := QuoteBuy(id, OutcomeYes, 1000)
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	sendCoins(cost - 1)
	uassert.AbortsWithMessage(t, cur, "must send exactly the cost in ugnot", func() {
		Buy(cross(cur), id, OutcomeYes, 1000, cost)
	})
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	sendCoins(cost)
	uassert.AbortsWithMessage(t, cur, "cost exceeds maxCost", func() {
		Buy(cross(cur), id, OutcomeYes, 1000, cost-1)
	})
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	sendCoins(1)
	uassert.AbortsWithMessage(t, cur, "shares must be > 0", func() {
		Buy(cross(cur), id, OutcomeYes, 0, 1)
	})
	uassert.AbortsWithMessage(t, cur, "outcome must be YES (1) or NO (2)", func() {
		Buy(cross(cur), id, 3, 1000, 1000000)
	})
	uassert.AbortsWithMessage(t, cur, "market not found", func() {
		Buy(cross(cur), 999, OutcomeYes, 1000, 1000000)
	})
}

func TestSell(cur realm, t *testing.T) {
	defer resetState()
	setTime(testNow)
	creator := testutils.TestAddress("creator3")
	resolver := testutils.TestAddress("resolver3")
	alice := testutils.TestAddress("alice3")
	testing.SetRealm(testing.NewUserRealm(creator))
	testing.SetOriginSend(chain.Coins{})
	id := createTestMarket(cur, resolver, minSeed()+100000)

	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	cost := buyTestShares(cur, id, OutcomeYes, 100000)
	uassert.True(t, cost > 0)

	// Sell half: refund is positive but less than the full buy cost,
	// balance and outstanding shares drop by exactly the sold amount.
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	refund := Sell(cross(cur), id, OutcomeYes, 50000, 0)
	uassert.True(t, refund > 0)
	uassert.True(t, refund < cost)
	uassert.Equal(t, int64(50000), BalanceOf(id, alice, true))
	uassert.Equal(t, int64(50000), GetMarket(id).QYes)
	uassert.Equal(t, refund, traderBalance(alice))

	// Oversell, minOut too high, and bad inputs must abort.
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	uassert.AbortsWithMessage(t, cur, "not enough shares", func() {
		Sell(cross(cur), id, OutcomeYes, 50001, 0)
	})
	uassert.AbortsWithMessage(t, cur, "refund below minOut", func() {
		Sell(cross(cur), id, OutcomeYes, 1000, 1000000000)
	})
	uassert.AbortsWithMessage(t, cur, "shares must be > 0", func() {
		Sell(cross(cur), id, OutcomeYes, 0, 0)
	})
	uassert.AbortsWithMessage(t, cur, "outcome must be YES (1) or NO (2)", func() {
		Sell(cross(cur), id, 0, 1000, 0)
	})
}

func TestResolve(cur realm, t *testing.T) {
	defer resetState()
	setTime(testNow)
	creator := testutils.TestAddress("creator4")
	resolver := testutils.TestAddress("resolver4")
	alice := testutils.TestAddress("alice4")
	testing.SetRealm(testing.NewUserRealm(creator))
	testing.SetOriginSend(chain.Coins{})
	id := createTestMarket(cur, resolver, minSeed())

	// Too early: the market has not closed yet.
	testing.SetRealm(testing.NewUserRealm(resolver))
	testing.SetOriginSend(chain.Coins{})
	uassert.AbortsWithMessage(t, cur, "market not closed yet", func() {
		Resolve(cross(cur), id, OutcomeYes)
	})
	// Non-resolver cannot resolve, even after close.
	setTime(testNow + 3601)
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	uassert.AbortsWithMessage(t, cur, "only the designated resolver can resolve", func() {
		Resolve(cross(cur), id, OutcomeYes)
	})
	// Bad outcome.
	testing.SetRealm(testing.NewUserRealm(resolver))
	testing.SetOriginSend(chain.Coins{})
	uassert.AbortsWithMessage(t, cur, "outcome must be YES (1) or NO (2)", func() {
		Resolve(cross(cur), id, 0)
	})
	// Happy path: dispute window opens at resolve time.
	testing.SetRealm(testing.NewUserRealm(resolver))
	testing.SetOriginSend(chain.Coins{})
	Resolve(cross(cur), id, OutcomeYes)
	v := GetMarket(id)
	uassert.True(t, v.Resolved)
	uassert.Equal(t, OutcomeYes, v.Outcome)
	uassert.Equal(t, int64(testNow+3601), v.ResolveTime)
	uassert.Equal(t, int64(testNow+3601+DisputeWindow), v.DisputeEndTime)
	// Double resolve must abort.
	testing.SetRealm(testing.NewUserRealm(resolver))
	testing.SetOriginSend(chain.Coins{})
	uassert.AbortsWithMessage(t, cur, "market already resolved", func() {
		Resolve(cross(cur), id, OutcomeNo)
	})
}

func TestRedeem(cur realm, t *testing.T) {
	defer resetState()
	setTime(testNow)
	creator := testutils.TestAddress("creator5")
	resolver := testutils.TestAddress("resolver5")
	alice := testutils.TestAddress("alice5")
	bob := testutils.TestAddress("bob5")
	seed := minSeed() + 100000
	testing.SetRealm(testing.NewUserRealm(creator))
	testing.SetOriginSend(chain.Coins{})
	id := createTestMarket(cur, resolver, seed)

	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	buyTestShares(cur, id, OutcomeYes, 100000)
	testing.SetRealm(testing.NewUserRealm(bob))
	testing.SetOriginSend(chain.Coins{})
	buyTestShares(cur, id, OutcomeNo, 100000)

	// Redeem before resolution must abort.
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	uassert.AbortsWithMessage(t, cur, "market not resolved yet", func() {
		Redeem(cross(cur), id)
	})

	// Resolve YES, then redeem inside the dispute window must abort.
	setTime(testNow + 3601)
	testing.SetRealm(testing.NewUserRealm(resolver))
	testing.SetOriginSend(chain.Coins{})
	Resolve(cross(cur), id, OutcomeYes)
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	uassert.AbortsWithMessage(t, cur, "dispute window still open", func() {
		Redeem(cross(cur), id)
	})

	// After the window: winner gets exactly 1 ugnot per YES share,
	// loser gets 0, and a second redeem is blocked for both.
	setTime(testNow + 3601 + DisputeWindow)
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	payout := Redeem(cross(cur), id)
	uassert.Equal(t, int64(100000), payout)
	uassert.Equal(t, int64(100000), traderBalance(alice))
	uassert.Equal(t, int64(0), BalanceOf(id, alice, true))
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{})
	uassert.AbortsWithMessage(t, cur, "already redeemed", func() {
		Redeem(cross(cur), id)
	})

	testing.SetRealm(testing.NewUserRealm(bob))
	testing.SetOriginSend(chain.Coins{})
	payout = Redeem(cross(cur), id)
	uassert.Equal(t, int64(0), payout)
	uassert.Equal(t, int64(0), traderBalance(bob))
	uassert.Equal(t, int64(100000), BalanceOf(id, bob, false))
	testing.SetRealm(testing.NewUserRealm(bob))
	testing.SetOriginSend(chain.Coins{})
	uassert.AbortsWithMessage(t, cur, "already redeemed", func() {
		Redeem(cross(cur), id)
	})
}

func TestBuyAfterClose(cur realm, t *testing.T) {
	defer resetState()
